176	/****************************************************************************
177	 * LLM Callback (called from ai_agent thread, NOT LVGL thread)
178	 ****************************************************************************/
179	
180	static void llm_response_cb(int status, const char *response, void *cookie)
181	{
182	    g_msg_status = status;
183	    if (status == 0 && response != NULL)
184	      {
185	        strncpy(g_pending_msg, response, MSG_BUF_LEN - 1);
186	        g_pending_msg[MSG_BUF_LEN - 1] = '\0';
187	      }
188	    else
189	      {
190	        snprintf(g_pending_msg, MSG_BUF_LEN, "[LLM error: %d]", status);
191	      }
192	    g_msg_ready = true;
193	}
194	
195	/****************************************************************************
196	 * Send a message to LLM with current role's system prompt
197	 ****************************************************************************/
198	
199	static void send_to_llm(const char *user_text)
200	{
201	    if (!g_agent_connected || g_agent_client == NULL)
202	      {
203	        lv_label_set_text(g_chat_status, "Agent offline - start 'ai_agent &' first");
204	        return;
205	      }
206	
207	    /* Build full prompt: system prompt + user text */
208	    const role_def_t *role = &g_roles[g_current_role];
209	    char full_prompt[MSG_BUF_LEN];
210	    snprintf(full_prompt, MSG_BUF_LEN,
211	             "[SYSTEM]\n%s\n\n[USER]\n%s",
212	             role->system_prompt, user_text);
213	
214	    velaclaw_ask_req_t req = {
215	        .text       = full_prompt,
216	        .timeout_ms = 15000  /* 15 second timeout */
217	    };
218	
219	    lv_label_set_text(g_chat_status, "Thinking...");
220	    if (g_chat_spinner)
221	      {
222	        lv_obj_clear_flag(g_chat_spinner, LV_OBJ_FLAG_HIDDEN);
223	      }
224	
225	    int ret = velaclaw_ask(g_agent_client, &req, llm_response_cb, NULL);
226	    if (ret < 0)
227	      {
228	        lv_label_set_text(g_chat_status, "Failed to send message");
229	        if (g_chat_spinner)
230	          {
231	            lv_obj_add_flag(g_chat_spinner, LV_OBJ_FLAG_HIDDEN);
232	          }
233	      }
234	}
