246	/****************************************************************************
247	 * LVGL Timer: poll for LLM responses and update UI
248	 ****************************************************************************/
249	
250	static void poll_timer_cb(lv_timer_t *timer)
251	{
252	    if (g_msg_ready)
253	      {
254	        g_msg_ready = false;
255	
256	        /* Hide spinner */
257	        if (g_chat_spinner)
258	          {
259	            lv_obj_add_flag(g_chat_spinner, LV_OBJ_FLAG_HIDDEN);
260	          }
261	
262	        if (g_msg_status == 0)
263	          {
264	            /* Show response in chat area */
265	            lv_label_set_text(g_chat_msg_area, g_pending_msg);
266	            lv_label_set_text(g_chat_status, "Tap 'Ask me!' to continue");
267	          }
268	        else
269	          {
270	            lv_label_set_text(g_chat_msg_area, g_pending_msg);
271	            lv_label_set_text(g_chat_status, "Error - check LLM config");
272	          }
273	      }
274	}
