555	/****************************************************************************
556	 * Public Functions
557	 ****************************************************************************/
558	
559	int main(int argc, char *argv[])
560	{
561	    lv_nuttx_dsc_t info;
562	    lv_nuttx_result_t result;
563	
564	    if (lv_is_initialized())
565	      {
566	        LV_LOG_ERROR("LVGL already initialized! aborting.");
567	        return -1;
568	      }
569	
570	#ifdef NEED_BOARDINIT
571	    boardctl(BOARDIOC_INIT, 0);
572	#endif
