#include "llm/llm_cache.h"

#include <pthread.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <time.h>

static const char* TAG = "llm_cache";

typedef struct {
    uint32_t hash;
    char* response;
    uint32_t ts; /* epoch seconds when stored */
    uint32_t hits;
    int tokens; /* total_tokens when cached */
} llm_cache_slot_t;

static llm_cache_slot_t s_slots[LLM_CACHE_SLOTS];
static pthread_mutex_t s_cache_lock = PTHREAD_MUTEX_INITIALIZER;
static uint32_t s_tokens_saved;
static uint32_t s_total_hits;

/* djb2 hash over first LLM_CACHE_KEY_LEN chars */

static uint32_t djb2_hash(const char* str, size_t len)
{
    uint32_t h = 5381;
    size_t n = len < LLM_CACHE_KEY_LEN ? len : LLM_CACHE_KEY_LEN;

    for (size_t i = 0; i < n; i++) {
        h = ((h << 5) + h) + (unsigned char)str[i];
    }
    return h;
}

void llm_cache_init(void)
{
    pthread_mutex_lock(&s_cache_lock);
    for (int i = 0; i < LLM_CACHE_SLOTS; i++) {
        if (s_slots[i].response) {
            free(s_slots[i].response);
            s_slots[i].response = NULL;
        }
        s_slots[i].hash = 0;
        s_slots[i].ts = 0;
        s_slots[i].hits = 0;
        s_slots[i].tokens = 0;
    }
    s_tokens_saved = 0;
    s_total_hits = 0;
    pthread_mutex_unlock(&s_cache_lock);
    syslog(LOG_INFO, "[%s] Cache initialized (%d slots, TTL %ds)\n",
        TAG, LLM_CACHE_SLOTS, LLM_CACHE_TTL_SEC);
}

char* llm_cache_get(const char* prompt, size_t prompt_len)
{
    if (!prompt || prompt_len == 0) {
        return NULL;
    }

    uint32_t h = djb2_hash(prompt, prompt_len);
    uint32_t now = (uint32_t)time(NULL);
    char* result = NULL;

    pthread_mutex_lock(&s_cache_lock);
    for (int i = 0; i < LLM_CACHE_SLOTS; i++) {
        llm_cache_slot_t* s = &s_slots[i];
        if (s->hash == h && s->response) {
            /* Check TTL */
            if (now - s->ts > LLM_CACHE_TTL_SEC) {
                free(s->response);
                s->response = NULL;
                s->hash = 0;
                break;
            }
            result = strdup(s->response);
            if (result) {
                s->hits++;
                s_total_hits++;
                if (s->tokens > 0) {
                    s_tokens_saved += (uint32_t)s->tokens;
                }
            }
            break;
        }
    }
    pthread_mutex_unlock(&s_cache_lock);
    return result;
}

void llm_cache_put(const char* prompt, size_t prompt_len,
    const char* response)
{
    if (!prompt || prompt_len == 0 || !response) {
        return;
    }

    uint32_t h = djb2_hash(prompt, prompt_len);
    uint32_t now = (uint32_t)time(NULL);

    pthread_mutex_lock(&s_cache_lock);

    /* Find: existing slot with same hash, or LRU (oldest ts) */
    int target = 0;
    uint32_t oldest_ts = UINT32_MAX;

    for (int i = 0; i < LLM_CACHE_SLOTS; i++) {
        if (s_slots[i].hash == h) {
            target = i;
            break;
        }
        if (s_slots[i].ts < oldest_ts) {
            oldest_ts = s_slots[i].ts;
            target = i;
        }
    }

    llm_cache_slot_t* s = &s_slots[target];
    if (s->response) {
        free(s->response);
        s->response = NULL;
    }

    s->response = strdup(response);
    if (!s->response) {
        pthread_mutex_unlock(&s_cache_lock);
        return;
    }
    s->hash = h;
    s->ts = now;
    s->hits = 0;

    pthread_mutex_unlock(&s_cache_lock);
}

void llm_cache_put_tokens(const char* prompt, size_t prompt_len,
    int total_tokens)
{
    if (!prompt || prompt_len == 0 || total_tokens <= 0) {
        return;
    }

    uint32_t h = djb2_hash(prompt, prompt_len);

    pthread_mutex_lock(&s_cache_lock);
    for (int i = 0; i < LLM_CACHE_SLOTS; i++) {
        if (s_slots[i].hash == h && s_slots[i].response) {
            s_slots[i].tokens = total_tokens;
            break;
        }
    }
    pthread_mutex_unlock(&s_cache_lock);
}

uint32_t llm_cache_tokens_saved(void)
{
    uint32_t val;
    pthread_mutex_lock(&s_cache_lock);
    val = s_tokens_saved;
    pthread_mutex_unlock(&s_cache_lock);
    return val;
}

uint32_t llm_cache_hit_count(void)
{
    uint32_t val;
    pthread_mutex_lock(&s_cache_lock);
    val = s_total_hits;
    pthread_mutex_unlock(&s_cache_lock);
    return val;
}

void llm_cache_cleanup(void)
{
    pthread_mutex_lock(&s_cache_lock);
    for (int i = 0; i < LLM_CACHE_SLOTS; i++) {
        free(s_slots[i].response);
        s_slots[i].response = NULL;
    }
    pthread_mutex_unlock(&s_cache_lock);
}

/* Run the ReAct tool-calling loop. Returns final_text (caller owns). */
static char* run_react_loop(const char* sys_prompt, cJSON* messages,
    const char* tools_json, char* tool_output, size_t tool_size,
    const agent_msg_t* msg)
{
    char prev_sig[512];
    int dup_count;
    char prev_name[64];
    int name_repeat;
    int iteration;
    char* final_text = NULL;

    prev_sig[0] = '\0';
    dup_count = 0;
    prev_name[0] = '\0';
    name_repeat = 0;
    int last_total_tokens = 0;
    bool watchdog_fired = false;

    /* Router: select and apply best backend before first LLM call.
     * Estimate complexity from the last user message. */
    llm_complexity_t complexity = LLM_COMPLEXITY_SIMPLE;
    if (msg->content) {
        complexity = llm_router_estimate_complexity(
            msg->content, strlen(msg->content));
    }
    int router_idx = llm_router_select(complexity);
    if (router_idx >= 0) {
        llm_router_apply(router_idx);
    }

    /* Structured trace: begin */
    agent_trace_t trace;
    agent_trace_begin(&trace, msg->chat_id, msg->channel);
    trace.backend_idx = router_idx;

    /* Cache check: for simple queries, try cache before LLM call */
    if (msg->content && complexity == LLM_COMPLEXITY_SIMPLE) {
        char* cached = llm_cache_get(msg->content, strlen(msg->content));
        if (cached) {
            syslog(LOG_INFO, "[%s] Cache hit, skipping LLM call\n", TAG);
            final_text = cached;
            agent_trace_step(&trace, 0, NULL, 0, 1);
            agent_trace_end(&trace, AGENT_TRACE_OK);
            goto send_reply;
        }
    }

    for (iteration = 0; iteration < AGENT_AI_AGENT_MAX_TOOL_ITER;
         iteration++) {
        send_working_status(msg, iteration);

        llm_response_t resp;
        struct timeval tv_start, tv_end;
        gettimeofday(&tv_start, NULL);
        int err = llm_chat_tools(sys_prompt, messages, tools_json, &resp);
        gettimeofday(&tv_end, NULL);
        uint32_t latency_ms = calc_elapsed_ms(&tv_start, &tv_end);

        /* Router failover: on LLM call failure, try next backend */
        if (err != OK && router_idx >= 0) {
            syslog(LOG_WARNING,
                "[%s] LLM call failed on backend %d, trying failover\n",
                TAG, router_idx);
            llm_router_report_failure(router_idx);

            int next_idx = llm_router_select(complexity);
            if (next_idx >= 0 && next_idx != router_idx) {
                llm_router_apply(next_idx);
                router_idx = next_idx;
                trace.backend_idx = next_idx;
                llm_response_free(&resp);
                gettimeofday(&tv_start, NULL);
                err = llm_chat_tools(sys_prompt, messages,
                    tools_json, &resp);
                gettimeofday(&tv_end, NULL);
                latency_ms = calc_elapsed_ms(&tv_start, &tv_end);
            }
        }

        if (err != OK) {
            /* Distinguish timeout-induced failure from other errors */
            if (llm_call_timed_out(latency_ms)) {
                syslog(LOG_WARNING,
                    "[%s] LLM watchdog: call failed after %" PRIu32 " ms "
                    "(limit %ds)\n",
                    TAG, latency_ms, AGENT_LLM_TIMEOUT_SEC);
                agent_trace_step(&trace, iteration, NULL,
                    latency_ms, 0);
                llm_response_free(&resp);
                final_text = strdup(LLM_TIMEOUT_MSG);
                watchdog_fired = true;
                break;
            }
            syslog(LOG_ERR, "[%s] LLM call failed (iter %d)\n",
                TAG, iteration);
            agent_trace_step(&trace, iteration, NULL, latency_ms, 0);
            llm_response_free(&resp);
            break;
        }

        /* Watchdog: if the LLM call took longer than the configured
         * timeout, treat it as a timeout even if it returned OK.
         * The socket SO_RCVTIMEO may have fired and caused a partial
         * or error response that llm_chat_tools mapped to ERROR above,
         * but if the call barely completed, we still flag it. */
        if (llm_call_timed_out(latency_ms)) {
            syslog(LOG_WARNING,
                "[%s] LLM watchdog: call took %" PRIu32 " ms (limit %ds), "
                "treating as timeout\n",
                TAG, latency_ms, AGENT_LLM_TIMEOUT_SEC);
            agent_trace_step(&trace, iteration, NULL, latency_ms, 0);
            llm_response_free(&resp);
            final_text = strdup(LLM_TIMEOUT_MSG);
            watchdog_fired = true;
            break;
        }

        /* Report success to router */
        if (router_idx >= 0) {
            llm_router_report_success(router_idx);
            llm_router_report_latency(router_idx, latency_ms);
            if (resp.total_tokens > 0) {
                llm_router_report_tokens(router_idx,
                    resp.prompt_tokens, resp.completion_tokens);
                last_total_tokens = resp.total_tokens;

