32	int voice_tts_register(const voice_tts_ops_t* ops)
33	{
34	    if (!ops || !ops->name || !ops->synthesize) {
35	        return -EINVAL;
36	    }
37	
38	    if (s_backend_count >= VOICE_TTS_MAX_BACKENDS) {
39	        syslog(LOG_ERR, "[%s] Too many TTS backends\n", TAG);
40	        return -ENOMEM;
41	    }
42	
43	    s_backends[s_backend_count++] = ops;
44	    syslog(LOG_INFO, "[%s] Registered backend: %s\n", TAG, ops->name);
45	
46	    /* First registered backend becomes the default */
47	    if (!s_active) {
48	        s_active = ops;
49	        if (ops->init) {
50	            ops->init();
51	        }
52	    }
53	
54	    return 0;
55	}
