57	int voice_tts_set_backend(const char* name)
58	{
59	    if (!name) {
60	        return -EINVAL;
61	    }
62	
63	    for (int i = 0; i < s_backend_count; i++) {
64	        if (strcmp(s_backends[i]->name, name) == 0) {
65	            if (s_active && s_active->deinit) {
66	                s_active->deinit();
67	            }
68	
69	            s_active = s_backends[i];
70	            if (s_active->init) {
71	                s_active->init();
72	            }
73	
74	            syslog(LOG_INFO, "[%s] Backend set to: %s\n",
75	                TAG, name);
76	            return 0;
77	        }
78	    }
79	
80	    syslog(LOG_ERR, "[%s] Backend not found: %s\n", TAG, name);
81	    return -ENOENT;
82	}
