54	static char* build_tts_request(const char* text,
55	    const char* speaker)
56	{
57	    cJSON* root = cJSON_CreateObject();
58	
59	    if (!root) {
60	        return NULL;
61	    }
62	
63	    cJSON* params = cJSON_CreateObject();
64	
65	    if (!params) {
66	        cJSON_Delete(root);
67	        return NULL;
68	    }
69	
70	    cJSON_AddStringToObject(params, "text", text);
71	    cJSON_AddStringToObject(params, "speaker", speaker);
72	
73	    cJSON* audio = cJSON_CreateObject();
74	
75	    if (audio) {
76	        cJSON_AddStringToObject(audio, "format", "pcm");
77	        cJSON_AddNumberToObject(audio, "sample_rate",
78	            AGENT_VOICE_SAMPLE_RATE);
79	        cJSON_AddItemToObject(params, "audio_params", audio);
80	    }
81	
82	    cJSON_AddItemToObject(root, "req_params", params);
83	
84	    char* json_str = cJSON_PrintUnformatted(root);
85	
86	    cJSON_Delete(root);
87	    return json_str;
88	}
89	
90	static int volc_tts_synthesize(const char* text,
91	    unsigned char* pcm_out,
92	    size_t pcm_cap,
93	    size_t* pcm_len)
94	{
95	    if (!text || !pcm_out || !pcm_len) {
96	        return -EINVAL;
97	    }
98	
99	    /* Reload credentials in case they changed at runtime */
100	    volc_tts_init();
101	
102	    if (s_api_key[0] == '\0') {
103	        syslog(LOG_ERR, "[%s] API key not configured\n", TAG);
104	        return -ENOENT;
105	    }
106	
107	    *pcm_len = 0;
108	
109	    char* body = build_tts_request(text, s_speaker);
110	
111	    if (!body) {
112	        syslog(LOG_ERR, "[%s] Failed to build TTS request\n", TAG);
113	        return -ENOMEM;
114	    }
115	
116	    vela_header_t hdrs[] = {
117	        { "x-api-key", s_api_key },
118	        { "X-Api-Resource-Id", AGENT_DOUBAO_TTS_RESOURCE },
119	        { "Connection", "close" },
120	        { NULL, NULL }
121	    };
122	
123	    char* resp = calloc(1, AGENT_VOICE_RESP_BUF_SIZE);
124	
125	    if (!resp) {
126	        free(body);
127	        return -ENOMEM;
128	    }
129	
130	    syslog(LOG_INFO, "[%s] TTS V3 request: text=%zu bytes\n",
131	        TAG, strlen(text));
132	
133	    size_t body_len;
134	    int status = vela_https_request(
135	        AGENT_DOUBAO_TTS_HOST, AGENT_DOUBAO_TTS_PORT,
136	        "POST", AGENT_DOUBAO_TTS_V3_PATH, hdrs,
137	        body, strlen(body),
138	        resp, AGENT_VOICE_RESP_BUF_SIZE, &body_len);
139	
140	    free(body);
141	    body = NULL;
142	
143	    if (status != 200) {
144	        syslog(LOG_ERR, "[%s] TTS HTTP %d: %.256s\n",
145	            TAG, status, resp);
146	        free(resp);
147	        return -EIO;
148	    }
149	
150	    if (body_len == 0) {
151	        syslog(LOG_ERR, "[%s] TTS: empty response body\n", TAG);
152	        free(resp);
153	        return -EPROTO;
154	    }
155	
156	    size_t total_pcm = 0;
157	    int chunks = 0;
158	    char* line = resp;
159	
160	    while (line && *line) {
161	        while (*line == '\n' || *line == '\r' || *line == ' ') {
162	            line++;
163	        }
164	
165	        if (*line == '\0') {
166	            break;
167	        }
168	
169	        char* eol = strchr(line, '\n');
170	
171	        if (eol) {
172	            *eol = '\0';
173	        }
174	
175	        cJSON* obj = cJSON_Parse(line);
176	
177	        if (!obj) {
178	            /* Truncated JSON at buffer boundary — skip silently
179	             * if we already decoded some audio data. */
180	            if (total_pcm > 0) {
181	                syslog(LOG_WARNING,
182	                    "[%s] TTS: truncated chunk %d (buffer full), "
183	                    "using %zu bytes decoded so far\n",
184	                    TAG, chunks, total_pcm);
185	                break;
186	            }
187	            syslog(LOG_ERR, "[%s] TTS: bad JSON chunk %d: %.80s\n",
188	                TAG, chunks, line);
189	            break;
190	        }
191	
192	        cJSON* code_j = cJSON_GetObjectItem(obj, "code");
193	        int code_val = code_j ? (int)code_j->valuedouble : -1;
194	
195	        if (!code_j || !cJSON_IsNumber(code_j)
196	            || (code_val != 0 && code_val != 20000000)) {
197	            cJSON* msg_j = cJSON_GetObjectItem(obj, "message");
198	
199	            syslog(LOG_ERR, "[%s] TTS error %d: %.80s\n",
200	                TAG, code_val,
201	                (msg_j && msg_j->valuestring)
202	                    ? msg_j->valuestring
203	                    : line);
204	            cJSON_Delete(obj);
205	            free(resp);
206	            return -EIO;
207	        }
208	
209	        cJSON* data_j = cJSON_GetObjectItem(obj, "data");
210	
211	        if (data_j && cJSON_IsString(data_j)
212	            && data_j->valuestring[0]) {
213	            const char* b64 = data_j->valuestring;
214	            size_t b64_len = strlen(b64);
215	            size_t decoded_len;
216	
217	            if (total_pcm + (b64_len * 3 / 4) > pcm_cap) {
218	                syslog(LOG_ERR,
219	                    "[%s] TTS: PCM buffer full at chunk %d\n",
220	                    TAG, chunks);
221	                cJSON_Delete(obj);
222	                break;
223	            }
224	
225	            mbedtls_base64_decode(
226	                pcm_out + total_pcm, pcm_cap - total_pcm,
227	                &decoded_len,
228	                (const unsigned char*)b64, b64_len);
229	            total_pcm += decoded_len;
230	            chunks++;
231	        }
232	
233	        cJSON_Delete(obj);
234	        line = eol ? eol + 1 : NULL;
235	    }
236	
237	    free(resp);
238	    resp = NULL;
239	
240	    if (total_pcm == 0) {
241	        syslog(LOG_ERR, "[%s] TTS: no PCM data decoded\n", TAG);
242	        return -EPROTO;
243	    }
244	
245	    *pcm_len = total_pcm;
246	
247	    syslog(LOG_INFO,
248	        "[%s] TTS: synthesized %zu PCM bytes (%d chunks)\n",
249	        TAG, *pcm_len, chunks);
250	    return 0;
251	}
252	
253	/* ── Streaming TTS (callback per chunk) ──────────────────────── */
254	
255	/* Streaming path uses smaller b64 decode buffer than batch.
256	 * The resp buffer stays at 128KB to support up to ~4s of TTS
257	 * audio (typical LLM reply length).  For >4s audio, true
258	 * chunked HTTP reception would be needed (future work).
259	 * Net saving vs batch: 80KB (b64 96KB→16KB). */
260	#define VOLC_TTS_STREAM_RESP_SIZE (512 * 1024)
261	#define VOLC_TTS_STREAM_B64_SIZE (16 * 1024)
262	
263	int volc_tts_synthesize_stream(const char* text,
264	    volc_tts_chunk_cb cb,
265	    void* user_data)
266	{
267	    if (!text || !cb) {
268	        return -EINVAL;
269	    }
270	
271	    volc_tts_init();
272	
273	    if (s_api_key[0] == '\0') {
274	        syslog(LOG_ERR, "[%s] stream: API key not configured\n",
275	            TAG);
276	        return -ENOENT;
277	    }
278	
279	    char* body = build_tts_request(text, s_speaker);
280	
281	    if (!body) {
282	        return -ENOMEM;
283	    }
284	
285	    vela_header_t hdrs[] = {
286	        { "x-api-key", s_api_key },
287	        { "X-Api-Resource-Id", AGENT_DOUBAO_TTS_RESOURCE },
288	        { "Connection", "close" },
289	        { NULL, NULL }
290	    };
291	
292	    char* resp = calloc(1, VOLC_TTS_STREAM_RESP_SIZE);
293	
294	    if (!resp) {
295	        free(body);
296	        return -ENOMEM;
297	    }
298	
299	    size_t body_len;
300	    int status = vela_https_request(
301	        AGENT_DOUBAO_TTS_HOST, AGENT_DOUBAO_TTS_PORT,
302	        "POST", AGENT_DOUBAO_TTS_V3_PATH, hdrs,
303	        body, strlen(body),
304	        resp, VOLC_TTS_STREAM_RESP_SIZE, &body_len);
305	
306	    free(body);
307	
308	    if (status != 200) {
309	        syslog(LOG_ERR, "[%s] stream: HTTP %d\n", TAG, status);
310	        free(resp);
311	        return -EIO;
312	    }
313	
314	    if (body_len == 0) {
315	        free(resp);
316	        return -EPROTO;
317	    }
318	
319	    /* Decode buffer for base64 chunks */
320	    unsigned char* pcm_tmp = malloc(VOLC_TTS_STREAM_B64_SIZE);
321	
322	    if (!pcm_tmp) {
323	        free(resp);
324	        return -ENOMEM;
325	    }
326	
327	    int chunks = 0;
328	    int err = 0;
329	    char* line = resp;
330	
331	    while (line && *line) {
332	        while (*line == '\n' || *line == '\r' || *line == ' ') {
333	            line++;
334	        }
335	
336	        if (*line == '\0') {
337	            break;
338	        }
339	
340	        char* eol = strchr(line, '\n');
341	
342	        if (eol) {
343	            *eol = '\0';
344	        }
345	
346	        cJSON* obj = cJSON_Parse(line);
347	
348	        if (!obj) {
349	            if (chunks > 0) {
350	                syslog(LOG_WARNING,
351	                    "[%s] stream: response truncated after "
352	                    "%d chunks (buffer full?)\n",
353	                    TAG, chunks);
354	                break;
355	            }
356	            syslog(LOG_ERR, "[%s] stream: bad JSON: %.80s\n",
357	                TAG, line);
358	            err = -EPROTO;
359	            break;
360	        }
361	
362	        cJSON* code_j = cJSON_GetObjectItem(obj, "code");
363	        int code_val = code_j ? (int)code_j->valuedouble : -1;
364	
365	        if (!code_j || !cJSON_IsNumber(code_j)
366	            || (code_val != 0 && code_val != 20000000)) {
367	            syslog(LOG_ERR, "[%s] stream: TTS error %d\n",
368	                TAG, code_val);
369	            cJSON_Delete(obj);
370	            err = -EIO;
371	            break;
372	        }
373	
374	        cJSON* data_j = cJSON_GetObjectItem(obj, "data");
375	
376	        if (data_j && cJSON_IsString(data_j)
377	            && data_j->valuestring[0]) {
378	            const char* b64 = data_j->valuestring;
379	            size_t b64_len = strlen(b64);
380	            size_t decoded_len;
381	
382	            mbedtls_base64_decode(
383	                pcm_tmp, VOLC_TTS_STREAM_B64_SIZE,
384	                &decoded_len,
385	                (const unsigned char*)b64, b64_len);
386	
387	            cb(pcm_tmp, decoded_len, 0, user_data);
388	            chunks++;
389	        }
390	
391	        cJSON_Delete(obj);
392	        line = eol ? eol + 1 : NULL;
393	    }
394	
395	    /* Send exactly one is_last=1 notification */
396	    if (chunks > 0 && err == 0) {
397	        cb(NULL, 0, 1, user_data);
398	    }
399	
400	    free(pcm_tmp);
401	    free(resp);
402	
403	    if (chunks == 0 && err == 0) {
404	        err = -EPROTO;
405	    }
406	
407	    syslog(LOG_INFO, "[%s] stream: %d chunks delivered\n",
408	        TAG, chunks);
409	    return err;
410	}
