100	typedef struct {
101	    void* heap;
102	    Ec2FloatState* ns;
103	    CompexpState* agc;
104	} audio_preproc_t;
105	
106	static audio_preproc_t* preproc_create(void)
107	{
108	    audio_preproc_t* pp = calloc(1, sizeof(*pp));
109	    if (!pp) {
110	        return NULL;
111	    }
112	
113	    pp->heap = malloc(PREPROC_HEAP_SIZE);
114	    if (!pp->heap) {
115	        free(pp);
116	        return NULL;
117	    }
118	    med_heap_init(pp->heap, PREPROC_HEAP_SIZE);
119	
120	    pp->ns = ec2float_create(AGENT_VOICE_SAMPLE_RATE,
121	        PREPROC_FRAME_SIZE, 0, &s_ns_cfg);
122	    pp->agc = compexp_create(AGENT_VOICE_SAMPLE_RATE,
123	        PREPROC_FRAME_SIZE, &s_agc_cfg);
124	
125	    syslog(LOG_INFO, "[%s] preproc: NS=%p AGC=%p heap=%dKB\n",
126	        TAG, (void*)pp->ns, (void*)pp->agc,
127	        PREPROC_HEAP_SIZE / 1024);
128	    return pp;
129	}
130	
131	static void preproc_destroy(audio_preproc_t* pp)
132	{
133	    if (!pp) {
134	        return;
135	    }
136	    if (pp->agc) {
137	        compexp_destroy(pp->agc);
138	    }
139	    if (pp->ns) {
140	        ec2float_destroy(pp->ns);
141	    }
142	    free(pp->heap);
143	    free(pp);
144	}
145	
146	static void preproc_chunk(audio_preproc_t* pp,
147	    unsigned char* buf, int bytes)
148	{
149	    if (!pp || (!pp->ns && !pp->agc)) {
150	        return;
151	    }
152	
153	    int16_t* samples = (int16_t*)buf;
154	    int total = bytes / 2;
155	    int fsz = PREPROC_FRAME_SIZE;
156	    int32_t in32[PREPROC_FRAME_SIZE];
157	    int32_t ref32[PREPROC_FRAME_SIZE];
158	    int32_t out32[PREPROC_FRAME_SIZE];
159	
160	    memset(ref32, 0, sizeof(ref32));
161	
162	    for (int off = 0; off < total; off += fsz) {
163	        int n = (off + fsz <= total) ? fsz : (total - off);
164	
165	        for (int i = 0; i < n; i++) {
166	            in32[i] = samples[off + i];
167	        }
168	
169	        if (pp->ns) {
170	            ec2float_process(pp->ns, in32, ref32, n, out32);
171	        } else {
172	            memcpy(out32, in32, n * sizeof(int32_t));
173	        }
174	
175	        if (pp->agc) {
176	            for (int i = 0; i < n; i++) {
177	                out32[i] <<= 8;
178	            }
179	            compexp_process_int24(pp->agc, out32, n);
180	            for (int i = 0; i < n; i++) {
181	                out32[i] >>= 8;
182	            }
183	        }
184	
185	        for (int i = 0; i < n; i++) {
186	            int32_t v = out32[i];
187	            if (v > 32767) {
188	                v = 32767;
189	            } else if (v < -32768) {
190	                v = -32768;
191	            }
192	            samples[off + i] = (int16_t)v;
193	        }
194	    }
195	}
