214	    pthread_t rec_thread;
215	    voice_asr_stream_t* asr_stream; /* streaming ASR handle */
216	    sem_t rec_ready; /* posted by recording_thread when ready to consume */
217	    volatile int tts_abort; /* set to 1 to stop active TTS playback */
218	    audio_playback_t* tts_pb; /* active TTS playback handle (or NULL) */
219	    pthread_mutex_t speak_lock; /* serialize concurrent speak calls */
