191	static void cmd_net_status(void)
192	{
193	    printf("Network connected: %s\n", network_is_connected() ? "yes" : "no");
194	    printf("IP: %s\n", network_get_ip());
195	#ifdef CONFIG_AI_AGENT_NET_RPMSG
196	    printf("State: %s\n",
197	        network_get_state() == NET_STATE_CONNECTED ? "CONNECTED" : "DISCONNECTED");
198	    printf("Active TCP conns: %d/%d\n",
199	        network_get_active_conns(), NET_MAX_TCP_CONNS);
200	    printf("IOB usage: %d%%\n", network_get_iob_usage());
201	    printf("Proxy mode: %s\n", network_get_proxy_mode());
202	    printf("RPMSG CPU: %s\n", network_get_rpmsg_cpu());
203	    /* Show DNS from resolv.conf */
204	    {
205	        FILE* fp = fopen("/tmp/resolv.conf", "r");
206	        if (fp) {
207	            char line[128];
208	            while (fgets(line, sizeof(line), fp)) {
209	                line[strcspn(line, "\n")] = '\0';
210	                printf("DNS: %s\n", line);
211	            }
212	            fclose(fp);
213	        }
214	    }
215	#endif
216	}
