774	/* ── install_skill: install a skill from URL ──────────────── */
775	
776	static void cmd_install_skill(int argc, char** argv)
777	{
778	    if (argc < 3) {
779	        printf("Usage: install_skill <name> <url>\n"
780	               "  name: skill filename (without .md)\n"
781	               "  url:  HTTPS URL to download skill markdown\n");
782	        return;
783	    }
784	
785	    const char* name = argv[1];
786	    const char* url = argv[2];
787	
788	    /* Validate name (lowercase + digits + hyphens) */
789	    for (const char* p = name; *p; p++) {
790	        if (!(*p >= 'a' && *p <= 'z') && !(*p >= '0' && *p <= '9')
791	            && *p != '-' && *p != '_') {
792	            printf("Invalid skill name: use a-z, 0-9, hyphens\n");
793	            return;
794	        }
795	    }
796	
797	    /* Validate URL starts with https:// */
798	    if (strncmp(url, "https://", 8) != 0) {
799	        printf("Only HTTPS URLs are allowed\n");
800	        return;
801	    }
802	
803	    char path[128];
804	    int n = snprintf(path, sizeof(path), "%s%s.md",
805	        AGENT_SKILLS_DIR, name);
806	    if (n < 0 || (size_t)n >= sizeof(path)) {
807	        printf("Skill name too long\n");
808	        return;
809	    }
810	
811	    char* buf = malloc(8192);
812	    if (!buf) {
813	        printf("OOM\n");
814	        return;
815	    }
816	
817	    memset(buf, 0, 8192);
818	    int rc = vela_https_get(url, "443", NULL, buf, 8192);
819	    if (rc < 200 || rc >= 300) {
820	        printf("Download failed: HTTP %d\n", rc);
821	        free(buf);
822	        return;
823	    }
824	
825	    /* Validate content looks like a markdown skill file */
826	    if (buf[0] == '\0') {
827	        printf("Downloaded content is empty\n");
828	        free(buf);
829	        return;
830	    }
831	
832	    /* Basic content validation: must start with # or --- (frontmatter) */
833	    const char* p = buf;
834	    while (*p == ' ' || *p == '\n' || *p == '\r')
835	        p++;
836	    if (*p != '#' && strncmp(p, "---", 3) != 0) {
837	        printf("Invalid skill format: must start with # or ---\n");
838	        free(buf);
839	        return;
840	    }
841	
842	    /* Size sanity check */
843	    size_t content_len = strlen(buf);
844	    if (content_len < 10) {
845	        printf("Downloaded content too small (%zu bytes)\n", content_len);
846	        free(buf);
847	        return;
848	    }
849	
850	    FILE* f = fopen(path, "w");
851	    if (!f) {
852	        printf("Cannot write: %s\n", path);
853	        free(buf);
854	        return;
855	    }
856	
857	    fputs(buf, f);
858	    fclose(f);
859	    free(buf);
860	    printf("Skill installed: %s (%zu bytes)\n", path, content_len);
861	}
