877	
878	static void* cli_thread(void* arg)
879	{
880	    (void)arg;
881	    char line[LINE_LEN];
882	    char* argv[MAX_ARGS];
883	
884	    syslog(LOG_INFO, "[%s] NSH CLI started. Type 'help' for commands.\n", TAG);
885	    pthread_mutex_lock(&g_stdout_lock);
886	    printf("vela> ");
887	    fflush(stdout);
888	    pthread_mutex_unlock(&g_stdout_lock);
889	
890	    while (fgets(line, sizeof(line), stdin) != NULL) {
891	        /* Strip trailing newline */
892	        size_t len = strlen(line);
893	        while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r'))
894	            line[--len] = '\0';
895	
896	        if (len == 0) {
897	            pthread_mutex_lock(&g_stdout_lock);
898	            printf("vela> ");
899	            fflush(stdout);
900	            pthread_mutex_unlock(&g_stdout_lock);
901	            continue;
902	        }
903	
904	        int argc = tokenise(line, argv, MAX_ARGS);
905	        if (argc == 0) {
906	            pthread_mutex_lock(&g_stdout_lock);
907	            printf("vela> ");
908	            fflush(stdout);
