static int mimo_tts_synthesize_stream(const char* text, voice_tts_chunk_cb cb, void* user_data)
{
    if (!text || !cb) return -EINVAL;

    mimo_audio_t a;
    int ret = mimo_fetch_audio(text, &a);
    if (ret != 0) return ret;

    unsigned char pcm_seg[MIMO_PCM_SEG + 4];
    size_t off = 0;
    int chunks = 0;
    int err = 0;

    while (off < a.b64_len) {
        size_t chunk = a.b64_len - off;
        if (chunk > MIMO_B64_SEG) chunk = MIMO_B64_SEG;

        size_t olen = 0;
        int rc = mbedtls_base64_decode(pcm_seg, sizeof(pcm_seg), &olen,
            (const unsigned char*)(a.b64 + off), chunk);
        if (rc != 0) {
            syslog(LOG_ERR, "[%s] stream base64 decode failed at %zu: %d\n",
                TAG, off, rc);
            err = -EPROTO;
            break;
        }
        if (olen > 0) {
            cb(pcm_seg, olen, 0, user_data);
            chunks++;
        }
        off += chunk;
    }

    if (chunks > 0 && err == 0) {
        cb(NULL, 0, 1, user_data);
    }
    if (chunks == 0 && err == 0) err = -EPROTO;

    mimo_audio_free(&a);
    syslog(LOG_INFO, "[%s] stream: %d chunks delivered\n", TAG, chunks);
    return err;
