73		syslog(LOG_INFO,"format:      %u\n", format);
74		syslog(LOG_INFO,"rate:	     %u\n", rate);
75		syslog(LOG_INFO,"channels:    %u\n", channels);
76		syslog(LOG_INFO,"data:	     %p\n", data);
77		syslog(LOG_INFO,"datalen:     %u\n", datalen);
78		syslog(LOG_INFO,"period_size: %lu\n", period_frames);
79		syslog(LOG_INFO,"buffer_size: %lu\n", buffer_frames);
80	
