82		ret = snd_vela_pcm_open(&handle, card_name, SND_VELA_PCM_STREAM_PLAYBACK, mode);
83		if (ret < 0) {
84			syslog(LOG_ERR,"audio open error:%d\n", ret);
85			return -1;
86		}
