258	static int sine_generate(void **buf, uint32_t *len, uint32_t rate, uint32_t channels, uint8_t bits)
259	{
260		int16_t *data_16;
261		int32_t *data_32;
262		int sine_hz = 1000;
263		int sine_point;
264		int accuracy;
265		int i, j;
266	
267		sine_point = rate / sine_hz;
268	
269		if (bits == 16) {
270			data_16 = malloc(sine_point * sizeof(int16_t) * channels);
271			if(!data_16){
272	                   return -1;
273			}
274			accuracy = INT16_MAX;
275			for (i = 0; i < sine_point; i++) {
276				int16_t value = (int16_t)(accuracy * sin(2 * (double)PI * i / sine_point));
277				for (j = 0; j < channels; j++)
278					data_16[(i * channels) + j] = value;
279			}
280	
281			*buf = data_16;
282			*len = sine_point * sizeof(int16_t) * channels;
283		} else if (bits == 32) {
284			data_32 = malloc(sine_point * sizeof(int32_t) * channels);
285			if(!data_32)
286			{
287	                   return -1;
288			}
289			accuracy = INT32_MAX;
290			for (i = 0; i < sine_point; i++) {
291				int32_t value = (int32_t)(accuracy * sin(2 * (double)PI * i / sine_point));
292				for (j = 0; j < channels; j++)
293					data_32[(i * channels) + j] = value;
294			}
295	
296			*buf = data_32;
297			*len = sine_point * sizeof(int32_t) * channels;
298		} else {
299			*buf = NULL;
300			*len = 0;
301			syslog(LOG_ERR,"unsupport bits:%u\n", bits);
302			return -1;
303		}
304	
305		return 0;
306	}
