79	static void apply_capture_gain(void* buf, size_t len)
80	{
81	#if AGENT_AUDIO_CAPTURE_GAIN > 1
82	    int16_t* samples = (int16_t*)buf;
83	    int count = (int)len / (int)sizeof(int16_t);
84	
85	    for (int i = 0; i < count; i++) {
86	        int32_t v = (int32_t)samples[i] * AGENT_AUDIO_CAPTURE_GAIN;
87	        if (v > 32767) {
88	            v = 32767;
89	        } else if (v < -32768) {
90	            v = -32768;
91	        }
92	        samples[i] = (int16_t)v;
93	    }
94	#else
95	    (void)buf;
96	    (void)len;
97	#endif
98	}
