/* ── Connect with retry ──────────────────────────────────────── */

/* The MiMo/OpenAI edge intermittently serves a leaf certificate whose public
 * key (Ed25519/Ed448) this mbedtls build cannot parse in TLS 1.2 — the same
 * host served a parseable RSA cert moments earlier, so the failure is
 * non-deterministic. A fresh TCP connect + handshake usually lands on a
 * different edge / cert, so retry a few times before giving up. */
#define TLS_CONNECT_MAX_ATTEMPTS 3

static int tls_ctx_connect_retry(tls_ctx_t* ctx, const char* host,
    const char* port)
{
    int ret = VELA_TLS_ERR_HANDSHAKE;

    for (int attempt = 0; attempt < TLS_CONNECT_MAX_ATTEMPTS; attempt++) {
        ret = tls_ctx_connect(ctx, host, port);

        if (ret == 0) {
            return 0;
        }

        /* Only transient failures (TLS handshake / TCP connect) warrant a
         * retry; anything else (config/entropy) is fatal. */
        if (ret != VELA_TLS_ERR_HANDSHAKE && ret != VELA_TLS_ERR_CONNECT) {
            return ret;
        }

        if (attempt + 1 == TLS_CONNECT_MAX_ATTEMPTS) {
            break; /* last attempt — leave ctx for the caller to free */
        }

        syslog(LOG_WARNING,
            "[%s] connect %s:%s attempt %d/%d failed (%d), retrying\n",
            TAG, host, port, attempt + 1, TLS_CONNECT_MAX_ATTEMPTS, ret);

        tls_ctx_free(ctx);
        usleep(200 * 1000);
    }

    return ret;
}

