82	static char* build_tts_request(const char* text)
83	{
84	    cJSON* root = cJSON_CreateObject();
85	
86	    if (!root) {
87	        return NULL;
88	    }
89	
90	    cJSON_AddStringToObject(root, "model", MIMO_TTS_MODEL);
91	
92	    cJSON* messages = cJSON_CreateArray();
93	    cJSON* assistant = cJSON_CreateObject();
94	
95	    if (!messages || !assistant) {
96	        cJSON_Delete(root);
97	        return NULL;
98	    }
99	
100	    cJSON_AddStringToObject(assistant, "role", "assistant");
101	    cJSON_AddStringToObject(assistant, "content", text);
102	    cJSON_AddItemToArray(messages, assistant);
103	    cJSON_AddItemToObject(root, "messages", messages);
104	
105	    cJSON* audio = cJSON_CreateObject();
106	
107	    if (!audio) {
108	        cJSON_Delete(root);
109	        return NULL;
110	    }
111	
112	    cJSON_AddStringToObject(audio, "format", MIMO_TTS_FORMAT);
113	    cJSON_AddStringToObject(audio, "voice", MIMO_TTS_VOICE);
114	    cJSON_AddItemToObject(root, "audio", audio);
115	
116	    char* json_str = cJSON_PrintUnformatted(root);
117	
118	    cJSON_Delete(root);
119	    return json_str;
120	}
