122	/* One fetched TTS response. resp holds the raw HTTP body; root holds the
123	 * parsed JSON (the base64 string lives inside root, not resp). */
124	typedef struct {
125	    char* resp;      /* owned, caller frees */
126	    cJSON* root;     /* owned, caller frees */
127	    const char* b64; /* pointer into root's strings */
128	    size_t b64_len;
129	} mimo_audio_t;
