140	static int mimo_fetch_audio(const char* text, mimo_audio_t* out)
141	{
142	    memset(out, 0, sizeof(*out));
143	
144	    mimo_tts_init();
145	
146	    if (s_api_key[0] == '\0') {
147	        syslog(LOG_ERR, "[%s] API key not configured (set 'api_key')\n",
148	            TAG);
149	        return -ENOENT;
150	    }
151	
152	    char* body = build_tts_request(text);
153	
154	    if (!body) {
155	        syslog(LOG_ERR, "[%s] failed to build TTS request\n", TAG);
156	        return -ENOMEM;
157	    }
158	
159	    char auth[256];
160	    snprintf(auth, sizeof(auth), "Bearer %s", s_api_key);
161	
162	    vela_header_t hdrs[] = {
163	        { "Authorization", auth },
164	        { "Content-Type", "application/json" },
165	        { "Connection", "close" },
166	        { NULL, NULL }
167	    };
168	
169	    char* resp = calloc(1, MIMO_TTS_RESP_SIZE);
170	
171	    if (!resp) {
172	        free(body);
173	        return -ENOMEM;
174	    }
175	
176	    syslog(LOG_INFO, "[%s] TTS request: text=%zu bytes host=%s\n",
177	        TAG, strlen(text), s_host);
178	
179	    size_t body_len;
180	    int status = vela_https_request(
181	        s_host, "443", "POST", MIMO_TTS_PATH, hdrs,
182	        body, strlen(body),
183	        resp, MIMO_TTS_RESP_SIZE, &body_len);
184	
185	    free(body);
186	
187	    if (status != 200) {
188	        syslog(LOG_ERR, "[%s] TTS HTTP %d: %.256s\n",
189	            TAG, status, resp);
190	        free(resp);
191	        return -EIO;
192	    }
193	
194	    if (body_len == 0) {
195	        syslog(LOG_ERR, "[%s] TTS: empty response body\n", TAG);
196	        free(resp);
197	        return -EPROTO;
198	    }
199	
200	    cJSON* root = cJSON_Parse(resp);
201	
202	    if (!root) {
203	        syslog(LOG_ERR, "[%s] TTS: bad JSON: %.256s\n", TAG, resp);
204	        free(resp);
205	        return -EPROTO;
206	    }
207	
208	    /* choices[0].message.audio.data */
209	    cJSON* choices = cJSON_GetObjectItem(root, "choices");
210	    cJSON* choice0 = (choices && cJSON_IsArray(choices))
211	        ? cJSON_GetArrayItem(choices, 0) : NULL;
212	    cJSON* msg = choice0 ? cJSON_GetObjectItem(choice0, "message") : NULL;
213	    cJSON* audio = msg ? cJSON_GetObjectItem(msg, "audio") : NULL;
214	    cJSON* data = audio ? cJSON_GetObjectItem(audio, "data") : NULL;
215	
216	    if (!data || !cJSON_IsString(data) || !data->valuestring[0]) {
217	        syslog(LOG_ERR, "[%s] TTS: no audio.data in response: %.256s\n",
218	            TAG, resp);
219	        cJSON_Delete(root);
220	        free(resp);
221	        return -EPROTO;
222	    }
223	
224	    out->resp = resp;
225	    out->root = root;
226	    out->b64 = data->valuestring;
227	    out->b64_len = strlen(data->valuestring);
228	    return 0;
229	}
