231	static int mimo_tts_synthesize(const char* text,
232	    unsigned char* pcm_out,
233	    size_t pcm_cap,
234	    size_t* pcm_len)
235	{
236	    if (!text || !pcm_out || !pcm_len) {
237	        return -EINVAL;
238	    }
239	
240	    *pcm_len = 0;
241	
242	    mimo_audio_t a;
243	    int ret = mimo_fetch_audio(text, &a);
244	
245	    if (ret != 0) {
246	        return ret;
247	    }
248	
249	    size_t olen = 0;
250	    int rc = mbedtls_base64_decode(pcm_out, pcm_cap, &olen,
251	        (const unsigned char*)a.b64, a.b64_len);
252	
253	    if (rc != 0) {
254	        syslog(LOG_ERR, "[%s] TTS: base64 decode failed: %d\n", TAG, rc);
255	        mimo_audio_free(&a);
256	        return (rc == MBEDTLS_ERR_BASE64_BUFFER_TOO_SMALL)
257	            ? -EFBIG : -EPROTO;
258	    }
259	
260	    *pcm_len = olen;
261	    mimo_audio_free(&a);
262	
263	    syslog(LOG_INFO, "[%s] TTS: synthesized %zu PCM bytes\n", TAG, olen);
264	    return 0;
265	}
