267	static int mimo_tts_synthesize_stream(const char* text,
268	    voice_tts_chunk_cb cb,
269	    void* user_data)
270	{
271	    if (!text || !cb) {
272	        return -EINVAL;
273	    }
274	
275	    mimo_audio_t a;
276	    int ret = mimo_fetch_audio(text, &a);
277	
278	    if (ret != 0) {
279	        return ret;
280	    }
281	
282	    unsigned char* pcm_seg = malloc(MIMO_PCM_SEG + 4);
283	
284	    if (!pcm_seg) {
285	        mimo_audio_free(&a);
286	        return -ENOMEM;
287	    }
288	
289	    size_t off = 0;
290	    int chunks = 0;
291	    int err = 0;
292	
293	    while (off < a.b64_len) {
294	        size_t chunk = a.b64_len - off;
295	
296	        if (chunk > MIMO_B64_SEG) {
297	            chunk = MIMO_B64_SEG;
298	        }
299	
300	        size_t olen = 0;
301	        int rc = mbedtls_base64_decode(pcm_seg, MIMO_PCM_SEG + 4, &olen,
302	            (const unsigned char*)(a.b64 + off), chunk);
303	
304	        if (rc != 0) {
305	            syslog(LOG_ERR,
306	                "[%s] stream: base64 decode failed at %zu: %d\n",
307	                TAG, off, rc);
308	            err = -EPROTO;
309	            break;
310	        }
311	
312	        if (olen > 0) {
313	            cb(pcm_seg, olen, 0, user_data);
314	            chunks++;
315	        }
316	
317	        off += chunk;
318	    }
319	
320	    if (chunks > 0 && err == 0) {
321	        cb(NULL, 0, 1, user_data);
322	    }
323	
324	    if (chunks == 0 && err == 0) {
325	        err = -EPROTO;
326	    }
327	
328	    free(pcm_seg);
329	    mimo_audio_free(&a);
330	
331	    syslog(LOG_INFO, "[%s] stream: %d chunks delivered\n", TAG, chunks);
332	    return err;
333	}
