/* ── Sentence chunking for TTS ──────────────────────────────── */

/* Return the byte length of a sentence-terminating punctuation mark at
 * *p (0 if *p is not a terminator). Full-width Chinese punctuation is
 * 3 bytes in UTF-8, so we match the whole character, not just one byte. */
static int tts_sentence_end_len(const char* p)
{
    static const char* const TERM[] = {
        "。", "！", "？", "；", "…", "\n", "!", "?", ";", ".", "~", NULL
    };

    for (int i = 0; TERM[i] != NULL; i++) {
        size_t n = strlen(TERM[i]);

        if (strncmp(p, TERM[i], n) == 0) {
            return (int)n;
        }
    }

    return 0;
}

/* Synthesize one sentence [s, e). Returns the backend result, or -EINVAL
 * if the slice is empty after stripping leading whitespace. */
static int tts_speak_sentence(const char* s, const char* e,
    audio_playback_t* pb)
{
    size_t len = (size_t)(e - s);
    char* sent = malloc(len + 1);

    if (!sent) {
        return -ENOMEM;
    }

    memcpy(sent, s, len);
    sent[len] = '\0';

    char* c = sent;
    while (*c == ' ' || *c == '\n' || *c == '\t' || *c == '\r') {
        c++;
    }

    int r = *c ? voice_tts_speak_stream(c, tts_stream_cb, pb) : -EINVAL;

    free(sent);
    return r;
}

/* Synthesize text one sentence at a time. A long story produces many
 * sentences; sending them individually keeps each TTS response small
 * (a single utterance's base64 audio can exceed MIMO_TTS_RESP_SIZE and
 * fail JSON parsing) and lets the child hear the first sentence while
 * the rest are still being fetched. */
static int tts_speak_chunked(const char* text, audio_playback_t* pb)
{
    const char* start = text;
    int first_err = 0;
    int any_ok = 0;

    while (*start) {
        const char* p = start;
        int tlen = 0;

        while (*p) {
            tlen = tts_sentence_end_len(p);
            if (tlen > 0) {
                break;
            }
            p++;
        }

        const char* end;

        if (*p) {
            end = p + tlen;

            /* Absorb immediately-following terminators (e.g. "!!!") so
             * they don't become empty one-punctuation sentences. */
            while (*end) {
                int n = tts_sentence_end_len(end);
                if (n > 0) {
                    end += n;
                } else {
                    break;
                }
            }
        } else {
            end = p; /* end of string */
        }

        if (end > start) {
            int r = tts_speak_sentence(start, end, pb);

            if (r == 0) {
                any_ok = 1;
            } else if (first_err == 0) {
                first_err = r;
            }
        }

        if (*end == '\0') {
            break;
        }

        start = end;

        if (s_voice.tts_abort) {
            break;
        }
    }

    if (any_ok) {
        return 0;
    }

    return first_err ? first_err : -EPROTO;
}

