     static int tts_speak_sentence(const char* s, const char* e, audio_playback_t* pb)
     {
         size_t len = (size_t)(e - s);
         char* sent = malloc(len + 1);
         if (!sent) return -ENOMEM;
         memcpy(sent, s, len);
