211	static int open_media_player_playback(audio_playback_t* pb,
212	    unsigned int sample_rate, unsigned int channels,
213	    unsigned int bits_per_sample)
214	{
215	    void* player = media_player_open(MEDIA_STREAM_MUSIC);
216	
217	    if (!player) {
218	        syslog(LOG_ERR, "[%s] media_player_open failed\n", TAG);
219	        return -EIO;
220	    }
221	
222	    char opts[PB_OPTIONS_LEN];
223	    snprintf(opts, sizeof(opts),
224	        "format=s%ule:sample_rate=%u:ch_layout=%s",
225	        bits_per_sample, sample_rate,
226	        (channels == 1) ? "mono" : "stereo");
227	
228	    int ret = media_player_prepare(player, NULL, opts);
229	
230	    if (ret < 0) {
231	        syslog(LOG_ERR, "[%s] prepare failed: %d\n", TAG, ret);
232	        media_player_close(player, 0);
233	        return ret;
234	    }
235	
236	    ret = media_player_start(player);
237	    if (ret < 0) {
238	        syslog(LOG_ERR, "[%s] start failed: %d\n", TAG, ret);
239	        media_player_close(player, 0);
240	        return ret;
241	    }
242	
243	    pb->backend = AUDIO_PLAYBACK_BACKEND_MEDIA_PLAYER;
244	    pb->handle.player = player;
245	    pb->bytes_per_frame = (bits_per_sample / 8) * channels;
246	
247	    syslog(LOG_INFO, "[%s] opened media player (%uHz %uch %ubit)\n",
248	        TAG, sample_rate, channels, bits_per_sample);
249	    return 0;
250	}
