252	audio_playback_t* audio_playback_open(const char* dev_path,
253	    unsigned int sample_rate, unsigned int channels,
254	    unsigned int bits_per_sample)
255	{
256	    if (s_active_pb) {
257	        syslog(LOG_WARNING, "[%s] force closing stale player\n", TAG);
258	        audio_playback_close(s_active_pb);
259	        usleep(100000);
260	    }
261	
262	    audio_playback_t* pb = calloc(1, sizeof(*pb));
263	
264	    if (!pb) {
265	        return NULL;
266	    }
267	
268	    int ret = -ENOTSUP;
269	#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
270	    ret = open_alsa_playback(pb, dev_path, sample_rate, channels,
271	        bits_per_sample);
272	    if (ret < 0) {
273	        syslog(LOG_WARNING,
274	            "[%s] direct ALSA playback unavailable (%d), falling back to media player\n",
275	            TAG, ret);
276	    }
277	#else
278	    (void)dev_path;
279	#endif
280	
281	    if (ret < 0) {
282	        ret = open_media_player_playback(pb, sample_rate, channels,
283	            bits_per_sample);
284	        if (ret < 0) {
285	            free(pb);
286	            return NULL;
287	        }
288	    }
289	
290	    s_active_pb = pb;
291	
292	    syslog(LOG_INFO, "[%s] opened (%uHz %uch %ubit)\n",
293	        TAG, sample_rate, channels, bits_per_sample);
294	    return pb;
295	}
296	
297	int audio_playback_write(audio_playback_t* pb, const void* buf, size_t len)
298	{
299	    if (!pb || !buf || len == 0) {
300	        return -EINVAL;
301	    }
302	
303	    if (pb->stopped) {
304	        return -ECANCELED;
305	    }
306	
307	#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
308	    if (pb->backend == AUDIO_PLAYBACK_BACKEND_ALSA) {
309	        snd_pcm_t* pcm = pb->handle.pcm;
310	        const unsigned char* src = buf;
311	        size_t written_bytes = 0;
312	
313	        while (written_bytes < len) {
314	            snd_pcm_uframes_t frames = snd_vela_pcm_bytes_to_frames(pcm,
315	                len - written_bytes);
316	            snd_pcm_sframes_t n = snd_vela_pcm_writei(pcm, src, frames);
317	
318	            if (n == -EAGAIN) {
319	                usleep(10 * 1000);
320	                continue;
321	            }
322	
323	            if (n == -EPIPE || n == -ESTRPIPE) {
324	                snd_vela_pcm_prepare(pcm);
325	                continue;
326	            }
327	
328	            if (n <= 0) {
329	                syslog(LOG_ERR, "[%s] ALSA write failed: %ld\n",
330	                    TAG, (long)n);
331	                return (n < 0) ? (int)n : -EIO;
332	            }
333	
334	            size_t bytes = (size_t)n * (size_t)pb->bytes_per_frame;
335	            src += bytes;
336	            written_bytes += bytes;
337	        }
338	
339	        pb->total_written += written_bytes;
340	        return (int)written_bytes;
341	    }
342	#endif
343	
344	    ssize_t n = media_player_write_data(pb->handle.player, buf, len);
345	
346	    if (n > 0) {
347	        pb->total_written += (size_t)n;
348	    }
349	
350	    return (int)n;
351	}
352	
353	void audio_playback_stop(audio_playback_t* pb)
354	{
355	    if (!pb) {
356	        return;
357	    }
358	
359	    pb->stopped = 1;
360	
361	#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
362	    if (pb->backend == AUDIO_PLAYBACK_BACKEND_ALSA) {
363	        if (pb->handle.pcm) {
364	            snd_vela_pcm_drop(pb->handle.pcm);
365	        }
366	        return;
367	    }
368	#endif
369	
370	    if (pb->handle.player) {
371	        media_player_stop(pb->handle.player);
372	    }
373	}
374	
375	void audio_playback_close(audio_playback_t* pb)
376	{
377	    if (!pb) {
378	        return;
379	    }
380	
381	#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
382	    if (pb->backend == AUDIO_PLAYBACK_BACKEND_ALSA) {
383	        if (pb->handle.pcm) {
384	            if (!pb->stopped) {
385	                /* Block until all written samples have played out. */
386	                snd_vela_pcm_drain(pb->handle.pcm);
387	            }
388	            syslog(LOG_INFO, "[%s] closing ALSA (%zu bytes written)\n",
389	                TAG, pb->total_written);
390	            snd_vela_pcm_close(pb->handle.pcm);
391	        }
392	        s_active_pb = NULL;
393	        free(pb);
394	        return;
395	    }
396	#endif
397	
398	    if (pb->handle.player) {
399	        syslog(LOG_INFO, "[%s] closing (%zu bytes written)\n",
400	            TAG, pb->total_written);
401	        media_player_stop(pb->handle.player);
402	        usleep(50 * 1000);
403	        media_player_close(pb->handle.player, 0);
404	    }
405	
406	    s_active_pb = NULL;
407	    free(pb);
408	}
