550	/* Run TTS on a worker thread. voice_channel_speak() does blocking network
551	 * round-trips (and several of them for a long story), so calling it inline
552	 * would stall the dispatch thread and leave the UI unresponsive — frozen
553	 * touch, screen not refreshing. A detached thread keeps the UI alive and
554	 * relies on voice_channel_speak()'s internal abort logic to cancel an
555	 * in-flight utterance when a newer one arrives. */
556	static void* tts_speak_thread(void* arg)
557	{
558	    char* text = (char*)arg;
559	
560	    if (text) {
561	        int ret = voice_channel_speak(text);
562	        if (ret != 0) {
563	            syslog(LOG_ERR, "[%s] voice_channel_speak failed (rc=%d)\n",
564	                TAG, ret);
565	        }
566	        free(text);
567	    }
568	
569	    return NULL;
570	}
571	
572	int lvgl_ui_channel_send(const char* text)
573	{
574	    int ret;
575	    async_msg_t* payload;
576	
577	    /* Parameter validation: NULL or empty string */
578	    if (!text || text[0] == '\0') {
579	        syslog(LOG_ERR, "[%s] send: invalid text (NULL or empty)\n", TAG);
580	        return -EINVAL;
581	    }
582	
583	    /* Check channel readiness */
584	    if (!s_state.initialized || !s_state.running) {
585	        syslog(LOG_ERR, "[%s] send: channel not ready (init=%d run=%d)\n",
586	            TAG, s_state.initialized, s_state.running);
587	        return -EINVAL;
588	    }
589	
590	    /* Auto-show chat screen on first Agent reply */
591	    if (!s_state.screen_visible) {
592	        lvgl_ui_channel_show();
593	    }
594	
595	    /* Schedule bubble creation in LVGL thread via lv_async_call.
596	     * This avoids the "Invalidate area is not allowed during rendering"
597	     * assertion crash that occurs when we create LVGL widgets from
598	     * the agent dispatch thread while miwear's LVGL thread is
599	     * mid-render. */
600	    payload = malloc(sizeof(async_msg_t));
601	    if (!payload) {
602	        syslog(LOG_ERR, "[%s] send: async payload alloc failed\n", TAG);
603	        return -ENOMEM;
604	    }
605	
606	    strncpy(payload->text, text, LVGL_UI_MSG_MAX_LEN - 1);
607	    payload->text[LVGL_UI_MSG_MAX_LEN - 1] = '\0';
608	    payload->is_user = false;
609	
610	    lv_async_call(chat_view_add_message_async_cb, payload);
611	
612	    /* TTS is blocking — run it on a worker thread after scheduling the UI
613	     * update so the dispatch thread returns immediately. */
614	    char* tts_text = malloc(strlen(text) + 1);
615	    if (!tts_text) {
616	        syslog(LOG_ERR, "[%s] TTS text alloc failed\n", TAG);
617	        return 0;
618	    }
619	
620	    strcpy(tts_text, text);
621	
622	    pthread_t tid;
623	    pthread_attr_t attr;
624	    pthread_attr_init(&attr);
625	    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
626	    ret = pthread_create(&tid, &attr, tts_speak_thread, tts_text);
627	    pthread_attr_destroy(&attr);
628	
629	    if (ret != 0) {
630	        free(tts_text);
631	        syslog(LOG_ERR, "[%s] TTS thread spawn failed (rc=%d)\n", TAG, ret);
632	    }
633	
634	    return 0;
635	}
636	
637	/* ── Async callback for LVGL thread ────────────────────────── */
638	
639	/* Called by lv_timer_handler() inside the LVGL thread.
640	 * Safe to create/modify LVGL objects here. */
641	static void chat_view_add_message_async_cb(void* data)
642	{
643	    async_msg_t* payload = (async_msg_t*)data;
644	
645	    if (!payload) {
646	        return;
647	    }
648	
649	    if (!s_state.initialized || !s_state.running) {
650	        free(payload);
651	        return;
652	    }
653	
654	    chat_view_add_message(payload->text, payload->is_user);
655	    free(payload);
656	    payload = NULL;
657	}
