659	/* ── Internal functions ───────────────────────────────────── */
660	
661	static void chat_view_add_message(const char* text, bool is_user)
662	{
663	    chat_history_t* h = &s_state.history;
664	    chat_msg_t* slot;
665	    lv_obj_t* bubble;
666	    lv_obj_t* lbl;
667	
668	    /* If history is already full, trim before overwriting */
669	    if (h->count == CHAT_HISTORY_MAX) {
670	        chat_view_trim_history();
671	    }
672	
673	    /* Store message in ring buffer (handles truncation + old bubble deletion) */
674	    slot = chat_history_add(h, text, is_user);
675	
676	    /* Create bubble container inside chat_list */
677	    bubble = lv_obj_create(s_state.chat_list);
678	    if (!bubble) {
679	        syslog(LOG_ERR, "[%s] bubble create failed\n", TAG);
680	        return;
681	    }
682	
683	    lv_obj_set_width(bubble, lv_pct(85));
684	    lv_obj_set_height(bubble, LV_SIZE_CONTENT);
685	    lv_obj_set_style_radius(bubble, LVGL_UI_BUBBLE_RADIUS, 0);
686	    lv_obj_set_style_pad_all(bubble, LVGL_UI_BUBBLE_PAD, 0);
687	    lv_obj_set_style_border_width(bubble, 0, 0);
688	
689	    if (is_user) {
690	        /* User bubble: right-aligned, blue background, white text */
691	        lv_obj_set_style_align(bubble, LV_ALIGN_RIGHT_MID, 0);
692	        lv_obj_set_style_bg_color(bubble, lv_color_hex(0x3a7bd5), 0);
693	        lv_obj_set_style_text_color(bubble, lv_color_white(), 0);
694	    } else {
695	        /* Agent bubble: left-aligned, semi-transparent dark bg */
696	        lv_obj_set_style_align(bubble, LV_ALIGN_LEFT_MID, 0);
697	        lv_obj_set_style_bg_color(bubble, lv_color_hex(0x2a2a40), 0);
698	        lv_obj_set_style_bg_opa(bubble, LV_OPA_90, 0);
699	        lv_obj_set_style_text_color(bubble, lv_color_hex(0xe8e8e8), 0);
700	    }
701	
702	    /* Create label inside bubble */
703	    lbl = lv_label_create(bubble);
704	    if (!lbl) {
705	        syslog(LOG_ERR, "[%s] bubble label create failed\n", TAG);
706	        lv_obj_del(bubble);
707	        slot->bubble = NULL;
708	        return;
709	    }
710	
711	    lv_label_set_text(lbl, slot->text);
712	    lv_label_set_long_mode(lbl, LV_LABEL_LONG_WRAP);
713	    lv_obj_set_width(lbl, lv_pct(100));
714	
715	    slot->bubble = bubble;
716	
717	    chat_view_scroll_to_bottom();
718	}
