731	
732	static void ptt_btn_event_cb(lv_event_t* e)
733	{
734	    lv_event_code_t code = lv_event_get_code(e);
735	
736	    /* Single-click toggle: first click starts recording, second stops */
737	    if (code != LV_EVENT_CLICKED) {
738	        return;
739	    }
740	
741	    pthread_mutex_lock(&s_state.lock);
742	
743	    if (s_state.is_processing) {
744	        pthread_mutex_unlock(&s_state.lock);
745	        return;
746	    }
747	
748	    if (!s_state.is_recording) {
749	        /* First click: start recording */
750	        int ret = voice_channel_start();
751	        if (ret != 0) {
752	            syslog(LOG_ERR, "[%s] voice_channel_start failed (rc=%d)\n", TAG, ret);
753	            pthread_mutex_unlock(&s_state.lock);
754	            chat_view_add_message("录音启动失败", false);
755	            return;
756	        }
757	
758	        s_state.is_recording = true;
759	        pthread_mutex_unlock(&s_state.lock);
760	
761	        recording_indicator_start();
762	    } else {
763	        /* Second click: stop recording and process */
764	        s_state.is_recording = false;
765	        s_state.is_processing = true;
766	        pthread_mutex_unlock(&s_state.lock);
767	
768	        recording_indicator_show_processing();
769	
770	        /* Stop recording and get ASR text synchronously */
771	        char asr_text[LVGL_UI_MSG_MAX_LEN];
772	        int ret = voice_channel_stop_with_text(asr_text,
773	            sizeof(asr_text));
774	
