401	/* The MiMo/OpenAI edge intermittently serves a leaf certificate whose public
402	 * key (Ed25519/Ed448) this mbedtls build cannot parse in TLS 1.2 — the same
403	 * host served a parseable RSA cert moments earlier, so the failure is
404	 * non-deterministic. A fresh TCP connect + handshake usually lands on a
405	 * different edge / cert, so retry a few times before giving up. */
406	#define TLS_CONNECT_MAX_ATTEMPTS 3
407	
408	static int tls_ctx_connect_retry(tls_ctx_t* ctx, const char* host,
409	    const char* port)
410	{
411	    int ret = VELA_TLS_ERR_HANDSHAKE;
412	
413	    for (int attempt = 0; attempt < TLS_CONNECT_MAX_ATTEMPTS; attempt++) {
414	        ret = tls_ctx_connect(ctx, host, port);
415	
416	        if (ret == 0) {
417	            return 0;
418	        }
419	
420	        /* Only transient failures (TLS handshake / TCP connect) warrant a
421	         * retry; anything else (config/entropy) is fatal. */
422	        if (ret != VELA_TLS_ERR_HANDSHAKE && ret != VELA_TLS_ERR_CONNECT) {
423	            return ret;
424	        }
425	
426	        if (attempt + 1 == TLS_CONNECT_MAX_ATTEMPTS) {
427	            break; /* last attempt — leave ctx for the caller to free */
428	        }
429	
430	        syslog(LOG_WARNING,
431	            "[%s] connect %s:%s attempt %d/%d failed (%d), retrying\n",
432	            TAG, host, port, attempt + 1, TLS_CONNECT_MAX_ATTEMPTS, ret);
433	
434	        tls_ctx_free(ctx);
435	        usleep(200 * 1000);
436	    }
437	
438	    return ret;
439	}
