243	    if (getaddrinfo(bind_ip, port, &hints, &addr_list) != 0) {
244	        return MBEDTLS_ERR_NET_UNKNOWN_HOST;
245	    }
246	
247	    /* Try the sockaddrs until a binding succeeds */
248	    ret = MBEDTLS_ERR_NET_UNKNOWN_HOST;
249	    for (cur = addr_list; cur != NULL; cur = cur->ai_next) {
250	        ctx->fd = (int) socket(cur->ai_family, cur->ai_socktype,
251	                               cur->ai_protocol);
252	        if (ctx->fd < 0) {
253	            ret = MBEDTLS_ERR_NET_SOCKET_FAILED;
254	            continue;
