85	        if (!tmp)
86	            return ERROR;
87	        rb->data = tmp;
88	        rb->cap = new_cap;
89	    }
90	    memcpy(rb->data + rb->len, data, len);
91	    rb->len += len;
92	    rb->data[rb->len] = '\0';
93	    return OK;
94	}
