692	    char api_key[128];
693	    char llm_host[128];
694	
695	    pthread_mutex_lock(&s_llm_lock);
696	    memcpy(model, s_model, sizeof(model));
697	    memcpy(api_key, s_api_key, sizeof(api_key));
698	    memcpy(llm_host, s_llm_host, sizeof(llm_host));
699	    pthread_mutex_unlock(&s_llm_lock);
700	
701	    if (api_key[0] == '\0') {
702	        return ERROR;
703	    }
704	
705	    cJSON* body = cJSON_CreateObject();
706	
707	    cJSON_AddStringToObject(body, "model",
708	        model_name_for_api(model, llm_host));
709	
710	    if (is_openai_compat_host(llm_host)) {
711	        cJSON_AddNumberToObject(body, "max_completion_tokens",
712	            AGENT_LLM_MAX_TOKENS_OPENAI);
713	    } else {
714	        cJSON_AddNumberToObject(body, "max_tokens",
715	            AGENT_LLM_MAX_TOKENS);
716	    }
717	
718	    /* Clone messages and prepend system message */
719	    cJSON* msgs = cJSON_Duplicate(messages, 1);
720	    cJSON* sys_msg = cJSON_CreateObject();
721	
722	    cJSON_AddStringToObject(sys_msg, "role", "system");
723	    cJSON_AddStringToObject(sys_msg, "content", system_prompt);
724	    cJSON_InsertItemInArray(msgs, 0, sys_msg);
725	    cJSON_AddItemToObject(body, "messages", msgs);
726	
727	    /* Convert tools to OpenAI format */
728	    cJSON* tools_arr = build_openai_tools_array(tools_json);
729	
730	    if (tools_arr) {
731	        cJSON_AddItemToObject(body, "tools", tools_arr);
732	    }
733	
734	    char* post_data = cJSON_PrintUnformatted(body);
735	
736	    cJSON_Delete(body);
737	    if (!post_data) {
738	        return ERROR;
739	    }
740	
741	    syslog(LOG_INFO,
742	        "[%s] OpenAI API with tools (model: %s, %d bytes)\n",
743	        TAG, model, (int)strlen(post_data));
744	
745	    resp_buf_t rb = { 0 };
746	    int status = 0;
747	    int err = ERROR;
748	    int retry;
749	
750	    for (retry = 0; retry <= AGENT_LLM_MAX_RETRIES; retry++) {
751	        if (retry > 0) {
752	            unsigned int delay = AGENT_LLM_RETRY_BASE_SEC << (retry - 1);
753	            syslog(LOG_WARNING, "[%s] Rate limited (429), retry %d/%d after %us\n",
754	                TAG, retry, AGENT_LLM_MAX_RETRIES, delay);
755	            sleep(delay);
756	        }
757	
758	        rb.len = 0;
759	        status = 0;
760	        err = llm_http_call(post_data, &rb, &status);
761	
762	        if (err != OK) {
763	            resp_buf_free(&rb);
764	            free(post_data);
765	            return err;
766	        }
767	
768	        if (status != 429)
769	            break;
770	
771	        resp_buf_free(&rb);
772	        memset(&rb, 0, sizeof(rb));
773	    }
774	
775	    free(post_data);
776	
777	    if (status != 200) {
778	        syslog(LOG_ERR, "[%s] API error %d: %.500s\n", TAG, status,
779	            rb.data ? rb.data : "");
780	        resp_buf_free(&rb);
781	        return ERROR;
782	    }
783	
784	    cJSON* root = cJSON_Parse(rb.data);
785	
786	    resp_buf_free(&rb);
787	    if (!root) {
788	        syslog(LOG_ERR, "[%s] Failed to parse API JSON\n", TAG);
789	        return ERROR;
790	    }
791	
792	    /* Extract from OpenAI response */
793	    cJSON* choices = cJSON_GetObjectItem(root, "choices");
794	
795	    if (!choices || !cJSON_IsArray(choices) || !choices->child) {
796	        cJSON_Delete(root);
797	        return ERROR;
798	    }
799	
800	    cJSON* choice = choices->child;
801	    cJSON* finish = cJSON_GetObjectItem(choice, "finish_reason");
802	
803	    resp->tool_use = (finish && cJSON_IsString(finish)
804	        && strcmp(finish->valuestring, "tool_calls") == 0);
805	
806	    cJSON* message = cJSON_GetObjectItem(choice, "message");
807	
808	    if (message) {
809	        cJSON* text_content = cJSON_GetObjectItem(message, "content");
810	        if (text_content && cJSON_IsString(text_content) && text_content->valuestring) {
811	            size_t tlen = strlen(text_content->valuestring);
812	            resp->text = calloc(1, tlen + 1);
813	            if (resp->text) {
814	                memcpy(resp->text, text_content->valuestring, tlen);
815	                resp->text_len = tlen;
816	            }
817	        }
818	
819	        /* Kimi thinking mode: preserve reasoning_content so it can be echoed
820	         * back in the next turn (required by the API). */
821	        cJSON* rc = cJSON_GetObjectItem(message, "reasoning_content");
822	        if (rc && cJSON_IsString(rc) && rc->valuestring && rc->valuestring[0]) {
823	            resp->reasoning_content = strdup(rc->valuestring);
824	        }
825	
826	        /* Extract tool calls from OpenAI format */
827	        cJSON* tool_calls = cJSON_GetObjectItem(message, "tool_calls");
828	        if (tool_calls && cJSON_IsArray(tool_calls)) {
829	            cJSON* tc;
830	            cJSON_ArrayForEach(tc, tool_calls)
831	            {
832	                if (resp->call_count >= AGENT_MAX_TOOL_CALLS)
833	                    break;
834	
835	                llm_tool_call_t* call = &resp->calls[resp->call_count];
836	
837	                /* OpenAI tool_calls format:
838	                   { "id": "call_xyz", "type": "function",
839	                     "function": { "name": "foo", "arguments": "{...}" }
840	                   }
841	                */
842	                cJSON* id_item = cJSON_GetObjectItem(tc, "id");
843	                if (id_item && cJSON_IsString(id_item))
844	                    strncpy(call->id, id_item->valuestring, sizeof(call->id) - 1);
845	
846	                cJSON* func_obj = cJSON_GetObjectItem(tc, "function");
847	                if (func_obj) {
848	                    cJSON* name_item = cJSON_GetObjectItem(func_obj, "name");
849	                    cJSON* args_item = cJSON_GetObjectItem(func_obj, "arguments");
850	
851	                    if (name_item && cJSON_IsString(name_item))
852	                        strncpy(call->name, name_item->valuestring, sizeof(call->name) - 1);
853	
854	                    if (args_item && cJSON_IsString(args_item)) {
855	                        size_t alen = strlen(args_item->valuestring);
856	                        call->input = calloc(1, alen + 1);
857	                        if (call->input) {
858	                            memcpy(call->input, args_item->valuestring, alen);
859	                            call->input_len = alen;
860	                        }
861	                    } else if (args_item && cJSON_IsObject(args_item)) {
862	                        /* Some models return arguments as a JSON object
863	                         * instead of a JSON string — serialize it. */
864	                        char* serialized = cJSON_PrintUnformatted(args_item);
865	                        if (serialized) {
866	                            call->input = serialized;
867	                            call->input_len = strlen(serialized);
868	                        }
869	                    }
870	                }
871	
872	                resp->call_count++;
873	            }
874	
875	            /* If we found tool calls, ensure tool_use flag is set
876	             * (some models/proxies return stop_reason="end_turn" even with tools) */
877	            if (resp->call_count > 0) {
878	                resp->tool_use = true;
879	            }
880	        }
881	    }
882	
883	    /* Extract token usage from API response */
884	    cJSON* usage = cJSON_GetObjectItem(root, "usage");
885	    if (usage) {
886	        cJSON* pt = cJSON_GetObjectItem(usage, "prompt_tokens");
887	        cJSON* ct = cJSON_GetObjectItem(usage, "completion_tokens");
888	        cJSON* tt = cJSON_GetObjectItem(usage, "total_tokens");
889	        if (pt && cJSON_IsNumber(pt))
890	            resp->prompt_tokens = (int)pt->valuedouble;
891	        if (ct && cJSON_IsNumber(ct))
892	            resp->completion_tokens = (int)ct->valuedouble;
893	        if (tt && cJSON_IsNumber(tt))
894	            resp->total_tokens = (int)tt->valuedouble;
895	    }
896	
897	    /* XML fallback parsers for non-standard models */
898	    parse_xml_tool_calls(resp);
899	    parse_ns_xml_tool_calls(resp);
900	
901	    cJSON_Delete(root);
902	
903	    syslog(LOG_INFO,
904	        "[%s] Response: %d bytes text, %d tool calls, finish=%s\n",
905	        TAG, (int)resp->text_len, resp->call_count,
906	        resp->tool_use ? "tool_calls" : "end_turn");
907	
908	    return OK;
909	}
