934	    snprintf(cur_sig, sizeof(cur_sig), "%s|%.400s",
935	        resp->calls[0].name,
936	        resp->calls[0].input ? resp->calls[0].input : "");
937	
938	    if (strcmp(cur_sig, prev_sig) == 0) {
939	        (*dup_count)++;
940	        if (*dup_count >= 2) {
941	            syslog(LOG_WARNING,
942	                "[%s] Duplicate tool call detected (%s), breaking\n",
943	                TAG, resp->calls[0].name);
944	            return true;
945	        }
946	    } else {
947	        *dup_count = 0;
948	    }
949	    strncpy(prev_sig, cur_sig, 511);
950	    prev_sig[511] = '\0';
951	
952	    /* Name-only repeat detection */
953	    if (strcmp(resp->calls[0].name, prev_name) == 0) {
954	        (*name_repeat)++;
955	        if (*name_repeat >= AGENT_TOOL_NAME_REPEAT_MAX) {
956	            syslog(LOG_WARNING,
957	                "[%s] Tool name repeat limit (%s called %d times)\n",
958	                TAG, resp->calls[0].name, *name_repeat + 1);
959	            return true;
960	        }
961	    } else {
962	        *name_repeat = 0;
963	    }
964	    strncpy(prev_name, resp->calls[0].name, 63);
965	    prev_name[63] = '\0';
