86	    while (src < end) {
87	        /* Find end of chunk-size line */
88	        char* crlf = (char*)memmem(src, (size_t)(end - src), "\r\n", 2);
89	        if (!crlf)
90	            break;
91	
92	        /* Parse hex chunk size */
93	        char* endptr;
94	        long chunk_sz = strtol(src, &endptr, 16);
95	
96	        /* Validate: endptr should reach the CRLF (skip spaces) */
97	        while (endptr < crlf && *endptr == ' ')
98	            endptr++;
99	
100	        if (endptr != crlf || chunk_sz < 0 || chunk_sz > (long)(end - crlf - 2))
101	            break;  /* malformed or oversized chunk header */
102	
103	        if (chunk_sz == 0)
104	            break;  /* final chunk */
105	
106	        src = crlf + 2;  /* skip past chunk-size CRLF */
107	
108	        /* Clamp to available data */
109	        if (src + chunk_sz > end)
110	            chunk_sz = (long)(end - src);
111	
112	        memmove(dst, src, (size_t)chunk_sz);
113	        dst += chunk_sz;
114	        src += chunk_sz;
115	
116	        /* Skip trailing CRLF after chunk data */
117	        if (src + 2 <= end && src[0] == '\r' && src[1] == '\n')
118	            src += 2;
119	    }
120	
121	    return (size_t)(dst - buf);
122	}
