910	int vela_https_head_date(const char* host, const char* port, const char* path,
911	    char* date_out, size_t date_cap)
912	{
913	    tls_ctx_t ctx;
914	    int ret;
915	
916	    if ((ret = tls_ctx_connect(&ctx, host, port)) != 0) {
917	        tls_ctx_free(&ctx);
918	        return ret;
919	    }
920	
921	    if ((ret = tls_write_request(&ctx, "HEAD", host, path, NULL, NULL, 0)) != 0) {
922	        tls_ctx_free(&ctx);
923	        return ret;
924	    }
925	
926	    /* Read raw response until end of headers (\r\n\r\n) */
927	    char hdr_buf[2048];
928	    int total = 0;
929	    while (total < (int)sizeof(hdr_buf) - 1) {
930	        ret = mbedtls_ssl_read(&ctx.ssl,
931	            (unsigned char*)hdr_buf + total,
932	            sizeof(hdr_buf) - 1 - total);
933	        if (ret == MBEDTLS_ERR_SSL_WANT_READ)
934	            continue;
935	        if (ret <= 0)
936	            break;
937	        total += ret;
938	        hdr_buf[total] = '\0';
939	        if (strstr(hdr_buf, "\r\n\r\n"))
940	            break;
941	    }
942	    tls_ctx_free(&ctx);
943	
944	    if (total <= 0)
945	        return VELA_TLS_ERR_READ;
946	
947	    /* Find Date: header (case-insensitive prefix search) */
948	    char* p = strcasestr(hdr_buf, "\r\nDate: ");
949	    if (!p)
950	        return VELA_TLS_ERR_READ;
951	    p += 8; /* skip \r\nDate:  */
952	    char* eol = strstr(p, "\r\n");
953	    if (!eol)
954	        return VELA_TLS_ERR_READ;
955	
956	    size_t dlen = (size_t)(eol - p);
957	    if (dlen >= date_cap)
958	        dlen = date_cap - 1;
959	    memcpy(date_out, p, dlen);
960	    date_out[dlen] = '\0';
961	    return 0;
962	}
