913	typedef struct {
914	    llm_response_t* resp;
915	    llm_stream_cb_t on_stream;
916	    void* on_stream_ctx;
917	
918	    char line[8192];      /* partial current line across reads */
919	    size_t line_len;
920	    bool done;            /* received [DONE] */
921	
922	    char raw[65536];      /* raw body kept as non-streaming fallback */
923	    size_t raw_len;
