927	static void sse_append_text(sse_parser_t* sp, const char* delta)
928	{
929	    llm_response_t* resp = sp->resp;
930	    size_t dlen = strlen(delta);
931	
932	    if (dlen == 0)
933	        return;
934	
935	    size_t new_len = resp->text_len + dlen;
936	    char* nt = realloc(resp->text, new_len + 1);
937	    if (!nt)
938	        return;
939	
940	    memcpy(nt + resp->text_len, delta, dlen);
941	    nt[new_len] = '\0';
942	    resp->text = nt;
943	    resp->text_len = new_len;
944	
945	    if (sp->on_stream)
946	        sp->on_stream(nt, sp->on_stream_ctx);
947	}
