949	static void sse_append_tool_calls(sse_parser_t* sp, cJSON* tool_calls)
950	{
951	    llm_response_t* resp = sp->resp;
952	    cJSON* tc;
953	
954	    cJSON_ArrayForEach(tc, tool_calls)
955	    {
956	        cJSON* idx = cJSON_GetObjectItem(tc, "index");
957	        int i = (idx && cJSON_IsNumber(idx)) ? (int)idx->valuedouble : 0;
958	        if (i < 0 || i >= AGENT_MAX_TOOL_CALLS)
959	            continue;
960	
961	        llm_tool_call_t* call = &resp->calls[i];
962	        if (resp->call_count <= i)
963	            resp->call_count = i + 1;
964	
965	        cJSON* id_item = cJSON_GetObjectItem(tc, "id");
966	        if (id_item && cJSON_IsString(id_item) && id_item->valuestring)
967	            strncpy(call->id, id_item->valuestring, sizeof(call->id) - 1);
968	
969	        cJSON* fn = cJSON_GetObjectItem(tc, "function");
970	        if (!fn)
971	            continue;
972	
973	        cJSON* name = cJSON_GetObjectItem(fn, "name");
974	        if (name && cJSON_IsString(name) && name->valuestring)
975	            strncpy(call->name, name->valuestring, sizeof(call->name) - 1);
976	
977	        cJSON* args = cJSON_GetObjectItem(fn, "arguments");
978	        if (args && cJSON_IsString(args) && args->valuestring
979	            && args->valuestring[0]) {
980	            size_t alen = strlen(args->valuestring);
981	            char* ninput = realloc(call->input, call->input_len + alen + 1);
982	            if (ninput) {
983	                memcpy(ninput + call->input_len, args->valuestring, alen);
984	                call->input_len += alen;
985	                ninput[call->input_len] = '\0';
986	                call->input = ninput;
987	            }
988	        }
989	    }
990	
991	    if (resp->call_count > 0)
992	        resp->tool_use = true;
993	}
