995	static void sse_handle_json(sse_parser_t* sp, cJSON* j)
996	{
997	    cJSON* choices = cJSON_GetObjectItem(j, "choices");
998	    if (!choices || !cJSON_IsArray(choices) || !choices->child)
999	        return;
1000	
1001	    cJSON* delta = cJSON_GetObjectItem(choices->child, "delta");
1002	    if (!delta)
1003	        return;
1004	
1005	    cJSON* content = cJSON_GetObjectItem(delta, "content");
1006	    if (content && cJSON_IsString(content) && content->valuestring)
1007	        sse_append_text(sp, content->valuestring);
1008	
1009	    cJSON* tool_calls = cJSON_GetObjectItem(delta, "tool_calls");
1010	    if (tool_calls && cJSON_IsArray(tool_calls))
1011	        sse_append_tool_calls(sp, tool_calls);
