1014	static void sse_handle_line(sse_parser_t* sp)
1015	{
1016	    const char* line = sp->line;
1017	
1018	    while (*line == ' ' || *line == '\r' || *line == '\t')
1019	        line++;
1020	
1021	    if (strncmp(line, "data:", 5) != 0)
1022	        return; /* not a data line */
1023	
1024	    line += 5;
1025	    while (*line == ' ')
1026	        line++;
1027	
1028	    if (strcmp(line, "[DONE]") == 0) {
1029	        sp->done = true;
1030	        return;
1031	    }
1032	
1033	    if (*line == '\0')
1034	        return;
1035	
1036	    cJSON* j = cJSON_Parse(line);
1037	    if (!j)
1038	        return; /* partial/empty data — ignore */
1039	
1040	    sse_handle_json(sp, j);
1041	    cJSON_Delete(j);
1042	}
