1044	static void sse_feed(sse_parser_t* sp, const char* data, size_t len)
1045	{
1046	    for (size_t i = 0; i < len; i++) {
1047	        char c = data[i];
1048	        if (c == '\n') {
1049	            sp->line[sp->line_len] = '\0';
1050	            sse_handle_line(sp);
1051	            sp->line_len = 0;
1052	        } else if (sp->line_len < sizeof(sp->line) - 1) {
1053	            sp->line[sp->line_len++] = c;
1054	        }
1055	    }
1056	
1057	    /* Keep a bounded copy of the raw body for a non-streaming fallback. */
1058	    size_t room = sizeof(sp->raw) - 1 - sp->raw_len;
1059	    size_t n = len < room ? len : room;
1060	    if (n > 0) {
1061	        memcpy(sp->raw + sp->raw_len, data, n);
1062	        sp->raw_len += n;
1063	        sp->raw[sp->raw_len] = '\0';
1064	    } else {
1065	        sp->raw_overflow = true;
1066	    }
1067	}
1068	
1069	static int llm_http_stream_cb(const char* data, size_t len, void* ctx)
1070	{
1071	    sse_feed((sse_parser_t*)ctx, data, len);
1072	    return 0;
1073	}
