970	/* Check if an LLM call exceeded the watchdog timeout.
971	 * Returns true when latency_ms exceeds AGENT_LLM_TIMEOUT_SEC. */
972	static bool llm_call_timed_out(uint32_t latency_ms)
973	{
974	    return latency_ms > (uint32_t)AGENT_LLM_TIMEOUT_SEC * 1000;
975	}
