977	/* Handle TASK_COMPLETE: inject hint and do one final LLM call.
978	 * If the LLM call times out, *out_timed_out is set to true. */
979	static char* handle_task_complete(const char* sys_prompt, cJSON* messages,
980	    bool* out_timed_out)
981	{
982	    cJSON* hint = cJSON_CreateObject();
983	
984	    cJSON_AddStringToObject(hint, "role", "system");
985	    cJSON_AddStringToObject(hint, "content",
986	        "The task has been completed successfully. "
987	        "Do NOT call any more tools. "
988	        "Reply to the user now confirming what was done.");
989	    cJSON_AddItemToArray(messages, hint);
990	
991	    llm_response_t final_resp;
992	    char* result = NULL;
993	    struct timeval t0, t1;
994	    gettimeofday(&t0, NULL);
995	    int err = llm_chat_tools(sys_prompt, messages, NULL, &final_resp);
996	    gettimeofday(&t1, NULL);
997	    uint32_t ms = calc_elapsed_ms(&t0, &t1);
998	    bool timed_out = llm_call_timed_out(ms);
999	
1000	    if (err == OK && !timed_out
1001	        && final_resp.text && final_resp.text_len > 0) {
1002	        result = strdup(final_resp.text);
1003	    }
1004	    llm_response_free(&final_resp);
1005	
1006	    if (!result && timed_out) {
1007	        if (out_timed_out) {
1008	            *out_timed_out = true;
1009	        }
1010	        return strdup(LLM_TIMEOUT_TASK_COMPLETE_MSG);
1011	    }
1012	    return result;
1013	}
1014	
1015	/* Run the ReAct tool-calling loop. Returns final_text (caller owns). */
1016	static char* run_react_loop(const char* sys_prompt, cJSON* messages,
1017	    const char* tools_json, char* tool_output, size_t tool_size,
1018	    const agent_msg_t* msg)
1019	{
1020	    char prev_sig[512];
1021	    int dup_count;
1022	    char prev_name[64];
1023	    int name_repeat;
1024	    int iteration;
1025	    char* final_text = NULL;
1026	
1027	    prev_sig[0] = '\0';
1028	    dup_count = 0;
1029	    prev_name[0] = '\0';
1030	    name_repeat = 0;
1031	    int last_total_tokens = 0;
1032	    bool watchdog_fired = false;
1033	
1034	    /* Router: select and apply best backend before first LLM call.
1035	     * Estimate complexity from the last user message. */
1036	    llm_complexity_t complexity = LLM_COMPLEXITY_SIMPLE;
1037	    if (msg->content) {
1038	        complexity = llm_router_estimate_complexity(
1039	            msg->content, strlen(msg->content));
1040	    }
1041	    int router_idx = llm_router_select(complexity);
1042	    if (router_idx >= 0) {
1043	        llm_router_apply(router_idx);
1044	    }
1045	
1046	    /* Structured trace: begin */
1047	    agent_trace_t trace;
1048	    agent_trace_begin(&trace, msg->chat_id, msg->channel);
1049	    trace.backend_idx = router_idx;
1050	
1051	    /* Cache check: for simple queries, try cache before LLM call */
1052	    if (msg->content && complexity == LLM_COMPLEXITY_SIMPLE) {
1053	        char* cached = llm_cache_get(msg->content, strlen(msg->content));
1054	        if (cached) {
1055	            syslog(LOG_INFO, "[%s] Cache hit, skipping LLM call\n", TAG);
1056	            final_text = cached;
1057	            agent_trace_step(&trace, 0, NULL, 0, 1);
1058	            agent_trace_end(&trace, AGENT_TRACE_OK);
1059	            goto send_reply;
1060	        }
1061	    }
1062	
1063	    for (iteration = 0; iteration < AGENT_AI_AGENT_MAX_TOOL_ITER;
1064	         iteration++) {
1065	        send_working_status(msg, iteration);
1066	
1067	        llm_response_t resp;
1068	        struct timeval tv_start, tv_end;
1069	        gettimeofday(&tv_start, NULL);
1070	        int err = llm_chat_tools(sys_prompt, messages, tools_json, &resp);
1071	        gettimeofday(&tv_end, NULL);
1072	        uint32_t latency_ms = calc_elapsed_ms(&tv_start, &tv_end);
1073	
1074	        /* Router failover: on LLM call failure, try next backend */
1075	        if (err != OK && router_idx >= 0) {
1076	            syslog(LOG_WARNING,
1077	                "[%s] LLM call failed on backend %d, trying failover\n",
1078	                TAG, router_idx);
1079	            llm_router_report_failure(router_idx);
1080	
1081	            int next_idx = llm_router_select(complexity);
1082	            if (next_idx >= 0 && next_idx != router_idx) {
1083	                llm_router_apply(next_idx);
1084	                router_idx = next_idx;
1085	                trace.backend_idx = next_idx;
1086	                llm_response_free(&resp);
1087	                gettimeofday(&tv_start, NULL);
1088	                err = llm_chat_tools(sys_prompt, messages,
1089	                    tools_json, &resp);
1090	                gettimeofday(&tv_end, NULL);
1091	                latency_ms = calc_elapsed_ms(&tv_start, &tv_end);
1092	            }
1093	        }
1094	
1095	        if (err != OK) {
1096	            /* Distinguish timeout-induced failure from other errors */
1097	            if (llm_call_timed_out(latency_ms)) {
1098	                syslog(LOG_WARNING,
1099	                    "[%s] LLM watchdog: call failed after %" PRIu32 " ms "
1100	                    "(limit %ds)\n",
1101	                    TAG, latency_ms, AGENT_LLM_TIMEOUT_SEC);
1102	                agent_trace_step(&trace, iteration, NULL,
1103	                    latency_ms, 0);
1104	                llm_response_free(&resp);
1105	                final_text = strdup(LLM_TIMEOUT_MSG);
1106	                watchdog_fired = true;
1107	                break;
1108	            }
1109	            syslog(LOG_ERR, "[%s] LLM call failed (iter %d)\n",
1110	                TAG, iteration);
1111	            agent_trace_step(&trace, iteration, NULL, latency_ms, 0);
1112	            llm_response_free(&resp);
1113	            break;
1114	        }
1115	
1116	        /* The socket-level SO_RCVTIMEO (AGENT_LLM_SOCKET_TIMEOUT_SEC) is the
1117	         * real backstop that unblocks the read. If llm_chat_tools returned
1118	         * OK, the response is complete and usable regardless of how long it
1119	         * took, so keep the valid reply instead of discarding it as timeout. */
1120	
1121	        /* Report success to router */
1122	        if (router_idx >= 0) {
1123	            llm_router_report_success(router_idx);
1124	            llm_router_report_latency(router_idx, latency_ms);
1125	            if (resp.total_tokens > 0) {
1126	                llm_router_report_tokens(router_idx,
1127	                    resp.prompt_tokens, resp.completion_tokens);
1128	                last_total_tokens = resp.total_tokens;
1129	            }
1130	        }
1131	
1132	        syslog(LOG_INFO,
1133	            "[%s] LLM resp: text=%zu, tool_use=%d, calls=%d\n",
1134	            TAG, resp.text_len, resp.tool_use, resp.call_count);
1135	
1136	        if (!resp.tool_use) {
1137	            /* Cascade routing: if AUTO profile selected a cheap backend
1138	             * for a SIMPLE query but the response looks inadequate,
1139	             * retry once with PREMIUM tier. */
1140	            bool cascade_retry = false;
1141	            if (llm_router_get_profile() == LLM_ROUTE_AUTO
1142	                && complexity == LLM_COMPLEXITY_SIMPLE
1143	                && router_idx >= 0
1144	                && resp.text != NULL) {
1145	                bool low_quality = (strstr(resp.text, "I don't know") != NULL
1146	                    || strstr(resp.text, "I cannot") != NULL
1147	                    || strstr(resp.text, "无法") != NULL);
1148	                if (low_quality) {
1149	                    cascade_retry = true;
1150	                }
1151	            }
1152	
1153	            if (cascade_retry) {
1154	                syslog(LOG_INFO,
1155	                    "[%s] Cascade: cheap response inadequate, "
1156	                    "retrying with PREMIUM\n",
1157	                    TAG);
1158	
1159	                /* Save the cheap response as fallback before freeing */
1160	                char* fallback_text = NULL;
1161	                if (resp.text && resp.text_len > 0) {
1162	                    fallback_text = strdup(resp.text);
1163	                }
1164	                llm_response_free(&resp);
1165	
1166	                /* Select a PREMIUM backend without changing profile */
1167	                int prem_idx = llm_router_select_with_profile(
1168	                    LLM_COMPLEXITY_MEDIUM, LLM_ROUTE_PREMIUM);
1169	
1170	                if (prem_idx >= 0 && prem_idx != router_idx) {
1171	                    llm_router_apply(prem_idx);
1172	                    router_idx = prem_idx;
1173	                    trace.backend_idx = prem_idx;
1174	
1175	                    gettimeofday(&tv_start, NULL);
1176	                    err = llm_chat_tools(sys_prompt, messages,
1177	                        tools_json, &resp);
1178	                    gettimeofday(&tv_end, NULL);
1179	                    latency_ms = calc_elapsed_ms(&tv_start, &tv_end);
1180	
1181	                    /* Watchdog check on cascade retry — only if the call
1182	                     * actually failed; a slow-but-valid reply is kept. */
1183	                    if (err != OK && llm_call_timed_out(latency_ms)) {
1184	                        syslog(LOG_WARNING,
1185	                            "[%s] LLM watchdog: cascade retry "
1186	                            "took %" PRIu32 " ms\n",
1187	                            TAG, latency_ms);
1188	                        free(fallback_text);
1189	                        fallback_text = NULL;
1190	                        final_text = strdup(LLM_TIMEOUT_MSG);
1191	                        watchdog_fired = true;
1192	                        agent_trace_step(&trace, iteration, NULL,
1193	                            latency_ms, 0);
1194	                        llm_response_free(&resp);
1195	                        break;
1196	                    }
1197	
1198	                    if (err == OK && resp.text && resp.text_len > 0) {
1199	                        final_text = strdup(resp.text);
1200	                        free(fallback_text);
1201	                        fallback_text = NULL;
1202	                    } else {
1203	                        /* Premium failed — fall back to cheap response */
1204	                        final_text = fallback_text;
1205	                        fallback_text = NULL;
1206	                    }
1207	                    agent_trace_step(&trace, iteration, NULL,
1208	                        latency_ms, err == OK);
1209	                    llm_response_free(&resp);
1210	                    break;
1211	                }
1212	                /* No premium backend available — use cheap response */
1213	                final_text = fallback_text;
1214	                fallback_text = NULL;
1215	                agent_trace_step(&trace, iteration, NULL, latency_ms, 1);
1216	                break;
1217	            }
1218	
1219	            if (resp.text && resp.text_len > 0 && !final_text) {
1220	                final_text = strdup(resp.text);
1221	            }
1222	            agent_trace_step(&trace, iteration, NULL, latency_ms, 1);
1223	            llm_response_free(&resp);
1224	            break;
1225	        }
1226	
1227	        syslog(LOG_INFO, "[%s] Tool iter %d: %d calls\n",
1228	            TAG, iteration + 1, resp.call_count);
1229	
1230	        /* Trace: log tool step */
1231	        agent_trace_step(&trace, iteration,
1232	            resp.call_count > 0 ? resp.calls[0].name : NULL,
1233	            latency_ms, 1);
1234	
1235	        /* Duplicate detection — break if stuck in a loop */
1236	        bool should_break = check_tool_dup(
1237	            &resp, prev_sig, &dup_count, prev_name, &name_repeat);
1238	
1239	        if (should_break) {
1240	            add_assistant_message(messages, &resp);
1241	            add_tool_result_messages(messages, &resp, tool_output,
1242	                tool_size, msg->channel, msg->chat_id);
1243	            llm_response_free(&resp);
1244	            break;
1245	        }
1246	
1247	        add_assistant_message(messages, &resp);
1248	        add_tool_result_messages(messages, &resp, tool_output,
1249	            tool_size, msg->channel, msg->chat_id);
1250	
1251	        /* Local tool shortcut: if the single tool in this round is a
1252	         * local file op, skip the next LLM round and use the tool
1253	         * output directly as the reply. Saves ~2s.
1254	         * Restricted to call_count == 1: the parallel path does not
1255	         * write into tool_output, so multi-call rounds must go through
1256	         * the LLM to aggregate results (and tool_output would be stale
1257	         * from a prior iteration if we allowed call_count > 1 here). */
1258	        if (resp.call_count == 1) {
1259	            bool all_local = true;
1260	            for (int i = 0; i < resp.call_count; i++) {
1261	                if (strcmp(resp.calls[i].name, "read_file") != 0
1262	                    && strcmp(resp.calls[i].name, "write_file") != 0
1263	                    && strcmp(resp.calls[i].name, "edit_file") != 0
1264	                    && strcmp(resp.calls[i].name, "list_dir") != 0) {
1265	                    all_local = false;
1266	                    break;
1267	                }
1268	            }
1269	            if (all_local && tool_output[0]) {
1270	                /* Don't shortcut if the tool read a skill file
1271	                 * from AGENT_SKILLS_DIR — the LLM needs to process
1272	                 * the skill content and generate a proper user-facing
1273	                 * response instead of dumping raw markdown to the user. */
1274	                bool is_skill_read = false;
1275	                if (strcmp(resp.calls[0].name, "read_file") == 0
1276	                    && resp.calls[0].input != NULL) {
1277	                    cJSON *input_obj = cJSON_Parse(resp.calls[0].input);
1278	                    if (input_obj) {
1279	                        cJSON *path_obj = cJSON_GetObjectItem(input_obj, "path");
1280	                        if (path_obj && cJSON_IsString(path_obj)
1281	                            && strncmp(path_obj->valuestring,
1282	                                AGENT_SKILLS_DIR,
1283	                                strlen(AGENT_SKILLS_DIR)) == 0) {
1284	                            is_skill_read = true;
1285	                        }
1286	                        cJSON_Delete(input_obj);
1287	                    }
1288	                }
1289	
1290	                if (!is_skill_read) {
1291	                    syslog(LOG_INFO,
1292	                        "[%s] Local tool shortcut: skip LLM round\n",
1293	                        TAG);
1294	                    final_text = strdup(tool_output);
1295	                    llm_response_free(&resp);
1296	                    break;
1297	                }
1298	
1299	                syslog(LOG_INFO,
1300	                    "[%s] Skill file read — no shortcut, LLM will process\n",
1301	                    TAG);
1302	            }
1303	        }
1304	
1305	        /* TASK_COMPLETE detection */
1306	        if (resp.call_count == 1 && tool_output[0]
1307	            && strstr(tool_output, "TASK_COMPLETE")) {
1308	            syslog(LOG_INFO,
1309	                "[%s] Tool %s returned TASK_COMPLETE\n",
1310	                TAG, resp.calls[0].name);
1311	            llm_response_free(&resp);
1312	            bool task_timed_out = false;
1313	            final_text = handle_task_complete(sys_prompt, messages,
1314	                &task_timed_out);
1315	            if (task_timed_out) {
1316	                watchdog_fired = true;
1317	            }
1318	            break;
1319	        }
1320	
1321	        llm_response_free(&resp);
1322	    }
1323	
1324	    /* Iteration limit reached — force a summary reply */
1325	    if (!final_text && iteration >= AGENT_AI_AGENT_MAX_TOOL_ITER) {
1326	        final_text = force_finish_reply(sys_prompt, messages);
1327	        agent_trace_end(&trace, AGENT_TRACE_TIMEOUT);
1328	    } else if (watchdog_fired) {
1329	        agent_trace_end(&trace, AGENT_TRACE_TIMEOUT);
1330	    } else if (final_text) {
1331	        agent_trace_end(&trace, AGENT_TRACE_OK);
1332	    } else {
1333	        agent_trace_end(&trace, AGENT_TRACE_FAIL);
1334	    }
1335	
1336	send_reply:
1337	    /* Cache store: save simple query responses for future reuse.
1338	     * Never cache a timeout/error reply — otherwise one slow LLM call
1339	     * would poison the cache and every subsequent identical question
1340	     * would return "请求超时" instantly instead of retrying. */
1341	    if (!watchdog_fired && final_text && msg->content
1342	        && complexity == LLM_COMPLEXITY_SIMPLE) {
1343	        llm_cache_put(msg->content, strlen(msg->content), final_text);
1344	        if (last_total_tokens > 0) {
1345	            llm_cache_put_tokens(msg->content, strlen(msg->content),
1346	                last_total_tokens);
1347	        }
1348	    }
1349	
1350	    return final_text;
1351	}
