1353	/* ── Build messages array from session history + current msg ─ */
1354	
1355	static cJSON* build_messages(const char* chat_id, const char* content,
1356	    char* history_json, size_t hist_size)
1357	{
1358	    session_get_history_json(chat_id, history_json, hist_size,
1359	        AGENT_AI_AGENT_MAX_HISTORY);
1360	
1361	    cJSON* messages = cJSON_Parse(history_json);
1362	
1363	    if (!messages) {
1364	        messages = cJSON_CreateArray();
1365	    }
1366	
1367	    cJSON* user_msg = cJSON_CreateObject();
1368	
1369	    cJSON_AddStringToObject(user_msg, "role", "user");
1370	    cJSON_AddStringToObject(user_msg, "content", content);
1371	    cJSON_AddItemToArray(messages, user_msg);
1372	    return messages;
1373	}
