1397	/* ── Main agent loop task ─────────────────────────────────── */
1398	
1399	static void* agent_loop_task(void* arg)
1400	{
1401	    (void)arg;
1402	    agent_mem_status_t mem_st;
1403	
1404	    agent_mem_get_status(&mem_st);
1405	    syslog(LOG_INFO, "[%s] Agent loop started, free heap: %zu\n",
1406	        TAG, mem_st.free_heap);
1407	
1408	    size_t ctx_size = agent_mem_safe_size(
1409	        AGENT_CONTEXT_BUF_SIZE, 4 * 1024);
1410	    size_t hist_size = agent_mem_safe_size(
1411	        AGENT_LLM_STREAM_BUF_SIZE, 8 * 1024);
1412	    size_t tool_size = agent_mem_safe_size(
1413	        TOOL_OUTPUT_SIZE, TOOL_OUTPUT_SIZE_MIN);
1414	
1415	    char* sys_prompt = calloc(1, ctx_size);
1416	    char* history_json = calloc(1, hist_size);
1417	    char* tool_output = calloc(1, tool_size);
1418	
1419	    if (!sys_prompt || !history_json || !tool_output) {
1420	        syslog(LOG_ERR, "[%s] Failed to allocate agent buffers\n", TAG);
1421	        free(sys_prompt);
1422	        free(history_json);
1423	        free(tool_output);
1424	        return NULL;
1425	    }
1426	
1427	    syslog(LOG_INFO, "[%s] Buffers: ctx=%zu hist=%zu tool=%zu\n",
1428	        TAG, ctx_size, hist_size, tool_size);
1429	
1430	    /* Initialize memory pool for parallel tool outputs */
1431	    size_t pool_buf_size = agent_mem_safe_size(
1432	        TOOL_OUTPUT_SIZE_LARGE, TOOL_OUTPUT_SIZE_MIN);
1433	    if (agent_pool_init(&s_tool_pool, pool_buf_size,
1434	            AGENT_MAX_TOOL_CALLS)
1435	        == OK) {
1436	        s_pool_ready = true;
1437	        syslog(LOG_INFO, "[%s] Tool output pool: %d x %zu bytes\n",
1438	            TAG, AGENT_MAX_TOOL_CALLS, pool_buf_size);
1439	    } else {
1440	        syslog(LOG_WARNING,
1441	            "[%s] Pool init failed, using heap fallback\n", TAG);
1442	    }
1443	
1444	    char* tools_json = tool_registry_get_tools_json();
1445	
1446	    syslog(LOG_INFO, "[%s] Tools JSON loaded: %d bytes\n",
1447	        TAG, tools_json ? (int)strlen(tools_json) : 0);
1448	
1449	    while (!agent_shutdown_requested()) {
1450	        agent_msg_t msg;
1451	        int err = message_bus_pop_inbound(&msg, UINT32_MAX);
1452	
1453	        if (err != OK) {
1454	            continue;
1455	        }
1456	
1457	        if (agent_shutdown_requested()) {
1458	            free(msg.content);
1459	            free(msg.image_b64);
1460	            break;
1461	        }
1462	
1463	        syslog(LOG_INFO, "[%s] Processing message from %s:%s\n",
1464	            TAG, msg.channel, msg.chat_id);
1465	
1466	        /* Check memory pressure */
1467	        agent_mem_get_status(&mem_st);
1468	        if (mem_st.free_heap < AGENT_MEM_RESERVE_BYTES) {
1469	            syslog(LOG_WARNING,
1470	                "[%s] Low memory: %zu bytes free, skipping\n",
1471	                TAG, mem_st.free_heap);
1472	            agent_msg_t out = { 0 };
1473	            strncpy(out.channel, msg.channel,
1474	                sizeof(out.channel) - 1);
1475	            strncpy(out.chat_id, msg.chat_id,
1476	                sizeof(out.chat_id) - 1);
1477	            out.content = strdup("系统内存不足，请稍后再试。");
1478	            if (out.content) {
1479	                if (message_bus_push_outbound(&out) != OK) {
1480	                    free(out.content);
1481	                }
1482	            }
1483	            free(msg.content);
1484	            continue;
1485	        }
1486	
1487	        /* Slash commands — fast path, bypass LLM */
1488	        char* reply = handle_slash_command(&msg);
1489	
1490	        /* Prompt injection check — before LLM */
1491	        if (!reply && tool_guard_check_injection(msg.content)) {
1492	            syslog(LOG_WARNING,
1493	                "[%s] Prompt injection blocked from %s:%s\n",
1494	                TAG, msg.channel, msg.chat_id);
1495	            reply = strdup("I can't do that.");
1496	            if (!reply) {
1497	                /* Fail-closed: skip this message entirely */
1498	                free(msg.content);
1499	                continue;
1500	            }
1501	        }
1502	
1503	        /* NL fast path — after injection check, before LLM */
1504	        if (!reply) {
1505	            reply = handle_nl_fast_path(msg.content);
1506	        }
1507	
1508	        if (reply) {
1509	            agent_msg_t out = { 0 };
1510	            strncpy(out.channel, msg.channel,
1511	                sizeof(out.channel) - 1);
1512	            strncpy(out.chat_id, msg.chat_id,
1513	                sizeof(out.chat_id) - 1);
1514	            out.content = reply;
1515	            if (message_bus_push_outbound(&out) != OK) {
1516	                free(reply);
1517	            }
1518	            free(msg.content);
1519	            continue;
1520	        }
1521	
1522	        /* Hot-reload skills if directory changed */
1523	        if (skill_loader_check_changed()) {
1524	            syslog(LOG_INFO, "[%s] Skills changed, refreshing\n", TAG);
1525	            skill_loader_refresh();
1526	        }
1527	
1528	        context_build_system_prompt(sys_prompt, ctx_size);
1529	        inject_session_context(sys_prompt, ctx_size,
1530	            msg.channel, msg.chat_id);
1531	
1532	        /* Refresh tools JSON — Node tools are dynamic */
1533	        free(tools_json);
1534	        tools_json = tool_registry_get_tools_json();
1535	
1536	        cJSON* messages = build_messages(msg.chat_id, msg.content,
1537	            history_json, hist_size);
1538	
1539	        char* final_text = NULL;
1540	
1541	        /* Vision path */
1542	        final_text = handle_vision_message(&msg);
1543	        if (final_text) {
1544	            cJSON_Delete(messages);
