181	/****************************************************************************
182	 * LLM Callback (called from ai_agent thread, NOT LVGL thread)
183	 ****************************************************************************/
184	
185	static void llm_response_cb(int status, const char *response, void *cookie)
186	{
187	    g_msg_status = status;
188	    if (status == 0 && response != NULL)
189	      {
190	        strncpy(g_pending_msg, response, MSG_BUF_LEN - 1);
191	        g_pending_msg[MSG_BUF_LEN - 1] = '\0';
192	      }
193	    else
194	      {
195	        snprintf(g_pending_msg, MSG_BUF_LEN, "[LLM error: %d]", status);
196	      }
197	    g_msg_ready = true;
198	}
