200	/****************************************************************************
201	 * Send a message to LLM with current role's system prompt
202	 ****************************************************************************/
203	
204	static void send_to_llm(const char *user_text)
205	{
206	    if (!g_agent_connected || g_agent_client == NULL)
207	      {
208	        lv_label_set_text(g_chat_status, "Agent offline - start 'ai_agent &' first");
209	        return;
210	      }
211	
212	    /* Build full prompt: system prompt + user text */
213	    const role_def_t *role = &g_roles[g_current_role];
214	    char full_prompt[MSG_BUF_LEN];
215	    snprintf(full_prompt, MSG_BUF_LEN,
216	             "[SYSTEM]\n%s\n\n[USER]\n%s",
217	             role->system_prompt, user_text);
218	
219	    velaclaw_ask_req_t req = {
220	        .text       = full_prompt,
221	        .timeout_ms = 15000  /* 15 second timeout */
222	    };
223	
224	    lv_label_set_text(g_chat_status, "Thinking...");
225	    if (g_chat_spinner)
226	      {
227	        lv_obj_clear_flag(g_chat_spinner, LV_OBJ_FLAG_HIDDEN);
228	      }
229	
230	    int ret = velaclaw_ask(g_agent_client, &req, llm_response_cb, NULL);
231	    if (ret < 0)
232	      {
233	        lv_label_set_text(g_chat_status, "Failed to send message");
234	        if (g_chat_spinner)
235	          {
236	            lv_obj_add_flag(g_chat_spinner, LV_OBJ_FLAG_HIDDEN);
237	          }
238	      }
239	}
