251	/****************************************************************************
252	 * LVGL Timer: poll for LLM responses and update UI
253	 ****************************************************************************/
254	
255	/* Speak a response aloud in a background thread so the LVGL UI stays
256	 * responsive while TTS synthesizes and plays. */
257	static void *tts_speak_thread(void *arg)
258	{
259	    char *text = (char *)arg;
260	
261	    voice_channel_speak(text);
262	    free(text);
263	    return NULL;
264	}
265	
266	static void speak_async(const char *text)
267	{
268	    char *copy = strdup(text);
269	
270	    if (!copy)
271	      {
272	        return;
273	      }
274	
275	    pthread_attr_t attr;
276	
277	    pthread_attr_init(&attr);
278	    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
279	    pthread_attr_setstacksize(&attr, 65536);
280	
281	    pthread_t tid;
282	
283	    if (pthread_create(&tid, &attr, tts_speak_thread, copy) != 0)
284	      {
285	        free(copy);
286	      }
287	
288	    pthread_attr_destroy(&attr);
289	}
290	
291	static void poll_timer_cb(lv_timer_t *timer)
292	{
293	    static int heartbeat;
294	
295	    (void)timer;
296	
297	    /* Liveness probe — logs once every ~10s (200ms period × 50). If this
298	     * stops after a TTS speak finishes, the LVGL thread has hung (screen
299	     * frozen), as opposed to a touch-only stall. */
300	    if (++heartbeat % 50 == 0)
301	      {
302	        syslog(LOG_INFO, "[kid_buddy] LVGL heartbeat #%d\n", heartbeat);
303	      }
304	
305	    if (g_msg_ready)
306	      {
307	        g_msg_ready = false;
308	
309	        /* Hide spinner */
310	        if (g_chat_spinner)
311	          {
312	            lv_obj_add_flag(g_chat_spinner, LV_OBJ_FLAG_HIDDEN);
313	          }
314	
315	        if (g_msg_status == 0)
316	          {
317	            /* Show response in chat area */
318	            lv_label_set_text(g_chat_msg_area, g_pending_msg);
319	            lv_label_set_text(g_chat_status, "Tap 'Ask me!' to continue");
320	
321	            /* Read the reply aloud (async so the UI stays responsive). */
322	            speak_async(g_pending_msg);
323	          }
324	        else
325	          {
326	            lv_label_set_text(g_chat_msg_area, g_pending_msg);
327	            lv_label_set_text(g_chat_status, "Error - check LLM config");
328	          }
329	      }
330	}
