/* ── Streaming TTS worker ─────────────────────────────────────
 * Speak a response aloud in a background thread so the LVGL UI stays
 * responsive while TTS synthesizes and plays. A single worker thread
 * serializes every speak (voice_channel_speak aborts any in-progress speak
 * on a concurrent call), and it only ever speaks complete sentences so a
 * half-streamed sentence isn't cut into two utterances. */

/* Byte length of a sentence terminator at *p (0 if not one). Mirrors the
 * terminator set in voice_channel.c so boundaries match TTS chunking. */
static int sentence_end_len_at(const char *p)
{
    static const char *const TERM[] = {
        "。", "！", "？", "；", "…", "\n", "!", "?", ";", ".", "~", NULL
    };

    for (int i = 0; TERM[i] != NULL; i++)
      {
        size_t n = strlen(TERM[i]);

        if (strncmp(p, TERM[i], n) == 0)
          {
            return (int)n;
          }
      }
    return 0;
}

/* Byte offset just past the last complete-sentence terminator in text. */
static size_t last_sentence_end(const char *text, size_t len)
{
    size_t last = 0;

    for (size_t i = 0; i < len; )
      {
        int n = sentence_end_len_at(text + i);

        if (n > 0)
          {
            last = i + (size_t)n;
            i += (size_t)n;
          }
        else
          {
            i++;
          }
      }
    return last;
}

static void *tts_stream_worker(void *arg)
{
    (void)arg;

    for (;;)
      {
        char text[MSG_BUF_LEN];
        bool final = false;
        unsigned int epoch;
        size_t spoken;

        pthread_mutex_lock(&g_tts_lock);
        while (!g_tts_pending_ready)
          {
            pthread_cond_wait(&g_tts_cond, &g_tts_lock);
          }
        strncpy(text, g_tts_pending, MSG_BUF_LEN - 1);
        text[MSG_BUF_LEN - 1] = '\0';
        final = g_tts_pending_final;
        epoch = g_tts_epoch;
        spoken = g_spoken_len;
        g_tts_pending_ready = false;
        g_tts_pending_final = false;
        pthread_mutex_unlock(&g_tts_lock);

        size_t len = strlen(text);

        if (spoken > len)
          {
            spoken = len; /* offset reset under us mid-speak */
          }

        /* Partial fragment: speak only complete sentences. Final fragment:
         * flush the trailing (possibly incomplete) sentence too. */
        size_t speak_end = final ? len : last_sentence_end(text, len);

        if (speak_end > spoken)
          {
            size_t n = speak_end - spoken;
            char suffix[MSG_BUF_LEN];

            if (n >= MSG_BUF_LEN)
              {
                n = MSG_BUF_LEN - 1;
              }
            memcpy(suffix, text + spoken, n);
            suffix[n] = '\0';

            voice_channel_speak(suffix);

            pthread_mutex_lock(&g_tts_lock);
            /* Advance only if no newer question reset the offset mid-speak. */
            if (epoch == g_tts_epoch)
              {
                g_spoken_len = speak_end;
              }
            pthread_mutex_unlock(&g_tts_lock);
          }
      }

    return NULL;
}

/* Enqueue the latest cumulative reply text for speaking. "latest wins" — a
 * newer fragment replaces an older one still waiting in the slot. */
static void enqueue_tts(const char *text, bool final)
{
    pthread_mutex_lock(&g_tts_lock);
    strncpy(g_tts_pending, text, MSG_BUF_LEN - 1);
    g_tts_pending[MSG_BUF_LEN - 1] = '\0';
    g_tts_pending_final = final;
    g_tts_pending_ready = true;
    pthread_cond_signal(&g_tts_cond);
    pthread_mutex_unlock(&g_tts_lock);
}

