281	
282	/* ── Streaming TTS worker ─────────────────────────────────────
283	 * Speak a response aloud in a background thread so the LVGL UI stays
284	 * responsive while TTS synthesizes and plays. A single worker thread
285	 * serializes every speak (voice_channel_speak aborts any in-progress speak
286	 * on a concurrent call), and it only ever speaks complete sentences so a
287	 * half-streamed sentence isn't cut into two utterances. */
288	
289	/* Byte length of a sentence terminator at *p (0 if not one). Mirrors the
290	 * terminator set in voice_channel.c so boundaries match TTS chunking. */
291	static int sentence_end_len_at(const char *p)
292	{
293	    static const char *const TERM[] = {
294	        "。", "！", "？", "；", "…", "\n", "!", "?", ";", ".", "~", NULL
295	    };
296	
297	    for (int i = 0; TERM[i] != NULL; i++)
298	      {
299	        size_t n = strlen(TERM[i]);
300	
301	        if (strncmp(p, TERM[i], n) == 0)
302	          {
303	            return (int)n;
304	          }
305	      }
306	    return 0;
307	}
308	
309	/* Byte offset just past the last complete-sentence terminator in text. */
310	static size_t last_sentence_end(const char *text, size_t len)
311	{
312	    size_t last = 0;
313	
314	    for (size_t i = 0; i < len; )
315	      {
316	        int n = sentence_end_len_at(text + i);
317	
318	        if (n > 0)
319	          {
320	            last = i + (size_t)n;
321	            i += (size_t)n;
322	          }
323	        else
324	          {
325	            i++;
326	          }
327	      }
328	    return last;
329	}
330	
331	static void *tts_stream_worker(void *arg)
332	{
333	    (void)arg;
334	
335	    for (;;)
336	      {
337	        char text[MSG_BUF_LEN];
338	        bool final = false;
339	        unsigned int epoch;
340	        size_t spoken;
341	
342	        pthread_mutex_lock(&g_tts_lock);
343	        while (!g_tts_pending_ready)
344	          {
345	            pthread_cond_wait(&g_tts_cond, &g_tts_lock);
346	          }
347	        strncpy(text, g_tts_pending, MSG_BUF_LEN - 1);
348	        text[MSG_BUF_LEN - 1] = '\0';
349	        final = g_tts_pending_final;
350	        epoch = g_tts_epoch;
351	        spoken = g_spoken_len;
352	        g_tts_pending_ready = false;
353	        g_tts_pending_final = false;
354	        pthread_mutex_unlock(&g_tts_lock);
355	
356	        size_t len = strlen(text);
357	
358	        if (spoken > len)
359	          {
360	            spoken = len; /* offset reset under us mid-speak */
361	          }
362	
363	        /* Partial fragment: speak only complete sentences. Final fragment:
364	         * flush the trailing (possibly incomplete) sentence too. */
365	        size_t speak_end = final ? len : last_sentence_end(text, len);
366	
367	        if (speak_end > spoken)
368	          {
369	            size_t n = speak_end - spoken;
370	            char suffix[MSG_BUF_LEN];
371	
372	            if (n >= MSG_BUF_LEN)
373	              {
374	                n = MSG_BUF_LEN - 1;
375	              }
376	            memcpy(suffix, text + spoken, n);
377	            suffix[n] = '\0';
378	
379	            voice_channel_speak(suffix);
380	
381	            pthread_mutex_lock(&g_tts_lock);
382	            /* Advance only if no newer question reset the offset mid-speak. */
383	            if (epoch == g_tts_epoch)
384	              {
385	                g_spoken_len = speak_end;
386	              }
387	            pthread_mutex_unlock(&g_tts_lock);
388	          }
389	      }
390	
391	    return NULL;
392	}
