394	/* Enqueue the latest cumulative reply text for speaking. "latest wins" — a
395	 * newer fragment replaces an older one still waiting in the slot. */
396	static void enqueue_tts(const char *text, bool final)
397	{
398	    pthread_mutex_lock(&g_tts_lock);
399	    strncpy(g_tts_pending, text, MSG_BUF_LEN - 1);
400	    g_tts_pending[MSG_BUF_LEN - 1] = '\0';
401	    g_tts_pending_final = final;
402	    g_tts_pending_ready = true;
403	    pthread_cond_signal(&g_tts_cond);
404	    pthread_mutex_unlock(&g_tts_lock);
405	}
