951	{
952	    llm_response_t* resp = sp->resp;
953	    cJSON* tc;
954	
955	    cJSON_ArrayForEach(tc, tool_calls)
956	    {
957	        cJSON* idx = cJSON_GetObjectItem(tc, "index");
958	        int i = (idx && cJSON_IsNumber(idx)) ? (int)idx->valuedouble : 0;
959	        if (i < 0 || i >= AGENT_MAX_TOOL_CALLS)
960	            continue;
961	
962	        llm_tool_call_t* call = &resp->calls[i];
963	        if (resp->call_count <= i)
964	            resp->call_count = i + 1;
965	
966	        cJSON* id_item = cJSON_GetObjectItem(tc, "id");
967	        if (id_item && cJSON_IsString(id_item) && id_item->valuestring)
968	            strncpy(call->id, id_item->valuestring, sizeof(call->id) - 1);
969	
970	        cJSON* fn = cJSON_GetObjectItem(tc, "function");
971	        if (!fn)
972	            continue;
973	
974	        cJSON* name = cJSON_GetObjectItem(fn, "name");
975	        if (name && cJSON_IsString(name) && name->valuestring)
976	            strncpy(call->name, name->valuestring, sizeof(call->name) - 1);
977	
978	        cJSON* args = cJSON_GetObjectItem(fn, "arguments");
979	        if (args && cJSON_IsString(args) && args->valuestring
980	            && args->valuestring[0]) {
