1015	static void sse_handle_line(sse_parser_t* sp)
1016	{
1017	    const char* line = sp->line;
1018	
1019	    while (*line == ' ' || *line == '\r' || *line == '\t')
1020	        line++;
1021	
1022	    if (strncmp(line, "data:", 5) != 0)
1023	        return; /* not a data line */
1024	
1025	    sp->saw_data = true;
1026	
1027	    line += 5;
1028	    while (*line == ' ')
1029	        line++;
1030	
1031	    if (strcmp(line, "[DONE]") == 0) {
1032	        sp->done = true;
1033	        return;
1034	    }
1035	
1036	    if (*line == '\0')
1037	        return;
1038	
1039	    cJSON* j = cJSON_Parse(line);
1040	    if (!j)
1041	        return; /* partial/empty data — ignore */
1042	
1043	    sse_handle_json(sp, j);
1044	    cJSON_Delete(j);
1045	}
