1047	static void sse_feed(sse_parser_t* sp, const char* data, size_t len)
1048	{
1049	    for (size_t i = 0; i < len; i++) {
1050	        char c = data[i];
1051	        if (c == '\n') {
1052	            /* Strip a trailing '\r' from CRLF line endings so the "[DONE]"
1053	             * sentinel and JSON both match exactly. */
1054	            if (sp->line_len > 0 && sp->line[sp->line_len - 1] == '\r')
1055	                sp->line_len--;
1056	            sp->line[sp->line_len] = '\0';
1057	            sse_handle_line(sp);
1058	            sp->line_len = 0;
1059	        } else if (sp->line_len < sizeof(sp->line) - 1) {
1060	            sp->line[sp->line_len++] = c;
1061	        }
1062	    }
1063	
1064	    /* Keep a bounded copy of the raw body for a non-streaming fallback, but
1065	     * only until the first "data:" line proves streaming is live — after that
1066	     * the SSE path owns the text and the raw copy is just wasted work. */
1067	    if (!sp->saw_data) {
1068	        size_t room = sizeof(sp->raw) - 1 - sp->raw_len;
1069	        size_t n = len < room ? len : room;
1070	        if (n > 0) {
1071	            memcpy(sp->raw + sp->raw_len, data, n);
1072	            sp->raw_len += n;
1073	            sp->raw[sp->raw_len] = '\0';
1074	        } else {
1075	            sp->raw_overflow = true;
1076	        }
1077	    }
1078	}
