953	static void tts_strip_markdown(char* s)
954	{
955	    char* r = s; /* read pointer */
956	    char* w = s; /* write pointer */
957	
958	    while (*r) {
959	        /* Skip ** (bold markers) */
960	        if (r[0] == '*' && r[1] == '*') {
961	            r += 2;
962	            continue;
963	        }
964	
965	        /* Skip lone * (italic markers) \xe2\x80\x94 but keep * in
966	         * contexts like "3*4" (digit before and after) */
967	        if (r[0] == '*') {
968	            if ((r == s || !isdigit((unsigned char)r[-1]))
969	                || !isdigit((unsigned char)r[1])) {
970	                r++;
971	                continue;
972	            }
973	        }
974	
975	        /* Skip # at line start (headings) */
976	        if (r[0] == '#' && (r == s || r[-1] == '\n')) {
977	            while (*r == '#' || *r == ' ') {
978	                r++;
979	            }
980	            continue;
981	        }
982	
983	        /* Skip "- " at line start (list bullets) */
984	        if (r[0] == '-' && r[1] == ' '
985	            && (r == s || r[-1] == '\n')) {
986	            r += 2;
987	            continue;
988	        }
989	
990	        *w++ = *r++;
991	    }
992	
993	    *w = '\0';
994	}
