35	static void tap_callback(const agent_msg_t* msg, void* cookie)
36	{
37	    struct velaclaw_client_s* c = (struct velaclaw_client_s*)cookie;
38	    if (!c) {
39	        return;
40	    }
41	
42	    pthread_mutex_lock(&c->mtx);
43	
44	    if (c->async_cb) {
45	        /* Async mode: invoke user callback directly.
46	         * Streaming replies arrive as a series of partial fragments
47	         * (status 1) followed by one final fragment (status 0). Keep the
48	         * callback registered across partial fragments so the whole stream
49	         * reaches the caller; clear it only on the final fragment. */
50	        void (*cb)(int, const char*, void*) = c->async_cb;
51	        void* ck = c->async_cookie;
52	        int status = msg->partial ? 1 : 0;
53	        if (!msg->partial) {
54	            c->async_cb = NULL;
55	            c->async_cookie = NULL;
56	        }
57	        pthread_mutex_unlock(&c->mtx);
58	
59	        cb(status, msg->content, ck);
60	        return;
61	    }
62	
63	    /* Sync mode: store reply and signal */
64	    free(c->reply_text);
65	    c->reply_text = msg->content ? strdup(msg->content) : NULL;
66	    c->reply_status = 0;
67	    pthread_mutex_unlock(&c->mtx);
68	
69	    sem_post(&c->reply_sem);
70	}
