376	void audio_playback_close(audio_playback_t* pb)
377	{
378	    if (!pb) {
379	        return;
380	    }
381	
382	#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
383	    if (pb->backend == AUDIO_PLAYBACK_BACKEND_ALSA) {
384	        if (pb->handle.pcm) {
385	            if (!pb->stopped) {
386	                /* Block until all written samples have played out. */
387	                struct timespec d0, d1;
388	                clock_gettime(CLOCK_MONOTONIC, &d0);
389	                int drc = snd_vela_pcm_drain(pb->handle.pcm);
390	                clock_gettime(CLOCK_MONOTONIC, &d1);
391	                long dms = (d1.tv_sec - d0.tv_sec) * 1000
392	                    + (d1.tv_nsec - d0.tv_nsec) / 1000000;
393	                syslog(LOG_INFO,
394	                    "[%s] drain rc=%d took %ldms (written=%zu bytes)\n",
395	                    TAG, drc, dms, pb->total_written);
396	            }
397	            syslog(LOG_INFO, "[%s] closing ALSA (%zu bytes written)\n",
398	                TAG, pb->total_written);
399	            snd_vela_pcm_close(pb->handle.pcm);
400	        }
401	        s_active_pb = NULL;
402	        free(pb);
403	        return;
404	    }
405	#endif
406	
407	    if (pb->handle.player) {
408	        syslog(LOG_INFO, "[%s] closing (%zu bytes written)\n",
409	            TAG, pb->total_written);
410	        media_player_stop(pb->handle.player);
411	        usleep(50 * 1000);
412	        media_player_close(pb->handle.player, 0);
413	    }
414	
415	    s_active_pb = NULL;
416	    free(pb);
417	}
