```c
/* ── TTS prefetch pipeline ──────────────────────────────────── */

/* One prefetched sentence: its text (owned) and the decoded PCM captured
 * by the streaming backend. The pipeline fetches sentence N+1 in a worker
 * thread while sentence N is being played, so the slow TTS network fetch
 * overlaps real-time playback instead of leaving silence between sentences. */
typedef struct {
    char* text;
    unsigned char* pcm;
    size_t pcm_len;
    size_t pcm_cap;
    int rc;
    int done;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} tts_prefetch_t;

/* Capture callback: accumulate streamed PCM into pf->pcm instead of writing
 * straight to the playback device. */
static int tts_prefetch_capture_cb(const unsigned char* pcm, size_t len,
    int is_last, void* user_data)
{
    tts_prefetch_t* pf = user_data;
    (void)is_last;

    if (s_voice.tts_abort) {
        return -1;   /* abort the stream early */
    }

    if (pcm && len > 0) {
        if (!s_tts_first_chunk) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            long ms = (now.tv_sec - s_tts_start.tv_sec) * 1000
                + (now.tv_nsec - s_tts_start.tv_nsec) / 1000000;
            syslog(LOG_INFO, "[%s] TTS first chunk: %ldms\n", TAG, ms);
            s_tts_first_chunk = 1;
        }

        if (pf->pcm_len + len > pf->pcm_cap) {
            size_t ncap = pf->pcm_cap ? pf->pcm_cap : 0;
            while (ncap < pf->pcm_len + len) {
                ncap = ncap ? ncap * 2 : (64 * 1024);
            }
            unsigned char* nd = realloc(pf->pcm, ncap);
            if (!nd) {
                pf->rc = -ENOMEM;
                return -1;
            }
            pf->pcm = nd;
            pf->pcm_cap = ncap;
        }
        memcpy(pf->pcm + pf->pcm_len, pcm, len);
        pf->pcm_len += len;
    }

    return 0;
}

static void* tts_prefetch_thread(void* arg)
{
    tts_prefetch_t* pf = arg;
    pf->rc = voice_tts_speak_stream(pf->text, tts_prefetch_capture_cb, pf);
    pthread_mutex_lock(&pf->lock);
    pf->done = 1;
    pthread_cond_broadcast(&pf->cond);
    pthread_mutex_unlock(&pf->lock);
    return NULL;
}

static void tts_prefetch_init(tts_prefetch_t* pf)
{
    memset(pf, 0, sizeof(*pf));
    pthread_mutex_init(&pf->lock, NULL);
    pthread_cond_init(&pf->cond, NULL);
}

static void tts_prefetch_deinit(tts_prefetch_t* pf)
{
    free(pf->text);
    free(pf->pcm);
    pthread_mutex_destroy(&pf->lock);
    pthread_cond_destroy(&pf->cond);
}

/* Copy a [s, s+len) slice into a NUL-terminated string with leading
 * whitespace stripped; returns NULL if nothing but whitespace remains. */
static char* tts_slice_dup(const char* s, int len)
{
    char* d = malloc(len + 1);
    if (!d) {
        return NULL;
    }
    memcpy(d, s, len);
    d[len] = '\0';

    char* c = d;
    while (*c == ' ' || *c == '\n' || *c == '\t' || *c == '\r') {
        c++;
    }
    if (*c == '\0') {
        free(d);
        return NULL;
    }
    if (c != d) {
        memmove(d, c, strlen(c) + 1);
    }
    return d;
}

/* Synthesize text one sentence at a time, but prefetch the NEXT sentence's
 * audio in a worker thread while the current one plays back. A long story
 * produces many sentences; keeping each TTS response small avoids a single
 * utterance's base64 audio overflowing MIMO_TTS_RESP_SIZE, and the prefetch
 * removes the per-sentence fetch gap (previously a ~5-12s silence before
 * every sentence — the reason a story appeared to stop after one sentence). */
static int tts_speak_chunked(const char* text, audio_playback_t* pb)
{
    /* First pass: collect sentence slices. */
    #define MAX_SLICES 128
    const char* slice_start[MAX_SLICES];
    int slice_len[MAX_SLICES];
    int nslices = 0;

    const char* start = text;
    while (*start && nslices < MAX_SLICES) {
        /* Bail early if the network dropped so we don't grind through the
         * remaining sentences with doomed handshakes and retries. */
        if (!network_is_connected()) {
            syslog(LOG_WARNING, "[%s] network down, stopping TTS\n", TAG);
            break;
        }

        const char* p = start;
        int tlen = 0;
        while (*p) {
            tlen = tts_sentence_end_len(p);
            if (tlen > 0) {
                break;
