        const char* end;
        if (*p) {
            end = p + tlen;
            /* Absorb immediately-following terminators (e.g. "!!!") so they
             * don't become empty one-punctuation sentences. */
            while (*end) {
                int n = tts_sentence_end_len(end);
                if (n > 0) {
                    end += n;
                } else {
                    break;
                }
            }
        } else {
            end = p; /* end of string */
        }

        if (end > start) {
            slice_start[nslices] = start;
            slice_len[nslices] = (int)(end - start);
            nslices++;
        }

        if (*end == '\0') {
            break;
        }
        start = end;
    }
    #undef MAX_SLICES

    if (nslices == 0) {
        return -EPROTO;
    }

    tts_prefetch_t pf[2];
    tts_prefetch_init(&pf[0]);
    tts_prefetch_init(&pf[1]);

    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setstacksize(&attr, 65536);

    int first_err = 0;
    int any_ok = 0;

    for (int i = 0; i < nslices; i++) {
        tts_prefetch_t* cur = &pf[i % 2];
        tts_prefetch_t* nxt = &pf[(i + 1) % 2];
        pthread_t tid = 0;
        int launched = 0;

        /* Kick off the next sentence's fetch in the background so it runs
         * while this sentence plays. */
        if (i + 1 < nslices && !s_voice.tts_abort) {
            nxt->text = tts_slice_dup(slice_start[i + 1], slice_len[i + 1]);
            if (nxt->text) {
                nxt->rc = 0;
                nxt->pcm_len = 0;
                nxt->pcm_cap = 0;
                if (pthread_create(&tid, &attr, tts_prefetch_thread, nxt) == 0) {
                    launched = 1;
                } else {
                    free(nxt->text);
                    nxt->text = NULL;
                    nxt->rc = -ENOMEM;
                }
            } else {
