            }
        }

        /* The first sentence has not been prefetched yet — fetch it inline
         * (its network latency is the unavoidable first-latency; the next
         * sentence's fetch above already overlaps it). */
        if (i == 0) {
            cur->text = tts_slice_dup(slice_start[0], slice_len[0]);
            cur->rc = cur->text ? 0 : -ENOMEM;
            cur->pcm_len = 0;
            cur->pcm_cap = 0;
            if (cur->text) {
                tts_prefetch_thread(cur);  /* run inline */
            }
        }

        /* Play the current sentence (blocks in real time). */
        if (cur->rc == 0 && cur->pcm_len > 0) {
            audio_playback_write(pb, cur->pcm, cur->pcm_len);
            any_ok = 1;
        } else if (cur->rc != 0 && first_err == 0) {
            first_err = cur->rc;
        }

        /* Release the current sentence's buffers. */
        free(cur->text);
        cur->text = NULL;
        free(cur->pcm);
        cur->pcm = NULL;
        cur->pcm_len = 0;
        cur->pcm_cap = 0;

        /* Wait for the next sentence's background fetch to finish. */
        if (launched) {
            pthread_join(tid, NULL);
        }

        if (s_voice.tts_abort) {
            break;
        }
    }

    pthread_attr_destroy(&attr);
    tts_prefetch_deinit(&pf[0]);
    tts_prefetch_deinit(&pf[1]);

    return any_ok ? 0 : (first_err ? first_err : -EPROTO);
}
