/* ── TTS prefetch pipeline ───────────────────────────────────── */

/* One prefetched sentence: its text (owned) and the decoded PCM captured
 * by the streaming backend. The pipeline fetches sentence N+1 in a worker
 * thread while sentence N plays, so the slow TTS network fetch overlaps
 * real-time playback instead of leaving a long silence between sentences. */
typedef struct {
    char* text;
    unsigned char* pcm;
    size_t pcm_len;
    size_t pcm_cap;
    int rc;   /* final result: backend result, or -ENOMEM on capture failure */
} tts_prefetch_t;

/* Capture callback: accumulate streamed PCM into pf->pcm instead of writing
 * straight to the playback device. (voice_tts_chunk_cb returns void, so we
 * can't abort the stream from here — just stop capturing on abort/failure.) */
static void tts_prefetch_capture_cb(const unsigned char* pcm, size_t len,
    int is_last, void* user_data)
{
    tts_prefetch_t* pf = user_data;
    (void)is_last;

    if (s_voice.tts_abort || pf->rc != 0) {
        return;
    }

    if (pcm && len > 0) {
        if (!s_tts_first_chunk) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            long ms = (now.tv_sec - s_tts_start.tv_sec) * 1000
                + (now.tv_nsec - s_tts_start.tv_nsec) / 1000000;
            syslog(LOG_INFO, "[%s] TTS first chunk: %ldms\n", TAG, ms);
            s_tts_first_chunk = 1;
        }

        if (pf->pcm_len + len > pf->pcm_cap) {
            size_t ncap = pf->pcm_cap ? pf->pcm_cap : 0;
            while (ncap < pf->pcm_len + len) {
                ncap = ncap ? ncap * 2 : (64 * 1024);
            }
            unsigned char* nd = realloc(pf->pcm, ncap);
            if (!nd) {
                pf->rc = -ENOMEM;
                return;
            }
            pf->pcm = nd;
            pf->pcm_cap = ncap;
        }
        memcpy(pf->pcm + pf->pcm_len, pcm, len);
        pf->pcm_len += len;
    }
}

static void* tts_prefetch_thread(void* arg)
{
    tts_prefetch_t* pf = arg;
    int backend_rc = voice_tts_speak_stream(pf->text,
        tts_prefetch_capture_cb, pf);
    /* Keep a capture failure (e.g. -ENOMEM) over a clean backend result. */
    if (pf->rc == 0) {
        pf->rc = backend_rc;
    }
    return NULL;
}

static void tts_prefetch_init(tts_prefetch_t* pf)
{
    memset(pf, 0, sizeof(*pf));
}

static void tts_prefetch_deinit(tts_prefetch_t* pf)
{
    free(pf->text);
    free(pf->pcm);
}

/* Copy a [s, s+len) slice into a NUL-terminated string with leading
 * whitespace stripped; returns NULL if nothing but whitespace remains. */
static char* tts_slice_dup(const char* s, int len)
{
    char* d = malloc(len + 1);
    if (!d) {
        return NULL;
    }
    memcpy(d, s, len);
    d[len] = '\0';

    char* c = d;
    while (*c == ' ' || *c == '\n' || *c == '\t' || *c == '\r') {
        c++;
    }
    if (*c == '\0') {
        free(d);
        return NULL;
    }
    if (c != d) {
        memmove(d, c, strlen(c) + 1);
    }
    return d;
}

/* Synthesize text one sentence at a time, but prefetch the NEXT sentence's
 * audio in a worker thread while the current one plays. A long story
 * produces many sentences; keeping each TTS response small avoids a single
 * utterance's base64 audio overflowing MIMO_TTS_RESP_SIZE. The prefetch is
 * what closes the gap: before, every sentence paid its full network fetch
 * (~5-12s) before any of it was audible, so a story sounded like it stopped
 * after the first sentence. */
static int tts_speak_chunked(const char* text, audio_playback_t* pb)
{
    /* First pass: split into sentence slices. */
    #define MAX_SLICES 128
    const char* slice_start[MAX_SLICES];
    int slice_len[MAX_SLICES];
    int nslices = 0;

    const char* start = text;
    while (*start && nslices < MAX_SLICES) {
        /* Bail early if the network dropped (e.g. WiFi disconnect) so we
         * don't grind through the remaining sentences with doomed
         * handshakes and retries. */
        if (!network_is_connected()) {
            syslog(LOG_WARNING, "[%s] network down, stopping TTS\n", TAG);
            break;
        }

        const char* p = start;
        int tlen = 0;
        while (*p) {
            tlen = tts_sentence_end_len(p);
            if (tlen > 0) {
                break;
            }
            p++;
        }

        const char* end;
        if (*p) {
            end = p + tlen;

            /* Absorb immediately-following terminators (e.g. "!!!") so
             * they don't become empty one-punctuation sentences. */
            while (*end) {
                int n = tts_sentence_end_len(end);
                if (n > 0) {
                    end += n;
                } else {
                    break;
                }
            }
        } else {
            end = p; /* end of string */
        }

        if (end > start) {
            slice_start[nslices] = start;
            slice_len[nslices] = (int)(end - start);
            nslices++;
        }

        if (*end == '\0') {
            break;
        }
        start = end;
    }
    #undef MAX_SLICES

    if (nslices == 0) {
        return -EPROTO;
    }

    tts_prefetch_t pf[2];
    tts_prefetch_init(&pf[0]);
    tts_prefetch_init(&pf[1]);

    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setstacksize(&attr, 65536);

    int first_err = 0;
    int any_ok = 0;

    for (int i = 0; i < nslices; i++) {
        tts_prefetch_t* cur = &pf[i % 2];
        tts_prefetch_t* nxt = &pf[(i + 1) % 2];
        pthread_t tid = 0;
        int launched = 0;

        /* Kick off the next sentence's fetch in the background so it overlaps
         * this sentence's playback. */
        if (i + 1 < nslices && !s_voice.tts_abort) {
            nxt->text = tts_slice_dup(slice_start[i + 1], slice_len[i + 1]);
            nxt->rc = nxt->text ? 0 : -ENOMEM;
            nxt->pcm = NULL;
            nxt->pcm_len = 0;
            nxt->pcm_cap = 0;
            if (nxt->text
                && pthread_create(&tid, &attr, tts_prefetch_thread, nxt) == 0) {
                launched = 1;
            } else {
                free(nxt->text);
                nxt->text = NULL;
                nxt->rc = -ENOMEM;
            }
        }

        /* The first sentence hasn't been prefetched yet — fetch it inline
         * (this network latency is the unavoidable first-latency; the next
         * sentence's fetch above already overlaps it). */
        if (i == 0) {
            cur->text = tts_slice_dup(slice_start[0], slice_len[0]);
            cur->rc = cur->text ? 0 : -ENOMEM;
            cur->pcm = NULL;
            cur->pcm_len = 0;
            cur->pcm_cap = 0;
            if (cur->text) {
                tts_prefetch_thread(cur); /* run inline */
            }
        }

        /* Play the current sentence (blocks in real time). */
        if (cur->rc == 0 && cur->pcm_len > 0) {
            audio_playback_write(pb, cur->pcm, cur->pcm_len);
            any_ok = 1;
        } else if (cur->rc != 0 && first_err == 0) {
            first_err = cur->rc;
        }

        /* Release the current sentence's buffers. */
        free(cur->text);
        cur->text = NULL;
        free(cur->pcm);
        cur->pcm = NULL;
        cur->pcm_len = 0;
        cur->pcm_cap = 0;

        /* Wait for the next sentence's background fetch to finish. */
        if (launched) {
            pthread_join(tid, NULL);
        }

        if (s_voice.tts_abort) {
            break;
        }
    }

    pthread_attr_destroy(&attr);
    tts_prefetch_deinit(&pf[0]);
    tts_prefetch_deinit(&pf[1]);

    return any_ok ? 0 : (first_err ? first_err : -EPROTO);
}

