52	static int simple_entropy_func(void* data, unsigned char* output, size_t len)
53	{
54	    (void)data;
55	    if (agent_secure_random(output, len) == 0) {
56	        return 0;
57	    }
58	    /* No fallback — cryptographic entropy is mandatory for TLS.
59	     * Returning an error forces the TLS handshake to fail safely
60	     * rather than proceeding with predictable key material. */
61	    syslog(LOG_ERR, "[vela_tls] CRITICAL: No secure entropy source available\n");
62	    return -1;  /* Generic error - TLS handshake will fail safely */
63	}
