133	static void tls_ctx_free(tls_ctx_t* ctx)
134	{
135	    mbedtls_ssl_close_notify(&ctx->ssl);
136	    mbedtls_net_free(&ctx->net);
137	    mbedtls_ssl_free(&ctx->ssl);
138	    mbedtls_ssl_config_free(&ctx->cfg);
139	    mbedtls_ctr_drbg_free(&ctx->ctr_drbg);
140	
141	#ifdef CONFIG_AI_AGENT_NET_RPMSG
142	    network_release_resource();
143	#endif
144	}
