146	/* ── Persistent connection pool (keep-alive) ─────────────────── */
147	/* Keeps one live TLS connection per host:port so repeated calls to
148	 * the same endpoint (Feishu REST, LLM API) skip the TLS handshake. */
149	
150	#ifdef CONFIG_AI_AGENT_TLS_CONN_POOL_SIZE
151	#define CONN_POOL_SIZE CONFIG_AI_AGENT_TLS_CONN_POOL_SIZE
152	#else
153	#define CONN_POOL_SIZE 2
154	#endif
155	
156	typedef struct {
157	    tls_ctx_t ctx;
158	    char host[128];
159	    char port[8];
160	    bool in_use; /* locked by a request */
161	    bool valid; /* connection is alive */
162	} conn_slot_t;
163	
164	static conn_slot_t s_pool[CONN_POOL_SIZE];
165	static pthread_mutex_t s_pool_lock = PTHREAD_MUTEX_INITIALIZER;
166	
167	/* Acquire a slot for host:port.  Returns a locked, connected ctx or NULL. */
168	static conn_slot_t* pool_acquire(const char* host, const char* port)
169	{
170	    pthread_mutex_lock(&s_pool_lock);
171	
172	    /* 1. Find an existing valid slot for this host:port */
173	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
174	        conn_slot_t* s = &s_pool[i];
175	        if (s->valid && !s->in_use && strcmp(s->host, host) == 0 && strcmp(s->port, port) == 0) {
176	            s->in_use = true;
177	            pthread_mutex_unlock(&s_pool_lock);
178	            return s;
179	        }
180	    }
181	
182	    /* 2. Find an empty slot */
183	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
184	        if (!s_pool[i].valid && !s_pool[i].in_use) {
185	            s_pool[i].in_use = true;
186	            pthread_mutex_unlock(&s_pool_lock);
187	            return &s_pool[i];
188	        }
189	    }
190	
191	    /* 3. Evict the first non-in-use slot */
192	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
193	        if (!s_pool[i].in_use) {
194	            tls_ctx_free(&s_pool[i].ctx);
195	            s_pool[i].valid = false;
196	            s_pool[i].in_use = true;
197	            pthread_mutex_unlock(&s_pool_lock);
198	            return &s_pool[i];
199	        }
200	    }
201	
202	    pthread_mutex_unlock(&s_pool_lock);
203	    return NULL; /* all slots busy — caller falls back to ephemeral */
204	}
205	
206	/* Return a slot to the pool.  keep=true means the connection is still alive. */
207	static void pool_release(conn_slot_t* s, const char* host, const char* port, bool keep)
208	{
209	    pthread_mutex_lock(&s_pool_lock);
210	    if (keep) {
211	        strncpy(s->host, host, sizeof(s->host) - 1);
212	        strncpy(s->port, port, sizeof(s->port) - 1);
213	        s->valid = true;
214	    } else {
215	        tls_ctx_free(&s->ctx);
216	        s->valid = false;
217	        s->host[0] = '\0';
218	    }
219	    s->in_use = false;
220	    pthread_mutex_unlock(&s_pool_lock);
221	}
222	
223	void vela_tls_pool_cleanup(void)
224	{
225	    pthread_mutex_lock(&s_pool_lock);
226	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
227	        if (s_pool[i].in_use) {
228	            syslog(LOG_WARNING,
229	                "[vela_tls] Pool slot %d still in use at shutdown, skipping\n", i);
230	            continue;
231	        }
232	        if (s_pool[i].valid) {
233	            tls_ctx_free(&s_pool[i].ctx);
234	            s_pool[i].valid = false;
235	        }
236	        s_pool[i].host[0] = '\0';
237	    }
238	    pthread_mutex_unlock(&s_pool_lock);
239	}
