614	/**
615	 * Read full HTTP/1.1 response.
616	 * Returns HTTP status code; writes body into resp_buf (NUL-terminated).
617	 * Handles Transfer-Encoding: chunked and Content-Length.
618	 */
619	#define TLS_RAW_BUF_SIZE 8192  /* 8KB: enough for HTTP headers + initial body */
620	
621	/* Number of static raw buffers — at most 2, scaled to pool size.
622	 * Each buffer is 8KB; pool=1 uses 1 buffer, pool>=2 uses 2. */
623	#define TLS_RAW_BUF_COUNT (CONN_POOL_SIZE < 2 ? 1 : 2)
624	
625	static char s_tls_raw_buf[TLS_RAW_BUF_COUNT][TLS_RAW_BUF_SIZE];
626	static pthread_mutex_t s_tls_raw_lock[TLS_RAW_BUF_COUNT];
627	static pthread_once_t s_tls_raw_once = PTHREAD_ONCE_INIT;
628	
629	static void tls_raw_init_once(void)
630	{
631	    for (int i = 0; i < TLS_RAW_BUF_COUNT; i++) {
632	        pthread_mutex_init(&s_tls_raw_lock[i], NULL);
633	    }
634	}
635	
636	static char* tls_raw_acquire(void)
637	{
638	    pthread_once(&s_tls_raw_once, tls_raw_init_once);
639	    for (int i = 0; i < TLS_RAW_BUF_COUNT; i++) {
640	        if (pthread_mutex_trylock(&s_tls_raw_lock[i]) == 0) {
641	            return s_tls_raw_buf[i];
642	        }
643	    }
644	    /* All busy — block on first */
645	    pthread_mutex_lock(&s_tls_raw_lock[0]);
646	    return s_tls_raw_buf[0];
647	}
648	
649	static void tls_raw_release(char* buf)
650	{
651	    for (int i = 0; i < TLS_RAW_BUF_COUNT; i++) {
652	        if (buf == s_tls_raw_buf[i]) {
653	            pthread_mutex_unlock(&s_tls_raw_lock[i]);
654	            return;
655	        }
656	    }
657	}
658	
659	static int tls_read_response(tls_ctx_t* ctx, char* resp_buf, size_t resp_cap,
660	    size_t* out_body_len, bool* out_keep_alive)
661	{
662	    /* Use static buffers to avoid heap fragmentation */
663	    char* raw = tls_raw_acquire();
664	    size_t raw_len = 0;
665	    int eof = 0;
666	    int ret;
667	
668	    /* Read until we have the full header (double CRLF) or buffer full */
669	    while (!eof && raw_len < TLS_RAW_BUF_SIZE - 1) {
670	        ret = mbedtls_ssl_read(&ctx->ssl,
671	            (unsigned char*)(raw + raw_len),
672	            TLS_RAW_BUF_SIZE - 1 - raw_len);
673	        if (ret > 0) {
674	            raw_len += (size_t)ret;
675	            if (memmem(raw, raw_len, "\r\n\r\n", 4))
676	                break;
677	        } else if (ret == 0 || ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
678	            eof = 1;
679	            break;
680	        } else if (ret != MBEDTLS_ERR_SSL_WANT_READ) {
681	            syslog(LOG_ERR, "[%s] ssl_read (header) ret=0x%x\n", TAG, -ret);
682	            tls_raw_release(raw);
683	            return VELA_TLS_ERR_READ;
684	        }
685	    }
686	    raw[raw_len] = '\0';
687	
688	    /* Parse status line */
689	    int http_status = 0;
690	    if (sscanf(raw, "HTTP/1.%*d %d", &http_status) != 1) {
691	        syslog(LOG_ERR, "[%s] Failed to parse HTTP status from: %.80s\n", TAG, raw);
692	        tls_raw_release(raw);
693	        return VELA_TLS_ERR_READ;
694	    }
695	
696	    /* Find header/body split */
697	    char* body_start = (char*)memmem(raw, raw_len, "\r\n\r\n", 4);
698	    if (!body_start) {
699	        resp_buf[0] = '\0';
700	        tls_raw_release(raw);
701	        return http_status;
702	    }
703	
704	    /* Determine keep-alive from Connection header (default true for HTTP/1.1) */
705	    if (out_keep_alive) {
706	        *out_keep_alive = true;  /* HTTP/1.1 default */
707	        char* conn_hdr = strcasestr(raw, "Connection:");
708	        if (conn_hdr && conn_hdr < body_start) {
709	            *out_keep_alive = (strcasestr(conn_hdr, "keep-alive") != NULL);
710	        }
711	    }
712	    body_start += 4; /* skip double CRLF */
713	
714	    /* Extract content-length if present */
715	    long content_length = -1;
716	    {
717	        char* cl_hdr = strcasestr(raw, "Content-Length:");
718	        if (cl_hdr && cl_hdr < body_start) {
719	            cl_hdr += strlen("Content-Length:");
720	            content_length = strtol(cl_hdr, NULL, 10);
721	            if (content_length < 0 || content_length > 10 * 1024 * 1024) {
722	                content_length = -1; /* reject absurd values */
723	            }
724	        }
725	    }
726	    int chunked = 0;
727	    {
728	        char* te_hdr = strcasestr(raw, "Transfer-Encoding:");
729	        if (te_hdr && te_hdr < body_start) {
730	            chunked = (strcasestr(te_hdr, "chunked") != NULL);
731	        }
732	    }
733	
734	    /* Initial fragment already in raw buffer */
735	    size_t initial = (size_t)(raw + raw_len - body_start);
736	    size_t resp_pos = 0;
737	
738	    /* Copy initial fragment */
739	    size_t copy = initial < resp_cap - 1 ? initial : resp_cap - 1;
740	    memcpy(resp_buf, body_start, copy);
741	    resp_pos = copy;
742	
743	    /* Keep reading body */
744	    if (!eof) {
745	        while (resp_pos < resp_cap - 1) {
746	            if (content_length >= 0 && (long)resp_pos >= content_length)
747	                break;
748	            ret = mbedtls_ssl_read(&ctx->ssl,
749	                (unsigned char*)(resp_buf + resp_pos),
750	                resp_cap - 1 - resp_pos);
751	            if (ret > 0) {
752	                resp_pos += (size_t)ret;
753	            } else if (ret == 0 || ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
754	                break;
755	            } else if (ret != MBEDTLS_ERR_SSL_WANT_READ) {
756	                break;
757	            }
758	        }
759	    }
760	
761	    resp_buf[resp_pos] = '\0';
762	    tls_raw_release(raw);
763	
764	    /* Chunked decode */
765	    if (chunked) {
766	        resp_pos = decode_chunked(resp_buf, resp_pos);
767	        resp_buf[resp_pos] = '\0';
768	    }
769	
770	    if (out_body_len)
771	        *out_body_len = resp_pos;
772	
773	    return http_status;
774	}
775	
776	/* ── Streaming response read ─────────────────────────────────── */
777	
778	/* Incremental chunked-transfer decoder.  Chunked framing is
779	 *   <hex-size>\r\n<data>\r\n ... 0\r\n\r\n
780	 * and the chunk headers/data may be split arbitrarily across TLS reads,
781	 * so we carry incomplete bytes between calls.  Fully-received chunk
782	 * payloads are emitted to cb(). */
783	typedef struct {
784	    char  buf[8192];
785	    size_t len;
786	} chunk_decoder_t;
787	
788	/* Feed `len` raw (still-encoded) body bytes into the decoder.
789	 * Returns 1 when the final (zero-size) chunk has been consumed, 0 while
790	 * more data is expected, -1 on malformed framing. */
791	static int chunk_decoder_feed(chunk_decoder_t *cd, const char *data,
792	    size_t len, vela_stream_cb_t cb, void *ctx)
793	{
794	    while (len > 0) {
795	        size_t room = sizeof(cd->buf) - cd->len;
796	        size_t n = len < room ? len : room;
797	        memcpy(cd->buf + cd->len, data, n);
798	        cd->len += n;
799	        data += n;
800	        len -= n;
801	        if (cd->len == sizeof(cd->buf)) {
802	            syslog(LOG_ERR, "[%s] chunk decoder overflow\n", TAG);
803	            return -1;
804	        }
805	    }
806	
807	    for (;;) {
808	        char *crlf = (char *)memmem(cd->buf, cd->len, "\r\n", 2);
809	        if (!crlf)
810	            break; /* incomplete size line */
811	
812	        char *endptr = NULL;
813	        long chunk_sz = strtol(cd->buf, &endptr, 16);
814	        while (endptr < crlf && *endptr == ' ')
815	            endptr++;
816	        if (endptr == cd->buf || endptr != crlf || chunk_sz < 0) {
817	            syslog(LOG_ERR, "[%s] malformed chunk header\n", TAG);
818	            return -1;
819	        }
820	
821	        size_t hdr_len = (size_t)(crlf - cd->buf) + 2; /* size line + CRLF */
822	
823	        if (chunk_sz == 0) {
824	            cd->len = 0; /* final chunk — done */
825	            return 1;
826	        }
827	
828	        size_t need = hdr_len + (size_t)chunk_sz + 2; /* payload + CRLF */
829	        if (cd->len < need)
830	            break; /* not all of this chunk has arrived yet */
831	
832	        if (cb(cd->buf + hdr_len, (size_t)chunk_sz, ctx) != 0)
833	            return 1; /* caller aborted */
834	
835	        size_t consumed = hdr_len + (size_t)chunk_sz + 2;
836	        memmove(cd->buf, cd->buf + consumed, cd->len - consumed);
837	        cd->len -= consumed;
838	    }
839	
840	    return 0;
841	}
842	
843	/* Read a response, delivering decoded body bytes to cb() as they arrive.
844	 * Mirrors tls_read_response() but does not buffer the whole body. */
845	static int tls_read_response_stream(tls_ctx_t *ctx, vela_stream_cb_t cb,
846	    void *uctx)
847	{
848	    char *raw = tls_raw_acquire();
849	    size_t raw_len = 0;
850	    int ret;
851	    int result = VELA_TLS_ERR_READ;
852	    chunk_decoder_t *cd = NULL;
853	    char *tmp = NULL;
854	
855	    /* Read until full header (double CRLF). */
856	    while (raw_len < TLS_RAW_BUF_SIZE - 1) {
857	        ret = mbedtls_ssl_read(&ctx->ssl,
858	            (unsigned char *)(raw + raw_len), TLS_RAW_BUF_SIZE - 1 - raw_len);
859	        if (ret > 0) {
860	            raw_len += (size_t)ret;
861	            if (memmem(raw, raw_len, "\r\n\r\n", 4))
862	                break;
863	        } else if (ret == 0 || ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
864	            break;
865	        } else if (ret != MBEDTLS_ERR_SSL_WANT_READ) {
866	            syslog(LOG_ERR, "[%s] ssl_read (header) ret=0x%x\n", TAG, -ret);
867	            goto cleanup;
868	        }
869	    }
870	    raw[raw_len] = '\0';
871	
872	    int http_status = 0;
873	    if (sscanf(raw, "HTTP/1.%*d %d", &http_status) != 1) {
874	        syslog(LOG_ERR, "[%s] Failed to parse HTTP status\n", TAG);
875	        goto cleanup;
876	    }
877	    result = http_status;
878	
879	    char *body_start = (char *)memmem(raw, raw_len, "\r\n\r\n", 4);
880	    if (!body_start) {
881	        goto cleanup; /* no body */
882	    }
883	    body_start += 4;
884	
885	    long content_length = -1;
886	    {
887	        char *cl_hdr = strcasestr(raw, "Content-Length:");
888	        if (cl_hdr && cl_hdr < body_start) {
889	            content_length = strtol(cl_hdr + strlen("Content-Length:"), NULL, 10);
890	            if (content_length < 0 || content_length > 10 * 1024 * 1024)
891	                content_length = -1;
892	        }
893	    }
894	    int chunked = 0;
895	    {
896	        char *te_hdr = strcasestr(raw, "Transfer-Encoding:");
897	        if (te_hdr && te_hdr < body_start)
898	            chunked = (strcasestr(te_hdr, "chunked") != NULL);
899	    }
900	
901	    /* Initial fragment (bytes already read past the header). */
902	    size_t initial = (size_t)(raw + raw_len - body_start);
903	    long emitted = (long)initial;
904	
905	    /* Heap-allocate the chunk decoder + read buffer: the caller's task stack
906	     * (agent loop) is only 32KB and already carries a tls_ctx_t. */
907	    cd = calloc(1, sizeof(*cd));
908	    tmp = malloc(4096);
909	    if (!cd || !tmp) {
910	        goto cleanup;
911	    }
912	
913	    if (chunked) {
914	        int r = chunk_decoder_feed(cd, body_start, initial, cb, uctx);
915	        if (r < 0) {
916	            result = VELA_TLS_ERR_READ;
917	            goto cleanup;
918	        }
919	        if (r == 1) {
920	            goto cleanup; /* final chunk already received */
921	        }
922	    } else if (initial > 0) {
923	        if (cb(body_start, initial, uctx) != 0) {
924	            goto cleanup;
925	        }
926	        if (content_length >= 0 && emitted >= content_length) {
927	            goto cleanup;
928	        }
929	    }
930	    tls_raw_release(raw);
931	    raw = NULL;
932	
933	    /* Keep reading the body. */
934	    for (;;) {
935	        ret = mbedtls_ssl_read(&ctx->ssl, (unsigned char *)tmp, 4096);
936	        if (ret > 0) {
937	            if (chunked) {
938	                int r = chunk_decoder_feed(cd, tmp, (size_t)ret, cb, uctx);
939	                if (r < 0) {
940	                    result = VELA_TLS_ERR_READ;
941	                    break;
942	                }
943	                if (r == 1)
944	                    break; /* final chunk — stop reading, don't wait for EOF */
945	            } else {
946	                if (cb(tmp, (size_t)ret, uctx) != 0)
947	                    break;
948	                emitted += ret;
949	                if (content_length >= 0 && emitted >= content_length)
950	                    break;
951	            }
952	        } else if (ret == 0 || ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
953	            break;
954	        } else if (ret != MBEDTLS_ERR_SSL_WANT_READ) {
955	            break;
956	        }
957	    }
958	
959	cleanup:
960	    free(cd);
961	    free(tmp);
962	    if (raw)
963	        tls_raw_release(raw);
964	    return result;
965	}
