967	/* ── Public API ──────────────────────────────────────────────── */
968	
969	int vela_https_request(
970	    const char* host,
971	    const char* port,
972	    const char* method,
973	    const char* path,
974	    const vela_header_t* headers,
975	    const char* body,
976	    size_t body_len,
977	    char* resp_buf,
978	    size_t resp_cap,
979	    size_t* out_body_len)
980	{
981	    int ret;
982	
983	    /* Try to get a pooled connection first */
984	    conn_slot_t* slot = pool_acquire(host, port);
985	
986	    if (slot && slot->valid) {
987	        /* Drain any leftover data from previous response before reuse.
988	         * Without this, a partially-read response body (e.g. truncated
989	         * chunked data) would be misinterpreted as the next HTTP status. */
990	        if (slot->ctx.net.fd >= 0) {
991	            unsigned char drain[512];
992	            int dr;
993	            /* Temporarily set a very short socket timeout to drain without blocking */
994	            struct timeval tv_drain = { .tv_sec = 0, .tv_usec = 10000 }; /* 10ms */
995	            struct timeval tv_orig = { .tv_sec = AGENT_LLM_SOCKET_TIMEOUT_SEC,
996	                .tv_usec = 0 };
997	            setsockopt(slot->ctx.net.fd, SOL_SOCKET, SO_RCVTIMEO,
998	                &tv_drain, sizeof(tv_drain));
999	            while ((dr = mbedtls_ssl_read(&slot->ctx.ssl, drain, sizeof(drain))) > 0)
1000	                ; /* discard leftover bytes */
1001	            /* Restore original timeout */
1002	            setsockopt(slot->ctx.net.fd, SOL_SOCKET, SO_RCVTIMEO,
1003	                &tv_orig, sizeof(tv_orig));
1004	            /* If peer closed the connection, reconnect */
1005	            if (dr == 0 || dr == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
1006	                goto pool_reconnect;
1007	            }
1008	        } else {
1009	            goto pool_reconnect;
1010	        }
1011	
1012	        /* Reuse existing connection — skip TLS handshake */
1013	        syslog(LOG_DEBUG, "[%s] Reusing pooled connection to %s:%s\n", TAG, host, port);
1014	        ret = tls_write_request(&slot->ctx, method, host, path, headers, body, body_len);
1015	        if (ret == 0) {
1016	            bool keep = false;
1017	            ret = tls_read_response(&slot->ctx, resp_buf, resp_cap, out_body_len, &keep);
1018	            if (ret > 0) {
1019	                pool_release(slot, host, port, keep);
1020	                return ret;
1021	            }
1022	        }
1023	        /* Connection went stale — fall through to reconnect */
1024	    pool_reconnect:
1025	        syslog(LOG_INFO, "[%s] Pooled connection stale, reconnecting\n", TAG);
1026	        tls_ctx_free(&slot->ctx);
1027	        slot->valid = false;
1028	    }
1029	
1030	    /* New connection */
1031	    if (!slot) {
1032	        /* Pool full — use a temporary ephemeral context */
1033	        tls_ctx_t tmp_ctx;
1034	        if ((ret = tls_ctx_connect_retry(&tmp_ctx, host, port)) != 0) {
1035	            tls_ctx_free(&tmp_ctx);
1036	            return ret;
1037	        }
1038	        if ((ret = tls_write_request(&tmp_ctx, method, host, path,
1039	                 headers, body, body_len))
1040	            != 0) {
1041	            syslog(LOG_ERR, "[%s] Write request failed: %d\n", TAG, ret);
1042	            tls_ctx_free(&tmp_ctx);
1043	            return ret;
1044	        }
1045	        ret = tls_read_response(&tmp_ctx, resp_buf, resp_cap, out_body_len, NULL);
1046	        tls_ctx_free(&tmp_ctx);
1047	        return ret;
1048	    }
1049	
1050	    /* Connect into the slot */
1051	    if ((ret = tls_ctx_connect_retry(&slot->ctx, host, port)) != 0) {
1052	        pool_release(slot, host, port, false);
1053	        return ret;
1054	    }
1055	
1056	    if ((ret = tls_write_request(&slot->ctx, method, host, path,
1057	             headers, body, body_len))
1058	        != 0) {
1059	        syslog(LOG_ERR, "[%s] Write request failed: %d\n", TAG, ret);
1060	        pool_release(slot, host, port, false);
1061	        return ret;
1062	    }
1063	
1064	    bool keep = false;
1065	    ret = tls_read_response(&slot->ctx, resp_buf, resp_cap, out_body_len, &keep);
1066	    pool_release(slot, host, port, ret > 0 && keep);
1067	    return ret;
1068	}
1069	
1070	int vela_https_get(const char* host, const char* port, const char* path,
1071	    char* resp_buf, size_t resp_cap)
1072	{
1073	    return vela_https_request(host, port, "GET", path, NULL, NULL, 0,
1074	        resp_buf, resp_cap, NULL);
1075	}
1076	
1077	int vela_https_post_json(const char* host, const char* port, const char* path,
1078	    const vela_header_t* extra_headers,
1079	    const char* json_body,
1080	    char* resp_buf, size_t resp_cap)
