292	 ****************************************************************************/
293	
294	/* ── Streaming TTS worker ─────────────────────────────────────
295	 * Speak a response aloud in a background thread so the LVGL UI stays
296	 * responsive while TTS synthesizes and plays. A single worker thread
297	 * serializes every speak (voice_channel_speak aborts any in-progress speak
298	 * on a concurrent call), and it only ever speaks complete sentences so a
299	 * half-streamed sentence isn't cut into two utterances. */
300	
301	/* Byte length of a sentence terminator at *p (0 if not one). Mirrors the
302	 * terminator set in voice_channel.c so boundaries match TTS chunking. */
303	static int sentence_end_len_at(const char *p)
304	{
305	    static const char *const TERM[] = {
306	        "。", "！", "？", "；", "…", "\n", "!", "?", ";", ".", "~", NULL
307	    };
308	
309	    for (int i = 0; TERM[i] != NULL; i++)
310	      {
311	        size_t n = strlen(TERM[i]);
312	
313	        if (strncmp(p, TERM[i], n) == 0)
314	          {
315	            return (int)n;
316	          }
317	      }
318	    return 0;
319	}
320	
321	/* Byte offset just past the last complete-sentence terminator in text. */
322	static size_t last_sentence_end(const char *text, size_t len)
323	{
324	    size_t last = 0;
325	
326	    for (size_t i = 0; i < len; )
327	      {
328	        int n = sentence_end_len_at(text + i);
329	
330	        if (n > 0)
331	          {
332	            last = i + (size_t)n;
333	            i += (size_t)n;
334	          }
335	        else
336	          {
337	            i++;
338	          }
339	      }
340	    return last;
341	}
342	
343	static void *tts_stream_worker(void *arg)
344	{
345	    (void)arg;
346	
347	    for (;;)
348	      {
349	        char text[MSG_BUF_LEN];
350	        bool final = false;
351	        unsigned int epoch;
352	        size_t spoken;
353	
354	        pthread_mutex_lock(&g_tts_lock);
355	        while (!g_tts_pending_ready)
356	          {
357	            pthread_cond_wait(&g_tts_cond, &g_tts_lock);
358	          }
359	        strncpy(text, g_tts_pending, MSG_BUF_LEN - 1);
360	        text[MSG_BUF_LEN - 1] = '\0';
361	        final = g_tts_pending_final;
362	        epoch = g_tts_epoch;

363	        spoken = g_spoken_len;
364	        g_tts_pending_ready = false;
365	        g_tts_pending_final = false;
366	        pthread_mutex_unlock(&g_tts_lock);
367	
368	        size_t len = strlen(text);
369	
370	        if (spoken > len)
371	          {
372	            spoken = len; /* offset reset under us mid-speak */
373	          }
374	
375	        /* Partial fragment: speak only complete sentences. Final fragment:
376	         * flush the trailing (possibly incomplete) sentence too. */
377	        size_t speak_end = final ? len : last_sentence_end(text, len);
378	
379	        syslog(LOG_INFO,
380	               "[kid_buddy] tts_worker final=%d len=%d spoken=%d speak_end=%d\n",
381	               (int)final, (int)len, (int)spoken, (int)speak_end);
382	
383	        if (speak_end > spoken)
384	          {
385	            size_t n = speak_end - spoken;
386	            char suffix[MSG_BUF_LEN];
387	
388	            if (n >= MSG_BUF_LEN)
389	              {
390	                n = MSG_BUF_LEN - 1;
391	              }
392	            memcpy(suffix, text + spoken, n);
393	            suffix[n] = '\0';
394	
395	            voice_channel_speak(suffix);
396	
397	            pthread_mutex_lock(&g_tts_lock);
398	            /* Advance only if no newer question reset the offset mid-speak. */
399	            if (epoch == g_tts_epoch)
400	              {
401	                g_spoken_len = speak_end;
402	              }
403	            pthread_mutex_unlock(&g_tts_lock);
404	          }
405	      }
406	
407	    return NULL;
408	}
