410	/* Enqueue the latest cumulative reply text for speaking. "latest wins" — a
411	 * newer fragment replaces an older one still waiting in the slot. */
412	static void enqueue_tts(const char *text, bool final)
413	{
414	    pthread_mutex_lock(&g_tts_lock);
415	    strncpy(g_tts_pending, text, MSG_BUF_LEN - 1);
416	    g_tts_pending[MSG_BUF_LEN - 1] = '\0';
417	    g_tts_pending_final = final;
418	    g_tts_pending_ready = true;
419	    syslog(LOG_INFO, "[kid_buddy] enqueue_tts final=%d len=%d\n",
420	           (int)final, (int)strlen(g_tts_pending));
421	    pthread_cond_signal(&g_tts_cond);
422	    pthread_mutex_unlock(&g_tts_lock);
423	}
