995	/* ── TTS prefetch pipeline ───────────────────────────────────── */
996	
997	/* One prefetched sentence: its text (owned) and the decoded PCM captured
998	 * by the streaming backend. The pipeline fetches sentence N+1 in a worker
999	 * thread while sentence N plays, so the slow TTS network fetch overlaps
1000	 * real-time playback instead of leaving a long silence between sentences. */
1001	typedef struct {
1002	    char* text;
1003	    unsigned char* pcm;
1004	    size_t pcm_len;
1005	    size_t pcm_cap;
1006	    int rc;   /* final result: backend result, or -ENOMEM on capture failure */
1007	} tts_prefetch_t;
1008	
1009	/* Capture callback: accumulate streamed PCM into pf->pcm instead of writing
1010	 * straight to the playback device. (voice_tts_chunk_cb returns void, so we
1011	 * can't abort the stream from here — just stop capturing on abort/failure.) */
1012	static void tts_prefetch_capture_cb(const unsigned char* pcm, size_t len,
1013	    int is_last, void* user_data)
1014	{
1015	    tts_prefetch_t* pf = user_data;
1016	    (void)is_last;
1017	
1018	    if (s_voice.tts_abort || pf->rc != 0) {
1019	        return;
1020	    }
1021	
1022	    if (pcm && len > 0) {
1023	        if (!s_tts_first_chunk) {
1024	            struct timespec now;
1025	            clock_gettime(CLOCK_MONOTONIC, &now);
1026	            long ms = (now.tv_sec - s_tts_start.tv_sec) * 1000
1027	                + (now.tv_nsec - s_tts_start.tv_nsec) / 1000000;
1028	            syslog(LOG_INFO, "[%s] TTS first chunk: %ldms\n", TAG, ms);
1029	            s_tts_first_chunk = 1;
1030	        }
1031	
1032	        if (pf->pcm_len + len > pf->pcm_cap) {
1033	            size_t ncap = pf->pcm_cap ? pf->pcm_cap : 0;
1034	            while (ncap < pf->pcm_len + len) {
1035	                ncap = ncap ? ncap * 2 : (64 * 1024);
1036	            }
1037	            unsigned char* nd = realloc(pf->pcm, ncap);
1038	            if (!nd) {
1039	                pf->rc = -ENOMEM;
1040	                return;
1041	            }
1042	            pf->pcm = nd;
1043	            pf->pcm_cap = ncap;
1044	        }
1045	        memcpy(pf->pcm + pf->pcm_len, pcm, len);
1046	        pf->pcm_len += len;
1047	    }
1048	}
1049	
1050	static void* tts_prefetch_thread(void* arg)
1051	{
1052	    tts_prefetch_t* pf = arg;
1053	    int backend_rc = voice_tts_speak_stream(pf->text,
1054	        tts_prefetch_capture_cb, pf);
1055	    /* Keep a capture failure (e.g. -ENOMEM) over a clean backend result. */
1056	    if (pf->rc == 0) {
1057	        pf->rc = backend_rc;
1058	    }
1059	    return NULL;
1060	}
1061	
1062	static void tts_prefetch_init(tts_prefetch_t* pf)
1063	{
1064	    memset(pf, 0, sizeof(*pf));
1065	}
1066	
1067	static void tts_prefetch_deinit(tts_prefetch_t* pf)
1068	{
1069	    free(pf->text);
1070	    free(pf->pcm);
1071	}
1072	
1073	/* Copy a [s, s+len) slice into a NUL-terminated string with leading
1074	 * whitespace stripped; returns NULL if nothing but whitespace remains. */
1075	static char* tts_slice_dup(const char* s, int len)
1076	{
1077	    char* d = malloc(len + 1);
1078	    if (!d) {
1079	        return NULL;
1080	    }
1081	    memcpy(d, s, len);
1082	    d[len] = '\0';
1083	
1084	    char* c = d;
1085	    while (*c == ' ' || *c == '\n' || *c == '\t' || *c == '\r') {
1086	        c++;
1087	    }
1088	    if (*c == '\0') {
1089	        free(d);
1090	        return NULL;
1091	    }
1092	    if (c != d) {
1093	        memmove(d, c, strlen(c) + 1);
1094	    }
1095	    return d;
1096	}
1097	
1098	/* Synthesize text one sentence at a time, but prefetch the NEXT sentence's
1099	 * audio in a worker thread while the current one plays. A long story
1100	 * produces many sentences; keeping each TTS response small avoids a single
1101	 * utterance's base64 audio overflowing MIMO_TTS_RESP_SIZE. The prefetch is
1102	 * what closes the gap: before, every sentence paid its full network fetch
1103	 * (~5-12s) before any of it was audible, so a story sounded like it stopped
1104	 * after the first sentence. */
1105	static int tts_speak_chunked(const char* text, audio_playback_t* pb)
1106	{
1107	    /* First pass: split into sentence slices. */
1108	    #define MAX_SLICES 128
1109	    const char* slice_start[MAX_SLICES];
1110	    int slice_len[MAX_SLICES];
1111	    int nslices = 0;
1112	
1113	    const char* start = text;
1114	    while (*start && nslices < MAX_SLICES) {
1115	        /* Bail early if the network dropped (e.g. WiFi disconnect) so we
1116	         * don't grind through the remaining sentences with doomed
1117	         * handshakes and retries. */
1118	        if (!network_is_connected()) {
1119	            syslog(LOG_WARNING, "[%s] network down, stopping TTS\n", TAG);
1120	            break;
1121	        }
1122	
1123	        const char* p = start;
1124	        int tlen = 0;
1125	        while (*p) {
1126	            tlen = tts_sentence_end_len(p);
1127	            if (tlen > 0) {
1128	                break;
1129	            }
1130	            p++;
1131	        }
1132	
1133	        const char* end;
1134	        if (*p) {
1135	            end = p + tlen;
1136	
1137	            /* Absorb immediately-following terminators (e.g. "!!!") so
1138	             * they don't become empty one-punctuation sentences. */
1139	            while (*end) {
1140	                int n = tts_sentence_end_len(end);
1141	                if (n > 0) {
1142	                    end += n;
1143	                } else {
1144	                    break;
1145	                }
1146	            }
1147	        } else {
1148	            end = p; /* end of string */
1149	        }
1150	
1151	        if (end > start) {
1152	            slice_start[nslices] = start;
1153	            slice_len[nslices] = (int)(end - start);
1154	            nslices++;
1155	        }
1156	
1157	        if (*end == '\0') {
1158	            break;
1159	        }
1160	        start = end;
1161	    }
1162	    #undef MAX_SLICES
1163	
1164	    if (nslices == 0) {
1165	        return -EPROTO;
1166	    }
1167	
1168	    tts_prefetch_t pf[2];
1169	    tts_prefetch_init(&pf[0]);
1170	    tts_prefetch_init(&pf[1]);
1171	
1172	    pthread_attr_t attr;
1173	    pthread_attr_init(&attr);
1174	    pthread_attr_setstacksize(&attr, 65536);
1175	
1176	    int first_err = 0;
1177	    int any_ok = 0;
1178	
1179	    for (int i = 0; i < nslices; i++) {
1180	        tts_prefetch_t* cur = &pf[i % 2];
1181	        tts_prefetch_t* nxt = &pf[(i + 1) % 2];
1182	        pthread_t tid = 0;
1183	        int launched = 0;
1184	
1185	        /* Kick off the next sentence's fetch in the background so it overlaps
1186	         * this sentence's playback. */
1187	        if (i + 1 < nslices && !s_voice.tts_abort) {
1188	            nxt->text = tts_slice_dup(slice_start[i + 1], slice_len[i + 1]);
1189	            nxt->rc = nxt->text ? 0 : -ENOMEM;
1190	            nxt->pcm = NULL;
1191	            nxt->pcm_len = 0;
1192	            nxt->pcm_cap = 0;
1193	            if (nxt->text
1194	                && pthread_create(&tid, &attr, tts_prefetch_thread, nxt) == 0) {
1195	                launched = 1;
1196	            } else {
1197	                free(nxt->text);
1198	                nxt->text = NULL;
1199	                nxt->rc = -ENOMEM;
1200	            }
1201	        }
1202	
1203	        /* The first sentence hasn't been prefetched yet — fetch it inline
1204	         * (this network latency is the unavoidable first-latency; the next
1205	         * sentence's fetch above already overlaps it). */
1206	        if (i == 0) {
1207	            cur->text = tts_slice_dup(slice_start[0], slice_len[0]);
1208	            cur->rc = cur->text ? 0 : -ENOMEM;
1209	            cur->pcm = NULL;
1210	            cur->pcm_len = 0;
1211	            cur->pcm_cap = 0;
1212	            if (cur->text) {
1213	                tts_prefetch_thread(cur); /* run inline */
1214	            }
1215	        }
1216	
1217	        /* Play the current sentence (blocks in real time). */
1218	        if (cur->rc == 0 && cur->pcm_len > 0) {
1219	            audio_playback_write(pb, cur->pcm, cur->pcm_len);
1220	            any_ok = 1;
1221	        } else if (cur->rc != 0 && first_err == 0) {
1222	            first_err = cur->rc;
1223	        }
1224	
1225	        /* Release the current sentence's buffers. */
1226	        free(cur->text);
1227	        cur->text = NULL;
1228	        free(cur->pcm);
1229	        cur->pcm = NULL;
1230	        cur->pcm_len = 0;
1231	        cur->pcm_cap = 0;
1232	
1233	        /* Wait for the next sentence's background fetch to finish. */
1234	        if (launched) {
1235	            pthread_join(tid, NULL);
1236	        }
1237	
1238	        if (s_voice.tts_abort) {
1239	            break;
1240	        }
1241	    }
1242	
1243	    pthread_attr_destroy(&attr);
1244	    tts_prefetch_deinit(&pf[0]);
1245	    tts_prefetch_deinit(&pf[1]);
1246	
1247	    return any_ok ? 0 : (first_err ? first_err : -EPROTO);
1248	}
