```c
/* Synthesize text one sentence at a time, buffering each sentence's PCM,
 * then play them all back-to-back. This avoids two problems at once:
 * (1) a single utterance's base64 can overflow MIMO_TTS_RESP_SIZE, so we
 * still chunk by sentence; (2) if we played each sentence right after its
 * own fetch, every sentence would be followed by a network-sized silence
 * (5-12s) before the next one — which is why a story sounded like it
 * stopped after the first sentence. Fetching all sentences up front costs
 * one combined first-sentence delay, but the story then reads continuously. */
static int tts_speak_chunked(const char* text, audio_playback_t* pb)
{
    /* First pass: split into sentence slices. */
    #define MAX_SLICES 128
    const char* slice_start[MAX_SLICES];
    int slice_len[MAX_SLICES];
    int nslices = 0;

    const char* start = text;
    while (*start && nslices < MAX_SLICES) {
        if (!network_is_connected()) {
            syslog(LOG_WARNING, "[%s] network down, stopping TTS\n", TAG);
            break;
        }

        const char* p = start;
        int tlen = 0;
        while (*p) {
            tlen = tts_sentence_end_len(p);
            if (tlen > 0) {
                break;
            }
            p++;
        }

        const char* end;
        if (*p) {
            end = p + tlen;
            while (*end) {
                int n = tts_sentence_end_len(end);
                if (n > 0) {
                    end += n;
                } else {
                    break;
                }
            }
        } else {
            end = p;
        }

        if (end > start) {
            slice_start[nslices] = start;
            slice_len[nslices] = (int)(end - start);
            nslices++;
        }

        if (*end == '\0') {
            break;
        }
        start = end;
    }
    #undef MAX_SLICES

    if (nslices == 0) {
        return -EPROTO;
    }

    /* Phase 1: fetch every sentence's audio sequentially into memory. */
    tts_buf_t bufs[MAX_SLICES];
    memset(bufs, 0, sizeof(bufs));

    int first_err = 0;
    int any_ok = 0;

    for (int i = 0; i < nslices; i++) {
        if (s_voice.tts_abort) {
            break;
        }
        if (!network_is_connected()) {
            syslog(LOG_WARNING, "[%s] network down, stopping TTS\n", TAG);
            if (first_err == 0) {
                first_err = -EIO;
            }
            break;
        }

        char* sent = tts_slice_dup(slice_start[i], slice_len[i]);
        if (!sent) {
            bufs[i].rc = -ENOMEM;
            if (first_err == 0) {
                first_err = -ENOMEM;
            }
            continue;
        }

        int r = voice_tts_speak_stream(sent, tts_capture_cb, &bufs[i]);
        free(sent);

        /* Keep a capture failure (OOM) over a clean backend result. */
        if (bufs[i].rc == 0) {
            bufs[i].rc = r;
        }

        if (r == 0 && bufs[i].pcm_len > 0) {
            any_ok = 1;
        } else if (bufs[i].rc != 0 && first_err == 0) {
            first_err = bufs[i].rc;
        }
    }

    /* Phase 2: play all buffered sentences back-to-back (continuous). */
    for (int i = 0; i < nslices; i++) {
        if (s_voice.tts_abort) {
            break;
        }
        if (bufs[i].rc == 0 && bufs[i].pcm_len > 0) {
            audio_playback_write(pb, bufs[i].pcm, bufs[i].pcm_len);
        }
    }

    for (int i = 0; i < nslices; i++) {
        free(bufs[i].pcm);
    }

    return any_ok ? 0 : (first_err ? first_err : -EPROTO);
}
