/* ── TTS prefetch pipeline ───────────────────────────────────── */

/* One prefetched sentence: its text (owned) and the decoded PCM captured
 * by the streaming backend. The pipeline fetches sentence N+1 in a worker
 * thread while sentence N plays, so the slow TTS network fetch overlaps
 * real-time playback instead of leaving a long silence between sentences. */
typedef struct {
    char* text;
    unsigned char* pcm;
    size_t pcm_len;
    size_t pcm_cap;
    int rc;   /* final result: backend result, or -ENOMEM on capture failure */
} tts_prefetch_t;

/* Capture callback: accumulate streamed PCM into pf->pcm instead of writing
 * straight to the playback device. (voice_tts_chunk_cb returns void, so we
 * can't abort the stream from here — just stop capturing on abort/failure.) */
static void tts_prefetch_capture_cb(const unsigned char* pcm, size_t len,
    int is_last, void* user_data)
{
    tts_prefetch_t* pf = user_data;
    (void)is_last;

    if (s_voice.tts_abort || pf->rc != 0) {
        return;
    }

    if (pcm && len > 0) {
        if (!s_tts_first_chunk) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            long ms = (now.tv_sec - s_tts_start.tv_sec) * 1000
                + (now.tv_nsec - s_tts_start.tv_nsec) / 1000000;
            syslog(LOG_INFO, "[%s] TTS first chunk: %ldms\n", TAG, ms);
            s_tts_first_chunk = 1;
        }

        if (pf->pcm_len + len > pf->pcm_cap) {
            size_t ncap = pf->pcm_cap ? pf->pcm_cap : 0;
            while (ncap < pf->pcm_len + len) {
                ncap = ncap ? ncap * 2 : (64 * 1024);
            }
            unsigned char* nd = realloc(pf->pcm, ncap);
            if (!nd) {
                pf->rc = -ENOMEM;
                return;
            }
            pf->pcm = nd;
            pf->pcm_cap = ncap;
        }
        memcpy(pf->pcm + pf->pcm_len, pcm, len);
        pf->pcm_len += len;
    }
}

static void* tts_prefetch_thread(void* arg)
{
    tts_prefetch_t* pf = arg;
    int backend_rc = voice_tts_speak_stream(pf->text,
        tts_prefetch_capture_cb, pf);
    /* Keep a capture failure (e.g. -ENOMEM) over a clean backend result. */
    if (pf->rc == 0) {
        pf->rc = backend_rc;
    }
    return NULL;
}

static void tts_prefetch_init(tts_prefetch_t* pf)
{
    memset(pf, 0, sizeof(*pf));
}

static void tts_prefetch_deinit(tts_prefetch_t* pf)
{
    free(pf->text);
    free(pf->pcm);
}
