927	/* Strip Markdown formatting that TTS would read aloud.
928	 * Removes: **bold**, *italic*, # headings, - list bullets.
929	 * Operates in-place, result is always <= original length. */
930	static void tts_strip_markdown(char* s)
931	{
932	    char* r = s; /* read pointer */
933	    char* w = s; /* write pointer */
934	
935	    while (*r) {
936	        /* Skip ** (bold markers) */
937	        if (r[0] == '*' && r[1] == '*') {
938	            r += 2;
939	            continue;
940	        }
941	
942	        /* Skip lone * (italic markers) \xe2\x80\x94 but keep * in
943	         * contexts like "3*4" (digit before and after) */
944	        if (r[0] == '*') {
945	            if ((r == s || !isdigit((unsigned char)r[-1]))
946	                || !isdigit((unsigned char)r[1])) {
947	                r++;
948	                continue;
949	            }
950	        }
951	
952	        /* Skip # at line start (headings) */
953	        if (r[0] == '#' && (r == s || r[-1] == '\n')) {
954	            while (*r == '#' || *r == ' ') {
955	                r++;
956	            }
957	            continue;
958	        }
959	
960	        /* Skip "- " at line start (list bullets) */
961	        if (r[0] == '-' && r[1] == ' '
962	            && (r == s || r[-1] == '\n')) {
963	            r += 2;
964	            continue;
965	        }
966	
967	        *w++ = *r++;
968	    }
969	
970	    *w = '\0';
971	}
