973	/* ── Sentence chunking for TTS ──────────────────────────────── */
974	
975	/* Return the byte length of a sentence-terminating punctuation mark at
976	 * *p (0 if *p is not a terminator). Full-width Chinese punctuation is
977	 * 3 bytes in UTF-8, so we match the whole character, not just one byte. */
978	static int tts_sentence_end_len(const char* p)
979	{
980	    static const char* const TERM[] = {
981	        "。", "！", "？", "；", "…", "\n", "!", "?", ";", ".", "~", NULL
982	    };
983	
984	    for (int i = 0; TERM[i] != NULL; i++) {
985	        size_t n = strlen(TERM[i]);
986	
987	        if (strncmp(p, TERM[i], n) == 0) {
988	            return (int)n;
989	        }
990	    }
991	
992	    return 0;
993	}
994	
995	/* ── TTS: fetch-then-play ───────────────────────────────────── */
996	
997	/* One sentence's decoded PCM (owned). Sentences are fetched sequentially,
998	 * buffered, then played back-to-back so the story reads continuously with
999	 * no network-sized silence between sentences. */
1000	typedef struct {
1001	    unsigned char* pcm;
1002	    size_t pcm_len;
1003	    size_t pcm_cap;
1004	    int rc;   /* 0 on success; backend error, or -ENOMEM on capture failure */
1005	} tts_buf_t;
1006	
1007	/* Capture callback: accumulate streamed PCM into b->pcm. (voice_tts_chunk_cb
1008	 * returns void, so a capture failure just sets b->rc and stops copying.) */
1009	static void tts_capture_cb(const unsigned char* pcm, size_t len,
1010	    int is_last, void* user_data)
1011	{
1012	    tts_buf_t* b = user_data;
1013	    (void)is_last;
1014	
1015	    if (s_voice.tts_abort || b->rc != 0) {
1016	        return;
1017	    }
1018	
1019	    if (pcm && len > 0) {
1020	        if (!s_tts_first_chunk) {
1021	            struct timespec now;
1022	            clock_gettime(CLOCK_MONOTONIC, &now);
1023	            long ms = (now.tv_sec - s_tts_start.tv_sec) * 1000
1024	                + (now.tv_nsec - s_tts_start.tv_nsec) / 1000000;
1025	            syslog(LOG_INFO, "[%s] TTS first chunk: %ldms\n", TAG, ms);
1026	            s_tts_first_chunk = 1;
1027	        }
1028	
1029	        if (b->pcm_len + len > b->pcm_cap) {
1030	            size_t ncap = b->pcm_cap ? b->pcm_cap : 0;
1031	            while (ncap < b->pcm_len + len) {
1032	                ncap = ncap ? ncap * 2 : (64 * 1024);
1033	            }
1034	            unsigned char* nd = realloc(b->pcm, ncap);
1035	            if (!nd) {
1036	                b->rc = -ENOMEM;
1037	                return;
1038	            }
1039	            b->pcm = nd;
1040	            b->pcm_cap = ncap;
1041	        }
1042	        memcpy(b->pcm + b->pcm_len, pcm, len);
1043	        b->pcm_len += len;
1044	    }
1045	}
1046	
1047	/* Copy a [s, s+len) slice into a NUL-terminated string with leading
1048	 * whitespace stripped; returns NULL if nothing but whitespace remains. */
1049	static char* tts_slice_dup(const char* s, int len)
1050	{
1051	    char* d = malloc(len + 1);
1052	    if (!d) {
1053	        return NULL;
1054	    }
1055	    memcpy(d, s, len);
1056	    d[len] = '\0';
1057	
1058	    char* c = d;
1059	    while (*c == ' ' || *c == '\n' || *c == '\t' || *c == '\r') {
1060	        c++;
1061	    }
1062	    if (*c == '\0') {
1063	        free(d);
1064	        return NULL;
1065	    }
1066	    if (c != d) {
1067	        memmove(d, c, strlen(c) + 1);
1068	    }
1069	    return d;
1070	}
1071	
1072	/* Synthesize text one sentence at a time, buffering each sentence's PCM,
1073	 * then play them all back-to-back. Chunking by sentence keeps each TTS
1074	 * response small (a single utterance's base64 audio can overflow
1075	 * MIMO_TTS_RESP_SIZE), while buffering first — instead of playing each
1076	 * sentence immediately after its own fetch — removes the 5-12s network
1077	 * silence that used to sit between sentences and made a story sound like
1078	 * it stopped after the first line. The cost is one combined first-sentence
1079	 * delay, but the story then reads continuously. */
1080	static int tts_speak_chunked(const char* text, audio_playback_t* pb)
1081	{
1082	    /* First pass: split into sentence slices. */
1083	    #define MAX_SLICES 128
1084	    const char* slice_start[MAX_SLICES];
1085	    int slice_len[MAX_SLICES];
1086	    int nslices = 0;
1087	
1088	    const char* start = text;
1089	    while (*start && nslices < MAX_SLICES) {
1090	        /* Bail early if the network dropped (e.g. WiFi disconnect) so we
1091	         * don't grind through the remaining sentences with doomed
1092	         * handshakes and retries. */
1093	        if (!network_is_connected()) {
1094	            syslog(LOG_WARNING, "[%s] network down, stopping TTS\n", TAG);
1095	            break;
1096	        }
1097	
1098	        const char* p = start;
1099	        int tlen = 0;
1100	        while (*p) {
1101	            tlen = tts_sentence_end_len(p);
1102	            if (tlen > 0) {
1103	                break;
1104	            }
1105	            p++;
1106	        }
1107	
1108	        const char* end;
1109	        if (*p) {
1110	            end = p + tlen;
1111	
1112	            /* Absorb immediately-following terminators (e.g. "!!!") so
1113	             * they don't become empty one-punctuation sentences. */
1114	            while (*end) {
1115	                int n = tts_sentence_end_len(end);
1116	                if (n > 0) {
1117	                    end += n;
1118	                } else {
1119	                    break;
1120	                }
1121	            }
1122	        } else {
1123	            end = p; /* end of string */
1124	        }
1125	
1126	        if (end > start) {
1127	            slice_start[nslices] = start;
1128	            slice_len[nslices] = (int)(end - start);
1129	            nslices++;
1130	        }
1131	
1132	        if (*end == '\0') {
1133	            break;
1134	        }
1135	        start = end;
1136	    }
1137	
1138	    if (nslices == 0) {
1139	        return -EPROTO;
1140	    }
1141	
1142	    tts_buf_t bufs[MAX_SLICES];
1143	    memset(bufs, 0, sizeof(bufs));
1144	
1145	    int first_err = 0;
1146	    int any_ok = 0;
1147	
1148	    /* Phase 1: fetch every sentence's audio sequentially into memory. */
1149	    for (int i = 0; i < nslices; i++) {
1150	        if (s_voice.tts_abort) {
1151	            break;
1152	        }
1153	        if (!network_is_connected()) {
1154	            syslog(LOG_WARNING, "[%s] network down, stopping TTS\n", TAG);
1155	            if (first_err == 0) {
1156	                first_err = -EIO;
1157	            }
1158	            break;
1159	        }
1160	
1161	        char* sent = tts_slice_dup(slice_start[i], slice_len[i]);
1162	        if (!sent) {
1163	            bufs[i].rc = -ENOMEM;
1164	            if (first_err == 0) {
1165	                first_err = -ENOMEM;
1166	            }
1167	            continue;
1168	        }
1169	
1170	        int r = voice_tts_speak_stream(sent, tts_capture_cb, &bufs[i]);
1171	        free(sent);
1172	
1173	        /* Keep a capture failure (e.g. -ENOMEM) over a clean backend result. */
1174	        if (bufs[i].rc == 0) {
1175	            bufs[i].rc = r;
1176	        }
1177	
1178	        if (r == 0 && bufs[i].pcm_len > 0) {
1179	            any_ok = 1;
1180	        } else if (bufs[i].rc != 0 && first_err == 0) {
1181	            first_err = bufs[i].rc;
1182	        }
1183	    }
1184	
1185	    /* Phase 2: play all buffered sentences back-to-back (continuous). */
1186	    for (int i = 0; i < nslices; i++) {
1187	        if (s_voice.tts_abort) {
1188	            break;
1189	        }
1190	        if (bufs[i].rc == 0 && bufs[i].pcm_len > 0) {
1191	            audio_playback_write(pb, bufs[i].pcm, bufs[i].pcm_len);
1192	        }
1193	    }
1194	
1195	    for (int i = 0; i < nslices; i++) {
1196	        free(bufs[i].pcm);
1197	    }
1198	
1199	    #undef MAX_SLICES
1200	    return any_ok ? 0 : (first_err ? first_err : -EPROTO);
1201	}
