1203	int voice_channel_speak(const char* text)
1204	{
1205	    if (!text || text[0] == '\0') {
1206	        return -EINVAL;
1207	    }
1208	
1209	    /* ── Serialize concurrent speak calls ── */
1210	    /* If another thread is already speaking, abort its TTS playback
1211	     * so we don't overlap media_player sessions (which causes the
1212	     * media framework to attempt a ~1.3GB allocation and crash). */
1213	    pthread_mutex_lock(&s_voice.lock);
1214	    if (s_voice.tts_pb) {
1215	        syslog(LOG_INFO, "[%s] speak: aborting previous TTS\n", TAG);
1216	        s_voice.tts_abort = 1;
1217	        audio_playback_stop(s_voice.tts_pb);
1218	    }
1219	    pthread_mutex_unlock(&s_voice.lock);
1220	
1221	    pthread_mutex_lock(&s_voice.speak_lock);
1222	
1223	    /* ── AEC workaround: reject TTS while PTT is recording ── */
1224	    pthread_mutex_lock(&s_voice.lock);
1225	    if (s_voice.state != VOICE_IDLE) {
1226	        pthread_mutex_unlock(&s_voice.lock);
1227	        pthread_mutex_unlock(&s_voice.speak_lock);
1228	        syslog(LOG_INFO,
1229	            "[%s] speak: skipped, recording active\n", TAG);
1230	        return -EBUSY;
1231	    }
1232	    pthread_mutex_unlock(&s_voice.lock);
1233	
1234	    /* Work on a mutable copy so we can strip markdown in-place */
1235	    size_t text_len = strlen(text);
1236	    char* clean = malloc(text_len + 1);
1237	
1238	    if (!clean) {
1239	        pthread_mutex_unlock(&s_voice.speak_lock);
1240	        return -ENOMEM;
1241	    }
1242	
1243	    memcpy(clean, text, text_len + 1);
1244	    tts_strip_markdown(clean);
1245	
1246	    /* If stripping left nothing, bail out */
1247	    if (clean[0] == '\0') {
1248	        free(clean);
1249	        pthread_mutex_unlock(&s_voice.speak_lock);
1250	        return 0;
1251	    }
1252	
1253	    syslog(LOG_INFO, "[%s] speak: \"%.*s\" (%zu bytes)\n",
1254	        TAG, 60, clean, strlen(clean));
1255	
1256	    clock_gettime(CLOCK_MONOTONIC, &s_tts_start);
1257	    s_tts_first_chunk = 0;
1258	
1259	    if (s_asr_done_ts.tv_sec > 0) {
1260	        long llm_ms = (s_tts_start.tv_sec - s_asr_done_ts.tv_sec) * 1000
1261	            + (s_tts_start.tv_nsec - s_asr_done_ts.tv_nsec) / 1000000;
1262	        syslog(LOG_INFO, "[%s] LLM latency: %ldms\n", TAG, llm_ms);
1263	    }
1264	
1265	    /* Try streaming TTS first (callback per chunk) */
1266	    audio_playback_t* pb = audio_playback_open(
1267	        AGENT_AUDIO_PLAYBACK_DEV,
1268	        AGENT_TTS_WS_SAMPLE_RATE,
1269	        AGENT_VOICE_CHANNELS,
1270	        AGENT_VOICE_BITS);
1271	
1272	    if (!pb) {
1273	        syslog(LOG_ERR, "[%s] playback open failed\n", TAG);
1274	        free(clean);
1275	        pthread_mutex_unlock(&s_voice.speak_lock);
1276	        return -EIO;
1277	    }
1278	
1279	    /* Register active playback so voice_channel_start() can abort it */
1280	    pthread_mutex_lock(&s_voice.lock);
1281	    s_voice.tts_abort = 0;
1282	    s_voice.tts_pb = pb;
1283	    pthread_mutex_unlock(&s_voice.lock);
1284	
1285	    /* Use streaming TTS, split sentence-by-sentence so a long story
1286	     * doesn't overflow the TTS response buffer. */
1287	    int ret = tts_speak_chunked(clean, pb);
1288	
1289	    struct timespec tts_net;
1290	    clock_gettime(CLOCK_MONOTONIC, &tts_net);
1291	    long net_ms = (tts_net.tv_sec - s_tts_start.tv_sec) * 1000
1292	        + (tts_net.tv_nsec - s_tts_start.tv_nsec) / 1000000;
1293	    syslog(LOG_INFO, "[%s] TTS network done: %ldms\n", TAG, net_ms);
1294	
1295	    /* Unregister active playback */
1296	    pthread_mutex_lock(&s_voice.lock);
1297	    s_voice.tts_pb = NULL;
1298	    s_voice.tts_abort = 0;
1299	    pthread_mutex_unlock(&s_voice.lock);
1300	
1301	    audio_playback_close(pb);
1302	    free(clean);
1303	
1304	    if (ret != 0) {
1305	        syslog(LOG_ERR, "[%s] TTS stream failed: %d\n", TAG, ret);
1306	        pthread_mutex_unlock(&s_voice.speak_lock);
1307	        return ret;
1308	    }
1309	
1310	    struct timespec tend;
1311	    clock_gettime(CLOCK_MONOTONIC, &tend);
1312	    long total_ms = (tend.tv_sec - s_tts_start.tv_sec) * 1000
1313	        + (tend.tv_nsec - s_tts_start.tv_nsec) / 1000000;
1314	    syslog(LOG_INFO, "[%s] speak done: total %ldms (play wait %ldms)\n",
1315	        TAG, total_ms, total_ms - net_ms);
1316	    pthread_mutex_unlock(&s_voice.speak_lock);
1317	    return 0;
1318	}
