1322	int voice_channel_test_tts(const char* text, const char* out_path)
1323	{
1324	    if (!text || !out_path) {
1325	        printf("Usage: voice_test_tts <text> [output_path]\n");
1326	        return -EINVAL;
1327	    }
1328	
1329	    printf("TTS: synthesizing \"%s\" ...\n", text);
1330	
