1334	        printf("Error: out of memory\n");
1335	        return -ENOMEM;
1336	    }
1337	
1338	    size_t pcm_len;
1339	    int ret = voice_tts_speak(text, pcm,
1340	        AGENT_VOICE_PCM_BUF_SIZE, &pcm_len);
