1364	static void* asr_file_worker(void* arg)
1365	{
1366	    asr_task_args_t* a = (asr_task_args_t*)arg;
1367	    unsigned char* pcm = NULL;
1368	    size_t pcm_len = 0;
1369	
1370	    int ret = read_pcm_file(a->pcm_path, &pcm, &pcm_len);
1371	
1372	    if (ret != 0) {
1373	        printf("Failed to read %s: %d\n", a->pcm_path, ret);
1374	        free(a);
1375	        return NULL;
1376	    }
1377	
1378	    printf("ASR: recognizing %zu bytes from %s ...\n",
1379	        pcm_len, a->pcm_path);
1380	
1381	    char text[512];
1382	
1383	    ret = voice_asr_recognize(pcm, pcm_len, text, sizeof(text));
1384	    free(pcm);
1385	
1386	    if (ret == 0) {
1387	        printf("ASR result: %s\n", text);
1388	
1389	        agent_msg_t msg;
1390	
1391	        memset(&msg, 0, sizeof(msg));
1392	        strncpy(msg.channel, AGENT_CHAN_VOICE,
1393	            sizeof(msg.channel) - 1);
1394	        strncpy(msg.chat_id, "voice",
1395	            sizeof(msg.chat_id) - 1);
1396	        msg.content = strdup(text);
1397	        if (msg.content) {
1398	            message_bus_push_inbound(&msg);
1399	            printf("Sent to agent.\n");
1400	        }
1401	    } else {
1402	        printf("ASR failed: %d\n", ret);
1403	    }
1404	
1405	    free(a);
1406	    return NULL;
1407	}
