168	/* Message queue between LLM callback and LVGL thread.
169	 * The LLM callback (ai_agent/outbound-dispatch thread) writes g_msg_status /
170	 * g_pending_msg / g_msg_ready while the LVGL timer reads them. Guard with a
171	 * mutex so the status byte and the text can't be torn apart mid-read (which
172	 * made a "final" status pair up with a stale short fragment). */
173	static char    g_pending_msg[MSG_BUF_LEN];
174	static bool    g_msg_ready = false;
175	static int     g_msg_status = 0;
176	static pthread_mutex_t g_msg_lock = PTHREAD_MUTEX_INITIALIZER;
177	
178	/* Streaming TTS state: a single worker thread speaks the reply sentence by
179	 * sentence as it streams in. voice_channel_speak() aborts any in-progress
180	 * speak when called concurrently, so every speak must go through this one
181	 * thread. The pending slot is "latest wins" — a newer fragment replaces an
182	 * older one still waiting to be spoken. */
183	static pthread_mutex_t g_tts_lock = PTHREAD_MUTEX_INITIALIZER;
184	static pthread_cond_t  g_tts_cond  = PTHREAD_COND_INITIALIZER;
185	static char     g_tts_pending[MSG_BUF_LEN];
186	static bool     g_tts_pending_ready = false;
187	static bool     g_tts_pending_final = false;
188	static size_t   g_spoken_len = 0;      /* bytes already spoken this response */
189	static unsigned int g_tts_epoch = 0;   /* bumped each new question */
190	
