199	/****************************************************************************
200	 * LLM Callback (called from ai_agent thread, NOT LVGL thread)
201	 ****************************************************************************/
202	
203	static void llm_response_cb(int status, const char *response, void *cookie)
204	{
205	    (void)cookie;
206	
207	    pthread_mutex_lock(&g_msg_lock);
208	
209	    g_msg_status = status;
210	    if ((status == 0 || status == 1) && response != NULL)
211	      {
212	        /* status 0 = final reply, status 1 = streaming fragment (cumulative
213	         * text so far). Both carry the running reply text. */
214	        strncpy(g_pending_msg, response, MSG_BUF_LEN - 1);
215	        g_pending_msg[MSG_BUF_LEN - 1] = '\0';
216	      }
217	    else
218	      {
219	        snprintf(g_pending_msg, MSG_BUF_LEN, "[LLM error: %d]", status);
220	      }
221	    g_msg_ready = true;
222	
223	    syslog(LOG_INFO, "[kid_buddy] llm_cb status=%d len=%d\n",
224	           status, (int)strlen(g_pending_msg));
225	
226	    pthread_mutex_unlock(&g_msg_lock);
227	}
