229	/****************************************************************************
230	 * Send a message to LLM with current role's system prompt
231	 ****************************************************************************/
232	
233	static void send_to_llm(const char *user_text)
234	{
235	    if (!g_agent_connected || g_agent_client == NULL)
236	      {
237	        lv_label_set_text(g_chat_status, "Agent offline - start 'ai_agent &' first");
238	        return;
239	      }
240	
241	    /* Build full prompt: system prompt + user text */
242	    const role_def_t *role = &g_roles[g_current_role];
243	    char full_prompt[MSG_BUF_LEN];
244	    snprintf(full_prompt, MSG_BUF_LEN,
245	             "[SYSTEM]\n%s\n\n[USER]\n%s",
246	             role->system_prompt, user_text);
247	
248	    velaclaw_ask_req_t req = {
249	        .text       = full_prompt,
250	        .timeout_ms = 15000  /* 15 second timeout */
251	    };
252	
253	    /* Start a fresh response: bump the epoch and reset the spoken offset so
254	     * the streamed reply is spoken from the beginning, and drop any stale
255	     * fragment still queued for the previous question. */
256	    pthread_mutex_lock(&g_tts_lock);
257	    g_tts_epoch++;
258	    g_spoken_len = 0;
259	    g_tts_pending_ready = false;
260	    g_tts_pending_final = false;
261	    pthread_mutex_unlock(&g_tts_lock);
262	
263	    lv_label_set_text(g_chat_status, "Thinking...");
264	    if (g_chat_spinner)
265	      {
266	        lv_obj_clear_flag(g_chat_spinner, LV_OBJ_FLAG_HIDDEN);
267	      }
268	
269	    int ret = velaclaw_ask(g_agent_client, &req, llm_response_cb, NULL);
270	    if (ret < 0)
271	      {
272	        lv_label_set_text(g_chat_status, "Failed to send message");
273	        if (g_chat_spinner)
274	          {
275	            lv_obj_add_flag(g_chat_spinner, LV_OBJ_FLAG_HIDDEN);
276	          }
277	      }
278	}
