789	
790	int main(int argc, char *argv[])
791	{
792	    lv_nuttx_dsc_t info;
793	    lv_nuttx_result_t result;
794	
795	    if (lv_is_initialized())
796	      {
797	        LV_LOG_ERROR("LVGL already initialized! aborting.");
798	        return -1;
799	      }
800	
801	#ifdef NEED_BOARDINIT
802	    boardctl(BOARDIOC_INIT, 0);
803	#endif
804	
805	    /* Step 1: Initialize LVGL */
806	    lv_init();
807	
808	    /* Step 2: Configure NuttX display backend */
809	    lv_nuttx_dsc_init(&info);
810	
811	#ifdef CONFIG_LV_USE_NUTTX_LCD
812	    info.fb_path = "/dev/lcd0";
813	#endif
814	
815	#ifdef CONFIG_INPUT_TOUCHSCREEN
816	    info.input_path = "/dev/input0";
817	#endif
818	
819	    lv_nuttx_init(&info, &result);
820	
821	    /* Necessary delay for LCD initialization timing */
822	    usleep(100000);
823	
824	    if (result.disp == NULL)
825	      {
826	        LV_LOG_ERROR("Display initialization failure!");
827	        return 1;
828	      }
829	
830	    /* Step 3: Connect to ai_agent daemon */
831	    g_agent_client = velaclaw_client_open("kid_buddy");
832	    if (g_agent_client != NULL)
833	      {
834	        g_agent_connected = true;
835	        LV_LOG_USER("Connected to AI Agent daemon.");
836	      }
837	    else
838	      {
839	        g_agent_connected = false;
840	        LV_LOG_WARN("AI Agent daemon not available. UI only mode.");
841	      }
842	
843	    /* Step 4: Create UI and start on role selection */
844	    ui_create_role_select();
845	    lv_scr_load(g_scr_role_select);
846	
847	    /* Step 5: Create poll timer to update UI from LLM callbacks */
848	    lv_timer_create(poll_timer_cb, 200, NULL);
849	
850	    /* Step 5b: Start the single TTS worker thread that speaks the streamed
851	     * reply sentence-by-sentence (serialized so it never aborts itself). */
852	    pthread_attr_t tts_attr;
853	
854	    pthread_attr_init(&tts_attr);
855	    pthread_attr_setstacksize(&tts_attr, 65536);
856	    pthread_t tts_tid;
857	
858	    if (pthread_create(&tts_tid, &tts_attr, tts_stream_worker, NULL) != 0)
859	      {
860	        syslog(LOG_ERR, "[kid_buddy] Failed to start TTS worker\n");
861	      }
862	    pthread_attr_destroy(&tts_attr);
863	
864	    /* Step 6: Main loop */
865	    while (1)
866	      {
867	        uint32_t idle = lv_timer_handler();
868	        idle = idle ? idle : 1;
869	        usleep(idle * 1000);
870	      }
871	
872	    return 0;
873	}
