17	/* audio_playback.c - Streaming audio playback via direct ALSA (aw-alsa-lib)
18	 * or media_player buffer mode.
19	 *
20	 * On the Allwinner R528 (Gemini-S1) board the openvela media_player framework
21	 * is not available at runtime, so playback uses the chip's aw-tiny-alsa-lib
22	 * directly (gated behind CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT). When that option
23	 * is disabled (or ALSA open fails), we fall back to media_player. */
24	
25	#include "voice/audio_playback.h"
26	#include "agent_config.h"
27	
28	#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
29	#include <aw-alsa-lib/pcm.h>
30	#endif
31	#include <errno.h>
32	#include <media_player.h>
33	#include <stdio.h>
34	#include <stdlib.h>
35	#include <string.h>
36	#include <syslog.h>
37	#include <time.h>
38	#include <unistd.h>
39	
40	static const char* TAG = "audio_pb";
41	
42	#define PB_OPTIONS_LEN 128
43	
44	enum audio_playback_backend {
45	    AUDIO_PLAYBACK_BACKEND_NONE = 0,
46	    AUDIO_PLAYBACK_BACKEND_ALSA,
47	    AUDIO_PLAYBACK_BACKEND_MEDIA_PLAYER,
48	};
49	
50	struct audio_playback {
51	    enum audio_playback_backend backend;
52	    union {
53	#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
54	        snd_pcm_t* pcm;
55	#endif
56	        void* player;
57	    } handle;
58	    size_t total_written;
59	    int bytes_per_frame;
60	    volatile int stopped;
61	};
62	
