66	
67	static const char* resolve_alsa_name(const char* dev_path)
68	{
69	    if (!dev_path || dev_path[0] == '\0') {
70	        return "default";
71	    }
72	
73	    if (strncmp(dev_path, "/dev/audio/", strlen("/dev/audio/")) == 0) {
74	        return "default";
75	    }
76	
77	    return dev_path;
78	}
79	
80	static int configure_alsa_playback(snd_pcm_t* pcm,
81	    unsigned int sample_rate, unsigned int channels)
82	{
83	    snd_pcm_hw_params_t* hw;
84	    snd_pcm_sw_params_t* sw;
85	    snd_pcm_uframes_t period_frames = sample_rate / 10;
86	    snd_pcm_uframes_t buffer_frames;
87	    snd_pcm_uframes_t boundary;
88	    int ret;
89	
90	    if (period_frames == 0) {
91	        period_frames = 256;
92	    }
93	
94	    buffer_frames = period_frames * 4;
95	
96	    snd_pcm_hw_params_alloca(&hw);
97	    ret = snd_vela_pcm_hw_params_any(pcm, hw);
98	    if (ret < 0) {
99	        return ret;
100	    }
101	
102	    ret = snd_vela_pcm_hw_params_set_access(pcm, hw,
103	        SND_PCM_ACCESS_RW_INTERLEAVED);
104	    if (ret < 0) {
105	        return ret;
106	    }
107	
108	    ret = snd_vela_pcm_hw_params_set_format(pcm, hw, SND_PCM_FORMAT_S16_LE);
109	    if (ret < 0) {
110	        return ret;
111	    }
112	
113	    ret = snd_vela_pcm_hw_params_set_channels(pcm, hw, channels);
114	    if (ret < 0) {
115	        return ret;
116	    }
117	
118	    ret = snd_vela_pcm_hw_params_set_rate(pcm, hw, sample_rate, 0);
119	    if (ret < 0) {
120	        return ret;
121	    }
122	
123	    ret = snd_vela_pcm_hw_params_set_period_size(pcm, hw,
124	        period_frames, 0);
125	    if (ret < 0) {
126	        return ret;
127	    }
128	
129	    ret = snd_vela_pcm_hw_params_set_buffer_size(pcm, hw,
130	        buffer_frames);
131	    if (ret < 0) {
132	        return ret;
133	    }
134	
135	    ret = snd_vela_pcm_hw_params(pcm, hw);
136	    if (ret < 0) {
137	        return ret;
138	    }
139	
140	    snd_pcm_sw_params_alloca(&sw);
141	    ret = snd_vela_pcm_sw_params_current(pcm, sw);
142	    if (ret < 0) {
143	        return ret;
144	    }
145	
146	    ret = snd_vela_pcm_sw_params_get_boundary(sw, &boundary);
147	    if (ret < 0) {
148	        return ret;
149	    }
150	
151	    ret = snd_vela_pcm_sw_params_set_start_threshold(pcm, sw,
152	        buffer_frames);
153	    if (ret < 0) {
154	        return ret;
155	    }
156	
157	    ret = snd_vela_pcm_sw_params_set_silence_size(pcm, sw, boundary);
158	    if (ret < 0) {
159	        return ret;
160	    }
161	
162	    ret = snd_vela_pcm_sw_params_set_stop_threshold(pcm, sw,
163	        buffer_frames);
164	    if (ret < 0) {
165	        return ret;
166	    }
167	
168	    ret = snd_vela_pcm_sw_params_set_avail_min(pcm, sw, period_frames);
169	    if (ret < 0) {
170	        return ret;
171	    }
172	
173	    return snd_vela_pcm_sw_params(pcm, sw);
174	}
175	
176	static int open_alsa_playback(audio_playback_t* pb,
177	    const char* dev_path, unsigned int sample_rate,
178	    unsigned int channels, unsigned int bits_per_sample)
179	{
180	    (void)bits_per_sample; /* 16-bit only for now */
181	
182	    const char* name = resolve_alsa_name(dev_path);
183	    snd_pcm_t* pcm = NULL;
184	
185	    int ret = snd_vela_pcm_open(&pcm, name,
186	        SND_VELA_PCM_STREAM_PLAYBACK, 0);
187	
188	    if (ret < 0) {
189	        syslog(LOG_ERR, "[%s] ALSA open failed: %d\n", TAG, ret);
190	        return ret;
191	    }
192	
193	    ret = configure_alsa_playback(pcm, sample_rate, channels);
194	    if (ret < 0) {
195	        syslog(LOG_ERR, "[%s] ALSA configure failed: %d\n", TAG, ret);
196	        snd_vela_pcm_close(pcm);
197	        return ret;
198	    }
199	
200	    pb->backend = AUDIO_PLAYBACK_BACKEND_ALSA;
201	    pb->handle.pcm = pcm;
202	    pb->bytes_per_frame = (bits_per_sample / 8) * channels;
203	
204	    syslog(LOG_INFO,
205	        "[%s] opened direct ALSA playback (%s, %uHz, %uch, %ubit)\n",
206	        TAG, name, sample_rate, channels, bits_per_sample);
207	    return 0;
208	}
