211	
212	static int open_media_player_playback(audio_playback_t* pb,
213	    unsigned int sample_rate, unsigned int channels,
214	    unsigned int bits_per_sample)
215	{
216	    void* player = media_player_open(MEDIA_STREAM_MUSIC);
217	
218	    if (!player) {
219	        syslog(LOG_ERR, "[%s] media_player_open failed\n", TAG);
220	        return -EIO;
221	    }
222	
223	    char opts[PB_OPTIONS_LEN];
224	    snprintf(opts, sizeof(opts),
225	        "format=s%ule:sample_rate=%u:ch_layout=%s",
226	        bits_per_sample, sample_rate,
227	        (channels == 1) ? "mono" : "stereo");
228	
229	    int ret = media_player_prepare(player, NULL, opts);
230	
231	    if (ret < 0) {
232	        syslog(LOG_ERR, "[%s] prepare failed: %d\n", TAG, ret);
233	        media_player_close(player, 0);
234	        return ret;
235	    }
236	
237	    ret = media_player_start(player);
238	    if (ret < 0) {
239	        syslog(LOG_ERR, "[%s] start failed: %d\n", TAG, ret);
240	        media_player_close(player, 0);
241	        return ret;
242	    }
243	
244	    pb->backend = AUDIO_PLAYBACK_BACKEND_MEDIA_PLAYER;
245	    pb->handle.player = player;
246	    pb->bytes_per_frame = (bits_per_sample / 8) * channels;
247	
248	    syslog(LOG_INFO, "[%s] opened media player (%uHz %uch %ubit)\n",
249	        TAG, sample_rate, channels, bits_per_sample);
250	    return 0;
251	}
252	
253	audio_playback_t* audio_playback_open(const char* dev_path,
254	    unsigned int sample_rate, unsigned int channels,
255	    unsigned int bits_per_sample)
256	{
257	    if (s_active_pb) {
258	        syslog(LOG_WARNING, "[%s] force closing stale player\n", TAG);
259	        audio_playback_close(s_active_pb);
260	        usleep(100000);
261	    }
262	
263	    audio_playback_t* pb = calloc(1, sizeof(*pb));
264	
265	    if (!pb) {
266	        return NULL;
267	    }
268	
269	    int ret = -ENOTSUP;
270	#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
271	    ret = open_alsa_playback(pb, dev_path, sample_rate, channels,
272	        bits_per_sample);
273	    if (ret < 0) {
274	        syslog(LOG_WARNING,
275	            "[%s] direct ALSA playback unavailable (%d), falling back to media player\n",
276	            TAG, ret);
277	    }
278	#else
279	    (void)dev_path;
280	#endif
281	
282	    if (ret < 0) {
283	        ret = open_media_player_playback(pb, sample_rate, channels,
284	            bits_per_sample);
285	        if (ret < 0) {
286	            free(pb);
287	            return NULL;
288	        }
289	    }
290	
291	    s_active_pb = pb;
292	
293	    syslog(LOG_INFO, "[%s] opened (%uHz %uch %ubit)\n",
294	        TAG, sample_rate, channels, bits_per_sample);
295	    return pb;
296	}
297	
298	int audio_playback_write(audio_playback_t* pb, const void* buf, size_t len)
299	{
300	    if (!pb || !buf || len == 0) {
301	        return -EINVAL;
302	    }
303	
304	    if (pb->stopped) {
305	        return -ECANCELED;
306	    }
307	
308	#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
309	    if (pb->backend == AUDIO_PLAYBACK_BACKEND_ALSA) {
310	        snd_pcm_t* pcm = pb->handle.pcm;
311	        const unsigned char* src = buf;
312	        size_t written_bytes = 0;
313	
314	        while (written_bytes < len) {
315	            snd_pcm_uframes_t frames = snd_vela_pcm_bytes_to_frames(pcm,
316	                len - written_bytes);
317	            snd_pcm_sframes_t n = snd_vela_pcm_writei(pcm, src, frames);
318	
319	            if (n == -EAGAIN) {
320	                usleep(10 * 1000);
321	                continue;
322	            }
323	
324	            if (n == -EPIPE || n == -ESTRPIPE) {
325	                snd_vela_pcm_prepare(pcm);
326	                continue;
327	            }
328	
329	            if (n <= 0) {
330	                syslog(LOG_ERR, "[%s] ALSA write failed: %ld\n",
331	                    TAG, (long)n);
332	                return (n < 0) ? (int)n : -EIO;
333	            }
334	
335	            size_t bytes = (size_t)n * (size_t)pb->bytes_per_frame;
336	            src += bytes;
337	            written_bytes += bytes;
338	        }
339	
340	        pb->total_written += written_bytes;
341	        return (int)written_bytes;
342	    }
343	#endif
344	
345	    ssize_t n = media_player_write_data(pb->handle.player, buf, len);
346	
347	    if (n > 0) {
348	        pb->total_written += (size_t)n;
349	    }
350	
351	    return (int)n;
352	}
353	
354	void audio_playback_stop(audio_playback_t* pb)
355	{
356	    if (!pb) {
357	        return;
358	    }
359	
360	    pb->stopped = 1;
361	
362	#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
363	    if (pb->backend == AUDIO_PLAYBACK_BACKEND_ALSA) {
364	        if (pb->handle.pcm) {
365	            snd_vela_pcm_drop(pb->handle.pcm);
366	        }
367	        return;
368	    }
369	#endif
370	
371	    if (pb->handle.player) {
372	        media_player_stop(pb->handle.player);
373	    }
374	}
375	
376	void audio_playback_close(audio_playback_t* pb)
377	{
378	    if (!pb) {
379	        return;
380	    }
381	
382	#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
383	    if (pb->backend == AUDIO_PLAYBACK_BACKEND_ALSA) {
384	        if (pb->handle.pcm) {
385	            if (!pb->stopped) {
386	                /* Block until all written samples have played out. */
387	                struct timespec d0, d1;
388	                clock_gettime(CLOCK_MONOTONIC, &d0);
389	                int drc = snd_vela_pcm_drain(pb->handle.pcm);
390	                clock_gettime(CLOCK_MONOTONIC, &d1);
391	                long dms = (d1.tv_sec - d0.tv_sec) * 1000
392	                    + (d1.tv_nsec - d0.tv_nsec) / 1000000;
393	                syslog(LOG_INFO,
394	                    "[%s] drain rc=%d took %ldms (written=%zu bytes)\n",
395	                    TAG, drc, dms, pb->total_written);
396	            }
397	            syslog(LOG_INFO, "[%s] closing ALSA (%zu bytes written)\n",
398	                TAG, pb->total_written);
399	            snd_vela_pcm_close(pb->handle.pcm);
400	        }
401	        s_active_pb = NULL;
402	        free(pb);
403	        return;
404	    }
405	#endif
406	
407	    if (pb->handle.player) {
408	        syslog(LOG_INFO, "[%s] closing (%zu bytes written)\n",
409	            TAG, pb->total_written);
410	        media_player_stop(pb->handle.player);
411	        usleep(50 * 1000);
412	        media_player_close(pb->handle.player, 0);
413	    }
414	
415	    s_active_pb = NULL;
416	    free(pb);
417	}
