306	static snd_pcm_sframes_t snd_pcm_hw_avail_update(snd_pcm_t *pcm)
307	{
308		snd_pcm_hw_t *hw = pcm->private_data;
309		snd_pcm_uframes_t avail;
310	
311		awalsa_debug("\n");
312		snd_pcm_sync_ptr(pcm, hw, 0);
313		avail = snd_pcm_mmap_avail(pcm);
314		switch (hw->mmap_status.state) {
315		case SNDRV_PCM_STATE_RUNNING:
316			if (avail >= pcm->stop_threshold) {
317				// TODO: notify XRUN to driver?
318	
319				/* everything is ok, state == SND_VELA_PCM_STATE_XRUN at the moment */
320				return -EPIPE;
321			}
322			break;
323		case SNDRV_PCM_STATE_XRUN:
324			return -EPIPE;
325		default:
326			break;
327		}
328		return avail;
329	}
