220	static void snd_pcm_link_ptr(snd_pcm_t *pcm, snd_pcm_rbptr_t *pcm_rbptr,
221				     snd_pcm_t *slave, snd_pcm_rbptr_t *slave_rbptr)
222	{
223		snd_pcm_t **a, **newa;
224		int idx;
225	
226		a = slave_rbptr->link_dst;
227		for (idx = 0; idx < slave_rbptr->link_dst_count; idx++)
228			if (a[idx] == NULL) {
229				a[idx] = pcm;
230				goto __found_free_place;
231			}
232		newa = realloc(a, sizeof(snd_pcm_t *) * (slave_rbptr->link_dst_count + 1));
233		if (newa == NULL) {
234			pcm_rbptr->ptr = NULL;
235			pcm_rbptr->offset = 0UL;
236			return;
237		}
238		a = newa;
239		a[slave_rbptr->link_dst_count++] = pcm;
240	__found_free_place:
241		pcm_rbptr->master = slave_rbptr->master ? slave_rbptr->master : slave;
242		pcm_rbptr->ptr = slave_rbptr->ptr;
243		pcm_rbptr->offset = slave_rbptr->offset;
244		slave_rbptr->link_dst = a;
245	}
