250		snd_pcm_t **a;
251		int idx;
252	
253		a = slave_rbptr->link_dst;
254		for (idx = 0; idx < slave_rbptr->link_dst_count; idx++) {
255			if (a[idx] == pcm) {
256				a[idx] = NULL;
257				goto __found;
258			}
259		}
260		/* assert(0); */
261		return;
262	
263	__found:
264		pcm_rbptr->master = NULL;
265		pcm_rbptr->ptr = NULL;
266		pcm_rbptr->offset = 0UL;
267	}
