433	int _snd_pcm_hw_param_set(snd_pcm_hw_params_t *params, snd_pcm_hw_param_t var, unsigned int val)
434	{
435		union snd_interval *interval = NULL;
436	
437		assert(params);
438		interval = &params->intervals[var - SND_PCM_HW_PARAM_FIRST_INTERVAL];
439		if (var <= SND_PCM_HW_PARAM_LAST_MASK) {
440			if (!(interval->mask & (1 << val)) &&
441					!snd_pcm_hw_param_can_changed(params, var))
442				goto err_out;
443			interval->mask = (1<<val);
444		} else {
445			if ((val < interval->range.min || val > interval->range.max) &&
446					!snd_pcm_hw_param_can_changed(params, var))
447				goto err_out;
448			interval->range.min = val;
449		}
450		return 0;
451	
452	err_out:
453		awalsa_err("invalid value (%u) for interval %d\n", val, var);
454		return -EINVAL;
455	}
