587	static int snd_pcm_sw_params_default(snd_pcm_t *pcm, snd_pcm_sw_params_t *params)
588	{
589		params->avail_min = pcm->period_size;
590		params->start_threshold = 1;
591		params->stop_threshold = pcm->buffer_size;
592		params->silence_size = 0;
593		params->boundary = pcm->buffer_size;
594		if (!pcm->buffer_size) {
595			awalsa_info("buffer size is 0...\n");
596			return 0;
597		}
598		while (params->boundary * 2 <= LONG_MAX - pcm->buffer_size)
599			params->boundary *= 2;
600		return 0;
601	}
602	
603	int _snd_pcm_hw_params_internal(snd_pcm_t *pcm, snd_pcm_hw_params_t *params)
604	{
605		int ret;
606		snd_pcm_sw_params_t sw;
607	
608		awalsa_debug("\n");
609	
610		assert(pcm->ops->hw_params);
611		ret = pcm->ops->hw_params(pcm->op_arg, params);
612		if (ret < 0)
613			return ret;
614	
615		pcm->setup = 1;
616	
617		snd_vela_pcm_hw_params_get_access(params, &pcm->access);
618		snd_vela_pcm_hw_params_get_format(params, &pcm->format);
619		snd_vela_pcm_hw_params_get_channels(params, &pcm->channels);
620		snd_vela_pcm_hw_params_get_rate(params, &pcm->rate, NULL);
621		snd_vela_pcm_hw_params_get_period_time(params, &pcm->period_time, NULL);
622		snd_vela_pcm_hw_params_get_period_size(params, &pcm->period_size, NULL);
623		snd_vela_pcm_hw_params_get_buffer_size(params, &pcm->buffer_size);
624		pcm->sample_bits = snd_pcm_format_physical_width(pcm->format);
625		pcm->frame_bits = pcm->sample_bits * pcm->channels;
626	
627		awalsa_debug("access:%u\n", pcm->access);
628		awalsa_debug("format:%u\n", pcm->format);
629		awalsa_debug("channels:%u\n", pcm->channels);
630		awalsa_debug("rate:%u\n", pcm->rate);
631		awalsa_debug("period_time:%u\n", pcm->period_time);
632		awalsa_debug("period_size:%lu\n", pcm->period_size);
633		awalsa_debug("buffer_size:%lu\n", pcm->buffer_size);
634		awalsa_debug("sample_bits:%u\n", pcm->sample_bits);
635		awalsa_debug("frame_bits:%u\n", pcm->frame_bits);
636	
637		snd_pcm_sw_params_default(pcm, &sw);
638		ret = snd_vela_pcm_sw_params(pcm, &sw);
639		if (ret < 0)
640			return ret;
641	
642		if (pcm->mmap_rw ||
643			pcm->access == SND_PCM_ACCESS_MMAP_INTERLEAVED ||
644			pcm->access == SND_PCM_ACCESS_MMAP_NONINTERLEAVED ||
645			pcm->access == SND_PCM_ACCESS_MMAP_COMPLEX) {
646			ret = snd_pcm_mmap(pcm);
647		}
648		if (ret < 0)
649			return ret;
650		return 0;
651	}
