1236	void snd_pcm_areas_from_buf(snd_pcm_t *pcm, snd_pcm_channel_area_t *areas, void *buf)
1237	{
1238		unsigned int channel;
1239		unsigned int channels;
1240	
1241		snd_pcm_lock(pcm);
1242		channels = pcm->channels;
1243		for (channel = 0; channel < channels; ++channel, ++areas) {
1244			areas->addr = buf;
1245			areas->first = channel * pcm->sample_bits;
1246			areas->step = pcm->frame_bits;
1247		}
1248		snd_pcm_unlock(pcm);
1249	}
