1257		channels = pcm->channels;
1258		for (channel = 0; channel < channels; ++channel, ++areas, ++bufs) {
1259			areas->addr = *bufs;
1260			areas->first = 0;
1261			areas->step = pcm->sample_bits;
1262		}
