1266	snd_pcm_sframes_t snd_pcm_read_areas(snd_pcm_t *pcm, const snd_pcm_channel_area_t *areas,
1267					     snd_pcm_uframes_t offset, snd_pcm_uframes_t size,
1268					     snd_pcm_xfer_areas_func_t func)
1269	{
1270		snd_pcm_uframes_t xfer = 0;
1271		snd_pcm_sframes_t err = 0;
1272		snd_pcm_state_t state;
1273	
1274		if (size == 0)
1275			return 0;
1276	
1277		snd_pcm_lock(pcm); /* forced lock */
1278		while (size > 0) {
1279			snd_pcm_uframes_t frames;
1280			snd_pcm_sframes_t avail;
1281		_again:
1282			state = __snd_pcm_state(pcm);
1283			switch (state) {
1284			case SND_VELA_PCM_STATE_PREPARED:
1285				err = __snd_pcm_start(pcm);
1286				if (err < 0)
1287					goto _end;
1288				break;
1289			case SND_VELA_PCM_STATE_RUNNING:
1290				err = __snd_pcm_hwsync(pcm);
1291				if (err < 0)
1292					goto _end;
1293				break;
1294			case SND_VELA_PCM_STATE_DRAINING:
1295			case SND_VELA_PCM_STATE_PAUSED:
1296				break;
1297			case SND_VELA_PCM_STATE_XRUN:
1298				err = -EPIPE;
1299				goto _end;
1300			case SND_VELA_PCM_STATE_SUSPENDED:
1301				err = -ESTRPIPE;
1302				goto _end;
1303			case SND_VELA_PCM_STATE_DISCONNECTED:
1304				err = -ENODEV;
1305				goto _end;
1306			default:
1307				err = -EBADFD;
1308				goto _end;
1309			}
1310			avail = __snd_pcm_avail_update(pcm);
1311			if (avail < 0) {
1312				err = avail;
1313				goto _end;
1314			}
1315			if (avail == 0) {
1316				if (state == SND_VELA_PCM_STATE_DRAINING)
1317					goto _end;
1318	#if 0
1319				if (pcm->mode & SND_VELA_PCM_NONBLOCK) {
1320					err = -EAGAIN;
1321					goto _end;
1322				}
1323	#endif
1324				err = __snd_pcm_wait_in_lock(pcm, -1);
1325				if (err < 0)
1326					break;
1327				goto _again;
1328			}
1329			frames = size;
1330			if (frames > (snd_pcm_uframes_t) avail)
1331				frames = avail;
1332			if (! frames)
1333				break;
1334			err = func(pcm, areas, offset, frames);
1335			if (err < 0)
1336				break;
1337			frames = err;
1338			offset += frames;
1339			size -= frames;
1340			xfer += frames;
1341		}
1342	 _end:
1343		snd_pcm_unlock(pcm);
1344		return xfer > 0 ? (snd_pcm_sframes_t) xfer : snd_pcm_check_error(pcm, err);
1345	}
1346	
1347	snd_pcm_sframes_t snd_pcm_write_areas(snd_pcm_t *pcm, const snd_pcm_channel_area_t *areas,
1348					      snd_pcm_uframes_t offset, snd_pcm_uframes_t size,
1349					      snd_pcm_xfer_areas_func_t func)
1350	{
1351		snd_pcm_uframes_t xfer = 0;
1352		snd_pcm_sframes_t err = 0;
1353		snd_pcm_state_t state;
1354	
1355		if (size == 0)
1356			return 0;
1357	
1358		awalsa_debug("\n");
1359		snd_pcm_lock(pcm); /* forced lock */
1360		while (size > 0) {
1361			snd_pcm_uframes_t frames;
1362			snd_pcm_sframes_t avail;
1363		_again:
1364			state = __snd_pcm_state(pcm);
1365			switch (state) {
1366			case SND_VELA_PCM_STATE_PREPARED:
1367			case SND_VELA_PCM_STATE_PAUSED:
1368				break;
1369			case SND_VELA_PCM_STATE_RUNNING:
1370				err = __snd_pcm_hwsync(pcm);
1371				if (err < 0)
1372					goto _end;
1373				break;
1374			case SND_VELA_PCM_STATE_XRUN:
1375				err = -EPIPE;
1376				goto _end;
1377			case SND_VELA_PCM_STATE_SUSPENDED:
1378				err = -ESTRPIPE;
1379				goto _end;
1380			case SND_VELA_PCM_STATE_DISCONNECTED:
1381				err = -ENODEV;
1382				goto _end;
1383			default:
1384				err = -EBADFD;
1385				goto _end;
1386			}
1387			avail = __snd_pcm_avail_update(pcm);
1388			awalsa_debug("avail: %ld\n", avail);
1389			if (avail < 0) {
1390				err = avail;
1391				goto _end;
1392			}
1393	
1394			/* wait to get avail_min */
1395	#if 1
1396			if ((state == SND_VELA_PCM_STATE_RUNNING &&
1397						size > (snd_pcm_uframes_t)avail &&
1398						snd_pcm_may_wait_for_avail_min(pcm, avail))) {
1399				err = snd_pcm_wait_nocheck(pcm, -1);
1400				if (err < 0)
1401					break;
1402				goto _again;
1403			}
1404	#endif
1405	
1406			frames = size;
1407			if (frames > (snd_pcm_uframes_t) avail)
1408				frames = avail;
1409			if (! frames)
1410				break;
1411			err = func(pcm, areas, offset, frames);
1412			if (err < 0)
1413				break;
1414			frames = err;
1415			if (state == SND_VELA_PCM_STATE_PREPARED) {
1416				snd_pcm_sframes_t hw_avail = pcm->buffer_size - avail;
1417				hw_avail += frames;
1418				/* some plugins might automatically start the stream */
1419				state = __snd_pcm_state(pcm);
1420				if (state == SND_VELA_PCM_STATE_PREPARED &&
1421						hw_avail >= (snd_pcm_sframes_t) pcm->start_threshold) {
1422					err = __snd_pcm_start(pcm);
1423					if (err < 0)
1424						goto _end;
1425				}
1426			}
1427			offset += frames;
1428			size -= frames;
1429			xfer += frames;
1430		}
1431	 _end:
1432		snd_pcm_unlock(pcm);
1433		return xfer > 0 ? (snd_pcm_sframes_t) xfer : snd_pcm_check_error(pcm, err);
1434	}
