1436	uint64_t snd_pcm_format_silence_64(snd_pcm_format_t format)
1437	{
1438		switch (format) {
1439		case SND_PCM_FORMAT_S8:
1440		case SND_PCM_FORMAT_S16_LE:
1441		case SND_PCM_FORMAT_S16_BE:
1442		case SND_PCM_FORMAT_S24_LE:
1443		case SND_PCM_FORMAT_S24_BE:
1444		case SND_PCM_FORMAT_S32_LE:
1445		case SND_PCM_FORMAT_S32_BE:
1446			return 0;
1447		case SND_PCM_FORMAT_U8:
1448			return 0x8080808080808080ULL;
1449		case SND_PCM_FORMAT_U16_LE:
1450			return 0x8000800080008000ULL;
1451		case SND_PCM_FORMAT_U24_LE:
1452			return 0x0080000000800000ULL;
1453		case SND_PCM_FORMAT_U32_LE:
1454			return 0x8000000080000000ULL;
1455		case SND_PCM_FORMAT_U16_BE:
1456			return 0x0080008000800080ULL;
1457		case SND_PCM_FORMAT_U24_BE:
1458			return 0x0000800000008000ULL;
1459		case SND_PCM_FORMAT_U32_BE:
1460			return 0x0000008000000080ULL;
1461		default:
1462			assert(0);
1463			return 0;
1464		}
1465		return 0;
1466	}
