1468	int snd_pcm_area_silence(const snd_pcm_channel_area_t *dst_area, snd_pcm_uframes_t dst_offset,
1469				 unsigned int samples, snd_pcm_format_t format)
1470	{
1471		/* FIXME: sub byte resolution and odd dst_offset */
1472		char *dst;
1473		unsigned int dst_step;
1474		int width;
1475		uint64_t silence;
1476	
1477		if (!dst_area->addr)
1478			return 0;
1479		dst = snd_pcm_channel_area_addr(dst_area, dst_offset);
1480		width = snd_pcm_format_physical_width(format);
1481		silence = snd_pcm_format_silence_64(format);
1482		if (dst_area->step == (unsigned int) width) {
1483			unsigned int dwords = samples * width / 64;
1484			uint64_t *dstp = (uint64_t *)dst;
1485			samples -= dwords * 64 / width;
1486			while (dwords-- > 0)
1487				*dstp++ = silence;
1488			if (samples == 0)
1489				return 0;
1490			dst = (char *)dstp;
1491		}
1492		dst_step = dst_area->step / 8;
1493		switch (width) {
1494		case 4: {
1495			uint8_t s0 = silence & 0xf0;
1496			uint8_t s1 = silence & 0x0f;
1497			int dstbit = dst_area->first % 8;
1498			int dstbit_step = dst_area->step % 8;
1499			while (samples-- > 0) {
1500				if (dstbit) {
1501					*dst &= 0xf0;
1502					*dst |= s1;
1503				} else {
1504					*dst &= 0x0f;
1505					*dst |= s0;
1506				}
1507				dst += dst_step;
1508				dstbit += dstbit_step;
1509				if (dstbit == 8) {
1510					dst++;
1511					dstbit = 0;
1512				}
1513			}
1514			break;
1515		}
1516		case 8: {
1517			uint8_t sil = silence;
1518			while (samples-- > 0) {
1519				*dst = sil;
1520				dst += dst_step;
1521			}
1522			break;
1523		}
1524		case 16: {
1525			uint16_t sil = silence;
1526			while (samples-- > 0) {
1527				*(uint16_t*)dst = sil;
1528				dst += dst_step;
1529			}
1530			break;
1531		}
1532		case 24:
1533			*(dst + 0) = silence >> 0;
1534			*(dst + 1) = silence >> 8;
1535			*(dst + 2) = silence >> 16;
1536			break;
1537		case 32: {
1538			uint32_t sil = silence;
1539			while (samples-- > 0) {
1540				*(uint32_t*)dst = sil;
1541				dst += dst_step;
1542			}
1543			break;
1544		}
1545		case 64: {
1546			while (samples-- > 0) {
1547				*(uint64_t*)dst = silence;
1548				dst += dst_step;
1549			}
1550			break;
1551		}
1552		default:
1553			awalsa_err("invalid format width %d", width);
1554			return -EINVAL;
1555		}
1556		return 0;
1557	}
1558	
1559	int snd_pcm_areas_silence(const snd_pcm_channel_area_t *dst_areas, snd_pcm_uframes_t dst_offset,
1560				  unsigned int channels, snd_pcm_uframes_t frames, snd_pcm_format_t format)
1561	{
1562		int width = snd_pcm_format_physical_width(format);
1563		while (channels > 0) {
1564			void *addr = dst_areas->addr;
1565			unsigned int step = dst_areas->step;
1566			const snd_pcm_channel_area_t *begin = dst_areas;
1567			int channels1 = channels;
1568			unsigned int chns = 0;
1569			int err;
1570			while (1) {
1571				channels1--;
1572				chns++;
1573				dst_areas++;
1574				if (channels1 == 0 ||
1575				    dst_areas->addr != addr ||
1576				    dst_areas->step != step ||
1577				    dst_areas->first != dst_areas[-1].first + width)
1578					break;
1579			}
1580			if (chns > 1 && chns * width == step) {
1581				/* Collapse the areas */
1582				snd_pcm_channel_area_t d;
1583				d.addr = begin->addr;
1584				d.first = begin->first;
1585				d.step = width;
1586				err = snd_pcm_area_silence(&d, dst_offset * chns, frames * chns, format);
1587				channels -= chns;
1588			} else {
1589				err = snd_pcm_area_silence(begin, dst_offset, frames, format);
1590				dst_areas = begin + 1;
1591				channels--;
1592			}
1593			if (err < 0)
1594				return err;
1595		}
1596		return 0;
1597	}
