1599	int snd_pcm_area_copy(const snd_pcm_channel_area_t *dst_area, snd_pcm_uframes_t dst_offset,
1600			      const snd_pcm_channel_area_t *src_area, snd_pcm_uframes_t src_offset,
1601			      unsigned int samples, snd_pcm_format_t format)
1602	{
1603		/* FIXME: sub byte resolution and odd dst_offset */
1604		const char *src;
1605		char *dst;
1606		int width;
1607		int src_step, dst_step;
1608		if (dst_area == src_area && dst_offset == src_offset)
1609			return 0;
1610		if (!src_area->addr)
1611			return snd_pcm_area_silence(dst_area, dst_offset, samples, format);
1612		src = snd_pcm_channel_area_addr(src_area, src_offset);
1613		if (!dst_area->addr)
1614			return 0;
1615		dst = snd_pcm_channel_area_addr(dst_area, dst_offset);
1616		width = snd_pcm_format_physical_width(format);
1617		if (src_area->step == (unsigned int) width &&
1618		    dst_area->step == (unsigned int) width) {
1619			size_t bytes = samples * width / 8;
1620			samples -= bytes * 8 / width;
1621			assert(src < dst || src >= dst + bytes);
1622			assert(dst < src || dst >= src + bytes);
1623			memcpy(dst, src, bytes);
1624			if (samples == 0)
1625				return 0;
1626		}
1627		src_step = src_area->step / 8;
1628		dst_step = dst_area->step / 8;
1629		switch (width) {
1630		case 4: {
1631			int srcbit = src_area->first % 8;
1632			int srcbit_step = src_area->step % 8;
1633			int dstbit = dst_area->first % 8;
1634			int dstbit_step = dst_area->step % 8;
1635			while (samples-- > 0) {
1636				unsigned char srcval;
1637				if (srcbit)
1638					srcval = *src & 0x0f;
1639				else
1640					srcval = *src & 0xf0;
1641				if (dstbit)
1642					*dst &= 0xf0;
1643				else
1644					*dst &= 0x0f;
1645				*dst |= srcval;
1646				src += src_step;
1647				srcbit += srcbit_step;
1648				if (srcbit == 8) {
1649					src++;
1650					srcbit = 0;
1651				}
1652				dst += dst_step;
1653				dstbit += dstbit_step;
1654				if (dstbit == 8) {
1655					dst++;
1656					dstbit = 0;
1657				}
1658			}
1659			break;
1660		}
1661		case 8: {
1662			while (samples-- > 0) {
1663				*dst = *src;
1664				src += src_step;
1665				dst += dst_step;
1666			}
1667			break;
1668		}
1669		case 16: {
1670			while (samples-- > 0) {
1671				*(uint16_t*)dst = *(const uint16_t*)src;
1672				src += src_step;
1673				dst += dst_step;
1674			}
1675			break;
1676		}
1677		case 24:
1678			while (samples-- > 0) {
1679				*(dst + 0) = *(src + 0);
1680				*(dst + 1) = *(src + 1);
1681				*(dst + 2) = *(src + 2);
1682				src += src_step;
1683				dst += dst_step;
1684			}
1685			break;
1686		case 32: {
1687			while (samples-- > 0) {
1688				*(uint32_t*)dst = *(const uint32_t*)src;
1689				src += src_step;
1690				dst += dst_step;
1691			}
1692			break;
1693		}
1694		case 64: {
1695			while (samples-- > 0) {
1696				*(uint64_t*)dst = *(const uint64_t*)src;
1697				src += src_step;
1698				dst += dst_step;
1699			}
1700			break;
1701		}
1702		default:
1703			awalsa_err("invalid format width %d", width);
1704			return -EINVAL;
1705		}
1706		return 0;
1707	}
1708	
1709	int snd_pcm_areas_copy(const snd_pcm_channel_area_t *dst_areas, snd_pcm_uframes_t dst_offset,
1710			       const snd_pcm_channel_area_t *src_areas, snd_pcm_uframes_t src_offset,
1711			       unsigned int channels, snd_pcm_uframes_t frames, snd_pcm_format_t format)
1712	{
1713		int width = snd_pcm_format_physical_width(format);
1714		assert(dst_areas);
1715		assert(src_areas);
1716		if (! channels) {
1717			awalsa_err("invalid channels %d\n", channels);
1718			return -EINVAL;
1719		}
1720		if (! frames) {
1721			awalsa_err("invalid frames %ld\n", frames);
1722			return -EINVAL;
1723		}
1724		while (channels > 0) {
1725			unsigned int step = src_areas->step;
1726			void *src_addr = src_areas->addr;
1727			const snd_pcm_channel_area_t *src_start = src_areas;
1728			void *dst_addr = dst_areas->addr;
1729			const snd_pcm_channel_area_t *dst_start = dst_areas;
1730			int channels1 = channels;
1731			unsigned int chns = 0;
1732			while (dst_areas->step == step) {
1733				channels1--;
1734				chns++;
1735				src_areas++;
1736				dst_areas++;
1737				if (channels1 == 0 ||
1738					src_areas->step != step ||
1739					src_areas->addr != src_addr ||
1740					dst_areas->addr != dst_addr ||
1741					src_areas->first != src_areas[-1].first + width ||
1742					dst_areas->first != dst_areas[-1].first + width)
1743					break;
1744			}
1745			if (chns > 1 && chns * width == step) {
1746				if (src_offset != dst_offset ||
1747					src_start->addr != dst_start->addr ||
1748					src_start->first != dst_start->first) {
1749					/* Collapse the areas */
1750					snd_pcm_channel_area_t s, d;
1751					s.addr = src_start->addr;
1752					s.first = src_start->first;
1753					s.step = width;
1754					d.addr = dst_start->addr;
1755					d.first = dst_start->first;
1756					d.step = width;
1757					snd_pcm_area_copy(&d, dst_offset * chns,
1758							&s, src_offset * chns,
1759							frames * chns, format);
1760				}
1761				channels -= chns;
1762			} else {
1763				snd_pcm_area_copy(dst_start, dst_offset,
1764						src_start, src_offset,
1765						frames, format);
1766				src_areas = src_start + 1;
1767				dst_areas = dst_start + 1;
1768				channels--;
1769			}
1770		}
1771		return 0;
1772	}
