1837	int __snd_pcm_mmap_begin(snd_pcm_t *pcm, const snd_pcm_channel_area_t **areas,
1838			       snd_pcm_uframes_t *offset, snd_pcm_uframes_t *frames)
1839	{
1840		snd_pcm_uframes_t cont;
1841		snd_pcm_uframes_t f;
1842		snd_pcm_uframes_t avail;
1843		const snd_pcm_channel_area_t *xareas;
1844		assert(pcm && areas && offset && frames);
1845	
1846		awalsa_debug("\n");
1847	
1848		xareas = snd_pcm_mmap_areas(pcm);
1849		if (xareas == NULL)
1850			return -EBADFD;
1851		*areas = xareas;
1852		*offset = *pcm->appl.ptr % pcm->buffer_size;
1853		avail = snd_pcm_mmap_avail(pcm);
1854		if (avail > pcm->buffer_size)
1855			avail = pcm->buffer_size;
1856		cont = pcm->buffer_size - *offset;
1857		f = *frames;
1858		if (f > avail)
1859			f = avail;
1860		if (f > cont)
1861			f = cont;
1862		*frames = f;
1863		return 0;
1864	}
