1880	snd_pcm_sframes_t __snd_pcm_mmap_commit(snd_pcm_t *pcm,
1881						snd_pcm_uframes_t offset,
1882						snd_pcm_uframes_t frames)
1883	{
1884		assert(pcm);
1885		awalsa_debug("\n");
1886	
1887		if (offset != *pcm->appl.ptr % pcm->buffer_size) {
1888			awalsa_err("commit offset (%ld) doesn't match with appl_ptr (%ld) %% buf_size (%ld)\n",
1889			       offset, *pcm->appl.ptr, pcm->buffer_size);
1890			return -EPIPE;
1891		}
1892		if (frames > snd_pcm_mmap_avail(pcm)) {
1893			awalsa_err("commit frames (%lu) overflow (avail = %ld)", frames,
1894			       snd_pcm_mmap_avail(pcm));
1895			return -EPIPE;
1896		}
1897		return pcm->fast_ops->mmap_commit(pcm->fast_op_arg, offset, frames);
1898	}
