952	static int sunxi_codec_dapm_control(struct snd_pcm_substream *substream,
953					struct snd_dai *dai, int onoff)
954	{
955		struct snd_codec *codec = dai->component;
956		struct sunxi_codec_info *sunxi_codec = codec->private_data;
957		struct sunxi_codec_param *param = &sunxi_codec->param;
958	
959		if (substream->dapm_state == onoff)
960			return 0;
961		if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
962			/*
963			 * Playback:
964			 * Playback --> DAC --> DAC_DIFFER --> LINEOUT/HPOUT + (External Speaker)
965			 */
966	
967			switch (param->pb_audio_route) {
968			case PB_AUDIO_ROUTE_LINEOUT_SPK:
969				sunxi_codec_playback_lineout_route(codec, 1, onoff);
970				break;
971			case PB_AUDIO_ROUTE_HEADPHONE_SPK:
972				sunxi_codec_playback_hp_route(codec, 1, onoff);
973				break;
974			case PB_AUDIO_ROUTE_LINEOUT:
975				sunxi_codec_playback_lineout_route(codec, 0, onoff);
976				break;
977			case PB_AUDIO_ROUTE_HEADPHONE:
978				sunxi_codec_playback_hp_route(codec, 0, onoff);
979				break;
980			case PB_AUDIO_ROUTE_LO_HP:
981				sunxi_codec_playback_lineout_route(codec, 0, onoff);
982				sunxi_codec_playback_hp_route(codec, 0, onoff);
983				break;
984			case PB_AUDIO_ROUTE_LO_HP_SPK:
985				sunxi_codec_playback_lineout_route(codec, onoff ? 0 : 1, onoff);
986				sunxi_codec_playback_hp_route(codec, onoff ? 1 : 0, onoff);
987				break;
988			}
989		} else {
990			/*
991			 * Capture:
992			 * Capture1 <-- ADC1 <-- Input Mixer <-- LINEINL PGA <-- LINEINL
993			 * Capture1 <-- ADC1 <-- Input Mixer <-- FMINL PGA <-- FMINL
994			 *
995			 * Capture2 <-- ADC2 <-- Input Mixer <-- LINEINR PGA <-- LINEINR
996			 * Capture2 <-- ADC2 <-- Input Mixer <-- FMINR PGA <-- FMINR
997			 *
998			 * Capture3 <-- ADC3 <-- Input Mixer <-- MIC3 PGA <-- MIC3
999			 */
1000			unsigned int channels = 0;
1001			channels = substream->runtime->channels;
1002	
1003			snd_print("channels = %u\n", channels);
1004			snd_print("adc flag:%d,%d,%d\n",
1005				param->adc1_flag, param->adc2_flag, param->adc3_flag);
1006			if (onoff) {
1007				if ((param->adc1_flag & ADC_AUDIO_ROUTE_MIC) ||
1008					(param->adc2_flag & ADC_AUDIO_ROUTE_MIC) ||
1009					(param->adc3_flag & ADC_AUDIO_ROUTE_MIC)) {
1010					snd_codec_update_bits(codec, SUNXI_MICBIAS_REG,
1011							      0x1<<MMICBIASEN,
1012							      0x1<<MMICBIASEN);
1013				}
1014				/* Capture on */
1015				hal_msleep(100);
1016				/* digital ADC enable */
1017				snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
1018						(0x1<<EN_AD), (0x1<<EN_AD));
1019	
1020				if (channels > 3 || channels < 1) {
1021					snd_err("unknown channels:%u\n", channels);
1022					return -EINVAL;
1023				}
1024	
1025				if (param->adc1_flag == ADC_AUDIO_ROUTE_MIC) {
1026					snd_codec_update_bits(codec, SUNXI_ADC1_ANA_CTL,
1027							      0x1<<ADC_EN,
1028							      0x1<<ADC_EN);
1029				} else if (param->adc1_flag == ADC_AUDIO_ROUTE_LINEIN ||
1030						param->adc1_flag == ADC_AUDIO_ROUTE_FMIN) {
1031	
1032					snd_codec_update_bits(codec, SUNXI_ADC1_ANA_CTL,
1033							      0x1F<<ADC_PGA_GAIN_CTL,
1034							      0x00<<ADC_PGA_GAIN_CTL);
1035	
1036					snd_codec_update_bits(codec, SUNXI_ADC1_ANA_CTL,
1037							      0x1<<MIC_SIN_EN,
1038							      0x1<<MIC_SIN_EN);
1039	
1040					snd_codec_update_bits(codec, SUNXI_ADC1_ANA_CTL,
1041							      0x1<<ADC_EN,
1042							      0x1<<ADC_EN);
1043				}
1044	
1045				if (param->adc2_flag == ADC_AUDIO_ROUTE_MIC) {
1046					snd_codec_update_bits(codec, SUNXI_ADC2_ANA_CTL,
1047							      0x1<<ADC_EN,
1048							      0x1<<ADC_EN);
1049				} else if (param->adc2_flag == ADC_AUDIO_ROUTE_LINEIN ||
1050						param->adc2_flag == ADC_AUDIO_ROUTE_FMIN) {
1051	
1052					snd_codec_update_bits(codec, SUNXI_ADC2_ANA_CTL,
1053							      0x1F<<ADC_PGA_GAIN_CTL,
1054							      0x00<<ADC_PGA_GAIN_CTL);
1055	
1056					snd_codec_update_bits(codec, SUNXI_ADC2_ANA_CTL,
1057							      0x1<<MIC_SIN_EN,
1058							      0x1<<MIC_SIN_EN);
1059	
1060					snd_codec_update_bits(codec, SUNXI_ADC2_ANA_CTL,
1061							      0x1<<ADC_EN,
1062							      0x1<<ADC_EN);
1063				}
1064	
1065				if (param->adc3_flag) {
1066					snd_codec_update_bits(codec, SUNXI_ADC3_ANA_CTL,
1067							      0x1<<ADC_EN,
1068							      0x1<<ADC_EN);
1069				}

1130				/* digital ADC enable */
1131				snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
1132						(0x1<<EN_AD), (0x0<<EN_AD));
1133			}
1134		}
1135		substream->dapm_state = onoff;
1136		return 0;
1137	}
