1148	static int sunxi_codec_hw_params(struct snd_pcm_substream *substream,
1149			struct snd_pcm_hw_params *params, struct snd_dai *dai)
1150	{
1151		struct snd_codec *codec = dai->component;
1152		struct sunxi_codec_info *sunxi_codec = codec->private_data;
1153		struct sunxi_codec_param *codec_param = &sunxi_codec->param;
1154		int i = 0;
1155	
1156		snd_print("\n");
1157		switch (params_format(params)) {
1158		case	SND_PCM_FORMAT_S16_LE:
1159			if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
1160				snd_codec_update_bits(codec, SUNXI_DAC_FIFOC,
1161					(3 << FIFO_MODE), (3 << FIFO_MODE));
1162				snd_codec_update_bits(codec, SUNXI_DAC_FIFOC,
1163					(1 << TX_SAMPLE_BITS), (0 << TX_SAMPLE_BITS));
1164			} else {
1165				snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
1166					(1 << RX_FIFO_MODE), (1 << RX_FIFO_MODE));
1167				snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
1168					(1 << RX_SAMPLE_BITS), (0 << RX_SAMPLE_BITS));
1169			}
1170			break;
1171		case	SND_PCM_FORMAT_S24_LE:
