1365		case SNDRV_PCM_TRIGGER_SUSPEND:
1366		case SNDRV_PCM_TRIGGER_PAUSE_PUSH:
1367			if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
1368				snd_codec_update_bits(codec, SUNXI_DAC_FIFOC,
1369					(1 << DAC_DRQ_EN), (0 << DAC_DRQ_EN));
1370			}
1371			else if (substream->stream == SNDRV_PCM_STREAM_CAPTURE) {
1372				snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
