384	static int snd_pcm_release_substream(struct snd_pcm *pcm, int stream)
385	{
386		struct snd_pcm_substream *substream;
387		struct snd_pcm_runtime *runtime;
388	
389		substream = pcm->streams[stream];
390		if (!substream)
391			return -ENODEV;
392	
393		substream->ref_count--;
394		if (substream->ref_count > 0)
395			return 0;
396	
397		if (substream->hw_opened) {
398			if (substream->ops->hw_free &&
399			    substream->runtime->status->state != SNDRV_PCM_STATE_OPEN)
400				substream->ops->hw_free(substream);
401			substream->ops->close(substream);
402			substream->ref_count = 0;
403			substream->hw_opened = 0;
404		}
405	
406		runtime = substream->runtime;
407		snd_free(runtime->hw_constrains.rules);
408		if (runtime->status) {
409			snd_free(runtime->status);
410			runtime->status = NULL;
411		}
412		if (runtime->control) {
413			snd_free(runtime->control);
414			runtime->control = NULL;
415		}
416		if (runtime->pcm_mutex) {
417			snd_mutex_destroy(runtime->pcm_mutex);
418			runtime->pcm_mutex = NULL;
419		}
420		if (runtime->tsleep) {
421			snd_schd_destroy(runtime->tsleep);
422			runtime->tsleep = NULL;
423		}
424		if (runtime->sleep) {
425			snd_schd_destroy(runtime->sleep);
426			runtime->sleep = NULL;
427		}
428		if (runtime->dsleep) {
429			snd_schd_destroy(runtime->dsleep);
430			runtime->dsleep = NULL;
431		}
432		snd_free(runtime);
433		substream->runtime = NULL;
434	
435		return 0;
436	}
