425	static void poll_timer_cb(lv_timer_t *timer)
426	{
427	    static int heartbeat;
428	
429	    (void)timer;
430	
431	    /* Liveness probe — logs once every ~10s (200ms period × 50). If this
432	     * stops after a TTS speak finishes, the LVGL thread has hung (screen
433	     * frozen), as opposed to a touch-only stall. */
434	    if (++heartbeat % 50 == 0)
435	      {
436	        syslog(LOG_INFO, "[kid_buddy] LVGL heartbeat #%d\n", heartbeat);
437	      }
438	
439	    /* Snapshot the latest LLM message under the same lock the callback uses,
440	     * so the status and text are read as one consistent pair (a torn read
441	     * could otherwise tag a stale short fragment as "final" and drop the
442	     * rest of the reply). */
443	    int  msg_status;
444	    char msg_text[MSG_BUF_LEN];
445	    bool have_msg = false;
446	
447	    pthread_mutex_lock(&g_msg_lock);
448	    if (g_msg_ready)
449	      {
