1047	/* Copy a [s, s+len) slice into a NUL-terminated string with leading
1048	 * whitespace stripped; returns NULL if nothing but whitespace remains. */
1049	static char* tts_slice_dup(const char* s, int len)
1050	{
1051	    char* d = malloc(len + 1);
1052	    if (!d) {
1053	        return NULL;
1054	    }
1055	    memcpy(d, s, len);
1056	    d[len] = '\0';
1057	
1058	    char* c = d;
1059	    while (*c == ' ' || *c == '\n' || *c == '\t' || *c == '\r') {
1060	        c++;
1061	    }
1062	    if (*c == '\0') {
1063	        free(d);
1064	        return NULL;
1065	    }
1066	    if (c != d) {
1067	        memmove(d, c, strlen(c) + 1);
1068	    }
1069	    return d;
1070	}
