114	static snd_pcm_format_t capture_format_from_bits(unsigned int bits_per_sample)
115	{
116	    switch (bits_per_sample) {
117	    case 16:
118	        return SND_PCM_FORMAT_S16_LE;
119	    case 24:
120	        return SND_PCM_FORMAT_S24_LE;
121	    default:
122	        return (snd_pcm_format_t)-1;
123	    }
124	}
