209	static int ensure_scratch_capacity(audio_capture_t* cap, size_t need)
210	{
211	    if (cap->scratch_size >= need) {
212	        return 0;
213	    }
214	
215	    unsigned char* scratch = realloc(cap->scratch, need);
216	    if (!scratch) {
217	        return -ENOMEM;
218	    }
219	
220	    cap->scratch = scratch;
221	    cap->scratch_size = need;
222	    return 0;
223	}
224	
225	static int alsa_read_frames(audio_capture_t* cap, void* buf,
226	    snd_pcm_uframes_t frames)
227	{
228	    snd_pcm_uframes_t done = 0;
229	    unsigned char* dst = buf;
230	
231	    while (done < frames) {
232	        snd_pcm_sframes_t ret = snd_vela_pcm_readi(cap->handle.pcm,
233	            dst + done * cap->hw_frame_bytes, frames - done);
234	
235	        if (ret == -EAGAIN) {
236	            usleep(10 * 1000);
237	            continue;
238	        }
239	
240	        if (ret == -EPIPE) {
241	            syslog(LOG_WARNING, "[%s] ALSA overrun, preparing capture\n",
242	                TAG);
243	            snd_vela_pcm_prepare(cap->handle.pcm);
244	            continue;
245	        }
246	
247	        if (ret == -ESTRPIPE) {
248	            continue;
249	        }
250	
251	        if (ret < 0) {
252	            return done > 0 ? (int)done : (int)ret;
253	        }
254	
255	        done += (snd_pcm_uframes_t)ret;
256	    }
257	
258	    return (int)done;
259	}
260	
261	static void downmix_interleaved_s16_to_mono(audio_capture_t* cap,
262	    void* out_buf, const void* in_buf, size_t frames)
263	{
264	    int16_t* out = out_buf;
265	    const int16_t* in = in_buf;
266	
267	    for (size_t i = 0; i < frames; i++) {
268	        int32_t mixed = 0;
269	
270	        for (unsigned int ch = 0; ch < cap->hw_channels; ch++) {
271	            mixed += in[i * cap->hw_channels + ch];
272	        }
273	
274	        out[i] = (int16_t)(mixed / (int32_t)cap->hw_channels);
275	    }
276	}
277	
278	static int open_alsa_capture(audio_capture_t* cap, const char* dev_path,
279	    unsigned int sample_rate, unsigned int channels,
280	    unsigned int bits_per_sample)
281	{
282	    const char* alsa_name = resolve_alsa_name(dev_path);
283	    snd_pcm_format_t format = capture_format_from_bits(bits_per_sample);
284	    unsigned int attempts[2];
285	    int attempt_count = 0;
286	    int last_ret = -ENODEV;
287	
288	    if ((int)format < 0) {
289	        return -ENOTSUP;
290	    }
291	
292	    attempts[attempt_count++] = channels;
293	    if (channels == 1) {
294	        attempts[attempt_count++] = 3;
295	    }
296	
297	    for (int i = 0; i < attempt_count; i++) {
298	        snd_pcm_t* pcm = NULL;
299	        unsigned int hw_channels = attempts[i];
300	        int ret = snd_vela_pcm_open(&pcm, alsa_name,
301	            SND_VELA_PCM_STREAM_CAPTURE, 0);
302	
303	        if (ret < 0) {
304	            last_ret = ret;
305	            continue;
306	        }
307	
308	        ret = configure_alsa_capture(pcm, format, sample_rate, hw_channels);
309	        if (ret < 0) {
310	            snd_vela_pcm_close(pcm);
311	            last_ret = ret;
312	            continue;
313	        }
314	
315	        cap->backend = AUDIO_CAPTURE_BACKEND_ALSA;
316	        cap->handle.pcm = pcm;
317	        cap->bits_per_sample = bits_per_sample;
318	        cap->requested_channels = channels;
319	        cap->hw_channels = hw_channels;
320	        cap->out_frame_bytes = (bits_per_sample / 8) * channels;
321	        cap->hw_frame_bytes = snd_vela_pcm_frames_to_bytes(pcm, 1);
322	
323	        syslog(LOG_INFO,
324	            "[%s] opened direct ALSA capture (%s, %uHz, req=%uch, hw=%uch, %ubit)\n",
325	            TAG, alsa_name, sample_rate, channels, hw_channels,
326	            bits_per_sample);
327	        return 0;
328	    }
329	
330	    return last_ret;
331	}
