147	
148	static void preproc_chunk(audio_preproc_t* pp,
149	    unsigned char* buf, int bytes)
150	{
151	    if (!pp || (!pp->ns && !pp->agc)) {
152	        return;
153	    }
154	
155	    int16_t* samples = (int16_t*)buf;
156	    int total = bytes / 2;
157	    int fsz = PREPROC_FRAME_SIZE;
158	    int32_t in32[PREPROC_FRAME_SIZE];
159	    int32_t ref32[PREPROC_FRAME_SIZE];
160	    int32_t out32[PREPROC_FRAME_SIZE];
161	
162	    memset(ref32, 0, sizeof(ref32));
163	
164	    for (int off = 0; off < total; off += fsz) {
165	        int n = (off + fsz <= total) ? fsz : (total - off);
166	
167	        for (int i = 0; i < n; i++) {
168	            in32[i] = samples[off + i];
169	        }
170	
171	        if (pp->ns) {
172	            ec2float_process(pp->ns, in32, ref32, n, out32);
173	        } else {
174	            memcpy(out32, in32, n * sizeof(int32_t));
175	        }
176	
177	        if (pp->agc) {
178	            for (int i = 0; i < n; i++) {
179	                out32[i] <<= 8;
180	            }
181	            compexp_process_int24(pp->agc, out32, n);
182	            for (int i = 0; i < n; i++) {
183	                out32[i] >>= 8;
184	            }
185	        }
186	
187	        for (int i = 0; i < n; i++) {
188	            int32_t v = out32[i];
189	            if (v > 32767) {
190	                v = 32767;
191	            } else if (v < -32768) {
192	                v = -32768;
193	            }
194	            samples[off + i] = (int16_t)v;
195	        }
196	    }
197	}
