228	/* ── File-based helpers (kept for QEMU test commands) ──── */
229	
230	static int read_pcm_file(const char* path,
231	    unsigned char** out, size_t* out_len)
232	{
233	    int fd = open(path, O_RDONLY);
234	
235	    if (fd < 0) {
236	        syslog(LOG_ERR, "[%s] Cannot open %s: %d\n",
237	            TAG, path, errno);
238	        return -errno;
239	    }
240	
241	    off_t fsize = lseek(fd, 0, SEEK_END);
242	
243	    if (fsize <= 0 || (size_t)fsize > AGENT_VOICE_PCM_BUF_SIZE) {
244	        syslog(LOG_ERR, "[%s] File too large or empty: %ld\n",
245	            TAG, (long)fsize);
246	        close(fd);
247	        return -EFBIG;
248	    }
249	
250	    lseek(fd, 0, SEEK_SET);
251	
252	    unsigned char* buf = malloc((size_t)fsize);
253	
254	    if (!buf) {
255	        close(fd);
256	        return -ENOMEM;
257	    }
258	
259	    ssize_t nread = read(fd, buf, (size_t)fsize);
260	
261	    close(fd);
262	
263	    if (nread != (ssize_t)fsize) {
264	        free(buf);
265	        return -EIO;
266	    }
267	
268	    *out = buf;
269	    *out_len = (size_t)fsize;
270	    return 0;
271	}
272	
273	static int write_pcm_file(const char* path,
274	    const unsigned char* data, size_t len)
275	{
276	    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
277	
278	    if (fd < 0) {
279	        syslog(LOG_ERR, "[%s] Cannot create %s: %d\n",
280	            TAG, path, errno);
281	        return -errno;
282	    }
283	
284	    ssize_t nw = write(fd, data, len);
285	
286	    close(fd);
287	    return (nw == (ssize_t)len) ? 0 : -EIO;
288	}
