290	/* ── Recording cleanup helper ────────────────────────────── */
291	
292	static void recording_cleanup_locked(voice_asr_stream_t* stream)
293	{
294	    /* Abort streaming ASR if active */
295	    if (stream) {
296	        voice_asr_stream_abort(stream);
297	        s_voice.asr_stream = NULL;
298	    }
299	
300	    /* Close capture device */
301	    if (s_voice.cap) {
302	        audio_capture_close(s_voice.cap);
303	        s_voice.cap = NULL;
304	    }
305	
306	    /* Free PCM buffer */
307	    free(s_voice.pcm_buf);
308	    s_voice.pcm_buf = NULL;
309	    s_voice.pcm_len = 0;
310	
311	    /* Reset state to IDLE */
312	    s_voice.state = VOICE_IDLE;
313	}
314	
315	/* Allocate fallback PCM buffer (must hold lock) */
316	static int alloc_fallback_buffer_locked(void)
317	{
318	    if (s_voice.pcm_buf) {
319	        return 0;
320	    }
321	
322	    s_voice.pcm_buf = malloc(s_voice.pcm_cap);
323	    if (!s_voice.pcm_buf) {
324	        syslog(LOG_ERR, "[%s] fallback buffer alloc failed\n", TAG);
325	        return -ENOMEM;
326	    }
327	
328	    s_voice.pcm_len = 0;
329	    return 0;
330	}
331	
332	/* Accumulate PCM chunk to fallback buffer (must hold lock) */
333	static void accumulate_pcm_locked(const unsigned char* chunk, size_t len)
334	{
335	    if (s_voice.pcm_buf && s_voice.pcm_len + len <= s_voice.pcm_cap) {
336	        memcpy(s_voice.pcm_buf + s_voice.pcm_len, chunk, len);
337	        s_voice.pcm_len += len;
338	    }
339	}
340	
341	/* Process one audio chunk: send to ASR or accumulate for fallback */
342	static int process_audio_chunk(voice_asr_stream_t** stream_ptr,
343	    const unsigned char* chunk, size_t len, int* need_fallback,
344	    size_t* bytes_sent)
345	{
346	    if (*need_fallback) {
347	        pthread_mutex_lock(&s_voice.lock);
348	        accumulate_pcm_locked(chunk, len);
349	        pthread_mutex_unlock(&s_voice.lock);
350	    }
351	
352	    if (*stream_ptr) {
353	        int ret = voice_asr_stream_send(*stream_ptr, chunk, len);
354	
355	        if (ret != 0) {
356	            syslog(LOG_ERR,
357	                "[%s] stream send failed: %d, batch fallback\n", TAG, ret);
358	            voice_asr_stream_abort(*stream_ptr);
359	            *stream_ptr = NULL;
360	            *need_fallback = 1;
361	
362	            pthread_mutex_lock(&s_voice.lock);
363	            alloc_fallback_buffer_locked();
364	            pthread_mutex_unlock(&s_voice.lock);
365	        } else {
366	            *bytes_sent += len;
367	        }
368	    }
369	
370	    return 0;
371	}
372	
373	/* ── Recording thread (PTT mode — streaming ASR) ─────────── */
374	
375	static void* recording_thread(void* arg)
376	{
377	    (void)arg;
378	    unsigned char chunk[AGENT_ASR_CHUNK_SIZE];
379	    int need_fallback = 0;
380	    // int dump_fd = -1;
381	    size_t total_bytes_read = 0;
382	    size_t total_bytes_sent = 0;
383	    int chunk_count = 0;
384	    int abnormal_exit = 0;
385	
386	    syslog(LOG_INFO, "[%s] recording thread started (streaming)\n", TAG);
387	
388	    /* Use pre-connected ASR stream if available (opened in
389	     * voice_channel_start to avoid TLS handshake delay during
390	     * recording).  Fall back to opening a new session if not. */
391	    pthread_mutex_lock(&s_voice.lock);
392	    voice_asr_stream_t* stream = s_voice.asr_stream;
393	    s_voice.asr_stream = NULL; /* thread now owns it */
394	    pthread_mutex_unlock(&s_voice.lock);
395	
396	    if (!stream) {
397	        /* No pre-connected stream — open now (may lose first 300-800ms) */
398	        stream = voice_asr_stream_open();
399	        syslog(LOG_WARNING,
400	            "[%s] streaming ASR unavailable, batch fallback\n", TAG);
401	        need_fallback = 1;
402	
403	        pthread_mutex_lock(&s_voice.lock);
404	        if (alloc_fallback_buffer_locked() != 0) {
405	            s_voice.state = VOICE_IDLE;
406	            pthread_mutex_unlock(&s_voice.lock);
407	            sem_post(&s_voice.rec_ready);
408	            return NULL;
409	        }
410	        pthread_mutex_unlock(&s_voice.lock);
411	    } else {
412	        syslog(LOG_INFO, "[%s] using pre-connected ASR stream\n", TAG);
413	    }
414	
415	    /* Signal voice_channel_start() that we are ready to consume
416	     * audio frames. Without this, sem_wait in start() deadlocks. */
417	    sem_post(&s_voice.rec_ready);
418	
419	    /* No flush needed: the new start sequence guarantees that
420	     * audio_capture_start() runs AFTER this thread is ready,
421	     * so there is no stale data in the queue. The old flush
422	     * was harmful — audio_capture_read() blocks, so it would
423	     * consume real audio frames instead of stale ones. */
424	
425	    while (1) {
426	        pthread_mutex_lock(&s_voice.lock);
427	        enum voice_state st = s_voice.state;
428	        pthread_mutex_unlock(&s_voice.lock);
429	
430	        if (st != VOICE_RECORDING) {
431	            break;
432	        }
433	
434	        int n = audio_capture_read(s_voice.cap,
435	            chunk, sizeof(chunk));
436	
437	        if (n == -EAGAIN || n == -EWOULDBLOCK) {
438	            /* Non-blocking capture socket has no data yet (common right
439	             * after start before the first frames arrive). Retry instead
440	             * of treating it as a fatal error. */
441	            usleep(10000);
442	            continue;
443	        }
444	
445	        if (n <= 0) {
446	            syslog(LOG_WARNING,
447	                "[%s] capture read returned %d, stopping\n", TAG, n);
448	            abnormal_exit = 1;
449	            break;
450	        }
451	
452	        total_bytes_read += (size_t)n;
453	        chunk_count++;
454	
455	        /* Dump raw PCM to file */
456	        // if (dump_fd >= 0) {
457	        //     write(dump_fd, chunk, (size_t)n);
458	        // }
459	
460	        /* Log audio level for first few chunks and periodically
461	         * to diagnose silence vs actual speech from QEMU mic. */
462	        if (chunk_count <= 3 || chunk_count % 50 == 0) {
463	            int16_t* samples = (int16_t*)chunk;
464	            int sample_count = n / 2;
465	            int32_t peak = 0;
466	
467	            for (int i = 0; i < sample_count; i++) {
468	                int32_t v = samples[i] < 0 ? -samples[i] : samples[i];
469	                if (v > peak) {
470	                    peak = v;
471	                }
472	            }
473	            syslog(LOG_INFO,
474	                "[%s] chunk#%d: %d bytes, peak=%ld\n",
475	                TAG, chunk_count, n, (long)peak);
476	        }
477	
478	#ifdef CONFIG_AI_AGENT_AUDIO_PREPROCESS
479	        preproc_chunk(pp, chunk, n);
480	#endif
481	
482	        process_audio_chunk(&stream, chunk, (size_t)n,
483	            &need_fallback, &total_bytes_sent);
484	    }
485	
486	#ifdef CONFIG_AI_AGENT_AUDIO_PREPROCESS
487	    preproc_destroy(pp);
488	#endif
489	
490	    /* Store stream handle for voice_channel_stop to finish */
491	    // if (dump_fd >= 0) {
492	    //     close(dump_fd);
493	    //     syslog(LOG_INFO, "[%s] PCM dump saved to /data/cap_dump.pcm\n", TAG);
494	    // }
495	
496	    pthread_mutex_lock(&s_voice.lock);
497	    s_voice.asr_stream = stream;
498	
499	    if (abnormal_exit && s_voice.state == VOICE_RECORDING) {
500	        syslog(LOG_WARNING, "[%s] abnormal exit, cleaning up\n", TAG);
501	        recording_cleanup_locked(stream);
502	    }
503	    pthread_mutex_unlock(&s_voice.lock);
504	
505	    syslog(LOG_INFO,
506	        "[%s] recording thread exit: %d chunks, %zu read, %zu sent%s\n",
507	        TAG, chunk_count, total_bytes_read, total_bytes_sent,
508	        abnormal_exit ? " (abnormal)" : "");
509	    return NULL;
510	}
