512	/* ── ASR worker thread ──────────────────────────────────── */
513	
514	#define ASR_THREAD_STACK (24 * 1024)
515	
516	static void* asr_and_dispatch(void* arg)
517	{
518	    unsigned char* pcm = (unsigned char*)arg;
519	    size_t pcm_len;
520	
521	    /* pcm_len is stored in the first sizeof(size_t) bytes */
522	    memcpy(&pcm_len, pcm, sizeof(size_t));
523	    const unsigned char* audio = pcm + sizeof(size_t);
524	
525	    syslog(LOG_INFO, "[%s] ASR: recognizing %zu bytes\n",
526	        TAG, pcm_len);
527	
528	    char text[512];
529	    int ret = voice_asr_recognize(audio, pcm_len,
530	        text, sizeof(text));
531	
532	    if (ret == 0 && text[0] != '\0') {
533	        syslog(LOG_INFO, "[%s] ASR result: %s\n", TAG, text);
534	        printf("ASR: %s\n", text);
535	
536	        agent_msg_t msg;
537	
538	        memset(&msg, 0, sizeof(msg));
539	        strncpy(msg.channel, AGENT_CHAN_VOICE,
540	            sizeof(msg.channel) - 1);
541	        strncpy(msg.chat_id, "voice",
542	            sizeof(msg.chat_id) - 1);
543	        msg.content = strdup(text);
544	        if (msg.content) {
545	            message_bus_push_inbound(&msg);
546	        }
547	    } else {
548	        syslog(LOG_WARNING, "[%s] ASR failed or empty: %d\n",
549	            TAG, ret);
550	    }
551	
552	    free(pcm);
553	    return NULL;
554	}
