558	/* s_tts_start is set at the top of voice_channel_speak(); s_tts_first_chunk
559	 * is cleared there and set by the first PCM chunk captured during the
560	 * fetch-then-play pipeline (see tts_capture_cb below). */
561	static struct timespec s_tts_start;
562	static int s_tts_first_chunk;
563	static struct timespec s_asr_done_ts;
