567	int voice_channel_init(void)
568	{
569	    syslog(LOG_INFO, "[%s] Voice channel initializing\n", TAG);
570	
571	    /* Reset state on init — static vars may persist across process restarts
572	     * in NuttX depending on how the binary is loaded. */
573	    s_voice.state = VOICE_IDLE;
574	    s_voice.cap = NULL;
575	    s_voice.pcm_buf = NULL;
576	    s_voice.pcm_len = 0;
577	    s_voice.asr_stream = NULL;
578	    s_voice.tts_abort = 0;
579	    s_voice.tts_pb = NULL;
580	    sem_init(&s_voice.rec_ready, 0, 0);
581	
582	    if (!s_backends_registered) {
583	        /* MiMo first so it becomes the default active TTS backend. */
584	        mimo_tts_register();
585	        volc_tts_register();
586	        volc_asr_register();
587	        s_backends_registered = 1;
588	    }
589	
590	    return 0;
591	}
592	
593	int voice_channel_start(void)
594	{
595	    pthread_mutex_lock(&s_voice.lock);
596	    if (s_voice.state != VOICE_IDLE) {
597	        pthread_mutex_unlock(&s_voice.lock);
598	        syslog(LOG_WARNING, "[%s] already recording\n", TAG);
599	        return -EBUSY;
600	    }
601	
602	    /* Drain stale sem posts from previous sessions to prevent
603	     * sem_wait returning immediately before thread is ready. */
604	    while (sem_trywait(&s_voice.rec_ready) == 0)
605	        ;
606	
607	    /* ── AEC workaround: stop active TTS to prevent echo ── */
608	    if (s_voice.tts_pb) {
609	        syslog(LOG_INFO,
610	            "[%s] PTT: stopping active TTS to prevent echo\n", TAG);
611	        s_voice.tts_abort = 1;
612	        audio_playback_stop(s_voice.tts_pb);
613	
614	        /* Release lock so the speak thread can finish closing the
615	         * playback device.  Without this, we hold the lock through
616	         * the entire ASR pre-connect (300-800ms), blocking the speak
617	         * thread from calling audio_playback_close().  The playback
618	         * device stays open while we open the capture device, and on
619	         * BES hardware the shared codec (ci2s) gets confused, causing
620	         * incomplete or corrupted recording. */
621	        pthread_mutex_unlock(&s_voice.lock);
622	
623	        /* Wait for the speak thread to finish — speak_lock is held
624	         * for the entire duration of voice_channel_speak(). */
625	        pthread_mutex_lock(&s_voice.speak_lock);
626	        pthread_mutex_unlock(&s_voice.speak_lock);
627	
628	        syslog(LOG_INFO,
629	            "[%s] PTT: TTS playback fully closed\n", TAG);
630	
631	        /* Re-acquire state lock and re-check — another thread may
632	         * have started recording while we released the lock. */
633	        pthread_mutex_lock(&s_voice.lock);
634	        if (s_voice.state != VOICE_IDLE) {
635	            pthread_mutex_unlock(&s_voice.lock);
636	            syslog(LOG_WARNING, "[%s] state changed during TTS stop\n", TAG);
637	            return -EBUSY;
638	        }
639	    }
640	
641	    /* PCM buffer is lazy-allocated only when streaming ASR fails
642	     * (batch fallback). This saves 128KB RAM on the happy path. */
643	    s_voice.pcm_cap = AGENT_VOICE_PCM_BUF_SIZE;
644	    s_voice.pcm_buf = NULL;
645	    s_voice.pcm_len = 0;
646	    s_voice.asr_stream = NULL;
647	
648	    /* Pre-open streaming ASR session HERE (before spawning the
649	     * recording thread) so that TLS handshake (~300-800ms) completes
650	     * before audio capture starts.  Without this, the handshake runs
651	     * inside recording_thread while audio is already flowing, causing
652	     * the first 300-800ms of speech to be lost.
653	     *
654	     * If the pre-open fails we fall back to batch mode as before. */
655	    voice_asr_stream_t* pre_stream = voice_asr_stream_open();
656	    if (!pre_stream) {
657	        syslog(LOG_WARNING,
658	            "[%s] pre-open ASR failed, will retry in thread\n", TAG);
659	    } else {
660	        syslog(LOG_INFO, "[%s] ASR pre-connected\n", TAG);
661	        s_voice.asr_stream = pre_stream;
662	    }
663	
664	    /* Open capture device (but do NOT start yet — start after the
665	     * recording thread is spawned so the consumer is ready before
666	     * audio frames begin flowing, preventing media_recorder queue
667	     * overflow "data queue is more than max count(4)"). */
668	    s_voice.cap = audio_capture_open(
669	        AGENT_AUDIO_CAPTURE_DEV,
670	        AGENT_VOICE_SAMPLE_RATE,
671	        AGENT_VOICE_CHANNELS,
672	        AGENT_VOICE_BITS);
673	
674	    if (!s_voice.cap) {
675	        if (pre_stream) {
676	            voice_asr_stream_abort(pre_stream);
677	            s_voice.asr_stream = NULL;
678	        }
679	        pthread_mutex_unlock(&s_voice.lock);
680	        syslog(LOG_ERR, "[%s] capture open failed\n", TAG);
681	        return -EIO;
682	    }
683	
684	    s_voice.state = VOICE_RECORDING;
685	    pthread_mutex_unlock(&s_voice.lock);
686	
687	    /* Spawn recording thread BEFORE starting capture */
688	    pthread_attr_t attr;
689	
690	    pthread_attr_init(&attr);
691	    pthread_attr_setstacksize(&attr, AGENT_VOICE_STACK);
692	
693	    int ret = pthread_create(&s_voice.rec_thread, &attr,
694	        recording_thread, NULL);
695	
696	    pthread_attr_destroy(&attr);
697	
698	    if (ret != 0) {
699	        pthread_mutex_lock(&s_voice.lock);
700	        s_voice.state = VOICE_IDLE;
701	        audio_capture_close(s_voice.cap);
702	        s_voice.cap = NULL;
703	        if (s_voice.asr_stream) {
704	            voice_asr_stream_abort(s_voice.asr_stream);
705	            s_voice.asr_stream = NULL;
706	        }
707	        free(s_voice.pcm_buf);
708	        s_voice.pcm_buf = NULL;
709	        pthread_mutex_unlock(&s_voice.lock);
710	        return -ret;
711	    }
712	
713	    /* Now start capture — wait for recording thread to be ready first */
714	    sem_wait(&s_voice.rec_ready);
715	
716	    if (audio_capture_start(s_voice.cap) < 0) {
717	        pthread_mutex_lock(&s_voice.lock);
718	        s_voice.state = VOICE_IDLE;
719	        if (s_voice.asr_stream) {
720	            voice_asr_stream_abort(s_voice.asr_stream);
721	            s_voice.asr_stream = NULL;
722	        }
723	        pthread_mutex_unlock(&s_voice.lock);
724	        audio_capture_abort(s_voice.cap);
725	        pthread_join(s_voice.rec_thread, NULL);
726	        audio_capture_close(s_voice.cap);
727	        s_voice.cap = NULL;
728	        return -EIO;
729	    }
730	
731	    syslog(LOG_INFO, "[%s] PTT recording started\n", TAG);
732	    printf("Voice: recording... (use voice_stop to finish)\n");
733	    return 0;
734	}
735	
736	int voice_channel_stop(void)
737	{
738	    pthread_mutex_lock(&s_voice.lock);
739	    if (s_voice.state != VOICE_RECORDING) {
740	        pthread_mutex_unlock(&s_voice.lock);
741	        return -EINVAL;
742	    }
743	    s_voice.state = VOICE_STOPPING;
744	    pthread_mutex_unlock(&s_voice.lock);
745	
746	    audio_capture_abort(s_voice.cap);
747	
748	    /* Wait for recording thread to finish */
749	    pthread_join(s_voice.rec_thread, NULL);
750	
751	    /* Close capture device */
752	    audio_capture_close(s_voice.cap);
753	
754	    pthread_mutex_lock(&s_voice.lock);
755	    s_voice.cap = NULL;
756	    size_t pcm_len = s_voice.pcm_len;
757	    voice_asr_stream_t* stream = s_voice.asr_stream;
758	    s_voice.asr_stream = NULL;
759	    s_voice.state = VOICE_IDLE;
760	    pthread_mutex_unlock(&s_voice.lock);
761	
762	    syslog(LOG_INFO, "[%s] recorded %zu bytes (stream=%p)\n",
763	        TAG, pcm_len, (void*)stream);
764	
765	    /* If streaming ASR was active, finish it to get result.
766	     * Note: in streaming mode pcm_len is always 0 because audio
767	     * goes directly to the ASR server, not to pcm_buf. */
768	    if (stream) {
769	        printf("Voice: streaming ASR active, finishing...\n");
770	        struct timespec asr_t0;
771	        clock_gettime(CLOCK_MONOTONIC, &asr_t0);
772	        char text[512];
773	        int ret = voice_asr_stream_finish(stream, text,
774	            sizeof(text));
775	        struct timespec asr_t1;
776	        clock_gettime(CLOCK_MONOTONIC, &asr_t1);
777	        long asr_ms = (asr_t1.tv_sec - asr_t0.tv_sec) * 1000
778	            + (asr_t1.tv_nsec - asr_t0.tv_nsec) / 1000000;
779	        syslog(LOG_INFO, "[%s] ASR finish: %ldms\n", TAG, asr_ms);
780	
781	        free(s_voice.pcm_buf); /* may be NULL */
782	        s_voice.pcm_buf = NULL;
783	
784	        if (ret == 0 && text[0] != '\0') {
785	            syslog(LOG_INFO, "[%s] stream ASR: %s\n", TAG, text);
786	            printf("ASR: %s\n", text);
787	            clock_gettime(CLOCK_MONOTONIC, &s_asr_done_ts);
788	
789	            agent_msg_t msg;
790	
791	            memset(&msg, 0, sizeof(msg));
792	            strncpy(msg.channel, AGENT_CHAN_VOICE,
793	                sizeof(msg.channel) - 1);
794	            strncpy(msg.chat_id, "voice",
795	                sizeof(msg.chat_id) - 1);
796	            msg.content = strdup(text);
797	            if (msg.content) {
798	                message_bus_push_inbound(&msg);
799	            }
800	        } else {
801	            syslog(LOG_WARNING,
802	                "[%s] stream ASR failed: %d\n", TAG, ret);
803	        }
804	        return 0;
805	    }
806	
807	    /* Batch fallback: pcm_buf must exist if we reach here */
808	    if (!s_voice.pcm_buf || pcm_len == 0) {
809	        free(s_voice.pcm_buf);
810	        s_voice.pcm_buf = NULL;
811	        syslog(LOG_ERR, "[%s] no PCM data for batch ASR\n", TAG);
812	        return -ENODATA;
813	    }
814	
815	    /* Batch fallback: pack pcm_len + audio for ASR thread */
816	    size_t total = sizeof(size_t) + pcm_len;
817	    unsigned char* pkg = malloc(total);
818	
819	    if (!pkg) {
820	        free(s_voice.pcm_buf);
821	        s_voice.pcm_buf = NULL;
822	        return -ENOMEM;
823	    }
824	
825	    memcpy(pkg, &pcm_len, sizeof(size_t));
826	    memcpy(pkg + sizeof(size_t), s_voice.pcm_buf, pcm_len);
827	    free(s_voice.pcm_buf);
828	    s_voice.pcm_buf = NULL;
829	
830	    /* Spawn ASR worker thread */
831	    int ret = agent_task_create(asr_and_dispatch, "asr_worker",
832	        ASR_THREAD_STACK, pkg, AGENT_VOICE_PRIO);
833	
834	    if (ret != OK) {
835	        free(pkg);
836	        return -EIO;
837	    }
838	
839	    return 0;
840	}
