842	int voice_channel_stop_with_text(char* text_out, size_t text_cap)
843	{
844	    if (!text_out || text_cap == 0) {
845	        return -EINVAL;
846	    }
847	
848	    text_out[0] = '\0';
849	
850	    pthread_mutex_lock(&s_voice.lock);
851	    if (s_voice.state != VOICE_RECORDING) {
852	        pthread_mutex_unlock(&s_voice.lock);
853	        return -EINVAL;
854	    }
855	    s_voice.state = VOICE_STOPPING;
856	    pthread_mutex_unlock(&s_voice.lock);
857	
858	    audio_capture_abort(s_voice.cap);
859	
860	    /* Wait for recording thread to finish */
861	    pthread_join(s_voice.rec_thread, NULL);
862	
863	    /* Close capture device */
864	    audio_capture_close(s_voice.cap);
865	
866	    pthread_mutex_lock(&s_voice.lock);
867	    s_voice.cap = NULL;
868	    size_t pcm_len = s_voice.pcm_len;
869	    voice_asr_stream_t* stream = s_voice.asr_stream;
870	    s_voice.asr_stream = NULL;
871	    s_voice.state = VOICE_IDLE;
872	    pthread_mutex_unlock(&s_voice.lock);
873	
874	    syslog(LOG_INFO, "[%s] recorded %zu bytes (with_text, stream=%p)\n",
875	        TAG, pcm_len, (void*)stream);
876	
877	    /* Streaming ASR path: finish and copy text to caller.
878	     * In streaming mode audio goes directly to server, so
879	     * pcm_len may be 0 — that's OK, don't abort. */
880	    if (stream) {
881	        char text[512];
882	        int ret = voice_asr_stream_finish(stream, text,
883	            sizeof(text));
884	
885	        free(s_voice.pcm_buf);
886	        s_voice.pcm_buf = NULL;
887	
888	        if (ret == 0 && text[0] != '\0') {
889	            syslog(LOG_INFO, "[%s] stream ASR (with_text): %s\n",
890	                TAG, text);
891	            strncpy(text_out, text, text_cap - 1);
892	            text_out[text_cap - 1] = '\0';
893	        }
894	        return 0;
895	    }
896	
897	    /* Batch fallback: synchronous ASR inline (no thread) */
898	    if (!s_voice.pcm_buf || pcm_len == 0) {
899	        free(s_voice.pcm_buf);
900	        s_voice.pcm_buf = NULL;
901	        syslog(LOG_ERR, "[%s] no PCM data for batch ASR\n", TAG);
902	        return -ENODATA;
903	    }
904	
905	    syslog(LOG_INFO, "[%s] batch ASR (with_text): %zu bytes\n",
906	        TAG, pcm_len);
907	
908	    char text[512];
909	    int ret = voice_asr_recognize(s_voice.pcm_buf, pcm_len,
910	        text, sizeof(text));
911	
912	    free(s_voice.pcm_buf);
913	    s_voice.pcm_buf = NULL;
914	
915	    if (ret == 0 && text[0] != '\0') {
916	        syslog(LOG_INFO, "[%s] batch ASR result: %s\n", TAG, text);
917	        strncpy(text_out, text, text_cap - 1);
918	        text_out[text_cap - 1] = '\0';
919	    } else if (ret != 0) {
920	        syslog(LOG_WARNING, "[%s] batch ASR failed: %d\n",
921	            TAG, ret);
922	    }
923	
924	    return 0;
925	}
