751	
752	int main(int argc, char *argv[])
753	{
754	    lv_nuttx_dsc_t info;
755	    lv_nuttx_result_t result;
756	
757	    if (lv_is_initialized())
758	      {
759	        LV_LOG_ERROR("LVGL already initialized! aborting.");
760	        return -1;
761	      }
762	
763	#ifdef NEED_BOARDINIT
764	    boardctl(BOARDIOC_INIT, 0);
765	#endif
766	
767	    /* Step 1: Initialize LVGL */
768	    lv_init();
769	
770	    /* Step 2: Configure NuttX display backend */
771	    lv_nuttx_dsc_init(&info);
772	
773	#ifdef CONFIG_LV_USE_NUTTX_LCD
774	    info.fb_path = "/dev/lcd0";
775	#endif
776	
777	#ifdef CONFIG_INPUT_TOUCHSCREEN
778	    info.input_path = "/dev/input0";
779	#endif
780	
781	    lv_nuttx_init(&info, &result);
782	
783	    /* Necessary delay for LCD initialization timing */
784	    usleep(100000);
785	
786	    if (result.disp == NULL)
787	      {
788	        LV_LOG_ERROR("Display initialization failure!");
789	        return 1;
790	      }
791	
792	    /* Step 3: Connect to ai_agent daemon */
793	    g_agent_client = velaclaw_client_open("kid_buddy");
794	    if (g_agent_client != NULL)
795	      {
796	        g_agent_connected = true;
797	        LV_LOG_USER("Connected to AI Agent daemon.");
798	      }
799	    else
800	      {
801	        g_agent_connected = false;
802	        LV_LOG_WARN("AI Agent daemon not available. UI only mode.");
803	      }
804	
805	    /* Step 4: Create UI and start on role selection */
806	    ui_create_role_select();
807	    lv_scr_load(g_scr_role_select);
808	
809	    /* Step 5: Create poll timer to update UI from LLM callbacks */
810	    lv_timer_create(poll_timer_cb, 200, NULL);
811	
812	    /* Step 5b: Start the single TTS worker thread that speaks the streamed
813	     * reply sentence-by-sentence (serialized so it never aborts itself). */
814	    pthread_attr_t tts_attr;
815	
816	    pthread_attr_init(&tts_attr);
817	    pthread_attr_setstacksize(&tts_attr, 65536);
818	    pthread_t tts_tid;
819	
820	    if (pthread_create(&tts_tid, &tts_attr, tts_stream_worker, NULL) != 0)
821	      {
822	        syslog(LOG_ERR, "[kid_buddy] Failed to start TTS worker\n");
823	      }
824	    pthread_attr_destroy(&tts_attr);
825	
826	    /* Step 6: Main loop */
827	    while (1)
828	      {
829	        uint32_t idle = lv_timer_handler();
830	        idle = idle ? idle : 1;
831	        usleep(idle * 1000);
832	      }
833	
834	    return 0;
835	}
