103	/* ── Streaming ASR (delegates to volc_asr streaming API) ─────── */
104	
105	struct voice_asr_stream {
106	    volc_asr_stream_t* inner;
107	};
108	
109	voice_asr_stream_t* voice_asr_stream_open(void)
110	{
111	    if (!s_active) {
112	        syslog(LOG_ERR, "[%s] No ASR backend for streaming\n", TAG);
113	        return NULL;
114	    }
115	
116	    volc_asr_stream_t* inner = volc_asr_stream_open();
117	
118	    if (!inner) {
119	        return NULL;
120	    }
121	
122	    voice_asr_stream_t* s = calloc(1, sizeof(*s));
123	
124	    if (!s) {
125	        volc_asr_stream_abort(inner);
126	        return NULL;
127	    }
128	
129	    s->inner = inner;
130	    return s;
131	}
132	
133	int voice_asr_stream_send(voice_asr_stream_t* s,
134	    const unsigned char* pcm, size_t len)
135	{
136	    if (!s || !s->inner) {
137	        return -EINVAL;
138	    }
139	
140	    return volc_asr_stream_send(s->inner, pcm, len);
141	}
142	
143	int voice_asr_stream_finish(voice_asr_stream_t* s,
144	    char* text_out, size_t text_cap)
145	{
146	    if (!s) {
147	        return -EINVAL;
148	    }
149	
150	    int ret = volc_asr_stream_finish(s->inner, text_out, text_cap);
151	
152	    /* s->inner is freed by volc_asr_stream_finish */
153	    free(s);
154	    return ret;
155	}
156	
157	void voice_asr_stream_abort(voice_asr_stream_t* s)
158	{
159	    if (!s) {
160	        return;
161	    }
162	
163	    volc_asr_stream_abort(s->inner);
164	    free(s);
165	}
