17	/* mimo_tts.c - Xiaomi MiMo TTS backend (mimo-v2.5-tts preset voices).
18	 *
19	 * MiMo TTS rides the OpenAI-compatible /v1/chat/completions endpoint.
20	 * We reuse the LLM's api_key + llm_host config so no extra credentials
21	 * are needed. Output is "pcm16" = 24kHz PCM16LE mono, which matches
22	 * AGENT_TTS_WS_SAMPLE_RATE used by voice_channel_speak() playback. */
23	
24	#include "voice/mimo_tts.h"
25	#include "infra/config_store.h"
26	#include "infra/vela_tls.h"
27	#include "agent_compat.h"
28	#include "agent_config.h"
29	#include "voice/voice_tts.h"
30	
31	#include "cJSON.h"
32	#include "mbedtls/base64.h"
33	#include <errno.h>
34	#include <stdio.h>
35	#include <stdlib.h>
36	#include <stdint.h>
37	#include <string.h>
38	#include <syslog.h>
39	
40	static const char* TAG = "mimo_tts";
41	
42	/* MiMo preset voice (Chinese, female). */
43	#define MIMO_TTS_VOICE "冰糖"
44	
45	/* MiMo TTS model and audio format. */
46	#define MIMO_TTS_MODEL "mimo-v2.5-tts"
47	#define MIMO_TTS_FORMAT "pcm16"
48	
49	/* Default host for the Token Plan (tp-) key. Reuses llm_host when set. */
50	#define MIMO_TTS_DEFAULT_HOST "token-plan-cn.xiaomimimo.com"
51	#define MIMO_TTS_PATH "/v1/chat/completions"
52	
53	/* Response buffer: holds the full base64 audio for one utterance.
54	 * ~384KB base64 ≈ 4s of 24kHz/16-bit/mono speech. A long story sentence
55	 * (~30 Chinese chars ≈ 7s ≈ 450KB base64) needs more; 1MB covers it with
56	 * headroom while sentences are kept short by the caller's chunking. */
57	#define MIMO_TTS_RESP_SIZE (1024 * 1024)
58	
59	/* Base64 is decoded in segments so we never need a second full-size PCM
60	 * buffer. Segment size must stay a multiple of 4 to keep 3-byte groups
61	 * aligned across segment boundaries. */
62	#define MIMO_B64_SEG (16 * 1024)              /* 16384, multiple of 4 */
63	#define MIMO_PCM_SEG (MIMO_B64_SEG / 4 * 3)   /* 12288 bytes of PCM */
64	
65	/* Credentials loaded from config store (shared with the MiMo LLM). */
66	static char s_api_key[128];
67	static char s_host[128];
68	
69	static int mimo_tts_init(void)
70	{
71	    memset(s_api_key, 0, sizeof(s_api_key));
72	    memset(s_host, 0, sizeof(s_host));
73	
74	    claw_config_get(AGENT_CFG_KEY_API_KEY, s_api_key, sizeof(s_api_key));
75	
76	    if (claw_config_get(AGENT_CFG_KEY_LLM_HOST, s_host, sizeof(s_host))
77	            != OK
78	        || s_host[0] == '\0') {
79	        strncpy(s_host, MIMO_TTS_DEFAULT_HOST, sizeof(s_host) - 1);
80	    }
81	
82	    return 0;
83	}
84	
85	static char* build_tts_request(const char* text)
86	{
87	    cJSON* root = cJSON_CreateObject();
88	
89	    if (!root) {
90	        return NULL;
91	    }
92	
93	    cJSON_AddStringToObject(root, "model", MIMO_TTS_MODEL);
94	
95	    cJSON* messages = cJSON_CreateArray();
96	    cJSON* assistant = cJSON_CreateObject();
97	
98	    if (!messages || !assistant) {
99	        cJSON_Delete(root);
100	        return NULL;
101	    }
102	
103	    cJSON_AddStringToObject(assistant, "role", "assistant");
104	    cJSON_AddStringToObject(assistant, "content", text);
105	    cJSON_AddItemToArray(messages, assistant);
106	    cJSON_AddItemToObject(root, "messages", messages);
107	
108	    cJSON* audio = cJSON_CreateObject();
109	
110	    if (!audio) {
111	        cJSON_Delete(root);
112	        return NULL;
113	    }
114	
115	    cJSON_AddStringToObject(audio, "format", MIMO_TTS_FORMAT);
116	    cJSON_AddStringToObject(audio, "voice", MIMO_TTS_VOICE);
117	    cJSON_AddItemToObject(root, "audio", audio);
118	
119	    char* json_str = cJSON_PrintUnformatted(root);
120	
121	    cJSON_Delete(root);
122	    return json_str;
123	}
124	
125	/* One fetched TTS response. resp holds the raw HTTP body; root holds the
126	 * parsed JSON (the base64 string lives inside root, not resp). */
127	typedef struct {
128	    char* resp;      /* owned, caller frees */
129	    cJSON* root;     /* owned, caller frees */
130	    const char* b64; /* pointer into root's strings */
131	    size_t b64_len;
132	} mimo_audio_t;
133	
134	static void mimo_audio_free(mimo_audio_t* a)
135	{
136	    if (a->root) {
137	        cJSON_Delete(a->root);
138	    }
139	    free(a->resp);
140	    memset(a, 0, sizeof(*a));
141	}
142	
143	static int mimo_fetch_audio(const char* text, mimo_audio_t* out)
144	{
145	    memset(out, 0, sizeof(*out));
146	
147	    mimo_tts_init();
148	
149	    if (s_api_key[0] == '\0') {
150	        syslog(LOG_ERR, "[%s] API key not configured (set 'api_key')\n",
151	            TAG);
152	        return -ENOENT;
153	    }
154	
155	    char* body = build_tts_request(text);
156	
157	    if (!body) {
158	        syslog(LOG_ERR, "[%s] failed to build TTS request\n", TAG);
159	        return -ENOMEM;
160	    }
161	
162	    char auth[256];
163	    snprintf(auth, sizeof(auth), "Bearer %s", s_api_key);
164	
165	    /* NOTE: do NOT send "Connection: close". tls_write_request() already
166	     * emits "Connection: keep-alive", and a "close" header here would force
167	     * the server to drop the socket after every sentence. That made each
168	     * TTS sentence pay a fresh TCP+TLS handshake (~2-3s, or 10s+ on the
169	     * flaky MiMo edge), which is why a long story took ~50s to speak. */
170	    vela_header_t hdrs[] = {
171	        { "Authorization", auth },
172	        { "Content-Type", "application/json" },
173	        { NULL, NULL }
174	    };
175	
176	    char* resp = calloc(1, MIMO_TTS_RESP_SIZE);
177	
178	    if (!resp) {
179	        free(body);
180	        return -ENOMEM;
181	    }
182	
183	    syslog(LOG_INFO, "[%s] TTS request: text=%zu bytes host=%s\n",
184	        TAG, strlen(text), s_host);
185	
186	    size_t body_len;
187	    int status = vela_https_request(
188	        s_host, "443", "POST", MIMO_TTS_PATH, hdrs,
189	        body, strlen(body),
190	        resp, MIMO_TTS_RESP_SIZE, &body_len);
191	
192	    free(body);
193	
194	    if (status != 200) {
195	        syslog(LOG_ERR, "[%s] TTS HTTP %d: %.256s\n",
196	            TAG, status, resp);
197	        free(resp);
198	        return -EIO;
199	    }
200	
201	    if (body_len == 0) {
202	        syslog(LOG_ERR, "[%s] TTS: empty response body\n", TAG);
203	        free(resp);
204	        return -EPROTO;
205	    }
206	
207	    cJSON* root = cJSON_Parse(resp);
208	
209	    if (!root) {
210	        syslog(LOG_ERR, "[%s] TTS: bad JSON: %.256s\n", TAG, resp);
211	        free(resp);
212	        return -EPROTO;
213	    }
214	
215	    /* choices[0].message.audio.data */
216	    cJSON* choices = cJSON_GetObjectItem(root, "choices");
217	    cJSON* choice0 = (choices && cJSON_IsArray(choices))
218	        ? cJSON_GetArrayItem(choices, 0) : NULL;
219	    cJSON* msg = choice0 ? cJSON_GetObjectItem(choice0, "message") : NULL;
220	    cJSON* audio = msg ? cJSON_GetObjectItem(msg, "audio") : NULL;
221	    cJSON* data = audio ? cJSON_GetObjectItem(audio, "data") : NULL;
222	
223	    if (!data || !cJSON_IsString(data) || !data->valuestring[0]) {
224	        syslog(LOG_ERR, "[%s] TTS: no audio.data in response: %.256s\n",
225	            TAG, resp);
226	        cJSON_Delete(root);
227	        free(resp);
228	        return -EPROTO;
229	    }
230	
231	    out->resp = resp;
232	    out->root = root;
233	    out->b64 = data->valuestring;
234	    out->b64_len = strlen(data->valuestring);
235	    return 0;
236	}
237	
238	static int mimo_tts_synthesize(const char* text,
239	    unsigned char* pcm_out,
240	    size_t pcm_cap,
241	    size_t* pcm_len)
242	{
243	    if (!text || !pcm_out || !pcm_len) {
244	        return -EINVAL;
245	    }
246	
247	    *pcm_len = 0;
248	
249	    mimo_audio_t a;
250	    int ret = mimo_fetch_audio(text, &a);
251	
252	    if (ret != 0) {
253	        return ret;
254	    }
255	
256	    size_t olen = 0;
257	    int rc = mbedtls_base64_decode(pcm_out, pcm_cap, &olen,
258	        (const unsigned char*)a.b64, a.b64_len);
259	
260	    if (rc != 0) {
261	        syslog(LOG_ERR, "[%s] TTS: base64 decode failed: %d\n", TAG, rc);
262	        mimo_audio_free(&a);
263	        return (rc == MBEDTLS_ERR_BASE64_BUFFER_TOO_SMALL)
264	            ? -EFBIG : -EPROTO;
265	    }
266	
267	    *pcm_len = olen;
268	    mimo_audio_free(&a);
269	
270	    syslog(LOG_INFO, "[%s] TTS: synthesized %zu PCM bytes\n", TAG, olen);
271	    return 0;
272	}
273	
274	static int mimo_tts_synthesize_stream(const char* text,
275	    voice_tts_chunk_cb cb,
276	    void* user_data)
277	{
278	    if (!text || !cb) {
279	        return -EINVAL;
280	    }
281	
282	    mimo_audio_t a;
283	    int ret = mimo_fetch_audio(text, &a);
284	
285	    if (ret != 0) {
286	        return ret;
287	    }
288	
289	    unsigned char* pcm_seg = malloc(MIMO_PCM_SEG + 4);
290	
291	    if (!pcm_seg) {
292	        mimo_audio_free(&a);
293	        return -ENOMEM;
294	    }
295	
296	    size_t off = 0;
297	    int chunks = 0;
298	    int err = 0;
299	
300	    while (off < a.b64_len) {
301	        size_t chunk = a.b64_len - off;
302	
303	        if (chunk > MIMO_B64_SEG) {
304	            chunk = MIMO_B64_SEG;
305	        }
306	
307	        size_t olen = 0;
308	        int rc = mbedtls_base64_decode(pcm_seg, MIMO_PCM_SEG + 4, &olen,
309	            (const unsigned char*)(a.b64 + off), chunk);
310	
311	        if (rc != 0) {
312	            syslog(LOG_ERR,
313	                "[%s] stream: base64 decode failed at %zu: %d\n",
314	                TAG, off, rc);
315	            err = -EPROTO;
316	            break;
317	        }
318	
319	        if (olen > 0) {
320	            /* Halve playback volume: scale each 16-bit mono sample by
321	             * 0.5 (-6 dB). pcm_seg is our scratch buffer, so scale it in
322	             * place before handing it to the audio callback. */
323	            int16_t* s = (int16_t*)pcm_seg;
324	            size_t nsamp = olen / sizeof(int16_t);
325	            for (size_t i = 0; i < nsamp; i++) {
326	                s[i] = (int16_t)(s[i] / 2);
327	            }
328	            cb(pcm_seg, olen, 0, user_data);
329	            chunks++;
330	        }
331	
332	        off += chunk;
333	    }
334	
335	    if (chunks > 0 && err == 0) {
336	        cb(NULL, 0, 1, user_data);
337	    }
338	
339	    if (chunks == 0 && err == 0) {
