300	 * voice_channel_speak() call. This keeps a single ALSA open/close cycle and
301	 * lets voice_channel_speak() buffer the full reply for continuous playback. */
302	
303	static void *tts_stream_worker(void *arg)
304	{
305	    (void)arg;
306	
307	    for (;;)
308	      {
309	        char text[MSG_BUF_LEN];
310	        bool final = false;
311	        unsigned int epoch;
312	        size_t spoken;
313	
314	        pthread_mutex_lock(&g_tts_lock);
315	        while (!g_tts_pending_ready)
316	          {
317	            pthread_cond_wait(&g_tts_cond, &g_tts_lock);
318	          }
319	        strncpy(text, g_tts_pending, MSG_BUF_LEN - 1);
320	        text[MSG_BUF_LEN - 1] = '\0';
321	        final = g_tts_pending_final;
322	        epoch = g_tts_epoch;
323	        spoken = g_spoken_len;
324	        g_tts_pending_ready = false;
325	        g_tts_pending_final = false;
326	        pthread_mutex_unlock(&g_tts_lock);
327	
328	        size_t len = strlen(text);
329	
330	        if (spoken > len)
331	          {
332	            spoken = len; /* offset reset under us mid-speak */
333	          }
334	
335	        /* Speak the whole reply in one voice_channel_speak() call, and only
336	         * once the reply is complete (final). Speaking sentence-by-sentence
337	         * as the text streamed made the worker open/close the ALSA codec
338	         * once per fragment; the codec's external-speaker PA (gpio_spk) is
339	         * armed on the first open but not reliably re-armed on a later open
340	         * in the same response, so only the first sentence was audible. A
341	         * single open/prepare/write/close cycle is the sequence the codec
342	         * plays reliably, and voice_channel_speak() already buffers the full
343	         * reply (fetch-then-play) so the story reads continuously. We trade
344	         * a later first word for complete, continuous speech — the priority
345	         * for a child's toy. */
346	        if (!final)
347	          {
348	            continue;
349	          }
350	
351	        syslog(LOG_INFO,
352	               "[kid_buddy] tts_worker final=1 len=%d speak_whole\n",
353	               (int)len);
354	
355	        if (len > spoken)
356	          {
357	            voice_channel_speak(text);
358	
359	            pthread_mutex_lock(&g_tts_lock);
360	            /* Advance only if no newer question reset the offset mid-speak. */
361	            if (epoch == g_tts_epoch)
362	              {
363	                g_spoken_len = len;
364	              }
365	            pthread_mutex_unlock(&g_tts_lock);
366	          }
367	      }
368	
369	    return NULL;
370	}
371	
372	/* Enqueue the latest cumulative reply text for speaking. "latest wins" — a
373	 * newer fragment replaces an older one still waiting in the slot. */
374	static void enqueue_tts(const char *text, bool final)
375	{
376	    pthread_mutex_lock(&g_tts_lock);
377	    strncpy(g_tts_pending, text, MSG_BUF_LEN - 1);
378	    g_tts_pending[MSG_BUF_LEN - 1] = '\0';
379	    g_tts_pending_final = final;
380	    g_tts_pending_ready = true;
381	    syslog(LOG_INFO, "[kid_buddy] enqueue_tts final=%d len=%d\n",
382	           (int)final, (int)strlen(g_tts_pending));
383	    pthread_cond_signal(&g_tts_cond);
384	    pthread_mutex_unlock(&g_tts_lock);
385	}
386	
387	static void poll_timer_cb(lv_timer_t *timer)
388	{
389	    static int heartbeat;
390	
391	    (void)timer;
392	
393	    /* Liveness probe — logs once every ~10s (200ms period × 50). If this
394	     * stops after a TTS speak finishes, the LVGL thread has hung (screen
395	     * frozen), as opposed to a touch-only stall. */
396	    if (++heartbeat % 50 == 0)
397	      {
398	        syslog(LOG_INFO, "[kid_buddy] LVGL heartbeat #%d\n", heartbeat);
399	      }
400	
401	    /* Snapshot the latest LLM message under the same lock the callback uses,
402	     * so the status and text are read as one consistent pair (a torn read
403	     * could otherwise tag a stale short fragment as "final" and drop the
404	     * rest of the reply). */
405	    int  msg_status;
406	    char msg_text[MSG_BUF_LEN];
407	    bool have_msg = false;
408	
409	    pthread_mutex_lock(&g_msg_lock);
410	    if (g_msg_ready)
411	      {
412	        g_msg_ready = false;
413	        msg_status = g_msg_status;
414	        strncpy(msg_text, g_pending_msg, MSG_BUF_LEN - 1);
415	        msg_text[MSG_BUF_LEN - 1] = '\0';
416	        have_msg = true;
417	      }
418	    pthread_mutex_unlock(&g_msg_lock);
419	
420	    if (have_msg)
421	      {
422	        /* Hide spinner as soon as the first text arrives. */
423	        if (g_chat_spinner)
424	          {
425	            lv_obj_add_flag(g_chat_spinner, LV_OBJ_FLAG_HIDDEN);
426	          }
427	
428	        if (msg_status == 0 || msg_status == 1)
429	          {
430	            /* Show the running reply text. */
431	            lv_label_set_text(g_chat_msg_area, msg_text);
432	
433	            /* Feed the cumulative text to the TTS worker. Partial fragments
434	             * (status 1) are spoken sentence-by-sentence as they complete;
435	             * the final fragment (status 0) flushes the remainder. */
436	            enqueue_tts(msg_text, msg_status == 0);
437	
438	            if (msg_status == 0)
439	              {
440	                lv_label_set_text(g_chat_status, "Tap 'Ask me!' to continue");
441	              }
442	            else
443	              {
444	                lv_label_set_text(g_chat_status, "Replying...");
445	              }
446	          }
447	        else
448	          {
449	            lv_label_set_text(g_chat_msg_area, msg_text);
450	            lv_label_set_text(g_chat_status, "Error - check LLM config");
451	          }
452	      }
453	}
