static char *listen_one_utterance(void)
{
    audio_capture_t *cap = audio_capture_open(NULL, WAKE_SAMPLE_RATE, 1, 16);
    if (!cap) {
        syslog(LOG_ERR, "[kid_buddy] wake: capture open failed\n");
        return NULL;
    }

