    char text[MSG_BUF_LEN];
    int ret = voice_asr_recognize(pcm, pcm_len, text, sizeof(text));
    free(pcm);

    if (ret < 0 || text[0] == '\0') {
        syslog(LOG_WARNING, "[kid_buddy] wake: ASR failed/empty ret=%d\n", ret);
        return NULL;
    }

    char *result = strdup(text);
    return result;
}
