122	static int sunxi_get_adc_ch(struct snd_codec *codec)
123	{
124		uint32_t reg_val;
125		struct sunxi_codec_info *sunxi_codec = codec->private_data;
126		struct sunxi_codec_param *codec_param = &sunxi_codec->param;
127	
128		codec_param->adc1_flag = 0;
129		reg_val = snd_codec_read(codec, SUNXI_ADC1_ANA_CTL);
130	
131		if (reg_val & (1 << MIC_PGA_EN)) {
132			codec_param->adc1_flag = ADC_AUDIO_ROUTE_MIC;
133		} else if (reg_val & (1 << FMINL_EN)) {
134			codec_param->adc1_flag = ADC_AUDIO_ROUTE_FMIN;
135		} else if (reg_val & (1 << LINEINL_EN)) {
136			codec_param->adc1_flag = ADC_AUDIO_ROUTE_FMIN;
137		} else if (codec_param->adc1_flag != 0) {
138			codec_param->adc1_flag |= ADC_AUDIO_ROUTE_ON;
139		}
140	
141		codec_param->adc2_flag = 0;
142		reg_val = snd_codec_read(codec, SUNXI_ADC2_ANA_CTL);
143	
144		if (reg_val & (1 << MIC_PGA_EN)) {
145			codec_param->adc2_flag = ADC_AUDIO_ROUTE_MIC;
146		} else if (reg_val & (1 << FMINR_EN)) {
147			codec_param->adc2_flag = ADC_AUDIO_ROUTE_FMIN;
148		} else if (reg_val & (1 << LINEINR_EN)) {
149			codec_param->adc2_flag = ADC_AUDIO_ROUTE_FMIN;
150		} else if (codec_param->adc2_flag != 0) {
151			codec_param->adc2_flag |= ADC_AUDIO_ROUTE_ON;
152		}
153	
154		codec_param->adc3_flag = 0;
155		reg_val = snd_codec_read(codec, SUNXI_ADC3_ANA_CTL);
156	
157		if (reg_val & (1 << MIC_PGA_EN)) {
158			codec_param->adc3_flag = ADC_AUDIO_ROUTE_MIC;
159		} else if (codec_param->adc3_flag != 0) {
160			codec_param->adc3_flag |= ADC_AUDIO_ROUTE_ON;
161		}
162	
163		if (codec_param->adc1_flag || codec_param->adc2_flag ||
164			codec_param->adc3_flag)
165			return 0;
166	
167		return -1;
168	}
