1072				if (channels > 3 || channels < 1) {
1073					snd_err("unknown channels:%u\n", channels);
1074					return -EINVAL;
1075				}
1076	
1077				if ((param->adc1_flag & ADC_AUDIO_ROUTE_MIC) ||
1078					(param->adc2_flag & ADC_AUDIO_ROUTE_MIC) ||
