695	     * rest of the reply). */
696	    int  msg_status;
697	    char msg_text[MSG_BUF_LEN];
698	    bool have_msg = false;
699	
700	    pthread_mutex_lock(&g_msg_lock);
701	    if (g_msg_ready)
702	      {
703	        g_msg_ready = false;
704	        msg_status = g_msg_status;
705	        strncpy(msg_text, g_pending_msg, MSG_BUF_LEN - 1);
706	        msg_text[MSG_BUF_LEN - 1] = '\0';
707	        have_msg = true;
708	      }
709	    pthread_mutex_unlock(&g_msg_lock);
710	
711	    if (have_msg)
712	      {
713	        /* Hide spinner as soon as the first text arrives. */
714	        if (g_chat_spinner)
715	          {
716	            lv_obj_add_flag(g_chat_spinner, LV_OBJ_FLAG_HIDDEN);
717	          }
718	
719	        if (msg_status == 0 || msg_status == 1)
720	          {
721	            /* Show the running reply text. */
722	            lv_label_set_text(g_chat_msg_area, msg_text);
723	
724	            /* Feed the cumulative text to the TTS worker. Partial fragments
725	             * (status 1) are spoken sentence-by-sentence as they complete;
726	             * the final fragment (status 0) flushes the remainder. */
727	            enqueue_tts(msg_text, msg_status == 0);
728	
729	            if (msg_status == 0)
730	              {
731	                lv_label_set_text(g_chat_status, "Tap 'Ask me!' to continue");
732	              }
733	            else
734	              {
735	                lv_label_set_text(g_chat_status, "Replying...");
736	              }
737	          }
738	        else
739	          {
740	            lv_label_set_text(g_chat_msg_area, msg_text);
741	            lv_label_set_text(g_chat_status, "Error - check LLM config");
742	            g_reply_busy = 0;  /* LLM errored out, release the wake loop */
743	          }
744	      }
