265	static void send_to_llm(const char *user_text)
266	{
267	    if (!g_agent_connected || g_agent_client == NULL)
268	      {
269	        lv_label_set_text(g_chat_status, "Agent offline - start 'ai_agent &' first");
270	        return;
271	      }
272	
273	    /* Mark an interaction in flight so the wake loop stays quiet through the
274	     * LLM request + TTS reply. Cleared by the TTS worker after the final
275	     * reply is spoken (or here if the request fails immediately). */
276	    g_reply_busy = 1;
277	
278	    /* Build full prompt: system prompt + user text */
279	    const role_def_t *role = &g_roles[g_current_role];
280	    char full_prompt[MSG_BUF_LEN];
281	    snprintf(full_prompt, MSG_BUF_LEN,
282	             "[SYSTEM]\n%s\n\n[USER]\n%s",
283	             role->system_prompt, user_text);
284	
285	    velaclaw_ask_req_t req = {
286	        .text       = full_prompt,
287	        .timeout_ms = 15000  /* 15 second timeout */
288	    };
289	
290	    /* Start a fresh response: bump the epoch and reset the spoken offset so
291	     * the streamed reply is spoken from the beginning, and drop any stale
292	     * fragment still queued for the previous question. */
293	    pthread_mutex_lock(&g_tts_lock);
294	    g_tts_epoch++;
295	    g_spoken_len = 0;
296	    g_tts_pending_ready = false;
297	    g_tts_pending_final = false;
298	    pthread_mutex_unlock(&g_tts_lock);
299	
300	    lv_label_set_text(g_chat_status, "Thinking...");
301	    if (g_chat_spinner)
302	      {
303	        lv_obj_clear_flag(g_chat_spinner, LV_OBJ_FLAG_HIDDEN);
304	      }
305	
306	    int ret = velaclaw_ask(g_agent_client, &req, llm_response_cb, NULL);
307	    if (ret < 0)
308	      {
309	        lv_label_set_text(g_chat_status, "Failed to send message");
310	        if (g_chat_spinner)
311	          {
312	            lv_obj_add_flag(g_chat_spinner, LV_OBJ_FLAG_HIDDEN);
313	          }
314	        g_reply_busy = 0;  /* request failed, release the wake loop */
315	      }
316	}
