 * boxes and, worse, MiMo TTS reads them aloud as a stray "think"-like word).
 * The simsun_16_cjk font covers ASCII + Latin + Greek/Cyrillic + GB2312/GBK
 * hanzi + kana + fullwidth, but NOT emoji (U+1F000..) or dingbats.  Walk the
 * UTF-8 string in place and drop any such code point (including the variation
 * selector / ZWJ that make up emoji sequences). */
static void strip_emoji(char *s)
{
    unsigned char *src = (unsigned char *)s;
    unsigned char *dst = (unsigned char *)s;

    while (*src) {
        unsigned int cp = 0;
        int n = 0;
        unsigned char c = *src;

        if (c < 0x80) {
            cp = c; n = 1;
        } else if ((c & 0xE0) == 0xC0) {
            cp = c & 0x1F; n = 2;
        } else if ((c & 0xF0) == 0xE0) {
            cp = c & 0x0F; n = 3;
        } else if ((c & 0xF8) == 0xF0) {
            cp = c & 0x07; n = 4;
        } else {
            /* Invalid UTF-8 lead byte — drop it. */
            src++;
            continue;
        }

        /* Decode continuation bytes. */
        int ok = 1;
        for (int i = 1; i < n; i++) {
            unsigned char cc = src[i];
            if ((cc & 0xC0) != 0x80) { ok = 0; break; }
            cp = (cp << 6) | (cc & 0x3F);
        }
        if (!ok) {
            src++;
            continue;
        }

        /* Emoji / unrenderable code points to drop. */
        int emoji =
            (cp >= 0x1F000 && cp <= 0x1FAFF) ||   /* emoji + pictographs */
            (cp >= 0x2600 && cp <= 0x27BF) ||     /* misc symbols + dingbats */
            (cp >= 0x2B00 && cp <= 0x2BFF) ||     /* supplemental symbols */
            cp == 0x200D ||                       /* zero-width joiner */
            (cp >= 0xFE00 && cp <= 0xFE0F) ||     /* variation selectors */
            (cp >= 0x1F1E6 && cp <= 0x1F1FF);     /* regional indicator flags */

        if (emoji) {
            src += n;
            continue;
        }

        /* Keep the code point. */
        for (int i = 0; i < n; i++) {
            *dst++ = *src++;
        }
    }
    *dst = '\0';
}
