726	            n = 4;
727	          }
728	        else
729	          {
730	            /* Invalid UTF-8 lead byte — drop it. */
731	            src++;
732	            continue;
733	          }
734	
735	        int ok = 1;
736	        for (int i = 1; i < n; i++)
737	          {
738	            unsigned char cc = src[i];
739	            if ((cc & 0xC0) != 0x80)
740	              {
741	                ok = 0;
742	                break;
743	              }
744	            cp = (cp << 6) | (cc & 0x3F);
745	          }
746	        if (!ok)
