72	velaclaw_client_t* velaclaw_client_open(const char* name)
73	{
74	    if (g_client_instance) {
75	        return g_client_instance;
76	    }
77	
78	    /* Check if message_bus is alive by trying a dummy operation */
79	    agent_msg_t probe = { 0 };
80	    strncpy(probe.channel, "__probe__", sizeof(probe.channel) - 1);
81	
82	    /* We can't easily probe, so just assume agent is running if
83	     * mbus_tap_register succeeds (it uses the same global state) */
84	
85	    struct velaclaw_client_s* c = calloc(1, sizeof(*c));
86	    if (!c) {
87	        return NULL;
88	    }
89	
90	    strncpy(c->app_id, name ? name : "app", sizeof(c->app_id) - 1);
91	    pthread_mutex_init(&c->mtx, NULL);
92	    sem_init(&c->reply_sem, 0, 0);
93	    c->reply_text = NULL;
94	    c->reply_status = 0;
95	
96	    if (mbus_tap_register(CLIENT_CHANNEL, tap_callback, c) != OK) {
97	        syslog(LOG_ERR, "[%s] tap register failed (agent not running?)\n", TAG);
98	        sem_destroy(&c->reply_sem);
99	        pthread_mutex_destroy(&c->mtx);
100	        free(c);
101	        return NULL;
102	    }
103	
104	    g_client_instance = c;
105	    syslog(LOG_INFO, "[%s] client opened: %s\n", TAG, c->app_id);
106	    return c;
107	}
