131	    const velaclaw_ask_req_t* req,
132	    void (*cb)(int, const char*, void*), void* cookie)
133	{
134	    if (!c || !req || !req->text) {
135	        return -EINVAL;
136	    }
137	
138	    /* Set up async callback */
139	    pthread_mutex_lock(&c->mtx);
140	    c->async_cb = cb;
141	    c->async_cookie = cookie;
142	    pthread_mutex_unlock(&c->mtx);
143	
144	    /* Push message to agent inbound queue */
145	    agent_msg_t msg = { 0 };
146	    strncpy(msg.channel, CLIENT_CHANNEL, sizeof(msg.channel) - 1);
147	    strncpy(msg.chat_id, c->app_id, sizeof(msg.chat_id) - 1);
148	    msg.content = strdup(req->text);
149	    if (!msg.content) {
150	        return -ENOMEM;
151	    }
152	
153	    int ret = message_bus_push_inbound(&msg);
154	    if (ret != OK) {
155	        free(msg.content);
156	        pthread_mutex_lock(&c->mtx);
157	        c->async_cb = NULL;
158	        c->async_cookie = NULL;
159	        pthread_mutex_unlock(&c->mtx);
160	        return -EIO;
161	    }
162	
163	    return 0;
164	}
