660	    bool started = false;
661	    int silence_run = 0;
662	
663	    syslog(LOG_INFO, "[kid_buddy] wake: listening...\n");
664	
665	    while (pcm_len < WAKE_MAX_BYTES) {
666	        /* A touch-triggered interaction may have started while we listened. */
667	        if (g_reply_busy) {
668	            syslog(LOG_INFO, "[kid_buddy] wake: reply busy, abort listen\n");
669	            break;
670	        }
671	
672	        int16_t chunk[WAKE_CHUNK_BYTES / 2];
673	        int n = audio_capture_read(cap, chunk, sizeof(chunk));
674	        if (n <= 0) {
675	            if (n < 0) {
676	                syslog(LOG_WARNING, "[kid_buddy] wake: read=%d\n", n);
677	                break;
678	            }
679	            continue;  /* EAGAIN / zero-length */
680	        }
681	
682	        int nsamp = n / (int)sizeof(int16_t);
683	        int64_t sum = 0;
684	        for (int i = 0; i < nsamp; i++) {
685	            int32_t v = chunk[i];
686	            sum += (int64_t)v * v;
687	        }
688	        int64_t ms = nsamp > 0 ? sum / nsamp : 0;
689	
690	        if (!started && ms >= WAKE_START_MSQ) {
691	            started = true;
692	            silence_run = 0;
693	            syslog(LOG_INFO, "[kid_buddy] wake: speech start (msq=%lld)\n",
694	                   (long long)ms);
695	        }
696	
697	        if (started) {
698	            if (pcm_len + (size_t)n <= WAKE_MAX_BYTES) {
699	                memcpy(pcm + pcm_len, chunk, n);
700	                pcm_len += n;
701	            }
702	
703	            if (ms < WAKE_END_MSQ) {
704	                if (++silence_run >= WAKE_SILENCE_CHUNKS) {
705	                    syslog(LOG_INFO, "[kid_buddy] wake: speech end (%zu bytes)\n",
706	                           pcm_len);
707	                    break;
708	                }
709	            } else {
710	                silence_run = 0;
711	            }
712	        }
713	    }
714	
715	    audio_capture_abort(cap);
716	    audio_capture_close(cap);
717	
718	    if (!started || pcm_len < WAKE_CHUNK_BYTES) {
719	        syslog(LOG_INFO, "[kid_buddy] wake: no speech (%zu bytes)\n", pcm_len);
720	        free(pcm);
721	        return NULL;
722	    }
723	
724	    char text[MSG_BUF_LEN];
725	    int ret = voice_asr_recognize(pcm, pcm_len, text, sizeof(text));
726	    free(pcm);
727	
728	    if (ret < 0 || text[0] == '\0') {
729	        syslog(LOG_WARNING, "[kid_buddy] wake: ASR failed/empty (ret=%d)\n",
730	               ret);
731	        return NULL;
732	    }
733	
734	    return strdup(text);
735	}
