        int32_t v = (int32_t)samples[i] * AGENT_AUDIO_CAPTURE_GAIN;
        if (v > 32767) {
            v = 32767;
        } else if (v < -32768) {
            v = -32768;
        }
        samples[i] = (int16_t)v;
    }
#else
    (void)buf;
    (void)len;
#endif
}

