142	    snd_pcm_hw_params_alloca(&hw);
143	    ret = snd_vela_pcm_hw_params_any(pcm, hw);
144	    if (ret < 0) {
145	        return ret;
146	    }
147	
148	    ret = snd_vela_pcm_hw_params_set_access(pcm, hw,
149	        SND_PCM_ACCESS_RW_INTERLEAVED);
