165	    if (ret < 0) {
166	        return ret;
167	    }
168	
169	    ret = snd_vela_pcm_hw_params_set_period_size(pcm, hw,
170	        period_frames, 0);
171	    if (ret < 0) {
172	        return ret;
173	    }
174	
175	    ret = snd_vela_pcm_hw_params_set_buffer_size(pcm, hw,
176	        buffer_frames);
