279	/*
280	 * The codec's analog MIC front-end (MIC PGA + MICBIAS) is NOT enabled by the
281	 * codec driver on boot, and the DAPM power-up in sunxi_codec_dapm_control only
282	 * runs AFTER hw_params.  sunxi_codec_hw_params() -> sunxi_get_adc_ch() reads the
283	 * MIC_PGA_EN bits and rejects capture with "capture only support 1~3 channel"
284	 * (-EINVAL) when none is armed.  The machine driver normally sets these via
285	 * snd_ctl_set() in sunxi_audio_start(), but the direct-ALSA capture path here
286	 * bypasses that, so we must arm the MIC input switch(es) + ADC digital volume
287	 * ourselves before opening the PCM.  Mirror sunxi_alsa.c:821-845.
288	 */
289	#define CAP_CODEC_CARD_NAME "audiocodec"
290	#define CAP_ADC_INIT_VOLUME 160
