293	{
294	    const char* card = CAP_CODEC_CARD_NAME;
295	
296	    switch (nchannels) {
297	    case 1:
298	        snd_ctl_set(card, "MIC1 input switch", 1);
299	        snd_ctl_set(card, "ADC1_2 digital volume switch", 1);
300	        snd_ctl_set(card, "ADC1 digital volume", CAP_ADC_INIT_VOLUME);
301	        break;
302	    case 2:
303	        snd_ctl_set(card, "MIC1 input switch", 1);
304	        snd_ctl_set(card, "MIC2 input switch", 1);
305	        snd_ctl_set(card, "ADC1_2 digital volume switch", 1);
306	        snd_ctl_set(card, "ADC1 digital volume", CAP_ADC_INIT_VOLUME);
307	        snd_ctl_set(card, "ADC2 digital volume", CAP_ADC_INIT_VOLUME);
308	        break;
309	    case 3:
310	        snd_ctl_set(card, "MIC1 input switch", 1);
311	        snd_ctl_set(card, "MIC2 input switch", 1);
312	        snd_ctl_set(card, "MIC3 input switch", 1);
313	        snd_ctl_set(card, "ADC1_2 digital volume switch", 1);
314	        snd_ctl_set(card, "ADC3 digital volume switch", 1);
315	        snd_ctl_set(card, "ADC1 digital volume", CAP_ADC_INIT_VOLUME);
316	        snd_ctl_set(card, "ADC2 digital volume", CAP_ADC_INIT_VOLUME);
317	        snd_ctl_set(card, "ADC3 digital volume", CAP_ADC_INIT_VOLUME);
