324	static int open_alsa_capture(audio_capture_t* cap, const char* dev_path,
325	    unsigned int sample_rate, unsigned int channels,
326	    unsigned int bits_per_sample)
327	{
328	    const char* alsa_name = resolve_alsa_name(dev_path);
329	    snd_pcm_format_t format = capture_format_from_bits(bits_per_sample);
330	    unsigned int attempts[2];
331	    int attempt_count = 0;
332	    int last_ret = -ENODEV;
333	
334	    if ((int)format < 0) {
335	        return -ENOTSUP;
336	    }
337	
338	    attempts[attempt_count++] = channels;
339	    if (channels == 1) {
340	        attempts[attempt_count++] = 3;
341	    }
342	
343	    for (int i = 0; i < attempt_count; i++) {
344	        snd_pcm_t* pcm = NULL;
345	        unsigned int hw_channels = attempts[i];
346	        int ret;
