518	int audio_capture_read(audio_capture_t* cap, void* buf, size_t len)
519	{
520	    if (!cap || !buf || len == 0) {
521	        return -EINVAL;
522	    }
523	
524	    switch (cap->backend) {
525	    case AUDIO_CAPTURE_BACKEND_ALSA: {
526	#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
527	        snd_pcm_uframes_t frames;
528	        int nframes;
529	        size_t out_len;
530	
531	        if (!cap->handle.pcm || cap->out_frame_bytes == 0) {
532	            return -EINVAL;
533	        }
534	
535	        frames = len / cap->out_frame_bytes;
536	        if (frames == 0) {
537	            return -EINVAL;
538	        }
539	
540	        if (cap->hw_channels == cap->requested_channels) {
541	            nframes = alsa_read_frames(cap, buf, frames);
542	            if (nframes <= 0) {
543	                return nframes;
544	            }
545	
546	            out_len = (size_t)nframes * cap->out_frame_bytes;
547	            if (cap->bits_per_sample == 16) {
548	                apply_capture_gain(buf, out_len);
549	            }
550	            return (int)out_len;
551	        }
552	
553	        if (cap->bits_per_sample != 16 || cap->requested_channels != 1) {
554	            return -ENOTSUP;
555	        }
556	
557	        if (ensure_scratch_capacity(cap, frames * cap->hw_frame_bytes) < 0) {
558	            return -ENOMEM;
559	        }
560	
561	        nframes = alsa_read_frames(cap, cap->scratch, frames);
562	        if (nframes <= 0) {
563	            return nframes;
564	        }
565	
566	        downmix_interleaved_s16_to_mono(cap, buf, cap->scratch,
567	            (size_t)nframes);
568	        out_len = (size_t)nframes * cap->out_frame_bytes;
569	        apply_capture_gain(buf, out_len);
570	        return (int)out_len;
571	#else
572	        return -ENOTSUP;
573	#endif
574	    }
575	
576	    case AUDIO_CAPTURE_BACKEND_MEDIA_RECORDER: {
577	        ssize_t n;
578	
579	        if (!cap->handle.recorder) {
580	            return -EINVAL;
581	        }
582	
583	        n = media_recorder_read_data(cap->handle.recorder, buf, len);
584	        if (n > 0 && cap->bits_per_sample == 16) {
585	            apply_capture_gain(buf, (size_t)n);
586	        }
587	
588	        return (int)n;
589	    }
590	
591	    default:
592	        return -EINVAL;
593	    }
594	}
