554	/* ── Wake-word listening (MiMo ASR + local VAD) ────────────────
555	 * The wake loop runs in its own thread, opens the onboard mic only when no
556	 * reply is playing (AEC is disabled, so the mic must not hear the speaker's
557	 * own TTS), buffers one utterance using an energy-threshold VAD, sends it to
558	 * MiMo ASR, matches the wake word, and hands the remainder to the LLM. */
559	
560	/* Characters to strip from either end of a recognized command. */
561	static const char *const g_junk[] = {
562	    " ", "\t", "\n", "\r",
563	    ",", ".", "!", "?", ";", ":", "~", "\"", "'",
564	    "，", "。", "！", "？", "、", "：", "；", "～", "…", "“", "”",
565	    NULL
566	};
567	
568	static int junk_prefix_len(const char *p)
569	{
570	    for (int i = 0; g_junk[i]; i++) {
571	        size_t n = strlen(g_junk[i]);
572	        if (strncmp(p, g_junk[i], n) == 0) {
573	            return (int)n;
574	        }
575	    }
576	    return 0;
577	}
578	
579	static int junk_suffix_len(const char *p, size_t len)
580	{
581	    for (int i = 0; g_junk[i]; i++) {
582	        size_t n = strlen(g_junk[i]);
583	        if (n <= len && strncmp(p + len - n, g_junk[i], n) == 0) {
584	            return (int)n;
585	        }
586	    }
587	    return 0;
588	}
589	
590	/* Strip whitespace + punctuation from both ends of a command in place. */
591	static void trim_junk(char *s)
592	{
593	    char *start = s;
594	    int n;
595	
596	    while (*start && (n = junk_prefix_len(start)) != 0) {
597	        start += n;
598	    }
599	
600	    size_t len = strlen(start);
601	    while (len > 0 && (n = junk_suffix_len(start, len)) != 0) {
602	        start[len - n] = '\0';
603	        len -= n;
604	    }
605	
606	    if (start != s) {
607	        memmove(s, start, len + 1);
608	    }
609	}
610	
611	/* Remove every occurrence of the wake word from text, then trim junk.
612	 * Returns the length of the remaining command (0 = wake word only). */
613	static size_t strip_wake_word(const char *text, char *out, size_t cap)
614	{
615	    size_t wlen = strlen(WAKE_WORD);
616	    size_t olen = 0;
617	    const char *p = text;
618	
619	    while (*p) {
620	        if (strncmp(p, WAKE_WORD, wlen) == 0) {
621	            p += wlen;
622	        } else {
623	            if (olen + 1 < cap) {
624	                out[olen++] = *p;
625	            }
626	            p++;
627	        }
628	    }
629	    out[olen] = '\0';
630	
631	    trim_junk(out);
632	    return strlen(out);
633	}
