737	/* Speak a standalone prompt (e.g. "我在呢") through the TTS worker so it is
738	 * serialized with reply speech, and mark the reply busy so the wake loop
739	 * stays quiet while the prompt plays. */
740	static void wake_speak_prompt(const char *text)
741	{
742	    pthread_mutex_lock(&g_tts_lock);
743	    g_tts_epoch++;
744	    g_spoken_len = 0;
745	    g_tts_pending_ready = false;
746	    g_tts_pending_final = false;
747	    pthread_mutex_unlock(&g_tts_lock);
748	
749	    g_reply_busy = 1;
750	    enqueue_tts(text, true);
751	}
752	
753	static void *wake_listen_worker(void *arg)
754	{
755	    (void)arg;
756	
757	    /* Settle briefly so ai_agent finishes registering the ASR backends. */
758	    usleep(2 * 1000 * 1000);
759	
760	    for (;;) {
761	        /* Wait for any in-flight reply to finish, then a short cooldown so
762	         * the tail of the TTS doesn't bleed into the mic. */
763	        while (g_reply_busy) {
764	            usleep(100 * 1000);
765	        }
766	        usleep(300 * 1000);
767	
768	        char *asr_text = listen_one_utterance();
769	        if (!asr_text) {
770	            continue;
771	        }
772	
773	        syslog(LOG_INFO, "[kid_buddy] wake: heard \"%s\"\n", asr_text);
774	
775	        bool has_wake = (strstr(asr_text, WAKE_WORD) != NULL);
776	        char command[MSG_BUF_LEN];
777	        size_t clen = strip_wake_word(asr_text, command, sizeof(command));
778	        free(asr_text);
779	
780	        if (!has_wake) {
781	            syslog(LOG_INFO, "[kid_buddy] wake: not the wake word, ignore\n");
782	            continue;
783	        }
784	
785	        if (clen == 0) {
786	            /* Wake word only — acknowledge and keep listening. */
787	            syslog(LOG_INFO, "[kid_buddy] wake: wake word only, prompt\n");
788	            wake_speak_prompt(WAKE_IDLE_PROMPT);
789	            continue;
790	        }
791	
792	        /* Hand the command to the LVGL thread (which calls send_to_llm). */
793	        pthread_mutex_lock(&g_wake_cmd_lock);
794	        strncpy(g_wake_cmd, command, MSG_BUF_LEN - 1);
795	        g_wake_cmd[MSG_BUF_LEN - 1] = '\0';
796	        g_wake_cmd_ready = true;
797	        pthread_mutex_unlock(&g_wake_cmd_lock);
798	
799	        syslog(LOG_INFO, "[kid_buddy] wake: command \"%s\"\n", command);
800	    }
801	
802	    return NULL;
803	}
