79	static int sunxi_pcm_preallocate_dma_buffer(struct snd_pcm *pcm, int stream)
80	{
81		const struct snd_pcm_hardware *hw = NULL;
82		struct snd_codec *codec = pcm->card->codec;
83		struct snd_dma_buffer *buf = &pcm->streams[stream]->dma_buffer;
84		size_t size = 0;
85	
86		snd_print("prealloc dma buffer\n");
87		if (codec->hw)
88			hw = &codec->hw[stream];
89		else
90			hw = &sunxi_pcm_hardware[stream];
91		size = hw->buffer_bytes_max;
92		buf->addr = hal_malloc_coherent(size);
93		if (!buf->addr)
94			return -ENOMEM;
95		buf->bytes = size;
96	
97		return 0;
98	}
99	
100	int sunxi_pcm_new(struct snd_pcm *pcm)
101	{
102		int ret;
103	
104		snd_print("\n");
105		if (pcm->streams[SNDRV_PCM_STREAM_PLAYBACK]) {
106			ret = sunxi_pcm_preallocate_dma_buffer(pcm,
107							SNDRV_PCM_STREAM_PLAYBACK);
108			if (ret != 0) {
109				snd_err("dma buffer malloc failed\n");
110				goto err;
111			}
112		}
113		if (pcm->streams[SNDRV_PCM_STREAM_CAPTURE]) {
114			ret = sunxi_pcm_preallocate_dma_buffer(pcm,
115							SNDRV_PCM_STREAM_CAPTURE);
116			if (ret != 0) {
117				snd_err("dma buffer malloc failed\n");
118				goto err;
119			}
120		}
121	err:
122		return 0;
123	}
