125	void sunxi_pcm_free(struct snd_pcm *pcm)
126	{
127		struct snd_pcm_substream *substream;
128		struct snd_dma_buffer *buf;
129		int stream;
130	
131		snd_print("\n");
132		for (stream = 0; stream < 2; stream++) {
133			substream = pcm->streams[stream];
134			if (!substream)
135				continue;
136			buf = &substream->dma_buffer;
137			if (!buf->addr)
138				continue;
139			snd_print("dma free.\n");
140			hal_free_coherent(buf->addr);
141			buf->addr = NULL;
142		}
143		return ;
144	}
