171	static int sunxi_pcm_hw_params(struct snd_pcm_substream *substream,
172		struct snd_pcm_hw_params *params)
173	{
174		int ret;
175		struct snd_card *card = substream->pcm->card;
176		struct snd_dai *cpu_dai = card->platform->cpu_dai;
177		struct dma_chan *chan = snd_dmaengine_pcm_get_chan(substream);
178		struct dma_slave_config slave_config = {0};
179		struct sunxi_dma_params *dmap;
180	#ifdef CONFIG_SND_PLATFORM_SUNXI_MAD
181		bool mad_bind = false;
182	#endif
183	
184		if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK)
185			dmap = cpu_dai->playback_dma_data;
186		else
187			dmap = cpu_dai->capture_dma_data;
188	
189		ret = snd_hwparams_to_dma_slave_config(substream, params, &slave_config);
190		if (ret != 0) {
191			snd_err("hw params config failed with err %d\n", ret);
192			return ret;
193		}
194		slave_config.dst_maxburst = dmap->dst_maxburst;
195		slave_config.src_maxburst = dmap->src_maxburst;
196	
197	#ifdef CONFIG_SND_PLATFORM_SUNXI_MAD
198		if (substream->stream == SNDRV_PCM_STREAM_CAPTURE) {
199			if (!strncmp(card->name, "audiocodecadc", 13)) {
200				ret = sunxi_mad_bind_get(MAD_PATH_CODECADC, &mad_bind);
201				if (ret) {
202					mad_bind = false;
203					snd_err("get mad_bind failed, path: %d\n", MAD_PATH_CODECADC);
204				}
205			} else if (!strncmp(card->name, "snddmic", 7)) {
206				ret = sunxi_mad_bind_get(MAD_PATH_DMIC, &mad_bind);
207				if (ret) {
208					mad_bind = false;
209					snd_err("get mad_bind failed, path: %d\n", MAD_PATH_DMIC);
210				}
211			} else if (!strncmp(card->name, "snddaudio0", 10)) {
212				ret = sunxi_mad_bind_get(MAD_PATH_I2S0, &mad_bind);
213				if (ret) {
214					mad_bind = false;
215					snd_err("get mad_bind failed, path: %d\n", MAD_PATH_I2S0);
216				}
217			}
218			snd_info("mad_bind[%s]: %s\n", card->name, mad_bind ? "On":"Off");
219			if (mad_bind) {
220				slave_config.src_addr_width = DMA_SLAVE_BUSWIDTH_4_BYTES;
221			}
222		}
223	#endif
224	
225		if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
226			slave_config.dst_addr = (unsigned long)dmap->dma_addr;
227			slave_config.src_addr_width = slave_config.dst_addr_width;
228			slave_config.slave_id = sunxi_slave_id(dmap->dma_drq_type_num, 0);
229		} else {
230			slave_config.src_addr = (unsigned long)dmap->dma_addr;
231			slave_config.dst_addr_width = slave_config.src_addr_width;
232			slave_config.slave_id = sunxi_slave_id(0, dmap->dma_drq_type_num);
233		}
234		snd_info("src_addr:%p, dst_addr:%p, drq_type:%d\n",
235			slave_config.src_addr, slave_config.dst_addr,
236			dmap->dma_drq_type_num);
237	
238		ret = dmaengine_slave_config(chan, &slave_config);
239		if (ret != 0) {
240			snd_err("dmaengine_slave_config failed with err %d\n", ret);
241			return ret;
242		}
243	
244		snd_pcm_set_runtime_buffer(substream, &substream->dma_buffer);
245	
246		return 0;
247	}
