75	#define DMA_LLI_POLL_ITEMS				(256)
76	#define BITMAP_WORDS					((DMA_LLI_POLL_ITEMS >> 5))
77	
78	#define BITMAP_SET(p, idx)		((p)->bitmap[(idx) >> 5] |=  BIT((idx) & 0x1f))
79	#define BITMAP_CLR(p, idx)		((p)->bitmap[(idx) >> 5] &= ~BIT((idx) & 0x1f))
80	#define TEST_IDX(p, idx)		((p)->bitmap[(idx) >> 5] & BIT((idx) & 0x1f))
81	
82	struct dma_lli_pool;
83	
84	struct dma_lli_wrap {
85		struct sunxi_dma_lli lli;
86		uint32_t idx;
87	};
88	
89	struct dma_lli_pool {
90		struct dma_lli_wrap items[DMA_LLI_POLL_ITEMS];
91		uint32_t bitmap[BITMAP_WORDS];
92		uint32_t last;
93		uint32_t used;
94		uint32_t missing;
95	};
96	
97	__attribute__((aligned(64))) static struct dma_lli_pool g_lli_pool = { 0 };
98	
99	static inline int __ffz(uint32_t val)
100	{
101		return __builtin_ffs(~val) - 1;;
102	}
103	
104	static struct sunxi_dma_lli *_dma_get_lli(void)
105	{
106		struct dma_lli_pool *pool = &g_lli_pool;
107		struct dma_lli_wrap *lli_wrap = NULL;
108		int i, idx;
109		unsigned long flags;
110	
111		flags = hal_spin_lock_irqsave(&dma_lock);
112	
113		if (pool->used != DMA_LLI_POLL_ITEMS) {
114			for (i = 0; i < BITMAP_WORDS; i++) {
115				if (pool->last == BITMAP_WORDS)
116					pool->last = 0;
117				idx = __ffz(pool->bitmap[pool->last]);
118				if (idx < 0) {
119					pool->last++;
120					continue;
121				}
122	
123				idx += (i << 5);
124				BITMAP_SET(pool, idx);
125				pool->used++;
126				lli_wrap = &pool->items[idx];
127				lli_wrap->idx = idx;
128				goto out;
129			}
130		}
131	
132	out:
133		hal_spin_unlock_irqrestore(&dma_lock, flags);
134	
135		if (!lli_wrap && ++pool->missing > 10) {
136			dmawarn("dma lli pool maybe too small\n");
137			pool->missing = 0;
138		}
139	
140		return (struct sunxi_dma_lli *)lli_wrap;
141	}
142	
143	static void _dma_put_lli(struct sunxi_dma_lli *lli)
144	{
145		struct dma_lli_wrap *lli_wrap = (struct dma_lli_wrap *)lli;
146		struct dma_lli_pool *pool = &g_lli_pool;
147		unsigned long flags;
148	
149		flags = hal_spin_lock_irqsave(&dma_lock);
150		BITMAP_CLR(pool, lli_wrap->idx);
151		pool->used--;
152		hal_spin_unlock_irqrestore(&dma_lock, flags);
153	}
