155	/*
156	 * Fix sconfig's bus width according to at_dmac.
157	 * 1 byte -> 0, 2 bytes -> 1, 4 bytes -> 2, 8bytes -> 3
158	 */
159	static inline uint32_t convert_buswidth(enum dma_slave_buswidth addr_width)
160	{
161	    if (addr_width > DMA_SLAVE_BUSWIDTH_8_BYTES)
162	    {
163	        return 0;
164	    }
165	
166	    switch (addr_width)
167	    {
168	        case DMA_SLAVE_BUSWIDTH_2_BYTES:
169	            return 1;
170	        case DMA_SLAVE_BUSWIDTH_4_BYTES:
171	            return 2;
172	        case DMA_SLAVE_BUSWIDTH_8_BYTES:
173	            return 3;
174	        default:
175	            /* For 1 byte width or fallback */
176	            return 0;
177	    }
178	}
179	
180	static inline void convert_burst(uint32_t *maxburst)
181	{
182	    switch (*maxburst)
183	    {
184	        case 1:
185	            *maxburst = 0;
186	            break;
187	        case 4:
188	            *maxburst = 1;
189	            break;
190	        case 8:
191	            *maxburst = 2;
192	            break;
193	        case 16:
194	            *maxburst = 3;
195	            break;
196	        default:
197	            dmaerr("unknown maxburst\n");
198	            *maxburst = 0;
199	            break;
200	    }
201	}
