203	static inline void sunxi_cfg_lli(struct sunxi_dma_lli *lli, uint32_t src_addr,
204	                            uint32_t dst_addr, uint32_t len,
205	                            struct dma_slave_config *config)
206	{
207	    uint32_t src_width = 0, dst_width = 0;
208	
209	    if (NULL == lli && NULL == config)
210	    {
211	        return;
212	    }
213	
214	    src_width = convert_buswidth(config->src_addr_width);
215	    dst_width = convert_buswidth(config->dst_addr_width);
216	    lli->cfg = SRC_BURST(config->src_maxburst) | \
217	               SRC_WIDTH(src_width) | \
218	               DST_BURST(config->dst_maxburst) | \
219	               DST_WIDTH(dst_width);
220	
221	    lli->src = src_addr - SUNXI_DMA_PHYADDR_OFFSET;
222	    lli->dst = dst_addr - SUNXI_DMA_PHYADDR_OFFSET;
223	    lli->len = len;
224	    lli->para = NORMAL_WAIT;
225	}
