296	static void *sunxi_lli_list(struct sunxi_dma_lli *prev, struct sunxi_dma_lli *next,
297	                        struct sunxi_dma_chan *chan)
298	{
299	    uint32_t temp_desc;
300	
301	    if ((!prev && !chan) || !next)
302	    {
303	        return NULL;
304	    }
305	
306	    temp_desc = __va_to_pa((unsigned long)next) - SUNXI_DMA_PHYADDR_OFFSET;
307	
308	    if (!prev)
309	    {
310	        chan->desc = next;
311	        chan->desc->p_lln = temp_desc;
312	        chan->desc->vlln = next;
313	    }
314	    else
315	    {
316	        prev->p_lln = temp_desc;
317	        prev->vlln = next;
318	    }
319	
320	    next->p_lln = LINK_END;
321	    next->vlln = NULL;
322	
323	    return next;
324	}
