326	static hal_irqreturn_t sunxi_dma_irq_handle(void *ptr)
327	{
328	
329	    uint32_t status_l = 0, status_h = 0;
330	    int i = 0;
331	
332	#if START_CHAN_OFFSET < HIGH_CHAN
333	    status_l = hal_readl(DMA_IRQ_STAT(0));
334	    status_l &= hal_readl(DMA_IRQ_EN(0));
335	#endif
336	#if NR_MAX_CHAN + START_CHAN_OFFSET > HIGH_CHAN
337	    status_h = hal_readl(DMA_IRQ_STAT(1));
338	    status_h &= hal_readl(DMA_IRQ_EN(1));
339	#endif
340	#if START_CHAN_OFFSET < HIGH_CHAN
341	    hal_writel(status_l, DMA_IRQ_STAT(0));
342	#endif
343	#if NR_MAX_CHAN + START_CHAN_OFFSET > HIGH_CHAN
344	    hal_writel(status_h, DMA_IRQ_STAT(1));
345	#endif
346	
347	    for (i = SUNXI_DMA_CHAN_START; i < NR_MAX_CHAN; i++)
348	    {
349	        uint32_t __cpsr;
350	        struct sunxi_dma_chan *chan = &dma_chan_source[i];
351	        uint32_t chan_num = chan->chan_count;
352	        uint32_t status = 0;
353	
354	        if (chan->used == 0)
355	        {
356	            continue;
357	        }
358	
359	        __cpsr = hal_spin_lock_irqsave(&chan->lock);
360	
361	        status = (chan_num + START_CHAN_OFFSET >= HIGH_CHAN) \
362	                 ? (status_h >> ((chan_num + START_CHAN_OFFSET - HIGH_CHAN) << 2)) \
363	                 : (status_l >> ((chan_num + START_CHAN_OFFSET) << 2));
364	
365	        if (!(chan->irq_type & status))
366	        {
367	            goto unlock;
368	        }
369	
370	        if (chan->cyclic)
371	        {
372	            dma_callback cb = NULL;
373	            void *cb_data = NULL;
374	
375	            chan->periods_pos ++;
376	            if (chan->periods_pos * chan->desc->len >= chan->buf_len)
377	            {
378	                chan->periods_pos = 0;
379	            }
380	            cb = chan->callback;
381	            cb_data = chan->callback_param;
382	
383	            hal_spin_unlock_irqrestore(&chan->lock, __cpsr);
384	            if (cb)
385	            {
386	                cb(cb_data);
387	            }
388	            __cpsr = hal_spin_lock_irqsave(&chan->lock);
389	        }
390	        else
391	        {
392	            dma_callback cb = NULL;
393	            void *cb_data = NULL;
394	
395	            cb = chan->callback;
396	            cb_data = chan->callback_param;
397	
398	            hal_spin_unlock_irqrestore(&chan->lock, __cpsr);
399	            if (cb)
400	            {
401	                cb(cb_data);
402	            }
403	            __cpsr = hal_spin_lock_irqsave(&chan->lock);
404	        }
405	unlock:
406	        hal_spin_unlock_irqrestore(&chan->lock, __cpsr);
407	    }
408	    return 0;
409	}
