411	static int sunxi_dma_clk_init(bool enable)
412	{
413	    hal_clk_status_t ret;
414	    u32  reset_id;
415	    hal_clk_id_t clk_id, mbus_clk_id, dsp_clk_id;
416	    hal_clk_t clk;
417	    struct reset_control *reset;
418	
419	    clk_id = SUNXI_CLK_DMA;
420	    reset_id = SUNXI_RST_DMA;
421	    mbus_clk_id = SUNXI_CLK_MBUS_DMA;
422	#ifdef CONFIG_ARCH_SUN55IW3
423	    hal_reset_type_t reset_type = HAL_SUNXI_DSP_RESET;
424	    hal_clk_type_t clk_type = HAL_SUNXI_DSP;
425	    dsp_clk_id = SUNXI_DSP_CLK;
426	#else
427	    hal_reset_type_t reset_type = HAL_SUNXI_RESET;
428	    hal_clk_type_t clk_type = HAL_SUNXI_CCU;
429	    dsp_clk_id = (hal_clk_id_t)NULL;
430	#endif
431	
432	    if (enable)
433	    {
434		if (reset_id) {
435			reset = hal_reset_control_get(reset_type, reset_id);
436			hal_reset_control_deassert(reset);
437			hal_reset_control_put(reset);
438		}
439		if (mbus_clk_id)
440			hal_clock_enable(hal_clock_get(clk_type, SUNXI_CLK_MBUS_DMA));
441	
442		clk = hal_clock_get(clk_type, clk_id);
443		ret = hal_clock_enable(clk);
444		if (ret != HAL_CLK_STATUS_OK)
445		    DMA_ERR("DMA clock enable failed.\n");
446		if (dsp_clk_id)
447		    hal_clock_enable(hal_clock_get(clk_type, dsp_clk_id));
448	    }
449	    else
450	    {
451		clk = hal_clock_get(clk_type, clk_id);
452		ret = hal_clock_disable(clk);
453		if (ret != HAL_CLK_STATUS_OK)
454		    DMA_ERR("DMA clock disable failed.\n");
455		if (mbus_clk_id)
456			hal_clock_disable(hal_clock_get(clk_type, SUNXI_CLK_MBUS_DMA));
457		hal_clock_put(clk);
458	    }
459	
460	    return ret;
461	}
