632	hal_dma_status_t hal_dma_prep_cyclic(struct sunxi_dma_chan *chan,
633					     uint32_t buf_addr, uint32_t buf_len,
634					     uint32_t period_len, enum dma_transfer_direction dir)
635	{
636	    struct sunxi_dma_lli *prev = NULL, *li_old = NULL;
637	    uint32_t periods = buf_len / period_len;
638	    struct dma_slave_config *config = NULL;
639	    unsigned long __cpsr;
640	    struct sunxi_dma_lli *l_item[periods];
641	    uint32_t i = 0;
642	
643	    if ((NULL == chan && chan->cyclic) || (0 == buf_addr))
644	    {
645	        DMA_ERR("[dma] chan or buf_addr is NULL\n");
646	        return HAL_DMA_STATUS_INVALID_PARAMETER;
647	    }
648	
649	    ASSERT(!in_interrupt());
650	
651		if  ( buf_addr <= 0x040210b8 && (buf_addr + buf_len) > 0x040210b8 ) {
652			syslog(LOG_ERR,"dma_test_cyclic: buf_addr:%lx,buf_len:%lx,period_len:%ld\n",
653					buf_addr,buf_len,period_len);
654			sched_dumpstack(gettid());
655		}
656	
657	    memset(l_item, 0, sizeof(l_item));
658	    for (i = 0; i < periods; i++) {
659		    l_item[i] = _dma_get_lli();
660		    if (!l_item[i])
661			goto no_mem;
662		    memset(l_item[i], 0, sizeof(struct sunxi_dma_lli));
663	    }
664	
665	    __cpsr = hal_spin_lock_irqsave(&chan->lock);
666	
667	    if (chan->desc) {
668	        li_old = chan->desc;
669	        chan->desc = NULL;
670	    }
671	
672	    config = &chan->cfg;
673	    for (i = 0; i < periods; i++)
674	    {
675	        if (dir == DMA_MEM_TO_DEV)
676	        {
677	            sunxi_cfg_lli(l_item[i], __va_to_pa(buf_addr + period_len * i),
678	                          config->dst_addr, period_len, config);
679	            l_item[i]->cfg |= GET_DST_DRQ(config->slave_id) \
680	                           | SRC_LINEAR_MODE \
681	                           | DST_IO_MODE \
682	                           | SRC_DRQ(DRQSRC_SDRAM);
683	        }
684	        else if (dir == DMA_DEV_TO_MEM)
685	        {
686	            sunxi_cfg_lli(l_item[i], config->src_addr, \
687	                          __va_to_pa(buf_addr + period_len * i), \
688	                          period_len, config);
689	            l_item[i]->cfg |= GET_SRC_DRQ(config->slave_id)  \
690	                            | DST_LINEAR_MODE \
691	                            | SRC_IO_MODE \
692	                            | DST_DRQ(DRQSRC_SDRAM);
693	        }
694	        else if (dir == DMA_DEV_TO_DEV)
695	        {
696	            sunxi_cfg_lli(l_item[i], config->src_addr, \
697	                          config->dst_addr, period_len, config);
698	            l_item[i]->cfg |= GET_SRC_DRQ(config->slave_id) \
699	                           | DST_IO_MODE \
700	                           | SRC_IO_MODE \
701	                           | GET_DST_DRQ(config->slave_id);
702	
703	        }
704	        prev = sunxi_lli_list(prev, l_item[i], chan);
705	    }
706	
707	    prev->p_lln = __va_to_pa((unsigned long)chan->desc);
708	    chan->cyclic = true;
709	#ifdef DMA_DEBUG
710	    for (prev = chan->desc; prev != NULL; prev = prev->vlln)
711	    {
712	        sunxi_dump_lli(chan, prev);
713	    }
714	#endif
715	    hal_spin_unlock_irqrestore(&chan->lock, __cpsr);
716	
717	    if (li_old) {
718	        struct sunxi_dma_lli *next = NULL;
719	
720	        while (li_old)
721	        {
722	            next = li_old->vlln;
723	            _dma_put_lli(li_old);
724	            li_old = next;
725	        }
726	    }
727	
728	    return HAL_DMA_STATUS_OK;
729	no_mem:
730	    for (i = 0; i < periods; i++) {
731		if (!l_item[i])
732			continue;
733		_dma_put_lli(l_item[i]);
734	    }
735	    return HAL_DMA_STATUS_NO_MEM;
736	}
