790	enum dma_status hal_dma_tx_status(struct sunxi_dma_chan *chan, uint32_t *left_size)
791	{
792	    uint32_t i = 0;
793	    struct sunxi_dma_lli *l_item = NULL;
794	    enum dma_status status = DMA_INVALID_PARAMETER;
795	    unsigned long __cpsr;
796	
797	    if (NULL == chan || NULL == left_size)
798	    {
799	        DMA_ERR("[dma] chan or left_size is NULL\n");
800	        return HAL_DMA_STATUS_INVALID_PARAMETER;
801	    }
802	
803	    __cpsr = hal_spin_lock_irqsave(&chan->lock);
804	    if (chan->cyclic)
805	    {
806	        for (i = 0, l_item = chan->desc; i <= chan->periods_pos; i++, l_item = l_item->vlln)
807	        {
808	            if (NULL == l_item)
809	            {
810	                *left_size = 0;
811	                status = DMA_COMPLETE;
812	                goto out;
813	            }
814	        }
815	        if (NULL == l_item)
816	        {
817	            *left_size = 0;
818	            status = DMA_COMPLETE;
819	        }
820	        else
821	        {
822	            uint32_t pos = 0;
823	            bool count = false;
824	
825	            pos = hal_readl(DMA_LLI_ADDR(chan->chan_count));
826	            *left_size = hal_readl(DMA_CNT(chan->chan_count));
827	            if (pos == LINK_END)
828	            {
829	                status = DMA_COMPLETE;
830	                goto out;
831	            }
832	            for (l_item = chan->desc; l_item != NULL; l_item = l_item->vlln)
833	            {
834	                if (l_item->p_lln == pos)
835	                {
836	                    count = true;
837	                    continue;
838	                }
839	                if (count)
840	                {
841	                    *left_size += l_item->len;
842	                }
843	            }
844	            status = DMA_IN_PROGRESS;
845	        }
846	    }
847	    else
848	    {
849	        *left_size = hal_readl(DMA_CNT(chan->chan_count));
850	
851	        if (*left_size == 0)
852	        {
853	            status = DMA_COMPLETE;
854	        }
855	        else
856	        {
857	            status = DMA_IN_PROGRESS;
858	        }
859	    }
860	
861	out:
862	    hal_spin_unlock_irqrestore(&chan->lock, __cpsr);
863	
864	    return status;
865	}
