867	static void hexdump(FAR const void *addr, size_t size)
868	{
869		char buf[96];
870		unsigned int i = 0, off = 0;
871		unsigned int *ptr = (unsigned int *)addr;
872	
873		for (i = 0; i < size; i += sizeof(*ptr)) {
874			if ((i % 32) == 0) {
875				if (off) {
876					buf[off] = 0;
877					syslog(LOG_ERR, "%s", buf);
878					off = 0;
879				}
880				off += sprintf(buf + off, "%08x: ", i);
881			}
882			off += sprintf(buf + off, "%08x ", ptr[i / sizeof(*ptr)]);
883		}
884	
885		if (off) {
886			buf[off] = 0;
887			syslog(LOG_ERR, "%s", buf);
888			off = 0;
889		}
890	}
