1156				     | DST_LINEAR_MODE \
1157				     | SRC_IO_MODE \
1158				     | DST_DRQ(DRQSRC_SDRAM);
1159			hal_dcache_invalidate((unsigned long)vdst, len1);
1160		}
1161		reg_data = *reg & (~(1<<4)); *reg = reg_data | (1<<4); // PE4 high
1162		l_item1->p_lln = LINK_END;
1163		l_item1->vlln = NULL;
1164		chan->desc = l_item1;
1165		hal_dcache_clean((unsigned long)l_item1, sizeof(*l_item1));
1166	
1167		reg_data = *reg & (~(1<<4)); *reg = reg_data; // PE4 low
1168	
1169		chan->cyclic = false;
