1181		val = hal_readl(DMA_IRQ_EN(high));
1182		val &= ~irq_mask;
1183		hal_writel(val, DMA_IRQ_EN(high));
1184		hal_spin_unlock_irqrestore(&dma_lock, __ccpsr);
1185	
1186		reg_data = *reg & (~(1<<4)); *reg = reg_data | (1<<4); // PE4 high
1187	
1188		l_item2 = _dma_get_lli();
