1197			sunxi_cfg_lli(l_item2, src + len1, dst, len2, config);
1198			l_item2->cfg |= GET_DST_DRQ(slave_id) \
1199				     | SRC_LINEAR_MODE \
1200				     | DST_IO_MODE \
1201				     | SRC_DRQ(DRQSRC_SDRAM);
1202			hal_dcache_clean((unsigned long)vsrc + len1, len2);
1203		} else if (dir == DMA_DEV_TO_MEM) {
1204			sunxi_cfg_lli(l_item2, src, dst + len1, len2, config);
1205			l_item2->cfg |= GET_SRC_DRQ(slave_id)  \
1206				     | DST_LINEAR_MODE \
1207				     | SRC_IO_MODE \
1208				     | DST_DRQ(DRQSRC_SDRAM);
1209			hal_dcache_invalidate((unsigned long)vdst + len1, len2);
1210		}
1211		l_item2->p_lln = LINK_END;
1212		l_item2->vlln = NULL;
1213	
1214		if (reuse == 0)
