1220			val = hal_readl(DMA_IRQ_STAT(high));
1221			if (val & irq_mask) {
1222				// clear dma irq pending and reset
1223				hal_writel(irq_mask, DMA_IRQ_STAT(high));
1224				hal_writel(CHAN_PAUSE, DMA_PAUSE(chan_num));
1225				hal_writel(CHAN_STOP, DMA_ENABLE(chan_num));
1226				hal_writel(CHAN_RESUME, DMA_PAUSE(chan_num));
1227				break;
1228			}
1229		}
1230		reg_data = *reg & (~(1<<4)); *reg = reg_data | (1<<4); // PE4 high
1231	
1232		if (reuse == 0) {
1233			// change desc
1234			chan->desc = l_item2;
1235			desc_addr = __va_to_pa((unsigned long)chan->desc) - SUNXI_DMA_PHYADDR_OFFSET;
