1304	void hal_dma_resource_get(void)
1305	{
1306	    uint32_t i = 0, high = 0, secure = 0;
1307	
1308	    memset((void *)dma_chan_source, 0, NR_MAX_CHAN * sizeof(struct sunxi_dma_chan));
1309	
1310	    hal_spin_lock_init(&dma_lock);
1311	
1312	    /* disable auto gating */
1313	    hal_writel(DMA_MCLK_GATE | DMA_COMMON_GATE | DMA_CHAN_GATE, DMA_GATE);
1314	    sunxi_dma_clk_init(true);
1315	
1316	    for (i = 0; i < NR_MAX_CHAN; i++)
1317	        hal_spin_lock_init(&dma_chan_source[i].lock);
1318	
1319	    for (i = START_CHAN_OFFSET + SUNXI_DMA_CHAN_START; i < START_CHAN_OFFSET + NR_MAX_CHAN; i++)
1320	    {
1321	        high = (i >= HIGH_CHAN) ? 1 : 0;
1322	        /*disable all dma irq*/
1323	        hal_writel(0, DMA_IRQ_EN(high));
1324	        /*clear all dma irq pending*/
1325	        hal_writel(0xffffffff, DMA_IRQ_STAT(high));
1326	
1327	#ifdef ENABLE_SECURE_DMA
1328	        /*set secure*/
1329	        secure = hal_readl(DMA_SECURE);
1330	        if ((secure & (1 << i)) != 0)
1331	            hal_writel(secure & (~(1 << i)), DMA_SECURE);
1332	#else
1333	        /*set non-secure*/
1334	        secure = hal_readl(DMA_SECURE);
1335	        if ((secure & (1 << i)) == 0)
1336	            hal_writel(secure | (1 << i), DMA_SECURE);
1337	#endif
1338	    }
1339	
1340	    /*request dma irq*/
1341	#ifdef ENABLE_SECURE_DMA
1342	    if (hal_request_irq(DMA_SECURE_IRQ_NUM, sunxi_dma_irq_handle, "dma-s", NULL) < 0)
1343	    {
1344	        DMA_ERR("[dma] request secure irq error\n");
1345	    }
1346	    hal_enable_irq(DMA_SECURE_IRQ_NUM);
1347	#else
1348	    if (hal_request_irq(DMA_IRQ_NUM, sunxi_dma_irq_handle, "dma", NULL) < 0)
1349	    {
1350	        DMA_ERR("[dma] request irq error\n");
1351	    }
1352	    hal_enable_irq(DMA_IRQ_NUM);
1353	#endif
1354	}
