236	static void llm_response_cb(int status, const char *response, void *cookie)
237	{
238	    (void)cookie;
239	
240	    pthread_mutex_lock(&g_msg_lock);
241	
242	    g_msg_status = status;
243	    if ((status == 0 || status == 1) && response != NULL)
244	      {
245	        /* status 0 = final reply, status 1 = streaming fragment (cumulative
246	         * text so far). Both carry the running reply text. */
247	        strncpy(g_pending_msg, response, MSG_BUF_LEN - 1);
248	        g_pending_msg[MSG_BUF_LEN - 1] = '\0';
249	      }
250	    else
251	      {
252	        snprintf(g_pending_msg, MSG_BUF_LEN, "[LLM error: %d]", status);
253	      }
254	    g_msg_ready = true;
255	
256	    syslog(LOG_INFO, "[kid_buddy] llm_cb status=%d len=%d\n",
257	           status, (int)strlen(g_pending_msg));
258	
259	    pthread_mutex_unlock(&g_msg_lock);
260	}
