262	/* Notify callback for UNSOLICITED outbound messages (e.g. cron-fired
263	 * reminders) delivered while no velaclaw_ask is in flight. Route into the
264	 * same g_pending_msg / g_msg_ready slot that llm_response_cb uses, so the
265	 * existing poll_timer_cb path (emoji/markdown strip → LCD → TTS) speaks and
266	 * displays the reminder with zero new UI code. Partial fragments (status 1)
267	 * are ignored — cron reminders arrive as a single complete message. */
268	static void kid_notify_cb(int status, const char *msg, void *cookie)
269	{
270	    (void)cookie;
271	
272	    if (msg == NULL || status == 1)
273	      {
274	        return;
275	      }
276	
277	    pthread_mutex_lock(&g_msg_lock);
278	    g_msg_status = 0;
279	    strncpy(g_pending_msg, msg, MSG_BUF_LEN - 1);
280	    g_pending_msg[MSG_BUF_LEN - 1] = '\0';
281	    g_msg_ready = true;
282	    pthread_mutex_unlock(&g_msg_lock);
283	
284	    syslog(LOG_INFO, "[kid_buddy] notify_cb len=%d\n", (int)strlen(msg));
285	}
