287	/****************************************************************************
288	 * Send a message to LLM with current role's system prompt
289	 ****************************************************************************/
290	
291	static void ui_show_chat_screen(void);
292	
293	static void send_to_llm(const char *user_text)
294	{
295	    /* A voice wake command can arrive before the kid has tapped a role: the
296	     * chat widgets (g_chat_status etc.) are created lazily in
297	     * ui_show_chat_screen(), so they are still NULL and lv_label_set_text()
298	     * below would fault.  Show the default-role chat screen first so every
299	     * label we touch actually exists. */
300	    if (g_chat_status == NULL)
301	      {
302	        ui_show_chat_screen();
303	      }
304	
305	    if (!g_agent_connected || g_agent_client == NULL)
306	      {
307	        lv_label_set_text(g_chat_status, "Agent offline - start 'ai_agent &' first");
308	        return;
309	      }
310	
311	    /* Mark an interaction in flight so the wake loop stays quiet through the
312	     * LLM request + TTS reply. Cleared by the TTS worker after the final
313	     * reply is spoken (or here if the request fails immediately). */
314	    g_reply_busy = 1;
315	
316	    /* Build full prompt: system prompt + user text */
317	    const role_def_t *role = &g_roles[g_current_role];
318	    char full_prompt[MSG_BUF_LEN];
319	    snprintf(full_prompt, MSG_BUF_LEN,
320	             "[SYSTEM]\n%s\n\n[USER]\n%s",
321	             role->system_prompt, user_text);
322	
323	    velaclaw_ask_req_t req = {
324	        .text       = full_prompt,
325	        .timeout_ms = 15000  /* 15 second timeout */
326	    };
327	
328	    /* Start a fresh response: bump the epoch and reset the spoken offset so
329	     * the streamed reply is spoken from the beginning, and drop any stale
330	     * fragment still queued for the previous question. */
331	    pthread_mutex_lock(&g_tts_lock);
332	    g_tts_epoch++;
333	    g_spoken_len = 0;
334	    g_tts_pending_ready = false;
