459	/* ── Streaming TTS worker ─────────────────────────────────────
460	 * Speak a response aloud in a background thread so the LVGL UI stays
461	 * responsive while TTS synthesizes and plays. A single worker thread
462	 * serializes every speak (voice_channel_speak aborts any in-progress speak
463	 * on a concurrent call). The worker does NOT speak partial fragments as they
464	 * stream: it waits for the final fragment and speaks the whole reply in one
465	 * voice_channel_speak() call. This keeps a single ALSA open/close cycle and
466	 * lets voice_channel_speak() buffer the full reply for continuous playback. */
467	
468	static void *tts_stream_worker(void *arg)
469	{
470	    (void)arg;
471	
472	    for (;;)
473	      {
474	        char text[MSG_BUF_LEN];
475	        bool final = false;
476	        unsigned int epoch;
477	        size_t spoken;
478	
479	        pthread_mutex_lock(&g_tts_lock);
480	        while (!g_tts_pending_ready)
481	          {
482	            pthread_cond_wait(&g_tts_cond, &g_tts_lock);
483	          }
484	        strncpy(text, g_tts_pending, MSG_BUF_LEN - 1);
485	        text[MSG_BUF_LEN - 1] = '\0';
486	        final = g_tts_pending_final;
487	        epoch = g_tts_epoch;
488	        spoken = g_spoken_len;
489	        g_tts_pending_ready = false;
490	        g_tts_pending_final = false;
491	        pthread_mutex_unlock(&g_tts_lock);
492	
493	        size_t len = strlen(text);
494	
495	        if (spoken > len)
496	          {
497	            spoken = len; /* offset reset under us mid-speak */
498	          }
499	
500	        /* Speak the whole reply in one voice_channel_speak() call, and only
501	         * once the reply is complete (final). Speaking sentence-by-sentence
502	         * as the text streamed made the worker open/close the ALSA codec
503	         * once per fragment; the codec's external-speaker PA (gpio_spk) is
504	         * armed on the first open but not reliably re-armed on a later open
505	         * in the same response, so only the first sentence was audible. A
506	         * single open/prepare/write/close cycle is the sequence the codec
507	         * plays reliably, and voice_channel_speak() already buffers the full
508	         * reply (fetch-then-play) so the story reads continuously. We trade
509	         * a later first word for complete, continuous speech — the priority
510	         * for a child's toy. */
511	        if (!final)
512	          {
513	            continue;
514	          }
515	
516	        syslog(LOG_INFO,
517	               "[kid_buddy] tts_worker final=1 len=%d speak_whole\n",
518	               (int)len);
519	
520	        if (len > spoken)
521	          {
522	            g_reply_busy = 1;
523	            voice_channel_speak(text);
524	            g_reply_busy = 0;   /* final reply spoken, wake loop may listen */
525	
526	            pthread_mutex_lock(&g_tts_lock);
527	            /* Advance only if no newer question reset the offset mid-speak. */
528	            if (epoch == g_tts_epoch)
529	              {
530	                g_spoken_len = len;
531	              }
532	            pthread_mutex_unlock(&g_tts_lock);
533	          }
534	      }
