941	static void poll_timer_cb(lv_timer_t *timer)
942	{
943	    static int heartbeat;
944	
945	    (void)timer;
946	
947	    /* Liveness probe — logs once every ~10s (200ms period × 50). If this
948	     * stops after a TTS speak finishes, the LVGL thread has hung (screen
949	     * frozen), as opposed to a touch-only stall. */
950	    if (++heartbeat % 50 == 0)
951	      {
952	        syslog(LOG_INFO, "[kid_buddy] LVGL heartbeat #%d\n", heartbeat);
953	      }
954	
955	    /* Snapshot the latest LLM message under the same lock the callback uses,
956	     * so the status and text are read as one consistent pair (a torn read
957	     * could otherwise tag a stale short fragment as "final" and drop the
958	     * rest of the reply). */
959	    int  msg_status;
960	    char msg_text[MSG_BUF_LEN];
961	    bool have_msg = false;
962	
963	    pthread_mutex_lock(&g_msg_lock);
964	    if (g_msg_ready)
965	      {
966	        g_msg_ready = false;
967	        msg_status = g_msg_status;
968	        strncpy(msg_text, g_pending_msg, MSG_BUF_LEN - 1);
969	        msg_text[MSG_BUF_LEN - 1] = '\0';
970	        have_msg = true;
971	      }
972	    pthread_mutex_unlock(&g_msg_lock);
973	
974	    if (have_msg)
975	      {
976	        /* Drop emoji before display AND before TTS: the LCD font can't show
977	         * them (tofu boxes) and MiMo TTS reads them as a stray "think" word. */
978	        strip_emoji(msg_text);
979	        /* Drop Markdown ("---", **bold**, #headers, bullets) — TTS reads the
980	         * "---" rule as a stray word too. */
981	        strip_markdown(msg_text);
982	
983	        /* Hide spinner as soon as the first text arrives. */
984	        if (g_chat_spinner)
985	          {
986	            lv_obj_add_flag(g_chat_spinner, LV_OBJ_FLAG_HIDDEN);
987	          }
988	
989	        if (msg_status == 0 || msg_status == 1)
990	          {
991	            /* Show the running reply text. */
992	            lv_label_set_text(g_chat_msg_area, msg_text);
993	
994	            /* Feed the cumulative text to the TTS worker. Partial fragments
995	             * (status 1) are spoken sentence-by-sentence as they complete;
996	             * the final fragment (status 0) flushes the remainder. */
997	            enqueue_tts(msg_text, msg_status == 0);
998	
999	            if (msg_status == 0)
1000	              {
1001	                lv_label_set_text(g_chat_status, "Tap 'Ask me!' to continue");
1002	              }
1003	            else
1004	              {
1005	                lv_label_set_text(g_chat_status, "Replying...");
1006	              }
1007	          }
1008	        else
1009	          {
1010	            lv_label_set_text(g_chat_msg_area, msg_text);
1011	            lv_label_set_text(g_chat_status, "Error - check LLM config");
1012	            g_reply_busy = 0;  /* LLM errored out, release the wake loop */
1013	          }
1014	      }
1015	
1016	    /* Voice wake-word command handoff: the wake thread writes the command
1017	     * (wake word already stripped), we call send_to_llm() here so all LVGL
1018	     * access stays on this thread. */
1019	    char wake_cmd[MSG_BUF_LEN];
1020	    bool have_wake = false;
1021	
1022	    pthread_mutex_lock(&g_wake_cmd_lock);
1023	    if (g_wake_cmd_ready)
1024	      {
1025	        g_wake_cmd_ready = false;
1026	        strncpy(wake_cmd, g_wake_cmd, MSG_BUF_LEN - 1);
1027	        wake_cmd[MSG_BUF_LEN - 1] = '\0';
1028	        have_wake = true;
1029	      }
1030	    pthread_mutex_unlock(&g_wake_cmd_lock);
1031	
1032	    if (have_wake)
1033	      {
1034	        send_to_llm(wake_cmd);
1035	      }
1036	}
