635	/* Listen for a single utterance and return its ASR text (heap-allocated).
636	 * Returns NULL if nothing was heard or ASR failed; caller free()s the result.
637	 * The mic is opened fresh each call so it is only live while we are actually
638	 * waiting for speech (never during TTS playback). */
639	static char *listen_one_utterance(void)
640	{
641	    /* Never open the mic while a reply is playing: capture and playback share
642	     * the codec's DMA engine, and opening the mic holds a DMA channel that the
643	     * TTS playback then fails to acquire ("request dma chan failed").  Check
644	     * BEFORE opening — not just inside the read loop — so the mic is not even
645	     * opened (and no DMA channel is grabbed) during a reply. */
646	    if (g_reply_busy)
647	      {
648	        return NULL;
649	      }
650	
651	    audio_capture_t *cap = audio_capture_open(NULL, WAKE_SAMPLE_RATE, 1, 16);
652	    if (!cap) {
653	        syslog(LOG_ERR, "[kid_buddy] wake: capture open failed\n");
654	        return NULL;
655	    }
656	
657	    if (audio_capture_start(cap) < 0) {
658	        syslog(LOG_ERR, "[kid_buddy] wake: capture start failed\n");
659	        audio_capture_close(cap);
660	        return NULL;
661	    }
662	
663	    unsigned char *pcm = malloc(WAKE_MAX_BYTES);
664	    if (!pcm) {
665	        audio_capture_close(cap);
666	        return NULL;
667	    }
668	
669	    size_t pcm_len = 0;
670	    bool started = false;
671	    int silence_run = 0;
672	
673	    syslog(LOG_INFO, "[kid_buddy] wake: listening...\n");
674	
675	    while (pcm_len < WAKE_MAX_BYTES) {
676	        /* A touch-triggered interaction may have started while we listened. */
677	        if (g_reply_busy) {
678	            syslog(LOG_INFO, "[kid_buddy] wake: reply busy, abort listen\n");
679	            break;
680	        }
681	
682	        int16_t chunk[WAKE_CHUNK_BYTES / 2];
683	        int n = audio_capture_read(cap, chunk, sizeof(chunk));
684	        if (n <= 0) {
685	            if (n < 0) {
686	                syslog(LOG_WARNING, "[kid_buddy] wake: read=%d\n", n);
687	                break;
688	            }
689	            continue;  /* EAGAIN / zero-length */
690	        }
691	
692	        int nsamp = n / (int)sizeof(int16_t);
693	        int64_t sum = 0;
694	        for (int i = 0; i < nsamp; i++) {
695	            int32_t v = chunk[i];
696	            sum += (int64_t)v * v;
697	        }
698	        int64_t ms = nsamp > 0 ? sum / nsamp : 0;
699	
700	        if (!started && ms >= WAKE_START_MSQ) {
701	            started = true;
702	            silence_run = 0;
703	            syslog(LOG_INFO, "[kid_buddy] wake: speech start (msq=%lld)\n",
704	                   (long long)ms);
705	        }
706	
707	        if (started) {
708	            if (pcm_len + (size_t)n <= WAKE_MAX_BYTES) {
709	                memcpy(pcm + pcm_len, chunk, n);
710	                pcm_len += n;
711	            }
712	
713	            if (ms < WAKE_END_MSQ) {
714	                if (++silence_run >= WAKE_SILENCE_CHUNKS) {
715	                    syslog(LOG_INFO, "[kid_buddy] wake: speech end (%zu bytes)\n",
716	                           pcm_len);
717	                    break;
718	                }
719	            } else {
720	                silence_run = 0;
721	            }
722	        }
723	    }
724	
725	    audio_capture_abort(cap);
726	    audio_capture_close(cap);
727	
728	    if (!started || pcm_len < WAKE_CHUNK_BYTES) {
729	        syslog(LOG_INFO, "[kid_buddy] wake: no speech (%zu bytes)\n", pcm_len);
730	        free(pcm);
731	        return NULL;
732	    }
733	
734	    char text[MSG_BUF_LEN];
735	    int ret = voice_asr_recognize(pcm, pcm_len, text, sizeof(text));
736	    free(pcm);
737	
738	    if (ret < 0 || text[0] == '\0') {
739	        syslog(LOG_WARNING, "[kid_buddy] wake: ASR failed/empty (ret=%d)\n",
740	               ret);
741	        return NULL;
742	    }
743	
744	    return strdup(text);
745	}
