186	/* Message queue between LLM callback and LVGL thread.
187	 * The LLM callback (ai_agent/outbound-dispatch thread) writes g_msg_status /
188	 * g_pending_msg / g_msg_ready while the LVGL timer reads them. Guard with a
189	 * mutex so the status byte and the text can't be torn apart mid-read (which
190	 * made a "final" status pair up with a stale short fragment). */
191	static char    g_pending_msg[MSG_BUF_LEN];
192	static bool    g_msg_ready = false;
193	static int     g_msg_status = 0;
194	static pthread_mutex_t g_msg_lock = PTHREAD_MUTEX_INITIALIZER;
195	
196	/* Streaming TTS state: a single worker thread speaks the whole reply in one
197	 * voice_channel_speak() call once the reply is complete. voice_channel_speak()
198	 * aborts any in-progress speak when called concurrently, so every speak must
199	 * go through this one thread. The pending slot is "latest wins" — a newer
200	 * fragment replaces an older one still waiting to be spoken. */
201	static pthread_mutex_t g_tts_lock = PTHREAD_MUTEX_INITIALIZER;
202	static pthread_cond_t  g_tts_cond  = PTHREAD_COND_INITIALIZER;
203	static char     g_tts_pending[MSG_BUF_LEN];
