/* A bare backchannel / acknowledgment ("嗯", "啊", "哦", …) is not a command —
 * it's the kid murmuring, or the mic picking up the tail of the TTS / ambient
 * noise and MiMo ASR transcribing it as a filler. Sending it to the LLM during
 * the follow-up window makes the buddy answer itself and repeat the story in a
 * loop, so drop these outright. Only pure fillers are filtered; real short
 * answers like "好"/"要"/"1" (a choice) still pass through. */
static bool is_filler_utterance(const char *s)
{
    static const char *const fillers[] = {
        "嗯",   "嗯嗯", "嗯嗯嗯", "啊",   "啊嗯", "哦",   "哦哦",
        "呃",   "额",   "诶",   "喂",   "哟",   "噢",   "唔",
        "嘿",   "哈",   "哈哈", "呵呵", "嘿嘿", "唉",   "哼",
