80	static int configure_alsa_playback(snd_pcm_t* pcm,
81	    unsigned int sample_rate, unsigned int channels)
82	{
83	    snd_pcm_hw_params_t* hw;
84	    snd_pcm_sw_params_t* sw;
85	    snd_pcm_uframes_t period_frames = sample_rate / 10;
86	    snd_pcm_uframes_t buffer_frames;
87	    snd_pcm_uframes_t boundary;
88	    int ret;
89	
90	    if (period_frames == 0) {
91	        period_frames = 256;
92	    }
93	
94	    buffer_frames = period_frames * 4;
95	
96	    snd_pcm_hw_params_alloca(&hw);
97	    ret = snd_vela_pcm_hw_params_any(pcm, hw);
98	    if (ret < 0) {
99	        return ret;
100	    }
101	
102	    ret = snd_vela_pcm_hw_params_set_access(pcm, hw,
103	        SND_PCM_ACCESS_RW_INTERLEAVED);
104	    if (ret < 0) {
105	        return ret;
106	    }
107	
108	    ret = snd_vela_pcm_hw_params_set_format(pcm, hw, SND_PCM_FORMAT_S16_LE);
109	    if (ret < 0) {
110	        return ret;
111	    }
112	
113	    ret = snd_vela_pcm_hw_params_set_channels(pcm, hw, channels);
114	    if (ret < 0) {
115	        return ret;
116	    }
117	
118	    ret = snd_vela_pcm_hw_params_set_rate(pcm, hw, sample_rate, 0);
119	    if (ret < 0) {
120	        return ret;
121	    }
122	
123	    ret = snd_vela_pcm_hw_params_set_period_size(pcm, hw,
124	        period_frames, 0);
125	    if (ret < 0) {
126	        return ret;
127	    }
128	
129	    ret = snd_vela_pcm_hw_params_set_buffer_size(pcm, hw,
130	        buffer_frames);
131	    if (ret < 0) {
132	        return ret;
133	    }
134	
135	    ret = snd_vela_pcm_hw_params(pcm, hw);
136	    if (ret < 0) {
137	        return ret;
138	    }
139	
140	    snd_pcm_sw_params_alloca(&sw);
141	    ret = snd_vela_pcm_sw_params_current(pcm, sw);
142	    if (ret < 0) {
143	        return ret;
144	    }
145	
146	    ret = snd_vela_pcm_sw_params_get_boundary(sw, &boundary);
147	    if (ret < 0) {
148	        return ret;
149	    }
150	
151	    ret = snd_vela_pcm_sw_params_set_start_threshold(pcm, sw,
152	        buffer_frames);
153	    if (ret < 0) {
154	        return ret;
155	    }
156	
157	    ret = snd_vela_pcm_sw_params_set_silence_size(pcm, sw, boundary);
158	    if (ret < 0) {
159	        return ret;
160	    }
161	
162	    ret = snd_vela_pcm_sw_params_set_stop_threshold(pcm, sw,
163	        buffer_frames);
164	    if (ret < 0) {
165	        return ret;
166	    }
167	
168	    ret = snd_vela_pcm_sw_params_set_avail_min(pcm, sw, period_frames);
169	    if (ret < 0) {
170	        return ret;
171	    }
172	
173	    return snd_vela_pcm_sw_params(pcm, sw);
174	}
