470	
471	/* ── Streaming TTS worker ─────────────────────────────────────
472	 * Speak a response aloud in a background thread so the LVGL UI stays
473	 * responsive while TTS synthesizes and plays. A single worker thread
474	 * serializes every speak (voice_channel_speak aborts any in-progress speak
475	 * on a concurrent call). The worker does NOT speak partial fragments as they
476	 * stream: it waits for the final fragment and speaks the whole reply in one
477	 * voice_channel_speak() call. This keeps a single ALSA open/close cycle and
478	 * lets voice_channel_speak() buffer the full reply for continuous playback. */
479	
480	static void *tts_stream_worker(void *arg)
481	{
482	    (void)arg;
483	
484	    for (;;)
485	      {
486	        char text[MSG_BUF_LEN];
487	        bool final = false;
488	        unsigned int epoch;
489	        size_t spoken;
490	
491	        pthread_mutex_lock(&g_tts_lock);
492	        while (!g_tts_pending_ready)
493	          {
494	            pthread_cond_wait(&g_tts_cond, &g_tts_lock);
495	          }
496	        strncpy(text, g_tts_pending, MSG_BUF_LEN - 1);
497	        text[MSG_BUF_LEN - 1] = '\0';
498	        final = g_tts_pending_final;
499	        epoch = g_tts_epoch;
500	        spoken = g_spoken_len;
501	        g_tts_pending_ready = false;
502	        g_tts_pending_final = false;
503	        pthread_mutex_unlock(&g_tts_lock);
504	
505	        size_t len = strlen(text);
506	
507	        if (spoken > len)
508	          {
509	            spoken = len; /* offset reset under us mid-speak */
510	          }
511	
512	        /* Speak the whole reply in one voice_channel_speak() call, and only
513	         * once the reply is complete (final). Speaking sentence-by-sentence
514	         * as the text streamed made the worker open/close the ALSA codec
515	         * once per fragment; the codec's external-speaker PA (gpio_spk) is
516	         * armed on the first open but not reliably re-armed on a later open
517	         * in the same response, so only the first sentence was audible. A
518	         * single open/prepare/write/close cycle is the sequence the codec
519	         * plays reliably, and voice_channel_speak() already buffers the full
520	         * reply (fetch-then-play) so the story reads continuously. We trade
521	         * a later first word for complete, continuous speech — the priority
522	         * for a child's toy. */
523	        if (!final)
524	          {
525	            continue;
526	          }
527	
528	        syslog(LOG_INFO,
529	               "[kid_buddy] tts_worker final=1 len=%d speak_whole\n",
530	               (int)len);
531	
532	        if (len > spoken)
533	          {
534	            g_reply_busy = 1;
535	            voice_channel_speak(text);
536	            g_reply_busy = 0;   /* final reply spoken, wake loop may listen */
537	            g_last_reply_ms = now_ms();  /* arm the follow-up answer window */
538	
539	            pthread_mutex_lock(&g_tts_lock);
540	            /* Advance only if no newer question reset the offset mid-speak. */
541	            if (epoch == g_tts_epoch)
542	              {
543	                g_spoken_len = len;
544	              }
545	            pthread_mutex_unlock(&g_tts_lock);
546	          }
547	      }
548	
549	    return NULL;
550	}
551	
552	/* Enqueue the latest cumulative reply text for speaking. "latest wins" — a
553	 * newer fragment replaces an older one still waiting in the slot. */
554	static void enqueue_tts(const char *text, bool final)
555	{
556	    pthread_mutex_lock(&g_tts_lock);
557	    strncpy(g_tts_pending, text, MSG_BUF_LEN - 1);
558	    g_tts_pending[MSG_BUF_LEN - 1] = '\0';
559	    g_tts_pending_final = final;
560	    g_tts_pending_ready = true;
561	    syslog(LOG_INFO, "[kid_buddy] enqueue_tts final=%d len=%d\n",
562	           (int)final, (int)strlen(g_tts_pending));
563	    pthread_cond_signal(&g_tts_cond);
564	    pthread_mutex_unlock(&g_tts_lock);
565	}
