966	int snd_vela_pcm_recover(snd_pcm_t *pcm, int err, int silent)
967	{
968		assert(pcm);
969		if (err > 0)
970			err = -err;
971		if (err == -EPIPE) {
972			const char *s = NULL;
973			if (snd_vela_pcm_stream(pcm) == SND_VELA_PCM_STREAM_PLAYBACK) {
974				s = "underrun";
975			} else {
976				s = "overrun";
977			}
978			if (silent == 0) {
979				awalsa_err("%s occured\n", s);
980			}
981			err = snd_vela_pcm_prepare(pcm);
982			if (err < 0) {
983				awalsa_err("cannot recovery from %s, prepare return: %d",
984					s, err);
985				return err;
986			}
987			return 0;
988		} else if (err == -ESTRPIPE) {
989			awalsa_info("resume...\n");
990			while ((err = snd_vela_pcm_resume(pcm)) == -EAGAIN) {
991				#ifdef CONFIG_KERNEL_FREERTOS
992				vTaskDelay(pdMS_TO_TICKS(1));
993				#elif defined(CONFIG_OS_NUTTX)
994				hal_msleep(1);
995				#endif
996			}
997			if (err < 0) {
998				err = snd_vela_pcm_prepare(pcm);
999				awalsa_err("cannot recovery from suspend, prepare return: %d", err);
1000				return err;
1001			}
1002			return 0;
1003		}
1004		return err;

