1470		/* detect already open or not */
1471		if (pcm->streams[stream]->ref_count != 0)
1472			return -EBUSY;
1473	
1474		snd_mutex_lock(pcm->open_mutex);
1475		substream = pcm->streams[stream];
1476		if (!substream) {
1477			snd_mutex_unlock(pcm->open_mutex);
1478			return -ENODEV;
1479		}
1480		substream->ref_count++;
1481		ret = snd_pcm_open_substream(pcm, stream);
1482		if (ret < 0) {
1483			snd_err("open substream failed,%d\n", ret);
1484			snd_mutex_unlock(pcm->open_mutex);
1485			return ret;
1486		}
