581	static int junk_prefix_len(const char *p)
582	{
583	    for (int i = 0; g_junk[i]; i++) {
584	        size_t n = strlen(g_junk[i]);
585	        if (strncmp(p, g_junk[i], n) == 0) {
586	            return (int)n;
587	        }
588	    }
