592	static int junk_suffix_len(const char *p, size_t len)
593	{
594	    for (int i = 0; g_junk[i]; i++) {
595	        size_t n = strlen(g_junk[i]);
596	        if (n <= len && strncmp(p + len - n, g_junk[i], n) == 0) {
597	            return (int)n;
598	        }
599	    }
600	    return 0;
601	}
