603	/* Strip whitespace + punctuation from both ends of a command in place. */
604	static void trim_junk(char *s)
605	{
606	    char *start = s;
607	    int n;
608	
609	    while (*start && (n = junk_prefix_len(start)) != 0) {
610	        start += n;
611	    }
612	
613	    size_t len = strlen(start);
614	    while (len > 0 && (n = junk_suffix_len(start, len)) != 0) {
615	        start[len - n] = '\0';
616	        len -= n;
617	    }
618	
619	    if (start != s) {
620	        memmove(s, start, len + 1);
621	    }
622	}
