624	/* Remove every occurrence of the wake word from text, then trim junk.
625	 * Returns the length of the remaining command (0 = wake word only). */
626	static size_t strip_wake_word(const char *text, char *out, size_t cap)
627	{
628	    size_t wlen = strlen(WAKE_WORD);
629	    size_t olen = 0;
630	    const char *p = text;
631	
632	    while (*p) {
633	        if (strncmp(p, WAKE_WORD, wlen) == 0) {
634	            p += wlen;
635	        } else {
636	            if (olen + 1 < cap) {
637	                out[olen++] = *p;
638	            }
639	            p++;
640	        }
641	    }
642	    out[olen] = '\0';
643	
644	    trim_junk(out);
645	    return strlen(out);
646	}
