648	/* Case-insensitive compare for the ASCII filler list. */
649	static bool ascii_ieq(const char *a, const char *b)
650	{
651	    while (*a && *b) {
652	        char ca = *a, cb = *b;
653	        if (ca >= 'A' && ca <= 'Z') ca += 'a' - 'A';
654	        if (cb >= 'A' && cb <= 'Z') cb += 'a' - 'A';
655	        if (ca != cb) return false;
656	        a++; b++;
657	    }
658	    return *a == '\0' && *b == '\0';
659	}
