661	/* A bare backchannel / acknowledgment ("嗯", "啊", "Yeah", …) is not a command —
662	 * it's the kid murmuring, or the mic picking up the tail of the TTS / ambient
663	 * noise and MiMo ASR transcribing it as a filler. Sending it to the LLM during
664	 * the follow-up window makes the buddy answer itself and keep talking, so drop
665	 * these outright. Only pure fillers are filtered; real short answers like
666	 * "好"/"要"/"1" (a choice) still pass through. */
667	static bool is_filler_utterance(const char *s)
668	{
669	    static const char *const fillers[] = {
670	        "嗯",   "嗯嗯", "嗯嗯嗯", "啊",   "啊嗯", "哦",   "哦哦",
671	        "呃",   "额",   "诶",   "喂",   "哟",   "噢",   "唔",
672	        "嘿",   "哈",   "哈哈", "呵呵", "嘿嘿", "唉",   "哼",
673	        NULL
674	    };
675	    /* MiMo ASR occasionally transcribes a noise burst as an English
676	     * backchannel word ("Yeah.", "Okay", "Uh") — treat those as filler too. */
677	    static const char *const en_fillers[] = {
678	        "yeah", "yes", "yep", "ok", "okay", "oh", "uh", "um", "umm",
679	        "hmm", "hmmm", "ah", "eh", "hey", "hi", "hello", "well", "so",
680	        "mhm", "uhhuh", "uh-huh", "huh", "no", NULL
681	    };
682	
683	    for (int i = 0; fillers[i] != NULL; i++) {
684	        if (strcmp(s, fillers[i]) == 0) {
685	            return true;
686	        }
687	    }
688	    for (int i = 0; en_fillers[i] != NULL; i++) {
689	        if (ascii_ieq(s, en_fillers[i])) {
690	            return true;
691	        }
692	    }
693	    return false;
694	}
