696	/* Monotonic clock in milliseconds (CLOCK_MONOTONIC). Used for the follow-up
697	 * answer window so a kid can answer a question without re-saying the wake word. */
698	static int64_t now_ms(void)
699	{
700	    struct timespec ts;
701	    clock_gettime(CLOCK_MONOTONIC, &ts);
702	    return (int64_t)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
703	}
