705	/* Listen for a single utterance and return its ASR text (heap-allocated).
706	 * Returns NULL if nothing was heard or ASR failed; caller free()s the result.
707	 * The mic is opened fresh each call so it is only live while we are actually
708	 * waiting for speech (never during TTS playback).
709	 *
710	 * timeout_ms > 0 bounds the listen: if the kid hasn't started speaking within
711	 * timeout_ms (used for the follow-up answer window), give up and return NULL.
712	 * timeout_ms == 0 waits indefinitely for speech (normal wake-word listening). */
713	static char *listen_one_utterance(int timeout_ms)
714	{
715	    /* Never open the mic while a reply is playing: capture and playback share
716	     * the codec's DMA engine, and opening the mic holds a DMA channel that the
717	     * TTS playback then fails to acquire ("request dma chan failed").  Check
718	     * BEFORE opening — not just inside the read loop — so the mic is not even
719	     * opened (and no DMA channel is grabbed) during a reply. */
720	    if (g_reply_busy)
721	      {
722	        return NULL;
723	      }
724	
725	    audio_capture_t *cap = audio_capture_open(NULL, WAKE_SAMPLE_RATE, 1, 16);
726	    if (!cap) {
727	        syslog(LOG_ERR, "[kid_buddy] wake: capture open failed\n");
728	        return NULL;
729	    }
730	
731	    if (audio_capture_start(cap) < 0) {
732	        syslog(LOG_ERR, "[kid_buddy] wake: capture start failed\n");
733	        audio_capture_close(cap);
734	        return NULL;
735	    }
736	
737	    unsigned char *pcm = malloc(WAKE_MAX_BYTES);
738	    if (!pcm) {
739	        audio_capture_close(cap);
740	        return NULL;
741	    }
742	
743	    size_t pcm_len = 0;
744	    bool started = false;
745	    int silence_run = 0;
746	    int64_t deadline = (timeout_ms > 0) ? (now_ms() + timeout_ms) : 0;
747	
748	    syslog(LOG_INFO, "[kid_buddy] wake: listening...\n");
749	
750	    while (pcm_len < WAKE_MAX_BYTES) {
751	        /* A touch-triggered interaction may have started while we listened. */
752	        if (g_reply_busy) {
753	            syslog(LOG_INFO, "[kid_buddy] wake: reply busy, abort listen\n");
754	            break;
755	        }
756	
757	        /* Follow-up window closed: if speech hasn't started yet, stop waiting. */
758	        if (!started && deadline > 0 && now_ms() >= deadline) {
759	            syslog(LOG_INFO, "[kid_buddy] wake: follow-up timeout\n");
760	            break;
761	        }
762	
763	        int16_t chunk[WAKE_CHUNK_BYTES / 2];
764	        int n = audio_capture_read(cap, chunk, sizeof(chunk));
765	        if (n <= 0) {
766	            if (n < 0) {
767	                syslog(LOG_WARNING, "[kid_buddy] wake: read=%d\n", n);
768	                break;
769	            }
770	            continue;  /* EAGAIN / zero-length */
771	        }
772	
773	        int nsamp = n / (int)sizeof(int16_t);
774	        int64_t sum = 0;
775	        for (int i = 0; i < nsamp; i++) {
776	            int32_t v = chunk[i];
777	            sum += (int64_t)v * v;
778	        }
779	        int64_t ms = nsamp > 0 ? sum / nsamp : 0;
780	
781	        if (!started && ms >= WAKE_START_MSQ) {
782	            started = true;
783	            silence_run = 0;
784	            syslog(LOG_INFO, "[kid_buddy] wake: speech start (msq=%lld)\n",
785	                   (long long)ms);
786	        }
787	
788	        if (started) {
789	            if (pcm_len + (size_t)n <= WAKE_MAX_BYTES) {
790	                memcpy(pcm + pcm_len, chunk, n);
791	                pcm_len += n;
792	            }
793	
794	            if (ms < WAKE_END_MSQ) {
795	                if (++silence_run >= WAKE_SILENCE_CHUNKS) {
796	                    syslog(LOG_INFO, "[kid_buddy] wake: speech end (%zu bytes)\n",
797	                           pcm_len);
798	                    break;
799	                }

800	            } else {
801	                silence_run = 0;
802	            }
803	        }
804	    }
805	
806	    audio_capture_abort(cap);
807	    audio_capture_close(cap);
808	
809	    if (!started || pcm_len < WAKE_CHUNK_BYTES) {
810	        syslog(LOG_INFO, "[kid_buddy] wake: no speech (%zu bytes)\n", pcm_len);
811	        free(pcm);
812	        return NULL;
813	    }
814	
815	    char text[MSG_BUF_LEN];
816	    int ret = voice_asr_recognize(pcm, pcm_len, text, sizeof(text));
817	    free(pcm);
818	
819	    if (ret < 0 || text[0] == '\0') {
820	        syslog(LOG_WARNING, "[kid_buddy] wake: ASR failed/empty (ret=%d)\n",
821	               ret);
822	        return NULL;
823	    }
824	
825	    return strdup(text);
826	}
