1317	static int sunxi_codec_prepare(struct snd_pcm_substream *substream,
1318			struct snd_dai *dai)
1319	{
1320		struct snd_codec *codec = dai->component;
1321	
1322		snd_print("\n");
1323	
1324		if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
1325			snd_codec_update_bits(codec, SUNXI_DAC_FIFOC,
1326				(1 << FIFO_FLUSH), (1 << FIFO_FLUSH));
1327			snd_codec_write(codec, SUNXI_DAC_FIFOS,
1328				(1 << DAC_TXE_INT | 1 << DAC_TXU_INT | 1 << DAC_TXO_INT));
1329			snd_codec_write(codec, SUNXI_DAC_CNT, 0);
1330		} else {
1331			snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
1332					(1 << ADC_FIFO_FLUSH), (1 << ADC_FIFO_FLUSH));
1333			snd_codec_write(codec, SUNXI_ADC_FIFOS,
1334					(1 << ADC_RXA_INT | 1 << ADC_RXO_INT));
1335			snd_codec_write(codec, SUNXI_ADC_CNT, 0);
1336		}
1337	
1338		return 0;
1339	}
