1341	static int sunxi_codec_trigger(struct snd_pcm_substream *substream,
1342			int cmd, struct snd_dai *dai)
1343	{
1344		struct snd_codec *codec = dai->component;
1345		struct sunxi_codec_info *sunxi_codec = codec->private_data;
1346	
1347		snd_print("\n");
1348		switch (cmd) {
1349		case SNDRV_PCM_TRIGGER_START:
1350		case SNDRV_PCM_TRIGGER_RESUME:
1351		case SNDRV_PCM_TRIGGER_PAUSE_RELEASE:
1352			if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
1353				snd_codec_update_bits(codec, SUNXI_DAC_FIFOC,
1354					(1 << DAC_DRQ_EN), (1 << DAC_DRQ_EN));
1355			}
1356			else if (substream->stream == SNDRV_PCM_STREAM_CAPTURE) {
1357				snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
1358					(1 << ADC_DRQ_EN), (1 << ADC_DRQ_EN));
1359				if (sunxi_codec->param.rx_sync_en && sunxi_codec->param.rx_sync_ctl)
1360					sunxi_rx_sync_control(sunxi_codec->param.rx_sync_domain,
1361							      sunxi_codec->param.rx_sync_id, 1);
1362			}
1363			break;
1364		case SNDRV_PCM_TRIGGER_STOP:
1365		case SNDRV_PCM_TRIGGER_SUSPEND:
1366		case SNDRV_PCM_TRIGGER_PAUSE_PUSH:
1367			if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
1368				snd_codec_update_bits(codec, SUNXI_DAC_FIFOC,
1369					(1 << DAC_DRQ_EN), (0 << DAC_DRQ_EN));
1370			}
1371			else if (substream->stream == SNDRV_PCM_STREAM_CAPTURE) {
1372				snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
1373					(1 << ADC_DRQ_EN), (0 << ADC_DRQ_EN));
1374				if (sunxi_codec->param.rx_sync_en && sunxi_codec->param.rx_sync_ctl)
1375					sunxi_rx_sync_control(sunxi_codec->param.rx_sync_domain,
1376							      sunxi_codec->param.rx_sync_id, 0);
1377			}
1378			break;
1379		default:
1380			return -EINVAL;
1381		}
1382	
1383		return 0;
1384	}
