1427	static void sunxi_jack_detect(void *param)
1428	{
1429		struct sunxi_codec_info *sunxi_codec = param;
1430		struct sunxi_codec_param *codec_param = &sunxi_codec->param;
1431		gpio_data_t gpio_status;
1432	
1433		if (codec_param->gpio_spk > 0) {
1434			hal_gpio_set_direction(codec_param->gpio_spk, GPIO_MUXSEL_OUT);
1435			hal_gpio_get_data(SUNXI_CODEC_JACK_DET, &gpio_status);
1436			if (gpio_status) {
1437				/* jack plug out */
1438				hal_gpio_set_data(codec_param->gpio_spk, codec_param->pa_level);
1439			} else {
1440				/* jack plug in */
1441				hal_gpio_set_data(codec_param->gpio_spk, !codec_param->pa_level);
1442			}
1443		}
1444	}
