1486				 sunxi_codec->param.rx_sync_id);
1487		}
1488	
1489		codec->codec_base_addr = (void *)SUNXI_CODEC_BASE_ADDR;
1490		codec->codec_dai->component = codec;
1491	
1492		reset = hal_reset_control_get(HAL_SUNXI_RESET, RST_BUS_AUDIO_CODEC);
1493		hal_reset_control_deassert(reset);
1494		hal_reset_control_put(reset);
1495	
1496		sunxi_codec->busclk = hal_clock_get(HAL_SUNXI_CCU, CLK_BUS_AUDIO_CODEC);

1496		sunxi_codec->busclk = hal_clock_get(HAL_SUNXI_CCU, CLK_BUS_AUDIO_CODEC);
1497		sunxi_codec->moduleclk = hal_clock_get(HAL_SUNXI_CCU, CLK_AUDIO_DAC);
1498		sunxi_codec->moduleclk1 = hal_clock_get(HAL_SUNXI_CCU, CLK_AUDIO_ADC);
1499		sunxi_codec->pllclk = hal_clock_get(HAL_SUNXI_CCU, CLK_PLL_AUDIO0);
1500		sunxi_codec->pllclk1 = hal_clock_get(HAL_SUNXI_CCU, CLK_PLL_AUDIO1_DIV5);
1501	
1502		hal_clk_set_parent(sunxi_codec->moduleclk, sunxi_codec->pllclk);
1503		hal_clk_set_parent(sunxi_codec->moduleclk1, sunxi_codec->pllclk);
1504	
1505		hal_clk_set_rate(sunxi_codec->pllclk, 22579200);
1506		hal_clk_set_rate(sunxi_codec->pllclk1, 614400000);
1507	
1508		ret = hal_clock_enable(sunxi_codec->pllclk);
1509		if (ret != HAL_CLK_STATUS_OK)
1510		    snd_err("pllclk clock enable failed.\n");
1511		ret = hal_clock_enable(sunxi_codec->pllclk1);
1512		if (ret != HAL_CLK_STATUS_OK)
1513		    snd_err("pllclk1 clock enable failed.\n");
1514		ret = hal_clock_enable(sunxi_codec->busclk);
1515		if (ret != HAL_CLK_STATUS_OK)
1516		    snd_err("busclk clock enable failed.\n");
1517		ret = hal_clock_enable(sunxi_codec->moduleclk);
1518		if (ret != HAL_CLK_STATUS_OK)
1519		    snd_err("moduleclk clock enable failed.\n");
1520		ret = hal_clock_enable(sunxi_codec->moduleclk1);
1521		if (ret != HAL_CLK_STATUS_OK)
1522		    snd_err("moduleclk1 clock enable failed.\n");
1523	
1524		sunxi_codec_init(codec);
1525	#ifdef SUNXI_ADC_DAUDIO_SYNC
1526		adc_daudio_sync_codec = codec;
1527	#endif
1528	
1529		if (sunxi_codec->param.hp_detect_used) {
1530			hal_timer_init(SUNXI_TMR0);
1531			if (hal_gpio_to_irq(SUNXI_CODEC_JACK_DET, &sunxi_codec->irq) < 0)
1532				snd_err("sunxi jack gpio to irq err.\n");
1533			if (hal_gpio_irq_request(sunxi_codec->irq, sunxi_jack_irq_handler, IRQ_TYPE_EDGE_FALLING, sunxi_codec) < 0)
1534				snd_err("sunxi jack irq request err.\n");
1535			sunxi_jack_detect(sunxi_codec);
1536			if (hal_gpio_irq_enable(sunxi_codec->irq) < 0)
1537				snd_err("sunxi jack irq enable err.\n");
1538		}
1539	
1540		return 0;
1541	}
