697			.reg_min = SUNXI_DAC_DAP_CTL,
698			.reg_max = SUNXI_DAC_DRC_HPFLGAIN,
699		};
700	
701		/* get chp version */
702		sunxi_codec->chip_ver = hal_efuse_get_chip_ver();
703	
704		/* In order to ensure that the ADC sampling is normal,
705		 * the A chip SOC needs to always open HPLDO and RMC_EN
706		 */
707		if (sunxi_codec->chip_ver == CHIP_VER_A) {
708			snd_codec_update_bits(codec, SUNXI_POWER_ANA_CTL,
709				(0x1<<HPLDO_EN), (0x1<<HPLDO_EN));
710			snd_codec_update_bits(codec, SUNXI_RAMP_ANA_CTL,
711				(0x1<<RMCEN), (0x1<<RMCEN));
712		} else {
713			snd_codec_update_bits(codec, SUNXI_POWER_ANA_CTL,
714				(0x1<<HPLDO_EN), (0x0<<HPLDO_EN));
715			snd_codec_update_bits(codec, SUNXI_RAMP_ANA_CTL,
716				(0x1<<RMCEN), (0x0<<RMCEN));
717		}
718	
719		/* Disable HPF(high passed filter) */
720		snd_codec_update_bits(codec, SUNXI_DAC_DPC,
721				(1 << HPF_EN), (0x0 << HPF_EN));
722	
723		if (param->rx_sync_en) {
724			/* disabled ADCFDT */
725			snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
726					(0x1 << ADCDFEN), (0x0 << ADCDFEN));
727			snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
728					(0x3 << ADCFDT), (0x2 << ADCFDT));
729			/* RX_SYNC_EN */
730			snd_codec_update_bits(codec, SUNXI_ADC_FIFOC, 1 << RX_SYNC_EN, 0 << RX_SYNC_EN);
731		} else {
732			/* Enable ADCFDT to overcome niose at the beginning */
733			snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
734					(0x1 << ADCDFEN), (0x1 << ADCDFEN));
735			snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
736					(0x3 << ADCFDT), (0x2 << ADCFDT));
737		}
738	
739		/* init the mic pga and vol params */
740		snd_codec_update_bits(codec, SUNXI_DAC_ANA_CTL,
741				0x1F << LINEOUT_VOL,
742				param->lineout_vol << LINEOUT_VOL);
743		snd_codec_update_bits(codec, SUNXI_HP_ANA_CTL,
744				0x7 << HP_GAIN,
745				param->hpout_vol << HP_GAIN);
746	
747		/* DAC_VOL_SEL enable */
