520	static int sunxi_daudio_prepare(struct snd_pcm_substream *substream,
521					struct snd_dai *dai)
522	{
523		struct snd_platform *platform = dai->component;
524		struct sunxi_daudio_info *sunxi_daudio = platform->private_data;
525		unsigned int i;
526	
527		snd_print("\n");
528		if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
529			for (i = 0 ; i < SUNXI_DAUDIO_FTX_TIMES ; i++) {
530				snd_platform_update_bits(platform,
531					SUNXI_DAUDIO_FIFOCTL,
532					(1 << FIFO_CTL_FTX), (1 << FIFO_CTL_FTX));
533				hal_usleep(1000);
534			}
535			snd_platform_write(platform, SUNXI_DAUDIO_TXCNT, 0);
536			if (sunxi_daudio->hub_mode && !sunxi_daudio->playback_en) {
537				snd_platform_update_bits(platform,
538						SUNXI_DAUDIO_CTL,
539						(1 << SDO0_EN) | (1 << CTL_TXEN),
540						(1 << SDO0_EN) | (1 << CTL_TXEN));
541				sunxi_daudio_global_enable(platform, true);
542				sunxi_daudio->playback_en = 1;
543			}
544		} else {
545			snd_platform_update_bits(platform, SUNXI_DAUDIO_FIFOCTL,
546					(1<<FIFO_CTL_FRX), (1<<FIFO_CTL_FRX));
547			snd_platform_write(platform, SUNXI_DAUDIO_RXCNT, 0);
548		}
549	
550		return 0;
551	}
