553	static int sunxi_daudio_trigger(struct snd_pcm_substream *substream,
554					int cmd, struct snd_dai *dai)
555	{
556		struct snd_platform *platform = dai->component;
557		struct sunxi_daudio_info *sunxi_daudio = platform->private_data;
558	
559		snd_print("\n");
560		switch (cmd) {
561		case SNDRV_PCM_TRIGGER_START:
562		case SNDRV_PCM_TRIGGER_RESUME:
563		case SNDRV_PCM_TRIGGER_PAUSE_RELEASE:
564			if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
565				sunxi_daudio_txctrl_enable(platform, true);
566				if (!sunxi_daudio->playback_en) {
567					/* Global enable I2S/TDM module */
568					sunxi_daudio_global_enable(platform, true);
569					sunxi_daudio->playback_en = 1;
570				}
571			} else {
572				sunxi_daudio_rxctrl_enable(platform, true);
573				/* Global enable I2S/TDM module */
574				sunxi_daudio_global_enable(platform, true);
575				if (sunxi_daudio->param.rx_sync_en && sunxi_daudio->param.rx_sync_ctl) {
576					sunxi_rx_sync_control(sunxi_daudio->param.rx_sync_domain,
577							      sunxi_daudio->param.rx_sync_id, true);
578				}
579			}
580			break;
581		case SNDRV_PCM_TRIGGER_STOP:
582		case SNDRV_PCM_TRIGGER_SUSPEND:
583		case SNDRV_PCM_TRIGGER_PAUSE_PUSH:
584			if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
585				sunxi_daudio_txctrl_enable(platform, false);
586				if (sunxi_daudio->playback_en) {
587					/* Global enable I2S/TDM module */
588					sunxi_daudio_global_enable(platform, false);
589					sunxi_daudio->playback_en = 0;
590				}
591			} else {
592				sunxi_daudio_rxctrl_enable(platform, false);
593				/* Global enable I2S/TDM module */
594				sunxi_daudio_global_enable(platform, false);
595				if (sunxi_daudio->param.rx_sync_en && sunxi_daudio->param.rx_sync_ctl) {
596					sunxi_rx_sync_control(sunxi_daudio->param.rx_sync_domain,
597							      sunxi_daudio->param.rx_sync_id, false);
598				}
599			}
600			break;
601		default:
602			return -EINVAL;
603		}
604	
605		return 0;
606	}
