609					struct snd_dai *dai)
610	{
611		struct snd_platform *platform = dai->component;
612		struct sunxi_daudio_info *sunxi_daudio = platform->private_data;
613	
614		snd_print("\n");
615	
616		snd_sunxi_pa_pin_disable(platform);
617	
618		if ((substream->stream == SNDRV_PCM_STREAM_PLAYBACK) && (sunxi_daudio->hub_mode)) {
619			snd_platform_update_bits(platform, SUNXI_DAUDIO_CTL,
620					(1 << SDO0_EN) | (1 << CTL_TXEN),
621					(0 << SDO0_EN) | (0 << CTL_TXEN));
622			if (sunxi_daudio->playback_en) {
623				sunxi_daudio_global_enable(platform, false);
624				sunxi_daudio->playback_en = 0;
625			}
626			return;
627		}
628	}
