1307	static int sunxi_codec_set_sysclk(struct snd_dai *dai,
1308			int clk_id, unsigned int freq, int dir)
1309	{
1310		struct snd_codec *codec = dai->component;
1311		struct sunxi_codec_info *sunxi_codec = codec->private_data;
1312	
1313		if (dir == SNDRV_PCM_STREAM_PLAYBACK) {
1314			hal_clock_disable(sunxi_codec->moduleclk);
1315			if (freq == 24576000) {
1316				hal_clk_set_parent(sunxi_codec->moduleclk, sunxi_codec->pllclk1);
1317			} else {
1318				hal_clk_set_parent(sunxi_codec->moduleclk, sunxi_codec->pllclk);
1319			}
1320			hal_clk_set_rate(sunxi_codec->moduleclk, freq);
1321			hal_msleep(50);
1322			hal_clock_enable(sunxi_codec->moduleclk);
1323		}
1324	
1325		if (dir == SNDRV_PCM_STREAM_CAPTURE) {
1326			if (freq == 24576000) {
1327				hal_clk_set_parent(sunxi_codec->moduleclk1, sunxi_codec->pllclk1);
1328			} else {
1329				hal_clk_set_parent(sunxi_codec->moduleclk1, sunxi_codec->pllclk);
1330			}
1331			hal_clk_set_rate(sunxi_codec->moduleclk1, freq);
1332		}
1333	
1334		return 0;
1335	}
