1342	static int sunxi_codec_prepare(struct snd_pcm_substream *substream,
1343			struct snd_dai *dai)
1344	{
1345		struct snd_codec *codec = dai->component;
1346	
1347		snd_print("\n");
1348	
1349		if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
1350			snd_codec_update_bits(codec, SUNXI_DAC_FIFOC,
1351				(1 << FIFO_FLUSH), (1 << FIFO_FLUSH));
1352			snd_codec_write(codec, SUNXI_DAC_FIFOS,
1353				(1 << DAC_TXE_INT | 1 << DAC_TXU_INT | 1 << DAC_TXO_INT));
1354			snd_codec_write(codec, SUNXI_DAC_CNT, 0);
1355		} else {
1356			snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
1357					(1 << ADC_FIFO_FLUSH), (1 << ADC_FIFO_FLUSH));
1358			snd_codec_write(codec, SUNXI_ADC_FIFOS,
1359					(1 << ADC_RXA_INT | 1 << ADC_RXO_INT));
1360			snd_codec_write(codec, SUNXI_ADC_CNT, 0);
1361		}
1362	
1363		return 0;
1364	}
