358		codec_dai = substream->pcm->card->codec->codec_dai;
359		platform = substream->pcm->card->platform;
360		cpu_dai = platform->cpu_dai;
361	
362		snd_print("\n");
363		/*snd_mutex_lock(runtime->pcm_mutex);*/
364		switch (params_rate(params)) {
365		case 8000:
366		case 12000:
367		case 16000:
368		case 24000:
369		case 32000:
370		case 48000:
371		case 64000:
372		case 96000:
373		case 192000:
374			freq = 24576000;
375			break;
376		case 11025:
377		case 22050:
378		case 44100:
379		case 88200:

380			freq = 22579200;
381			break;
382		default:
383			snd_err("unsupport params rate:%d\n", params_rate(params));
384			ret = -EINVAL;
385			goto _end_lock;
386		}
387	
388		ret = soc_dai_set_sysclk(cpu_dai, 0, freq, substream->stream);
389		if (ret < 0) {
390			snd_err("cpu_dai set sysclk failed\n");
391			goto _end_lock;
392		}
393		ret = soc_dai_set_sysclk(codec_dai, 0, freq, substream->stream);
