395			snd_err("codec_dai set sysclk failed\n");
396			goto _end_lock;
397		}
398		ret = soc_dai_set_pll(cpu_dai, 0, 0, freq, freq);
399		if (ret < 0) {
400			snd_err("cpu_dai set pll failed\n");
401			goto _end_lock;
402		}
403		ret = soc_dai_set_pll(codec_dai, 0, 0, freq, freq);
404		if (ret < 0) {
405			snd_err("codec_dai set pll failed\n");
406			goto _end_lock;
407		}
408		clk_div = freq / params_rate(params);
409		ret = soc_dai_set_clkdiv(cpu_dai, 0, clk_div);
410		if (ret < 0) {
411			snd_err("cpu_dai set clkdiv failed\n");
412			goto _end_lock;
413		}
414		ret = soc_dai_set_clkdiv(codec_dai, 0, clk_div);
415		if (ret < 0) {
416			snd_err("codec_dai set clkdiv failed\n");
417			goto _end_lock;
418		}
419	
420		if (codec_dai->ops->hw_params) {
421			ret = codec_dai->ops->hw_params(substream, params, codec_dai);
422			if (ret < 0) {
423				snd_err("codec_dai set hw params failed\n");
424				goto _end_lock;
425			}
426		}
427		if (cpu_dai->ops->hw_params) {
428			ret = cpu_dai->ops->hw_params(substream, params, cpu_dai);
429			if (ret < 0) {
430				snd_err("cpu_dai set hw params failed\n");
431				goto cpu_dai_err;
432			}
433		}
434		if (platform->ops->hw_params) {
435			ret = platform->ops->hw_params(substream, params);
436			if (ret < 0) {
437				snd_err("platform set hw params failed\n");
438				goto platform_err;
439			}
440		}
441	
442		return ret;
443	
444	platform_err:
445		if (cpu_dai->ops->hw_free)
446			cpu_dai->ops->hw_free(substream, cpu_dai);
447	cpu_dai_err:
448		if (codec_dai->ops->hw_free)
449			codec_dai->ops->hw_free(substream, codec_dai);
450	_end_lock:
451		/*snd_mutex_unlock(runtime->pcm_mutex);*/
452	
453		return ret;
454	}
