633	{
634		struct snd_pcm_substream *substream;
635		static struct snd_pcm_ops pcm_ops = {
636			.open		= soc_pcm_open,
637			.hw_params	= soc_pcm_hw_params,
638			.prepare	= soc_pcm_prepare,
639			.trigger	= soc_pcm_trigger,

1173	static int sunxi_codec_hw_params(struct snd_pcm_substream *substream,
1174			struct snd_pcm_hw_params *params, struct snd_dai *dai)
1175	{
1176		struct snd_codec *codec = dai->component;
1177		struct sunxi_codec_info *sunxi_codec = codec->private_data;
1178		struct sunxi_codec_param *codec_param = &sunxi_codec->param;
1179		int i = 0;
1180	
1181		snd_print("\n");
1182		switch (params_format(params)) {
1183		case	SND_PCM_FORMAT_S16_LE:
1184			if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
1185				snd_codec_update_bits(codec, SUNXI_DAC_FIFOC,
1186					(3 << FIFO_MODE), (3 << FIFO_MODE));
1187				snd_codec_update_bits(codec, SUNXI_DAC_FIFOC,
1188					(1 << TX_SAMPLE_BITS), (0 << TX_SAMPLE_BITS));
1189			} else {
1190				snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
1191					(1 << RX_FIFO_MODE), (1 << RX_FIFO_MODE));
1192				snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
1193					(1 << RX_SAMPLE_BITS), (0 << RX_SAMPLE_BITS));
1194			}
1195			break;
1196		case	SND_PCM_FORMAT_S24_LE:
1197		case	SND_PCM_FORMAT_S32_LE:
1198			if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
1199				snd_codec_update_bits(codec, SUNXI_DAC_FIFOC,
1200					(3 << FIFO_MODE), (0 << FIFO_MODE));
1201				snd_codec_update_bits(codec, SUNXI_DAC_FIFOC,
1202					(1 << TX_SAMPLE_BITS), (1 << TX_SAMPLE_BITS));
1203			} else {
1204				snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
1205					(1 << RX_FIFO_MODE), (0 << RX_FIFO_MODE));
1206				snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
1207					(1 << RX_SAMPLE_BITS), (1 << RX_SAMPLE_BITS));
1208			}
1209			break;
1210		default:
1211			break;
1212		}
1213	
1214		for (i = 0; i < ARRAY_SIZE(sample_rate_conv); i++) {
1215			if (sample_rate_conv[i].samplerate == params_rate(params)) {
1216				if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
1217					snd_codec_update_bits(codec, SUNXI_DAC_FIFOC,
1218						(0x7 << DAC_FS),
1219						(sample_rate_conv[i].rate_bit << DAC_FS));
1220				} else {
1221					if (sample_rate_conv[i].samplerate > 48000)
1222						return -EINVAL;
1223					snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
1224						(0x7 << ADC_FS),
1225						(sample_rate_conv[i].rate_bit<<ADC_FS));
1226				}
1227			}
1228		}
1229	
1230		/* reset the adchpf func setting for different sampling */
1231		if (substream->stream == SNDRV_PCM_STREAM_CAPTURE) {
1232			if (codec_param->adchpf_cfg) {
1233				if (params_rate(params) == 16000) {
1234	
1235					snd_codec_write(codec, SUNXI_ADC_DRC_HHPFC,
1236							(0x00F623A5 >> 16) & 0xFFFF);
1237	
1238					snd_codec_write(codec, SUNXI_ADC_DRC_LHPFC,
1239								0x00F623A5 & 0xFFFF);
1240	
1241				} else if (params_rate(params) == 44100) {
1242	
1243					snd_codec_write(codec, SUNXI_ADC_DRC_HHPFC,
1244							(0x00FC60DB >> 16) & 0xFFFF);
1245	
1246					snd_codec_write(codec, SUNXI_ADC_DRC_LHPFC,
1247								0x00FC60DB & 0xFFFF);
1248				} else {
1249					snd_codec_write(codec, SUNXI_ADC_DRC_HHPFC,
1250							(0x00FCABB3 >> 16) & 0xFFFF);
1251	
1252					snd_codec_write(codec, SUNXI_ADC_DRC_LHPFC,
1253								0x00FCABB3 & 0xFFFF);
1254				}
1255			}
1256		}
1257	
1258		if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
1259			switch (params_channels(params)) {
1260			case 1:
1261				snd_codec_update_bits(codec, SUNXI_DAC_FIFOC,
1262						(1<<DAC_MONO_EN), 1<<DAC_MONO_EN);
1263				break;
1264			case 2:
1265				snd_codec_update_bits(codec, SUNXI_DAC_FIFOC,
1266						(1<<DAC_MONO_EN), (0<<DAC_MONO_EN));
1267				break;
1268			default:
1269				snd_err("cannot support the channels:%u.\n",
1270					params_channels(params));
1271				return -EINVAL;
1272			}
1273		} else {
1274			if (sunxi_get_adc_ch(codec) < 0) {
1275				snd_err("capture only support 1~3 channel\n");
1276				return -EINVAL;
1277			}
1278			if (codec_param->adc1_flag)
1279				snd_codec_update_bits(codec, SUNXI_ADC_DIG_CTL,
1280						      0x1<<ADC1_CHANNEL_EN,
1281						      0x1<<ADC1_CHANNEL_EN);
1282			else
1283				snd_codec_update_bits(codec, SUNXI_ADC_DIG_CTL,
1284						      0x1<<ADC1_CHANNEL_EN,
1285						      0x0<<ADC1_CHANNEL_EN);
1286			if (codec_param->adc2_flag)
1287				snd_codec_update_bits(codec, SUNXI_ADC_DIG_CTL,
1288						      0x1<<ADC2_CHANNEL_EN,
1289						      0x1<<ADC2_CHANNEL_EN);
1290			else
1291				snd_codec_update_bits(codec, SUNXI_ADC_DIG_CTL,
1292						      0x1<<ADC2_CHANNEL_EN,
1293						      0x0<<ADC2_CHANNEL_EN);
1294			if (codec_param->adc3_flag)
1295				snd_codec_update_bits(codec, SUNXI_ADC_DIG_CTL,
1296						      0x1<<ADC3_CHANNEL_EN,
1297						      0x1<<ADC3_CHANNEL_EN);
1298			else
1299				snd_codec_update_bits(codec, SUNXI_ADC_DIG_CTL,
1300						      0x1<<ADC3_CHANNEL_EN,
1301						      0x0<<ADC3_CHANNEL_EN);
1302		}
1303	
1304		return 0;
1305	}
