298	int snd_platform_cpudai_register(struct snd_platform *platform, int arg)
299	{
300		int ret = 0;
301	
302		platform->name = strdup("audiocodec-platform");
303		platform->ops = &sunxi_pcm_ops;
304		platform->pcm_new = sunxi_pcm_new;
305		platform->pcm_free = sunxi_pcm_free;
306		platform->cpu_dai = snd_malloc(sizeof(struct snd_dai));
307		if (!platform->cpu_dai) {
308			snd_err("cpu_dai malloc failed.\n");
309			ret = -ENOMEM;
310			goto err_cpu_dai_malloc;
311		}
312		memcpy(platform->cpu_dai, &sunxi_cpudai, sizeof(struct snd_dai));
313	
314		switch (arg) {
315			case SND_PLATFORM_TYPE_CPUDAI:
316				platform->probe = sunxi_cpudai_platform_probe;
317				break;
318			case SND_PLATFORM_TYPE_CPUDAI_DAC:
319				platform->probe = sunxi_cpudai_platform_probe_dac;
320				break;
321			case SND_PLATFORM_TYPE_CPUDAI_ADC:
322				platform->probe = sunxi_cpudai_platform_probe_adc;
323				break;
324			default:
325				goto err_platform_type;
326		}
327		platform->remove = sunxi_cpudai_platform_remove;
328	
329		return 0;
330	
331	err_platform_type:
332		snd_free(platform->cpu_dai);
333	err_cpu_dai_malloc:
