257	{
258		snd_info("stream:%u, cmd:%u\n", substream->stream, cmd);
259		if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
260			switch (cmd) {
261			case SNDRV_PCM_TRIGGER_START:
262			case SNDRV_PCM_TRIGGER_RESUME:
263			case SNDRV_PCM_TRIGGER_PAUSE_RELEASE:
264				snd_dmaengine_pcm_trigger(substream,
265						SNDRV_PCM_TRIGGER_START);
266				break;
267			case SNDRV_PCM_TRIGGER_SUSPEND:
268			case SNDRV_PCM_TRIGGER_STOP:
269			case SNDRV_PCM_TRIGGER_PAUSE_PUSH:
270				snd_dmaengine_pcm_trigger(substream,
271						SNDRV_PCM_TRIGGER_STOP);
272				break;
273			}
274		} else {
275			switch (cmd) {
276			case SNDRV_PCM_TRIGGER_START:
277			case SNDRV_PCM_TRIGGER_RESUME:
278			case SNDRV_PCM_TRIGGER_PAUSE_RELEASE:
279				snd_dmaengine_pcm_trigger(substream,
280						SNDRV_PCM_TRIGGER_START);
281				break;
282			case SNDRV_PCM_TRIGGER_SUSPEND:
283			case SNDRV_PCM_TRIGGER_STOP:
284			case SNDRV_PCM_TRIGGER_PAUSE_PUSH:
285				snd_dmaengine_pcm_trigger(substream,
286						SNDRV_PCM_TRIGGER_STOP);
287				break;
288			}
289		}
290		return 0;
291	}
