1153	static int sunxi_codec_startup(struct snd_pcm_substream *substream,
1154			struct snd_dai *dai)
1155	{
1156		snd_print("\n");
1157	
1158		/* Force the DAPM route (DAC analog enables + external speaker PA) to
1159		 * re-run on EVERY open. A previous close should set dapm_state back to
1160		 * 0, but if any path leaves it stuck at 1 the next prepare's
1161		 * dapm_control(1) short-circuits and the analog path stays off — the
1162		 * symptom is "only the first reply is audible". Resetting here is
1163		 * harmless: the field only gates that one early-return. */
1164		substream->dapm_state = 0;
1165	
1166		syslog(LOG_INFO, "[codec] startup: stream=%d dapm_state reset\n",
1167			substream->stream);
1168	
1169		return 0;

1170	}
