1342	static int sunxi_codec_prepare(struct snd_pcm_substream *substream,
1343			struct snd_dai *dai)
1344	{
1345		struct snd_codec *codec = dai->component;
1346	
1347		snd_print("\n");
1348	
1349		if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
1350			snd_codec_update_bits(codec, SUNXI_DAC_FIFOC,
1351				(1 << FIFO_FLUSH), (1 << FIFO_FLUSH));
1352			snd_codec_write(codec, SUNXI_DAC_FIFOS,
1353				(1 << DAC_TXE_INT | 1 << DAC_TXU_INT | 1 << DAC_TXO_INT));
1354			snd_codec_write(codec, SUNXI_DAC_CNT, 0);
1355		} else {
1356			snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
1357					(1 << ADC_FIFO_FLUSH), (1 << ADC_FIFO_FLUSH));
1358			snd_codec_write(codec, SUNXI_ADC_FIFOS,
1359					(1 << ADC_RXA_INT | 1 << ADC_RXO_INT));
1360			snd_codec_write(codec, SUNXI_ADC_CNT, 0);
1361		}
1362	
1363		return 0;
1364	}
1365	
1366	static int sunxi_codec_trigger(struct snd_pcm_substream *substream,
1367			int cmd, struct snd_dai *dai)
1368	{
1369		struct snd_codec *codec = dai->component;
1370		struct sunxi_codec_info *sunxi_codec = codec->private_data;
1371	
1372		snd_print("\n");
1373		switch (cmd) {
1374		case SNDRV_PCM_TRIGGER_START:
1375		case SNDRV_PCM_TRIGGER_RESUME:
1376		case SNDRV_PCM_TRIGGER_PAUSE_RELEASE:
1377			if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
1378				snd_codec_update_bits(codec, SUNXI_DAC_FIFOC,
1379					(1 << DAC_DRQ_EN), (1 << DAC_DRQ_EN));
1380			}
1381			else if (substream->stream == SNDRV_PCM_STREAM_CAPTURE) {
1382				snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
1383					(1 << ADC_DRQ_EN), (1 << ADC_DRQ_EN));
1384				if (sunxi_codec->param.rx_sync_en && sunxi_codec->param.rx_sync_ctl)
1385					sunxi_rx_sync_control(sunxi_codec->param.rx_sync_domain,
1386							      sunxi_codec->param.rx_sync_id, 1);
1387			}
1388			break;
1389		case SNDRV_PCM_TRIGGER_STOP:
1390		case SNDRV_PCM_TRIGGER_SUSPEND:
1391		case SNDRV_PCM_TRIGGER_PAUSE_PUSH:
1392			if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
1393				snd_codec_update_bits(codec, SUNXI_DAC_FIFOC,
1394					(1 << DAC_DRQ_EN), (0 << DAC_DRQ_EN));
1395			}
1396			else if (substream->stream == SNDRV_PCM_STREAM_CAPTURE) {
1397				snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
1398					(1 << ADC_DRQ_EN), (0 << ADC_DRQ_EN));
1399				if (sunxi_codec->param.rx_sync_en && sunxi_codec->param.rx_sync_ctl)
1400					sunxi_rx_sync_control(sunxi_codec->param.rx_sync_domain,
1401							      sunxi_codec->param.rx_sync_id, 0);
1402			}
1403			break;
1404		default:
1405			return -EINVAL;
1406		}
1407	
1408		return 0;
1409	}
