452	int _snd_pcm_hw_open(snd_pcm_t **pcmp, const snd_pcm_config_t *pcm_config,
453			snd_pcm_stream_t stream, int mode)
454	{
455		const snd_pcm_hw_config_t *hw_config = (const snd_pcm_hw_config_t *)(pcm_config->config);
456		int card_num = 0;
457		int ret = 0;
458		snd_pcm_t *pcm = NULL;
459		void *substream = NULL;
460		snd_pcm_hw_t *hw = NULL;
461	
462		awalsa_debug("\n");
463		card_num = ksnd_card_index(hw_config->card_name);
464		if (card_num < 0) {
465			awalsa_err("no such card:%s\n", hw_config->card_name);
466			ret = -ENODEV;
467			goto err_out;
468		}
469	
470		awalsa_debug("\n");
471	
472		ret = snd_pcm_new(&pcm, SND_VELA_PCM_TYPE_HW, pcm_config->name, stream, mode);
473		if (ret < 0) {
474			awalsa_err("failed to new hw pcm\n");
475			goto err_out;
476		}
477		pcm->ops = &snd_pcm_hw_ops;
478		pcm->fast_ops = &snd_pcm_hw_fast_ops;
479	
480		hw = snd_malloc(sizeof(snd_pcm_hw_t));
481		if (!hw) {
482			awalsa_err("no memory\n");
483			ret = -ENOMEM;
484			goto free_pcm;
485		}
486	
487		ret = ksnd_pcm_open(card_num, hw_config->device_num, stream, mode, &substream);
488		if (ret != 0) {
489			goto free_hw;
490		}
491		hw->card_num = card_num;
492		hw->device_num = hw_config->device_num;
493		hw->substream = substream;
494	
495		snd_pcm_set_hw_ptr(pcm, &hw->mmap_status.hw_ptr, 0, 0);
496		snd_pcm_set_appl_ptr(pcm, &hw->mmap_control.appl_ptr, 0, 0);
497		/* sync control, status */
498		snd_pcm_sync_ptr(pcm, hw, 0);
499	
500		pcm->private_data = hw;
501	
502		*pcmp = pcm;
503		return 0;
504	
505	free_hw:
506		snd_free(hw);
507	free_pcm:
508		snd_pcm_free(pcm);
509	err_out:
510		return ret;
511	}
