1452	static void sunxi_jack_detect(void *param)
1453	{
1454		struct sunxi_codec_info *sunxi_codec = param;
1455		struct sunxi_codec_param *codec_param = &sunxi_codec->param;
1456		gpio_data_t gpio_status;
1457	
1458		if (codec_param->gpio_spk > 0) {
1459			hal_gpio_set_direction(codec_param->gpio_spk, GPIO_MUXSEL_OUT);
1460			hal_gpio_get_data(SUNXI_CODEC_JACK_DET, &gpio_status);
1461			if (gpio_status) {
1462				/* jack plug out */
1463				hal_gpio_set_data(codec_param->gpio_spk, codec_param->pa_level);
1464			} else {
1465				/* jack plug in */
1466				hal_gpio_set_data(codec_param->gpio_spk, !codec_param->pa_level);
1467			}
1468		}
1469	}
