336	int sunxi_codec_playback_prepare(void)
337	{
338		struct sunxi_codec *codec = &g_codec;
339	
340		/* FIFO flush, clear pending, clear sample counter */
341		sunxi_codec_update_bits(codec, SUNXI_DAC_FIFOC,
342					(1 << FIFO_FLUSH), (1 << FIFO_FLUSH));
343		sunxi_codec_write(codec, SUNXI_DAC_FIFOS,
344				  (1 << DAC_TXE_INT | 1 << DAC_TXU_INT | 1 << DAC_TXO_INT));
345		sunxi_codec_write(codec, SUNXI_DAC_CNT, 0);
346	
347		/* enable FIFO empty DRQ */
348		sunxi_codec_update_bits(codec, SUNXI_DAC_FIFOC,
349					(1 << DAC_DRQ_EN), (1 << DAC_DRQ_EN));
350	
351		/* Enable DAC analog left channel */
352		sunxi_codec_update_bits(codec, SUNXI_DAC_REG, (0x1 << DACLEN),
353					(0x1 << DACLEN));
354		/* Enable DAC analog right channel */
355		sunxi_codec_update_bits(codec, SUNXI_DAC_REG, (0x1 << DACREN),
356					(0x1 << DACREN));
357		/* enable DAC digital part */
358		sunxi_codec_update_bits(codec, SUNXI_DAC_DPC,
359					(0x1 << EN_DAC), (0x1 << EN_DAC));
360		/* enable left and right HPOUT */
361		sunxi_codec_update_bits(codec, SUNXI_HEADPHONE_REG,
362					(0x1 << HPPA_EN), (0x1 << HPPA_EN));
363		sunxi_codec_update_bits(codec, SUNXI_HEADPHONE_REG,
364					(0x1 << HPOUTPUTEN), (0x1 << HPOUTPUTEN));
365		sunxi_codec_update_bits(codec, SUNXI_HEADPHONE_REG,
366					(0x1 << HPINPUTEN), (0x1 << HPINPUTEN));
367		/* increase delay time, if Pop occured */
368		mdelay(10);
369		gpio_direction_output(codec->spk_gpio, codec->pa_ctl_level);
370	
371		return 0;
372	}
