New code:
```c
static int sunxi_codec_set_sysclk(struct snd_dai *dai,
		int clk_id, unsigned int freq, int dir)
{
	struct snd_codec *codec = dai->component;
	struct sunxi_codec_info *sunxi_codec = codec->private_data;

	if (dir == SNDRV_PCM_STREAM_PLAYBACK) {
		/* If the DAC clock is already at the requested rate, leave it
		 * alone: the disable -> re-parent -> re-rate -> enable cycle can
		 * itself glitch the codec DAC clock on a 2nd+ open (follow-up
		 * reply silent). Re-config only when the rate actually differs. */
		unsigned int cur = hal_clk_get_rate(sunxi_codec->moduleclk);
		if (cur != freq) {
			hal_clock_disable(sunxi_codec->moduleclk);
			if (freq == 24576000) {
				hal_clk_set_parent(sunxi_codec->moduleclk, sunxi_codec->pllclk1);
			} else {
				hal_clk_set_parent(sunxi_codec->moduleclk, sunxi_codec->pllclk);
			}
			hal_clk_set_rate(sunxi_codec->moduleclk, freq);
			hal_msleep(50);
			hal_clock_enable(sunxi_codec->moduleclk);
		}
		syslog(LOG_INFO, "[codec] set_sysclk PLAY freq=%u cur=%u now=%u\n",
			freq, cur, hal_clk_get_rate(sunxi_codec->moduleclk));
	}

	if (dir == SNDRV_PCM_STREAM_CAPTURE) {
		if (freq == 24576000) {
			hal_clk_set_parent(sunxi_codec->moduleclk1, sunxi_codec->pllclk1);
		} else {
			hal_clk_set_parent(sunxi_codec->moduleclk1, sunxi_codec->pllclk);
		}
		hal_clk_set_rate(sunxi_codec->moduleclk1, freq);
		syslog(LOG_INFO, "[codec] set_sysclk CAPTURE freq=%u adc_rate=%u\n",
			freq, hal_clk_get_rate(sunxi_codec->moduleclk1));
	}

	return 0;
}
```

