852	        /* Wait for any in-flight reply to finish, then a short cooldown so
853	         * the tail of the TTS doesn't bleed into the mic. */
854	        while (g_reply_busy) {
855	            usleep(100 * 1000);
856	        }
857	        usleep(300 * 1000);
858	
859	        /* Follow-up window: for a short while after the buddy finishes a

859	        /* Follow-up window: for a short while after the buddy finishes a
860	         * reply, accept the kid's next utterance as a command even without
861	         * the wake word (so they can pick a story option by just answering,
862	         * not by re-saying "小伙伴"). */
863	        int64_t elapsed = now_ms() - g_last_reply_ms;
864	        bool follow_up = (g_last_reply_ms != 0 && elapsed < FOLLOW_UP_MS);
865	        int timeout_ms = follow_up ? (int)(FOLLOW_UP_MS - elapsed) : 0;
866	
867	        char *asr_text = listen_one_utterance(timeout_ms);
868	        if (!asr_text) {
869	            continue;
870	        }
871	
872	        syslog(LOG_INFO, "[kid_buddy] wake: heard \"%s\"%s\n", asr_text,
873	               follow_up ? " (follow-up)" : "");
874	
875	        bool has_wake = (strstr(asr_text, WAKE_WORD) != NULL);
876	        char command[MSG_BUF_LEN];
877	        size_t clen = strip_wake_word(asr_text, command, sizeof(command));
878	        free(asr_text);
879	
880	        if (!has_wake && !follow_up) {
881	            syslog(LOG_INFO, "[kid_buddy] wake: not the wake word, ignore\n");
882	            continue;
883	        }
884	
885	        if (clen == 0) {
886	            if (has_wake) {
887	                /* Wake word only — acknowledge and keep listening. */
888	                syslog(LOG_INFO, "[kid_buddy] wake: wake word only, prompt\n");
889	                wake_speak_prompt(WAKE_IDLE_PROMPT);
890	            } else {
891	                syslog(LOG_INFO, "[kid_buddy] wake: empty follow-up, ignore\n");
892	            }
893	            continue;
894	        }
895	
896	        /* A bare "嗯/啊/哦" is not a command — the kid murmuring or the mic
897	         * catching the TTS tail, not an answer. Sending it to the LLM makes
898	         * the buddy answer itself and repeat the story in a loop. */
899	        if (is_filler_utterance(command)) {
900	            syslog(LOG_INFO, "[kid_buddy] wake: filler \"%s\" ignored\n",
901	                   command);
902	            continue;
903	        }
904	
905	        /* Hand the command to the LVGL thread (which calls send_to_llm).
906	         * Mark busy NOW (before this loop iterates) so the wake loop re-enters
907	         * the g_reply_busy wait and does NOT re-open the mic — and steal the
908	         * codec DMA channel — before the LVGL timer calls send_to_llm().
909	         * send_to_llm() sets it again (idempotent) and the TTS worker clears
910	         * it after the reply is spoken. */
911	        g_reply_busy = 1;
912	        pthread_mutex_lock(&g_wake_cmd_lock);
913	        strncpy(g_wake_cmd, command, MSG_BUF_LEN - 1);
914	        g_wake_cmd[MSG_BUF_LEN - 1] = '\0';
915	        g_wake_cmd_ready = true;
916	        pthread_mutex_unlock(&g_wake_cmd_lock);
917	
918	        syslog(LOG_INFO, "[kid_buddy] wake: command \"%s\"\n", command);
919	    }
920	
921	    return NULL;
922	}
