924	/* Strip emoji and other glyphs the LCD font can't render.  The simsun_16_cjk
925	 * font covers ASCII/Latin/Greek/Cyrillic/GB2312+GBK hanzi/kana/fullwidth but
926	 * NOT emoji (U+1F000..) or dingbats — those show as tofu boxes, and worse,
927	 * MiMo TTS reads them aloud as a stray "think"-like word.  Walk the UTF-8
928	 * string in place and drop any emoji code point (plus the variation-selector
929	 * and zero-width-joiner bytes that make up emoji sequences). */
930	static void strip_emoji(char *s)
931	{
932	    unsigned char *src = (unsigned char *)s;
933	    unsigned char *dst = (unsigned char *)s;
934	
935	    while (*src)
936	      {
937	        unsigned int cp = 0;
938	        int n = 0;
939	        unsigned char c = *src;
940	
941	        if (c < 0x80)
942	          {
943	            cp = c;
944	            n = 1;
945	          }
946	        else if ((c & 0xE0) == 0xC0)
947	          {
948	            cp = c & 0x1F;
949	            n = 2;
950	          }
951	        else if ((c & 0xF0) == 0xE0)
952	          {
953	            cp = c & 0x0F;
954	            n = 3;
955	          }
956	        else if ((c & 0xF8) == 0xF0)
957	          {
958	            cp = c & 0x07;
959	            n = 4;
960	          }
961	        else
962	          {
963	            /* Invalid UTF-8 lead byte — drop it. */
964	            src++;
965	            continue;
966	          }
967	
968	        int ok = 1;
969	        for (int i = 1; i < n; i++)
970	          {
971	            unsigned char cc = src[i];
972	            if ((cc & 0xC0) != 0x80)
973	              {
974	                ok = 0;
975	                break;
976	              }
977	            cp = (cp << 6) | (cc & 0x3F);
978	          }
979	        if (!ok)
980	          {
981	            src++;
982	            continue;
983	          }
984	
985	        int emoji =
986	            (cp >= 0x1F000 && cp <= 0x1FAFF) ||   /* emoji + pictographs */
987	            (cp >= 0x2600 && cp <= 0x27BF) ||     /* misc symbols + dingbats */
988	            (cp >= 0x2B00 && cp <= 0x2BFF) ||     /* supplemental symbols */
989	            cp == 0x200D ||                       /* zero-width joiner */
990	            (cp >= 0xFE00 && cp <= 0xFE0F) ||     /* variation selectors */
991	            (cp >= 0x1F1E6 && cp <= 0x1F1FF);     /* regional indicator flags */
992	
993	        if (emoji)
994	          {
995	            src += n;
996	            continue;
997	          }
