226	static int alsa_read_frames(audio_capture_t* cap, void* buf,
227	    snd_pcm_uframes_t frames)
228	{
229	    snd_pcm_uframes_t done = 0;
230	    unsigned char* dst = buf;
231	
232	    while (done < frames) {
233	        snd_pcm_sframes_t ret = snd_vela_pcm_readi(cap->handle.pcm,
234	            dst + done * cap->hw_frame_bytes, frames - done);
235	
236	        if (ret == -EAGAIN) {
237	            usleep(10 * 1000);
238	            continue;
239	        }
240	
241	        if (ret == -EPIPE) {
242	            syslog(LOG_WARNING, "[%s] ALSA overrun, preparing capture\n",
243	                TAG);
244	            snd_vela_pcm_prepare(cap->handle.pcm);
245	            continue;
246	        }
247	
248	        if (ret == -ESTRPIPE) {
249	            continue;
250	        }
251	
252	        if (ret < 0) {
253	            return done > 0 ? (int)done : (int)ret;
254	        }
255	
256	        done += (snd_pcm_uframes_t)ret;
257	    }
258	
259	    return (int)done;
260	}
