262	static void downmix_interleaved_s16_to_mono(audio_capture_t* cap,
263	    void* out_buf, const void* in_buf, size_t frames)
264	{
265	    int16_t* out = out_buf;
266	    const int16_t* in = in_buf;
267	
268	    for (size_t i = 0; i < frames; i++) {
269	        int32_t mixed = 0;
270	
271	        for (unsigned int ch = 0; ch < cap->hw_channels; ch++) {
272	            mixed += in[i * cap->hw_channels + ch];
273	        }
274	
275	        out[i] = (int16_t)(mixed / (int32_t)cap->hw_channels);
276	    }
277	}
