317	    if (!g_agent_connected || g_agent_client == NULL)
318	      {
319	        lv_label_set_text(g_chat_status, "Agent offline - start 'ai_agent &' first");
320	        return;
321	      }
322	
323	    /* Mark an interaction in flight so the wake loop stays quiet through the
324	     * LLM request + TTS reply. Cleared by the TTS worker after the final
325	     * reply is spoken (or here if the request fails immediately). */
326	    g_reply_busy = 1;
327	
328	    /* Build full prompt: system prompt + user text */
329	    const role_def_t *role = &g_roles[g_current_role];
330	    char full_prompt[MSG_BUF_LEN];
