332	             "[SYSTEM]\n%s\n\n[USER]\n%s",
333	             role->system_prompt, user_text);
334	
335	    velaclaw_ask_req_t req = {
336	        .text       = full_prompt,
337	        .timeout_ms = 15000  /* 15 second timeout */
338	    };
339	
340	    /* Start a fresh response: bump the epoch and reset the spoken offset so
341	     * the streamed reply is spoken from the beginning, and drop any stale
342	     * fragment still queued for the previous question. */
