353	        lv_obj_clear_flag(g_chat_spinner, LV_OBJ_FLAG_HIDDEN);
354	      }
355	
356	    int ret = velaclaw_ask(g_agent_client, &req, llm_response_cb, NULL);
357	    if (ret < 0)
358	      {
359	        lv_label_set_text(g_chat_status, "Failed to send message");
