1060	static void poll_timer_cb(lv_timer_t *timer)
1061	{
1062	    static int heartbeat;
1063	
1064	    (void)timer;
1065	
1066	    /* Liveness probe — logs once every ~10s (200ms period × 50). If this
1067	     * stops after a TTS speak finishes, the LVGL thread has hung (screen
1068	     * frozen), as opposed to a touch-only stall. */
1069	    if (++heartbeat % 50 == 0)
1070	      {
1071	        syslog(LOG_INFO, "[kid_buddy] LVGL heartbeat #%d\n", heartbeat);
1072	      }
1073	
1074	    /* Snapshot the latest LLM message under the same lock the callback uses,
1075	     * so the status and text are read as one consistent pair (a torn read
1076	     * could otherwise tag a stale short fragment as "final" and drop the
1077	     * rest of the reply). */
1078	    int  msg_status;
1079	    char msg_text[MSG_BUF_LEN];
1080	    bool have_msg = false;
1081	
1082	    pthread_mutex_lock(&g_msg_lock);
1083	    if (g_msg_ready)
1084	      {
1085	        g_msg_ready = false;
1086	        msg_status = g_msg_status;
1087	        strncpy(msg_text, g_pending_msg, MSG_BUF_LEN - 1);
1088	        msg_text[MSG_BUF_LEN - 1] = '\0';
1089	        have_msg = true;
1090	      }
1091	    pthread_mutex_unlock(&g_msg_lock);
1092	
1093	    if (have_msg)
1094	      {
1095	        /* Drop emoji before display AND before TTS: the LCD font can't show
1096	         * them (tofu boxes) and MiMo TTS reads them as a stray "think" word. */
1097	        strip_emoji(msg_text);
1098	        /* Drop Markdown ("---", **bold**, #headers, bullets) — TTS reads the
1099	         * "---" rule as a stray word too. */
1100	        strip_markdown(msg_text);
1101	
1102	        /* Hide spinner as soon as the first text arrives. */
1103	        if (g_chat_spinner)
1104	          {
1105	            lv_obj_add_flag(g_chat_spinner, LV_OBJ_FLAG_HIDDEN);
1106	          }
1107	
1108	        if (msg_status == 0 || msg_status == 1)
1109	          {
1110	            /* Show the running reply text. */
1111	            lv_label_set_text(g_chat_msg_area, msg_text);
1112	
1113	            /* Feed the cumulative text to the TTS worker. Partial fragments
1114	             * (status 1) are spoken sentence-by-sentence as they complete;
1115	             * the final fragment (status 0) flushes the remainder. */
1116	            enqueue_tts(msg_text, msg_status == 0);
1117	
1118	            if (msg_status == 0)
1119	              {
1120	                lv_label_set_text(g_chat_status, "Tap 'Ask me!' to continue");
1121	              }
1122	            else
1123	              {
1124	                lv_label_set_text(g_chat_status, "Replying...");
1125	              }
1126	          }
1127	        else
1128	          {
1129	            lv_label_set_text(g_chat_msg_area, msg_text);
1130	            lv_label_set_text(g_chat_status, "Error - check LLM config");
1131	            g_reply_busy = 0;  /* LLM errored out, release the wake loop */
1132	          }
1133	      }
1134	
1135	    /* Voice wake-word command handoff: the wake thread writes the command
1136	     * (wake word already stripped), we call send_to_llm() here so all LVGL
1137	     * access stays on this thread. */
1138	    char wake_cmd[MSG_BUF_LEN];
1139	    bool have_wake = false;
1140	
1141	    pthread_mutex_lock(&g_wake_cmd_lock);
1142	    if (g_wake_cmd_ready)
1143	      {
1144	        g_wake_cmd_ready = false;
1145	        strncpy(wake_cmd, g_wake_cmd, MSG_BUF_LEN - 1);
1146	        wake_cmd[MSG_BUF_LEN - 1] = '\0';
1147	        have_wake = true;
1148	      }
1149	    pthread_mutex_unlock(&g_wake_cmd_lock);
1150	
1151	    if (have_wake)
1152	      {
1153	        send_to_llm(wake_cmd);
1154	      }
1155	}
