778	    int silence_run = 0;
779	    int64_t deadline = (timeout_ms > 0) ? (now_ms() + timeout_ms) : 0;
780	
781	    syslog(LOG_INFO, "[kid_buddy] wake: listening...\n");
782	
783	    while (pcm_len < WAKE_MAX_BYTES) {
784	        /* A touch-triggered interaction may have started while we listened. */
785	        if (g_reply_busy) {
