898	        bool follow_up = (g_last_reply_ms != 0 && elapsed < FOLLOW_UP_MS);
899	        int timeout_ms = follow_up ? (int)(FOLLOW_UP_MS - elapsed) : 0;
900	
901	        char *asr_text = listen_one_utterance(timeout_ms);
902	        if (!asr_text) {
903	            continue;
904	        }
905	
906	        syslog(LOG_INFO, "[kid_buddy] wake: heard \"%s\"%s\n", asr_text,
