33	int voice_tts_register(const voice_tts_ops_t* ops)
34	{
35	    if (!ops || !ops->name || !ops->synthesize) {
36	        return -EINVAL;
37	    }
38	
39	    if (s_backend_count >= VOICE_TTS_MAX_BACKENDS) {
40	        syslog(LOG_ERR, "[%s] Too many TTS backends\n", TAG);
41	        return -ENOMEM;
42	    }
43	
44	    s_backends[s_backend_count++] = ops;
45	    syslog(LOG_INFO, "[%s] Registered backend: %s\n", TAG, ops->name);
46	
47	    /* First registered backend becomes the default */
48	    if (!s_active) {
49	        s_active = ops;
50	        if (ops->init) {
51	            ops->init();
52	        }
53	    }
54	
55	    return 0;
56	}
57	
58	int voice_tts_set_backend(const char* name)
59	{
60	    if (!name) {
61	        return -EINVAL;
62	    }
63	
64	    for (int i = 0; i < s_backend_count; i++) {
65	        if (strcmp(s_backends[i]->name, name) == 0) {
66	            if (s_active && s_active->deinit) {
67	                s_active->deinit();
68	            }
69	
70	            s_active = s_backends[i];
71	            if (s_active->init) {
72	                s_active->init();
73	            }
74	
75	            syslog(LOG_INFO, "[%s] Backend set to: %s\n",
76	                TAG, name);
77	            return 0;
78	        }
79	    }
80	
81	    syslog(LOG_ERR, "[%s] Backend not found: %s\n", TAG, name);
82	    return -ENOENT;
83	}
84	
85	const char* voice_tts_get_backend(void)
86	{
87	    return s_active ? s_active->name : NULL;
88	}
