691	static void sunxi_codec_init(struct snd_codec *codec)
692	{
693		struct sunxi_codec_info *sunxi_codec = codec->private_data;
694		struct sunxi_codec_param *param = &sunxi_codec->param;
695		struct alg_cfg_reg_domain domain_1bdrc = {
696			.reg_base = (void *)SUNXI_CODEC_BASE_ADDR,
697			.reg_min = SUNXI_DAC_DAP_CTL,
698			.reg_max = SUNXI_DAC_DRC_HPFLGAIN,
699		};
700	
701		/* get chp version */
702		sunxi_codec->chip_ver = hal_efuse_get_chip_ver();
703	
704		/* In order to ensure that the ADC sampling is normal,
705		 * the A chip SOC needs to always open HPLDO and RMC_EN
706		 */
707		if (sunxi_codec->chip_ver == CHIP_VER_A) {
708			snd_codec_update_bits(codec, SUNXI_POWER_ANA_CTL,
709				(0x1<<HPLDO_EN), (0x1<<HPLDO_EN));
710			snd_codec_update_bits(codec, SUNXI_RAMP_ANA_CTL,
711				(0x1<<RMCEN), (0x1<<RMCEN));
712		} else {
713			snd_codec_update_bits(codec, SUNXI_POWER_ANA_CTL,
714				(0x1<<HPLDO_EN), (0x0<<HPLDO_EN));
715			snd_codec_update_bits(codec, SUNXI_RAMP_ANA_CTL,
716				(0x1<<RMCEN), (0x0<<RMCEN));
717		}
718	
719		/* Disable HPF(high passed filter) */
720		snd_codec_update_bits(codec, SUNXI_DAC_DPC,
721				(1 << HPF_EN), (0x0 << HPF_EN));
722	
723		if (param->rx_sync_en) {
724			/* disabled ADCFDT */
725			snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
726					(0x1 << ADCDFEN), (0x0 << ADCDFEN));
727			snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
728					(0x3 << ADCFDT), (0x2 << ADCFDT));
729			/* RX_SYNC_EN */
730			snd_codec_update_bits(codec, SUNXI_ADC_FIFOC, 1 << RX_SYNC_EN, 0 << RX_SYNC_EN);
731		} else {
732			/* Enable ADCFDT to overcome niose at the beginning */
733			snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
734					(0x1 << ADCDFEN), (0x1 << ADCDFEN));
735			snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
736					(0x3 << ADCFDT), (0x2 << ADCFDT));
737		}
738	
739		/* init the mic pga and vol params */
740		snd_codec_update_bits(codec, SUNXI_DAC_ANA_CTL,
741				0x1F << LINEOUT_VOL,
742				param->lineout_vol << LINEOUT_VOL);
743		snd_codec_update_bits(codec, SUNXI_HP_ANA_CTL,
744				0x7 << HP_GAIN,
745				param->hpout_vol << HP_GAIN);
746	
747		/* DAC_VOL_SEL enable */
748		snd_codec_update_bits(codec, SUNXI_DAC_VOL_CTL,
749				(0x1 << DAC_VOL_SEL), (0x1 << DAC_VOL_SEL));
750		snd_codec_update_bits(codec, SUNXI_DAC_DPC,
751				0x3F << DVOL,
752				param->digital_vol << DVOL);
753	
754		snd_codec_update_bits(codec, SUNXI_DAC_ANA_CTL,
755				(0x1 << LINEOUTLDIFFEN) | (0x1 << LINEOUTRDIFFEN),
756				(0x1 << LINEOUTLDIFFEN) | (0x1 << LINEOUTRDIFFEN));
757	
758		snd_codec_update_bits(codec, SUNXI_ADC1_ANA_CTL,
759				0x1F << ADC_PGA_GAIN_CTL,
760				param->mic1gain << ADC_PGA_GAIN_CTL);
761	
762		snd_codec_update_bits(codec, SUNXI_ADC2_ANA_CTL,
763				0x1F << ADC_PGA_GAIN_CTL,
764				param->mic2gain << ADC_PGA_GAIN_CTL);
765	
766		snd_codec_update_bits(codec, SUNXI_ADC3_ANA_CTL,
767				0x1F << ADC_PGA_GAIN_CTL,
768				param->mic3gain << ADC_PGA_GAIN_CTL);
769	
770	#ifdef SUNXI_CODEC_DAP_ENABLE
771		if (param->dacdrc_cfg || param->dachpf_cfg) {
772			snd_codec_update_bits(codec, SUNXI_DAC_DAP_CTL,
773					(0x1 << DDAP_EN), (0x1 << DDAP_EN));
774		}
775	
776		if (param->adcdrc_cfg || param->adchpf_cfg) {
777			snd_codec_update_bits(codec, SUNXI_ADC_DAP_CTL,
778					(0x1 << ADC_DAP0_EN | 0x1 << ADC_DAP1_EN),
779					(0x1 << ADC_DAP0_EN | 0x1 << ADC_DAP1_EN));
780		}
781	
782		if (param->adcdrc_cfg) {
783			adcdrc_config(codec);
784			adcdrc_enable(codec, 1);
785		}
786		if (param->adchpf_cfg) {
787			adchpf_config(codec);
788			adchpf_enable(codec, 1);
789		}
790		if (param->dacdrc_cfg) {
791			dacdrc_config(codec);
792			dacdrc_enable(codec, 1);
793		}
794		if (param->dachpf_cfg) {
795			dachpf_config(codec);
796			dachpf_enable(codec, 1);
797		}
798	#endif
799	
800		sunxi_alg_cfg_domain_set(&domain_1bdrc, SUNXI_ALG_CFG_DOMAIN_1BDRC);
801	}
