803	static void sunxi_codec_playback_hp_route(struct snd_codec *codec, int spk, int onoff)
804	{
805		struct sunxi_codec_info *sunxi_codec = codec->private_data;
806		struct sunxi_codec_param *param = &sunxi_codec->param;
807	
808		if (onoff) {
809			if (sunxi_codec->chip_ver == CHIP_VER_A) {
810				snd_codec_update_bits(codec, SUNXI_HP_ANA_CTL,
811						(0x1<<HPFB_BUF_EN) | (0x1<<HPFB_IN_EN),
812						(0x1<<HPFB_BUF_EN) | (0x1<<HPFB_IN_EN));
813				/* ramp out enable */
814				snd_codec_update_bits(codec, SUNXI_HP_ANA_CTL,
815						(0x1<<RAMP_OUT_EN) | (0x1<<RSWITCH),
816						(0x1<<RAMP_OUT_EN) | (0x1<<RSWITCH));
817				/* digital DAC enable */
818				snd_codec_update_bits(codec, SUNXI_DAC_DPC,
819						(0x1<<EN_DAC), (0x1<<EN_DAC));
820				hal_msleep(5);
821				/* analog DAC enable */
822				snd_codec_update_bits(codec, SUNXI_DAC_ANA_CTL,
823						(0x1<<DACLEN) | (0x1<<DACREN),
824						(0x1<<DACLEN) | (0x1<<DACREN));
825				/* HEADPONEOUT */
826				snd_codec_update_bits(codec, SUNXI_HP_ANA_CTL,
827					(0x1<<HP_DRVEN) | (0x1<<HP_DRVOUTEN),
828					(0x1<<HP_DRVEN) | (0x1<<HP_DRVOUTEN));
829				/* Playback on */
830				snd_codec_update_bits(codec, SUNXI_POWER_ANA_CTL,
831					(0x1<<HPLDO_EN), (0x1<<HPLDO_EN));
832			} else {
833				/* digital DAC enable */
834				snd_codec_update_bits(codec, SUNXI_DAC_DPC,
835						(0x1<<EN_DAC), (0x1<<EN_DAC));
836				snd_codec_update_bits(codec, SUNXI_RAMP_ANA_CTL,
837						(0x1<<RDEN), (0x1<<RDEN));
838			}
839			if (spk) {
840				hal_gpio_set_direction(param->gpio_spk, GPIO_MUXSEL_OUT);
841				hal_gpio_set_data(param->gpio_spk, param->pa_level);
842				hal_msleep(param->pa_msleep_time);
843			}
844		} else {
845			if (spk) {
846				hal_gpio_set_direction(param->gpio_spk, GPIO_MUXSEL_OUT);
847				hal_gpio_set_data(param->gpio_spk, !param->pa_level);
848			}
849			/* Playback off */
850			if (sunxi_codec->chip_ver == CHIP_VER_A) {
851				/* HEADPONE_EN */
852				snd_codec_update_bits(codec, SUNXI_HP_ANA_CTL,
853						(0x1<<HP_DRVEN), (0x0<<HP_DRVEN));
854				/* power off */
855				/* note: HPLDO is always open to avoid KEY_ADC sampling fail */
856				/* snd_codec_update_bits(codec, SUNXI_POWER_ANA_CTL, */
857				/* 		(0x1<<HPLDO_EN), (0x0<<HPLDO_EN)); */
858				hal_msleep(30);
859				/* HEADPONE_OUT */
860				snd_codec_update_bits(codec, SUNXI_HP_ANA_CTL,
861						(0x1<<HP_DRVOUTEN), (0x0<<HP_DRVOUTEN));
862				/* analog DAC */
863				snd_codec_update_bits(codec, SUNXI_DAC_ANA_CTL,
864						(0x1<<DACLEN) | (0x1<<DACREN),
865						(0x0<<DACLEN) | (0x0<<DACREN));
866				/* digital DAC */
867				snd_codec_update_bits(codec, SUNXI_DAC_DPC,
868						(0x1<<EN_DAC), (0x0<<EN_DAC));
869	
870				snd_codec_update_bits(codec, SUNXI_HP_ANA_CTL,
871						(0x1<<RAMP_OUT_EN) | (0x1<<RSWITCH),
872						(0x0<<RAMP_OUT_EN) | (0x0<<RSWITCH));
873	
874				snd_codec_update_bits(codec, SUNXI_HP_ANA_CTL,
875						(0x1<<HPFB_BUF_EN) | (0x1<<HPFB_IN_EN),
876						(0x0<<HPFB_BUF_EN) | (0x0<<HPFB_IN_EN));
877			} else {
878				/* analog DAC */
879				snd_codec_update_bits(codec, SUNXI_DAC_ANA_CTL,
880						(0x1<<DACLEN) | (0x1<<DACREN),
881						(0x0<<DACLEN) | (0x0<<DACREN));
882				/* digital DAC enable */
883				snd_codec_update_bits(codec, SUNXI_DAC_DPC,
884						(0x1<<EN_DAC), (0x0<<EN_DAC));
885				snd_codec_update_bits(codec, SUNXI_RAMP_ANA_CTL,
886						(0x1<<RDEN), (0x0<<RDEN));
887			}
888		}
889	}
