891	static void sunxi_codec_playback_lineout_route(struct snd_codec *codec, int spk, int onoff)
892	{
893		struct sunxi_codec_info *sunxi_codec = codec->private_data;
894		struct sunxi_codec_param *param = &sunxi_codec->param;
895	
896		if (onoff) {
897			/* digital DAC enable */
898			snd_codec_update_bits(codec, SUNXI_DAC_DPC,
899					(0x1<<EN_DAC), (0x1<<EN_DAC));
900			hal_msleep(5);
901			/* analog DAC enable */
902			snd_codec_update_bits(codec, SUNXI_DAC_ANA_CTL,
903					(0x1<<DACLEN) | (0x1<<DACREN),
904					(0x1<<DACLEN) | (0x1<<DACREN));
905			snd_codec_update_bits(codec, SUNXI_DAC_ANA_CTL,
906					(0x1<<DACLMUTE) | (0x1<<DACRMUTE),
907					(0x1<<DACLMUTE) | (0x1<<DACRMUTE));
908			if (sunxi_codec->chip_ver != CHIP_VER_A) {
909				uint32_t reg_val;
910				reg_val = snd_codec_read(codec, SUNXI_RAMP_ANA_CTL);
911				if(!(reg_val & (0x1 << RDEN)))
912					snd_codec_update_bits(codec, SUNXI_RAMP_ANA_CTL,
913							0x1<<RDEN, 0x1<<RDEN);
914			}
915			snd_codec_update_bits(codec, SUNXI_DAC_REG,
916					(0x1<<LINEOUTL_EN) | (0x1<<LINEOUTR_EN),
917					(0x1<<LINEOUTL_EN) | (0x1<<LINEOUTR_EN));
918			if (spk) {
919				hal_gpio_set_direction(param->gpio_spk, GPIO_MUXSEL_OUT);
920				hal_gpio_set_data(param->gpio_spk, param->pa_level);
921				hal_msleep(param->pa_msleep_time);
922			}
923		} else {
924			if (spk) {
925				hal_gpio_set_direction(param->gpio_spk, GPIO_MUXSEL_OUT);
926				hal_gpio_set_data(param->gpio_spk, !param->pa_level);
927			}
928			/* analog DAC */
929			snd_codec_update_bits(codec, SUNXI_DAC_ANA_CTL,
930					(0x1<<DACLEN) | (0x1<<DACREN),
931					(0x0<<DACLEN) | (0x0<<DACREN));
932			snd_codec_update_bits(codec, SUNXI_DAC_ANA_CTL,
933					(0x1<<DACLMUTE) | (0x1<<DACRMUTE),
934					(0x0<<DACLMUTE) | (0x0<<DACRMUTE));
935			/* digital DAC enable */
936			snd_codec_update_bits(codec, SUNXI_DAC_DPC,
937					(0x1<<EN_DAC), (0x0<<EN_DAC));
938			snd_codec_update_bits(codec, SUNXI_DAC_REG,
939					(0x1<<LINEOUTL_EN) | (0x1<<LINEOUTR_EN),
940					(0x0<<LINEOUTL_EN) | (0x0<<LINEOUTR_EN));
941			if (sunxi_codec->chip_ver != CHIP_VER_A) {
942				uint32_t reg_val;
943				reg_val = snd_codec_read(codec, SUNXI_RAMP_ANA_CTL);
944				if(!(reg_val & (0x1 << RDEN)))
945					snd_codec_update_bits(codec, SUNXI_RAMP_ANA_CTL,
946							0x1<<RDEN, 0x0<<RDEN);
947			}
948		}
949	
950	}
