952	static int sunxi_codec_dapm_control(struct snd_pcm_substream *substream,
953					struct snd_dai *dai, int onoff)
954	{
955		struct snd_codec *codec = dai->component;
956		struct sunxi_codec_info *sunxi_codec = codec->private_data;
957		struct sunxi_codec_param *param = &sunxi_codec->param;
958	
959		/* Belt-and-suspenders: re-assert the external speaker PA on every
960		 * playback ON, BEFORE the dapm_state early-return below. The route
961		 * functions arm gpio_spk, but if they get skipped (stale dapm_state)
962		 * the speaker amp stays off and a follow-up reply is silent. Re-arming
963		 * here is idempotent and cheap. */
964		if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK && onoff &&
965			param->gpio_spk > 0) {
966			hal_gpio_set_direction(param->gpio_spk, GPIO_MUXSEL_OUT);
967			hal_gpio_set_data(param->gpio_spk, param->pa_level);
968			hal_msleep(param->pa_msleep_time);
969			syslog(LOG_INFO, "[codec] PA re-arm: gpio_spk=%d pa_level=%d\n",

969			syslog(LOG_INFO, "[codec] PA re-arm: gpio_spk=%d pa_level=%d\n",
970				param->gpio_spk, param->pa_level);
971		}
972	
973		if (substream->dapm_state == onoff)
974			return 0;
975		if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
976			/*
977			 * Playback:
978			 * Playback --> DAC --> DAC_DIFFER --> LINEOUT/HPOUT + (External Speaker)
979			 */
980	
981			switch (param->pb_audio_route) {
982			case PB_AUDIO_ROUTE_LINEOUT_SPK:
983				sunxi_codec_playback_lineout_route(codec, 1, onoff);
984				break;
985			case PB_AUDIO_ROUTE_HEADPHONE_SPK:
986				sunxi_codec_playback_hp_route(codec, 1, onoff);
987				break;
988			case PB_AUDIO_ROUTE_LINEOUT:
989				sunxi_codec_playback_lineout_route(codec, 0, onoff);
990				break;
991			case PB_AUDIO_ROUTE_HEADPHONE:
992				sunxi_codec_playback_hp_route(codec, 0, onoff);
993				break;
994			case PB_AUDIO_ROUTE_LO_HP:
995				sunxi_codec_playback_lineout_route(codec, 0, onoff);
996				sunxi_codec_playback_hp_route(codec, 0, onoff);
997				break;
998			case PB_AUDIO_ROUTE_LO_HP_SPK:
999				sunxi_codec_playback_lineout_route(codec, onoff ? 0 : 1, onoff);
1000				sunxi_codec_playback_hp_route(codec, onoff ? 1 : 0, onoff);
1001				break;
1002			}
1003		} else {
1004			/*
1005			 * Capture:
1006			 * Capture1 <-- ADC1 <-- Input Mixer <-- LINEINL PGA <-- LINEINL
1007			 * Capture1 <-- ADC1 <-- Input Mixer <-- FMINL PGA <-- FMINL
1008			 *
1009			 * Capture2 <-- ADC2 <-- Input Mixer <-- LINEINR PGA <-- LINEINR
1010			 * Capture2 <-- ADC2 <-- Input Mixer <-- FMINR PGA <-- FMINR
1011			 *
1012			 * Capture3 <-- ADC3 <-- Input Mixer <-- MIC3 PGA <-- MIC3
1013			 */
1014			unsigned int channels = 0;
1015			channels = substream->runtime->channels;
1016	
1017			snd_print("channels = %u\n", channels);
1018			snd_print("adc flag:%d,%d,%d\n",
1019				param->adc1_flag, param->adc2_flag, param->adc3_flag);
1020			if (onoff) {
1021				if ((param->adc1_flag & ADC_AUDIO_ROUTE_MIC) ||
1022					(param->adc2_flag & ADC_AUDIO_ROUTE_MIC) ||
1023					(param->adc3_flag & ADC_AUDIO_ROUTE_MIC)) {
1024					snd_codec_update_bits(codec, SUNXI_MICBIAS_REG,
1025							      0x1<<MMICBIASEN,
1026							      0x1<<MMICBIASEN);
1027				}
1028				/* Capture on */
1029				hal_msleep(100);
1030				/* digital ADC enable */
1031				snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
1032						(0x1<<EN_AD), (0x1<<EN_AD));
1033	
1034				if (channels > 3 || channels < 1) {
1035					snd_err("unknown channels:%u\n", channels);
1036					return -EINVAL;
1037				}
1038	
1039				if (param->adc1_flag == ADC_AUDIO_ROUTE_MIC) {
1040					snd_codec_update_bits(codec, SUNXI_ADC1_ANA_CTL,
1041							      0x1<<ADC_EN,
1042							      0x1<<ADC_EN);
1043				} else if (param->adc1_flag == ADC_AUDIO_ROUTE_LINEIN ||
1044						param->adc1_flag == ADC_AUDIO_ROUTE_FMIN) {
1045	
1046					snd_codec_update_bits(codec, SUNXI_ADC1_ANA_CTL,
1047							      0x1F<<ADC_PGA_GAIN_CTL,
1048							      0x00<<ADC_PGA_GAIN_CTL);
1049	
1050					snd_codec_update_bits(codec, SUNXI_ADC1_ANA_CTL,
1051							      0x1<<MIC_SIN_EN,
1052							      0x1<<MIC_SIN_EN);
1053	
1054					snd_codec_update_bits(codec, SUNXI_ADC1_ANA_CTL,
1055							      0x1<<ADC_EN,
1056							      0x1<<ADC_EN);
1057				}
1058	
1059				if (param->adc2_flag == ADC_AUDIO_ROUTE_MIC) {
1060					snd_codec_update_bits(codec, SUNXI_ADC2_ANA_CTL,
1061							      0x1<<ADC_EN,
1062							      0x1<<ADC_EN);
1063				} else if (param->adc2_flag == ADC_AUDIO_ROUTE_LINEIN ||
1064						param->adc2_flag == ADC_AUDIO_ROUTE_FMIN) {
1065	
1066					snd_codec_update_bits(codec, SUNXI_ADC2_ANA_CTL,
1067							      0x1F<<ADC_PGA_GAIN_CTL,
1068							      0x00<<ADC_PGA_GAIN_CTL);
1069	
1070					snd_codec_update_bits(codec, SUNXI_ADC2_ANA_CTL,
1071							      0x1<<MIC_SIN_EN,
1072							      0x1<<MIC_SIN_EN);
1073	
1074					snd_codec_update_bits(codec, SUNXI_ADC2_ANA_CTL,
1075							      0x1<<ADC_EN,
1076							      0x1<<ADC_EN);
1077				}
1078	
1079				if (param->adc3_flag) {
1080					snd_codec_update_bits(codec, SUNXI_ADC3_ANA_CTL,
1081							      0x1<<ADC_EN,
1082							      0x1<<ADC_EN);
1083				}
1084			} else {
1085				/* Capture off */
1086				if (channels > 3 || channels < 1) {
1087					snd_err("unknown channels:%u\n", channels);
1088					return -EINVAL;
1089				}
1090	
1091				if ((param->adc1_flag & ADC_AUDIO_ROUTE_MIC) ||
1092					(param->adc2_flag & ADC_AUDIO_ROUTE_MIC) ||
1093					(param->adc3_flag & ADC_AUDIO_ROUTE_MIC)) {
1094					snd_codec_update_bits(codec, SUNXI_MICBIAS_REG,
1095							      0x1<<MMICBIASEN,
1096							      0x0<<MMICBIASEN);
1097				}
1098	
1099				if (param->adc1_flag == ADC_AUDIO_ROUTE_MIC) {
1100					snd_codec_update_bits(codec, SUNXI_ADC1_ANA_CTL,
1101							      0x1<<ADC_EN,
1102							      0x0<<ADC_EN);
1103				} else if (param->adc1_flag == ADC_AUDIO_ROUTE_LINEIN ||
1104						param->adc1_flag == ADC_AUDIO_ROUTE_FMIN) {
1105	
1106					snd_codec_update_bits(codec, SUNXI_ADC1_ANA_CTL,
1107							      0x1F<<ADC_PGA_GAIN_CTL,
1108							      param->mic1gain<<ADC_PGA_GAIN_CTL);
1109	
1110					snd_codec_update_bits(codec, SUNXI_ADC1_ANA_CTL,
1111							      0x1<<MIC_SIN_EN,
1112							      0x0<<MIC_SIN_EN);
1113	
1114					snd_codec_update_bits(codec, SUNXI_ADC1_ANA_CTL,
1115							      0x1<<ADC_EN,
1116							      0x0<<ADC_EN);
1117				}
1118	
1119				if (param->adc2_flag == ADC_AUDIO_ROUTE_MIC) {
1120					snd_codec_update_bits(codec, SUNXI_ADC2_ANA_CTL,
1121							      0x1<<ADC_EN,
1122							      0x0<<ADC_EN);
1123				} else if (param->adc2_flag == ADC_AUDIO_ROUTE_LINEIN ||
1124						param->adc2_flag == ADC_AUDIO_ROUTE_FMIN) {
1125	
1126					snd_codec_update_bits(codec, SUNXI_ADC2_ANA_CTL,
1127							      0x1F<<ADC_PGA_GAIN_CTL,
1128							      param->mic2gain<<ADC_PGA_GAIN_CTL);
1129	
1130					snd_codec_update_bits(codec, SUNXI_ADC2_ANA_CTL,
1131							      0x1<<MIC_SIN_EN,
1132							      0x0<<MIC_SIN_EN);
1133	
1134					snd_codec_update_bits(codec, SUNXI_ADC2_ANA_CTL,
1135							      0x1<<ADC_EN,
1136							      0x0<<ADC_EN);
1137				}
1138	
1139				if (param->adc3_flag) {
1140					snd_codec_update_bits(codec, SUNXI_ADC3_ANA_CTL,
1141							      0x1<<ADC_EN,
1142							      0x0<<ADC_EN);
1143				}
1144				/* digital ADC enable */
1145				snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
1146						(0x1<<EN_AD), (0x0<<EN_AD));
1147			}
1148		}
1149		if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
1150			syslog(LOG_INFO, "[codec] DAC regs onoff=%d DPC=0x%08x ANA=0x%08x RAMP=0x%08x FIFOC=0x%08x dac_rate=%u\n",
1151				onoff,
1152				snd_codec_read(codec, SUNXI_DAC_DPC),
1153				snd_codec_read(codec, SUNXI_DAC_ANA_CTL),
1154				snd_codec_read(codec, SUNXI_RAMP_ANA_CTL),
1155				snd_codec_read(codec, SUNXI_DAC_FIFOC),
1156				hal_clk_get_rate(sunxi_codec->moduleclk));
1157		}
1158		substream->dapm_state = onoff;
1159		return 0;
1160	}
