1182	static int sunxi_codec_hw_params(struct snd_pcm_substream *substream,
1183			struct snd_pcm_hw_params *params, struct snd_dai *dai)
1184	{
1185		struct snd_codec *codec = dai->component;
1186		struct sunxi_codec_info *sunxi_codec = codec->private_data;
1187		struct sunxi_codec_param *codec_param = &sunxi_codec->param;
1188		int i = 0;
1189	
1190		snd_print("\n");
1191		switch (params_format(params)) {
1192		case	SND_PCM_FORMAT_S16_LE:
1193			if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
1194				snd_codec_update_bits(codec, SUNXI_DAC_FIFOC,
1195					(3 << FIFO_MODE), (3 << FIFO_MODE));
1196				snd_codec_update_bits(codec, SUNXI_DAC_FIFOC,
1197					(1 << TX_SAMPLE_BITS), (0 << TX_SAMPLE_BITS));
1198			} else {
1199				snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
1200					(1 << RX_FIFO_MODE), (1 << RX_FIFO_MODE));
1201				snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
1202					(1 << RX_SAMPLE_BITS), (0 << RX_SAMPLE_BITS));
1203			}
1204			break;
1205		case	SND_PCM_FORMAT_S24_LE:
1206		case	SND_PCM_FORMAT_S32_LE:
1207			if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
1208				snd_codec_update_bits(codec, SUNXI_DAC_FIFOC,
1209					(3 << FIFO_MODE), (0 << FIFO_MODE));
1210				snd_codec_update_bits(codec, SUNXI_DAC_FIFOC,
1211					(1 << TX_SAMPLE_BITS), (1 << TX_SAMPLE_BITS));
1212			} else {
1213				snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
1214					(1 << RX_FIFO_MODE), (0 << RX_FIFO_MODE));
1215				snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
1216					(1 << RX_SAMPLE_BITS), (1 << RX_SAMPLE_BITS));
1217			}
1218			break;
1219		default:
1220			break;
1221		}
1222	
1223		for (i = 0; i < ARRAY_SIZE(sample_rate_conv); i++) {
1224			if (sample_rate_conv[i].samplerate == params_rate(params)) {
1225				if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
1226					snd_codec_update_bits(codec, SUNXI_DAC_FIFOC,
1227						(0x7 << DAC_FS),
1228						(sample_rate_conv[i].rate_bit << DAC_FS));
1229				} else {
1230					if (sample_rate_conv[i].samplerate > 48000)
1231						return -EINVAL;
1232					snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
1233						(0x7 << ADC_FS),
1234						(sample_rate_conv[i].rate_bit<<ADC_FS));
1235				}
1236			}
1237		}
1238	
1239		/* reset the adchpf func setting for different sampling */
1240		if (substream->stream == SNDRV_PCM_STREAM_CAPTURE) {
1241			if (codec_param->adchpf_cfg) {
1242				if (params_rate(params) == 16000) {
1243	
1244					snd_codec_write(codec, SUNXI_ADC_DRC_HHPFC,
1245							(0x00F623A5 >> 16) & 0xFFFF);
1246	
1247					snd_codec_write(codec, SUNXI_ADC_DRC_LHPFC,
1248								0x00F623A5 & 0xFFFF);
1249	
1250				} else if (params_rate(params) == 44100) {
1251	
1252					snd_codec_write(codec, SUNXI_ADC_DRC_HHPFC,
1253							(0x00FC60DB >> 16) & 0xFFFF);
1254	
1255					snd_codec_write(codec, SUNXI_ADC_DRC_LHPFC,
1256								0x00FC60DB & 0xFFFF);
1257				} else {
1258					snd_codec_write(codec, SUNXI_ADC_DRC_HHPFC,
1259							(0x00FCABB3 >> 16) & 0xFFFF);
1260	
1261					snd_codec_write(codec, SUNXI_ADC_DRC_LHPFC,
1262								0x00FCABB3 & 0xFFFF);
1263				}
1264			}
1265		}
1266	
1267		if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
1268			switch (params_channels(params)) {
1269			case 1:
1270				snd_codec_update_bits(codec, SUNXI_DAC_FIFOC,
1271						(1<<DAC_MONO_EN), 1<<DAC_MONO_EN);
1272				break;
1273			case 2:
1274				snd_codec_update_bits(codec, SUNXI_DAC_FIFOC,
1275						(1<<DAC_MONO_EN), (0<<DAC_MONO_EN));
1276				break;
1277			default:
1278				snd_err("cannot support the channels:%u.\n",
1279					params_channels(params));
1280				return -EINVAL;
1281			}
1282		} else {
1283			if (sunxi_get_adc_ch(codec) < 0) {
1284				snd_err("capture only support 1~3 channel\n");
1285				return -EINVAL;
1286			}
1287			if (codec_param->adc1_flag)
1288				snd_codec_update_bits(codec, SUNXI_ADC_DIG_CTL,
1289						      0x1<<ADC1_CHANNEL_EN,
1290						      0x1<<ADC1_CHANNEL_EN);
1291			else

1300				snd_codec_update_bits(codec, SUNXI_ADC_DIG_CTL,
1301						      0x1<<ADC2_CHANNEL_EN,
1302						      0x0<<ADC2_CHANNEL_EN);
1303			if (codec_param->adc3_flag)
1304				snd_codec_update_bits(codec, SUNXI_ADC_DIG_CTL,
1305						      0x1<<ADC3_CHANNEL_EN,
1306						      0x1<<ADC3_CHANNEL_EN);
1307			else
1308				snd_codec_update_bits(codec, SUNXI_ADC_DIG_CTL,
1309						      0x1<<ADC3_CHANNEL_EN,
1310						      0x0<<ADC3_CHANNEL_EN);
1311		}
1312	
1313		return 0;
1314	}
