1316	static int sunxi_codec_set_sysclk(struct snd_dai *dai,
1317			int clk_id, unsigned int freq, int dir)
1318	{
1319		struct snd_codec *codec = dai->component;
1320		struct sunxi_codec_info *sunxi_codec = codec->private_data;
1321	
1322		if (dir == SNDRV_PCM_STREAM_PLAYBACK) {
1323			/* If the DAC clock is already at the requested rate, leave it
1324			 * alone. The disable -> re-parent -> re-rate -> enable cycle can
1325			 * itself glitch the codec DAC clock on a 2nd+ open (follow-up reply
1326			 * silent); re-configure only when the rate actually differs. */
1327			unsigned int cur = hal_clk_get_rate(sunxi_codec->moduleclk);
1328			if (cur != freq) {
1329				hal_clock_disable(sunxi_codec->moduleclk);
1330				if (freq == 24576000) {
1331					hal_clk_set_parent(sunxi_codec->moduleclk, sunxi_codec->pllclk1);
1332				} else {
1333					hal_clk_set_parent(sunxi_codec->moduleclk, sunxi_codec->pllclk);
1334				}
1335				hal_clk_set_rate(sunxi_codec->moduleclk, freq);
1336				hal_msleep(50);
1337				hal_clock_enable(sunxi_codec->moduleclk);
1338			}
1339			syslog(LOG_INFO, "[codec] set_sysclk PLAY freq=%u cur=%u now=%u\n",
1340				freq, cur, hal_clk_get_rate(sunxi_codec->moduleclk));
1341		}
1342	
1343		if (dir == SNDRV_PCM_STREAM_CAPTURE) {
1344			if (freq == 24576000) {
1345				hal_clk_set_parent(sunxi_codec->moduleclk1, sunxi_codec->pllclk1);
1346			} else {
1347				hal_clk_set_parent(sunxi_codec->moduleclk1, sunxi_codec->pllclk);
1348			}
1349			hal_clk_set_rate(sunxi_codec->moduleclk1, freq);
1350			syslog(LOG_INFO, "[codec] set_sysclk CAP freq=%u adc_rate=%u\n",
1351				freq, hal_clk_get_rate(sunxi_codec->moduleclk1));
1352		}
1353	
1354		return 0;
1355	}
