1386	static int sunxi_codec_trigger(struct snd_pcm_substream *substream,
1387			int cmd, struct snd_dai *dai)
1388	{
1389		struct snd_codec *codec = dai->component;
1390		struct sunxi_codec_info *sunxi_codec = codec->private_data;
1391	
1392		snd_print("\n");
1393		switch (cmd) {
1394		case SNDRV_PCM_TRIGGER_START:
1395		case SNDRV_PCM_TRIGGER_RESUME:
1396		case SNDRV_PCM_TRIGGER_PAUSE_RELEASE:
1397			if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
1398				snd_codec_update_bits(codec, SUNXI_DAC_FIFOC,
1399					(1 << DAC_DRQ_EN), (1 << DAC_DRQ_EN));
1400			}
1401			else if (substream->stream == SNDRV_PCM_STREAM_CAPTURE) {
1402				snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
1403					(1 << ADC_DRQ_EN), (1 << ADC_DRQ_EN));
1404				if (sunxi_codec->param.rx_sync_en && sunxi_codec->param.rx_sync_ctl)
1405					sunxi_rx_sync_control(sunxi_codec->param.rx_sync_domain,
1406							      sunxi_codec->param.rx_sync_id, 1);
1407			}
