505	/* ── Streaming TTS worker ─────────────────────────────────────
506	 * Speak a response aloud in a background thread so the LVGL UI stays
507	 * responsive while TTS synthesizes and plays. A single worker thread
508	 * serializes every speak (voice_channel_speak aborts any in-progress speak
509	 * on a concurrent call). The worker does NOT speak partial fragments as they
510	 * stream: it waits for the final fragment and speaks the whole reply in one
511	 * voice_channel_speak() call. This keeps a single ALSA open/close cycle and
512	 * lets voice_channel_speak() buffer the full reply for continuous playback. */
513	
514	static void *tts_stream_worker(void *arg)
515	{
516	    (void)arg;
517	
518	    for (;;)
519	      {
520	        char text[MSG_BUF_LEN];
521	        bool final = false;
522	        unsigned int epoch;
523	        size_t spoken;
