525	        pthread_mutex_lock(&g_tts_lock);
526	        while (!g_tts_pending_ready)
527	          {
528	            pthread_cond_wait(&g_tts_cond, &g_tts_lock);
529	          }
530	        strncpy(text, g_tts_pending, MSG_BUF_LEN - 1);
531	        text[MSG_BUF_LEN - 1] = '\0';
532	        final = g_tts_pending_final;
533	        epoch = g_tts_epoch;
534	        spoken = g_spoken_len;
535	        g_tts_pending_ready = false;
536	        g_tts_pending_final = false;
537	        pthread_mutex_unlock(&g_tts_lock);
538	
539	        size_t len = strlen(text);
540	
541	        if (spoken > len)
542	          {
543	            spoken = len; /* offset reset under us mid-speak */
544	          }
545	
546	        /* Speak the whole reply in one voice_channel_speak() call, and only
547	         * once the reply is complete (final). Speaking sentence-by-sentence
548	         * as the text streamed made the worker open/close the ALSA codec
549	         * once per fragment; the codec's external-speaker PA (gpio_spk) is
550	         * armed on the first open but not reliably re-armed on a later open
551	         * in the same response, so only the first sentence was audible. A
552	         * single open/prepare/write/close cycle is the sequence the codec
553	         * plays reliably, and voice_channel_speak() already buffers the full
