67	/* Upper bound (seconds) on a single TLS handshake.  The socket is blocking
68	 * with SO_RCVTIMEO, so a WANT_READ retry just blocks again for another full
69	 * timeout; capping the handshake lets tls_ctx_connect_retry() actually recover
70	 * from a half-open MiMo edge instead of stalling forever. */
71	#define AGENT_TLS_HANDSHAKE_TIMEOUT_SEC 10
