146	/* ── Persistent connection pool (keep-alive) ─────────────────── */
147	/* Keeps one live TLS connection per host:port so repeated calls to
148	 * the same endpoint (Feishu REST, LLM API) skip the TLS handshake. */
149	
150	#ifdef CONFIG_AI_AGENT_TLS_CONN_POOL_SIZE
151	#define CONN_POOL_SIZE CONFIG_AI_AGENT_TLS_CONN_POOL_SIZE
152	#else
153	#define CONN_POOL_SIZE 2
154	#endif
155	
156	typedef struct {
157	    tls_ctx_t ctx;
158	    char host[128];
159	    char port[8];
160	    bool in_use; /* locked by a request */
161	    bool valid; /* connection is alive */
162	} conn_slot_t;
163	
164	static conn_slot_t s_pool[CONN_POOL_SIZE];
165	static pthread_mutex_t s_pool_lock = PTHREAD_MUTEX_INITIALIZER;
166	
167	/* Acquire a slot for host:port.  Returns a locked, connected ctx or NULL. */
168	static conn_slot_t* pool_acquire(const char* host, const char* port)
169	{
170	    pthread_mutex_lock(&s_pool_lock);
171	
172	    /* 1. Find an existing valid slot for this host:port */
173	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
174	        conn_slot_t* s = &s_pool[i];
175	        if (s->valid && !s->in_use && strcmp(s->host, host) == 0 && strcmp(s->port, port) == 0) {
176	            s->in_use = true;
177	            pthread_mutex_unlock(&s_pool_lock);
178	            return s;
179	        }
180	    }
181	
182	    /* 2. Find an empty slot */
183	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
184	        if (!s_pool[i].valid && !s_pool[i].in_use) {
185	            s_pool[i].in_use = true;
186	            pthread_mutex_unlock(&s_pool_lock);
187	            return &s_pool[i];
188	        }
189	    }
190	
191	    /* 3. Evict the first non-in-use slot */
192	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
193	        if (!s_pool[i].in_use) {
194	            tls_ctx_free(&s_pool[i].ctx);
195	            s_pool[i].valid = false;
196	            s_pool[i].in_use = true;
197	            pthread_mutex_unlock(&s_pool_lock);
198	            return &s_pool[i];
199	        }
200	    }
201	
202	    pthread_mutex_unlock(&s_pool_lock);
203	    return NULL; /* all slots busy — caller falls back to ephemeral */
204	}
205	
206	/* Return a slot to the pool.  keep=true means the connection is still alive. */
207	static void pool_release(conn_slot_t* s, const char* host, const char* port, bool keep)
208	{
209	    pthread_mutex_lock(&s_pool_lock);
210	    if (keep) {
211	        strncpy(s->host, host, sizeof(s->host) - 1);
212	        strncpy(s->port, port, sizeof(s->port) - 1);
213	        s->valid = true;
214	    } else {
215	        tls_ctx_free(&s->ctx);
216	        s->valid = false;
217	        s->host[0] = '\0';
218	    }
219	    s->in_use = false;
220	    pthread_mutex_unlock(&s_pool_lock);
221	}
222	
223	void vela_tls_pool_cleanup(void)
224	{
225	    pthread_mutex_lock(&s_pool_lock);
226	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
227	        if (s_pool[i].in_use) {
228	            syslog(LOG_WARNING,
229	                "[vela_tls] Pool slot %d still in use at shutdown, skipping\n", i);
230	            continue;
231	        }
232	        if (s_pool[i].valid) {
233	            tls_ctx_free(&s_pool[i].ctx);
234	            s_pool[i].valid = false;
235	        }
236	        s_pool[i].host[0] = '\0';
237	    }
238	    pthread_mutex_unlock(&s_pool_lock);
239	}
240	
241	static int tls_ctx_connect(tls_ctx_t* ctx, const char* host, const char* port)
242	{
243	    int ret;
244	
245	    /* Replicate mbedtls_net_connect()'s net_prepare(): ignore SIGPIPE so a
246	     * write to a peer-closed socket returns EPIPE instead of terminating us.
247	     * (Our manual connect below bypasses net_prepare.) */
248	    signal(SIGPIPE, SIG_IGN);
249	
250	    mbedtls_ssl_init(&ctx->ssl);
251	    mbedtls_ssl_config_init(&ctx->cfg);
252	    mbedtls_net_init(&ctx->net);
253	    mbedtls_ctr_drbg_init(&ctx->ctr_drbg);
254	
255	    /* Seed RNG directly with our robust function */
256	    const char* pers = "vela_tls";
257	    if ((ret = mbedtls_ctr_drbg_seed(&ctx->ctr_drbg, simple_entropy_func, NULL,
258	             (const unsigned char*)pers,
259	             strlen(pers)))
260	        != 0) {
261	        syslog(LOG_ERR, "[%s] ctr_drbg_seed ret=0x%x\n", TAG, -ret);
262	        return VELA_TLS_ERR_HANDSHAKE;
263	    }
264	
265	    /* Check system time — crucial for TLS certificate validation. */
266	    time_t now = time(NULL);
267	    syslog(LOG_DEBUG, "[%s] Handshake start: Host=%s, UNIX=%ld\n", TAG, host, (long)now);
268	
269	    if (now < 1704067200) { /* Jan 1 2024 */
270	        syslog(LOG_WARNING, "[%s] Clock too old, forcing to 2026\n", TAG);
271	        struct timespec ts = { .tv_sec = 1772275200, .tv_nsec = 0 };
272	        clock_settime(CLOCK_REALTIME, &ts);
273	    }
274	
275	    /* TCP connect — use HTTP CONNECT proxy if configured */
276	#ifdef CONFIG_AI_AGENT_NET_RPMSG
277	    {
278	        int res_ret = network_acquire_resource(network_get_connect_timeout() * 1000);
279	        if (res_ret != 0) {
280	            syslog(LOG_ERR, "[%s] Resource acquire failed: %d\n", TAG, res_ret);
281	            return VELA_TLS_ERR_CONNECT;
282	        }
283	    }
284	#endif
285	
286	    if (http_proxy_is_enabled()) {
287	        int tunnel_fd = proxy_open_tunnel(host, atoi(port), 30000);
288	        if (tunnel_fd < 0) {
289	            syslog(LOG_ERR, "[%s] proxy tunnel to %s:%s failed\n",
290	                TAG, host, port);
291	            return VELA_TLS_ERR_CONNECT;
292	        }
293	        ctx->net.fd = tunnel_fd;
294	        syslog(LOG_INFO, "[%s] Using proxy tunnel fd=%d for %s:%s\n",
295	            TAG, tunnel_fd, host, port);
296	    } else {
297	        /* Manual connect (instead of mbedtls_net_connect) so we can set
298	         * SO_SNDTIMEO on the socket before connect().  A half-open peer
299	         * (flaky MiMo edge) would otherwise block the caller for the full
300	         * TCP SYN retry window, which has no timeout on this build. */
301	        struct addrinfo hints;
302	        struct addrinfo* addr_list = NULL;
303	        struct addrinfo* cur;
304	        int fd = -1;
305	
306	        memset(&hints, 0, sizeof(hints));
307	        hints.ai_family = AF_UNSPEC;
308	        hints.ai_socktype = SOCK_STREAM;
309	        hints.ai_protocol = 0;
310	
311	        if (getaddrinfo(host, port, &hints, &addr_list) != 0) {
312	            syslog(LOG_ERR, "[%s] getaddrinfo %s:%s failed\n",
313	                TAG, host, port);
314	            return VELA_TLS_ERR_CONNECT;
315	        }
316	
317	        char ipbuf[64] = "?";
318	        for (cur = addr_list; cur != NULL; cur = cur->ai_next) {
319	            fd = (int)socket(cur->ai_family, cur->ai_socktype,
320	                cur->ai_protocol);
321	            if (fd < 0) {
322	                continue;
323	            }
324	
325	            struct timeval ctv = { .tv_sec = AGENT_LLM_SOCKET_TIMEOUT_SEC,
326	                .tv_usec = 0 };
327	            setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &ctv, sizeof(ctv));
328	
329	            if (connect(fd, cur->ai_addr, cur->ai_addrlen) == 0) {
330	                if (cur->ai_family == AF_INET) {
331	                    inet_ntop(AF_INET,
332	                        &((struct sockaddr_in*)cur->ai_addr)->sin_addr,
333	                        ipbuf, sizeof(ipbuf));
334	                } else if (cur->ai_family == AF_INET6) {
335	                    inet_ntop(AF_INET6,
336	                        &((struct sockaddr_in6*)cur->ai_addr)->sin6_addr,
337	                        ipbuf, sizeof(ipbuf));
338	                }
339	                break;
340	            }
341	
342	            close(fd);
343	            fd = -1;
344	        }
345	
346	        freeaddrinfo(addr_list);
347	
348	        if (fd < 0) {
349	            syslog(LOG_ERR, "[%s] connect %s:%s failed\n", TAG, host, port);
350	            return VELA_TLS_ERR_CONNECT;
351	        }
352	
353	        ctx->net.fd = fd;
354	        syslog(LOG_INFO, "[%s] TCP connected to %s:%s (fd=%d, ip=%s)\n",
355	            TAG, host, port, fd, ipbuf);
356	    }
357	
358	    /* Force blocking mode and set socket-level read timeout.
359	     * This avoids using select()/poll() inside mbedtls_net_recv_timeout
360	     * which returns MBEDTLS_ERR_NET_POLL_FAILED (-0x0047) on NuttX/QEMU.
361	     * Timeout is configured via AGENT_LLM_SOCKET_TIMEOUT_SEC in
362	     * agent_config.h.  LLM APIs (especially kimi with thinking mode)
363	     * can take over 60s for long responses. */
364	    mbedtls_net_set_block(&ctx->net);
365	    if (ctx->net.fd >= 0) {
366	#ifdef CONFIG_AI_AGENT_NET_RPMSG
367	        int read_timeout_sec = network_get_read_timeout();
368	        struct timeval tv = { .tv_sec = read_timeout_sec, .tv_usec = 0 };
369	#else
370	        struct timeval tv = { .tv_sec = AGENT_LLM_SOCKET_TIMEOUT_SEC,
371	            .tv_usec = 0 };
372	#endif
373	        setsockopt(ctx->net.fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
374	
375	#ifdef CONFIG_AI_AGENT_NET_RPMSG
376	        {
377	            int timeout_sec = network_get_connect_timeout();
378	            struct timeval ctv = { .tv_sec = timeout_sec, .tv_usec = 0 };
379	            setsockopt(ctx->net.fd, SOL_SOCKET, SO_SNDTIMEO, &ctv, sizeof(ctv));
380	        }
381	#endif
382	    }
383	
384	    /* SSL config: client, TLS, default ciphersuites */
385	    if ((ret = mbedtls_ssl_config_defaults(&ctx->cfg,
386	             MBEDTLS_SSL_IS_CLIENT,
387	             MBEDTLS_SSL_TRANSPORT_STREAM,
388	             MBEDTLS_SSL_PRESET_DEFAULT))
389	        != 0) {
390	        syslog(LOG_ERR, "[%s] ssl_config_defaults ret=0x%x\n", TAG, -ret);
391	        return VELA_TLS_ERR_HANDSHAKE;
392	    }
393	
394	    /* Pin the TLS version range to what is actually compiled in.
395	     * Setting max to MBEDTLS_SSL_VERSION_TLS1_3 when MBEDTLS_SSL_PROTO_TLS1_3
396	     * is not defined causes mbedtls_ssl_setup() to return BAD_CONFIG (-0x5e80).
397	     * Use TLS 1.3 as the ceiling only when the library was built with TLS 1.3
398	     * support; otherwise cap at TLS 1.2. */
399	    mbedtls_ssl_conf_min_tls_version(&ctx->cfg, MBEDTLS_SSL_VERSION_TLS1_2);
400	#if defined(MBEDTLS_SSL_PROTO_TLS1_3)
401	    mbedtls_ssl_conf_max_tls_version(&ctx->cfg, MBEDTLS_SSL_VERSION_TLS1_3);
402	#else
403	    mbedtls_ssl_conf_max_tls_version(&ctx->cfg, MBEDTLS_SSL_VERSION_TLS1_2);
404	#endif
405	
406	    /* Advertise ALPN so Cloudflare/OpenAI servers don't silently reject us.
407	     * Modern HTTPS servers send a fatal TLS alert or close the connection
408	     * when no ALPN extension is present in the ClientHello.
409	     * MBEDTLS_SSL_ALPN must be enabled in the build (it is). */
410	#if defined(MBEDTLS_SSL_ALPN)
411	    static const char* alpn_protos[] = { "http/1.1", NULL };
412	    if ((ret = mbedtls_ssl_conf_alpn_protocols(&ctx->cfg, alpn_protos)) != 0) {
413	        syslog(LOG_WARNING, "[%s] Failed to set ALPN protocols: -0x%04x (non-fatal)\n", TAG, -ret);
414	    }
415	#endif
416	
417	    /* Skip full chain verification — keeps portability without CA bundle */
418	    mbedtls_ssl_conf_authmode(&ctx->cfg, MBEDTLS_SSL_VERIFY_OPTIONAL);
419	    mbedtls_ssl_conf_rng(&ctx->cfg, mbedtls_ctr_drbg_random, &ctx->ctr_drbg);
420	
421	    /* Read timeout is handled at the socket level via SO_RCVTIMEO,
422	     * not via mbedtls_ssl_conf_read_timeout + mbedtls_net_recv_timeout,
423	     * because select()/poll() inside mbedtls_net_recv_timeout fails on
424	     * NuttX/QEMU with MBEDTLS_ERR_NET_POLL_FAILED (-0x0047). */
425	
426	    if ((ret = mbedtls_ssl_setup(&ctx->ssl, &ctx->cfg)) != 0) {
427	        syslog(LOG_ERR, "[%s] ssl_setup ret=0x%x\n", TAG, -ret);
428	        return VELA_TLS_ERR_HANDSHAKE;
429	    }
430	
431	    if ((ret = mbedtls_ssl_set_hostname(&ctx->ssl, host)) != 0) {
432	        syslog(LOG_ERR, "[%s] ssl_set_hostname ret=0x%x\n", TAG, -ret);
433	        return VELA_TLS_ERR_HANDSHAKE;
434	    }
435	
436	    /* Use blocking recv — no select()/poll().  The read
437	     * timeout is enforced by the SO_RCVTIMEO socket option set above. */
438	    mbedtls_ssl_set_bio(&ctx->ssl, &ctx->net,
439	        mbedtls_net_send, mbedtls_net_recv, NULL);
440	
441	    /* Handshake — bound both the per-recv timeout and the total elapsed time
442	     * so a half-open edge can't stall us for the full 120s read timeout
443	     * repeatedly.  Restore the long timeout afterwards for the response read. */
444	    struct timeval tv_hs = { .tv_sec = AGENT_TLS_HANDSHAKE_TIMEOUT_SEC,
445	        .tv_usec = 0 };
446	    struct timeval tv_full = { .tv_sec = AGENT_LLM_SOCKET_TIMEOUT_SEC,
447	        .tv_usec = 0 };
448	    if (ctx->net.fd >= 0) {
449	        setsockopt(ctx->net.fd, SOL_SOCKET, SO_RCVTIMEO, &tv_hs, sizeof(tv_hs));
450	    }
451	
452	    struct timespec hs0;
453	    clock_gettime(CLOCK_MONOTONIC, &hs0);
454	    while ((ret = mbedtls_ssl_handshake(&ctx->ssl)) != 0) {
455	        if (ret != MBEDTLS_ERR_SSL_WANT_READ && ret != MBEDTLS_ERR_SSL_WANT_WRITE) {
456	#if defined(MBEDTLS_ERROR_C)
457	            char err_buf[128];
458	            mbedtls_strerror(ret, err_buf, sizeof(err_buf));
459	            syslog(LOG_ERR, "[%s] ssl_handshake ret=-0x%04x: %s\n", TAG, -ret, err_buf);
460	#else
461	            syslog(LOG_ERR, "[%s] ssl_handshake ret=-0x%04x\n", TAG, -ret);
462	#endif
463	            /* Log if it was a fatal alert */
464	            if (ret == MBEDTLS_ERR_SSL_FATAL_ALERT_MESSAGE) {
465	                syslog(LOG_ERR, "[%s] Server sent fatal alert message\n", TAG);
466	            }
467	            return VELA_TLS_ERR_HANDSHAKE;
468	        }
469	
470	        struct timespec hs1;
471	        clock_gettime(CLOCK_MONOTONIC, &hs1);
472	        if (hs1.tv_sec - hs0.tv_sec >= AGENT_TLS_HANDSHAKE_TIMEOUT_SEC) {
473	            syslog(LOG_ERR, "[%s] ssl_handshake timed out (>%ds)\n",
474	                TAG, AGENT_TLS_HANDSHAKE_TIMEOUT_SEC);
475	            return VELA_TLS_ERR_HANDSHAKE;
476	        }
477	    }
478	
479	    if (ctx->net.fd >= 0) {
480	        setsockopt(ctx->net.fd, SOL_SOCKET, SO_RCVTIMEO, &tv_full, sizeof(tv_full));
481	    }
482	
483	    syslog(LOG_INFO, "[%s] Handshake OK: %s / %s\n", TAG, mbedtls_ssl_get_version(&ctx->ssl),
484	        mbedtls_ssl_get_ciphersuite(&ctx->ssl));
485	
486	    return 0;
487	}
