489	/* ── Connect with retry ──────────────────────────────────────── */
490	
491	/* The MiMo/OpenAI edge intermittently serves a leaf certificate whose public
492	 * key (Ed25519/Ed448) this mbedtls build cannot parse in TLS 1.2 — the same
493	 * host served a parseable RSA cert moments earlier, so the failure is
494	 * non-deterministic. A fresh TCP connect + handshake usually lands on a
495	 * different edge / cert, so retry a few times before giving up. */
496	#define TLS_CONNECT_MAX_ATTEMPTS 5
497	
498	static int tls_ctx_connect_retry(tls_ctx_t* ctx, const char* host,
499	    const char* port)
500	{
501	    int ret = VELA_TLS_ERR_HANDSHAKE;
502	
503	    for (int attempt = 0; attempt < TLS_CONNECT_MAX_ATTEMPTS; attempt++) {
504	        ret = tls_ctx_connect(ctx, host, port);
505	
506	        if (ret == 0) {
507	            return 0;
508	        }
509	
510	        /* Only transient failures (TLS handshake / TCP connect) warrant a
511	         * retry; anything else (config/entropy) is fatal. */
512	        if (ret != VELA_TLS_ERR_HANDSHAKE && ret != VELA_TLS_ERR_CONNECT) {
513	            return ret;
514	        }
515	
516	        if (attempt + 1 == TLS_CONNECT_MAX_ATTEMPTS) {
517	            break; /* last attempt — leave ctx for the caller to free */
518	        }
519	
520	        syslog(LOG_WARNING,
521	            "[%s] connect %s:%s attempt %d/%d failed (%d), retrying\n",
522	            TAG, host, port, attempt + 1, TLS_CONNECT_MAX_ATTEMPTS, ret);
523	
524	        tls_ctx_free(ctx);
525	        usleep(200 * 1000);
526	    }
527	
528	    return ret;
529	}
