531	/* ── HTTP/1.1 framing ────────────────────────────────────────── */
532	
533	static int tls_write_request(tls_ctx_t* ctx,
534	    const char* method, const char* host,
535	    const char* path,
536	    const vela_header_t* headers,
537	    const char* body, size_t body_len)
538	{
539	    /* Heap-allocate header buffer to reduce stack pressure.
540	     * This function is called from threads with limited stack
541	     * (outbound dispatch 16KB) and the TLS context already
542	     * consumes significant stack space. */
543	    char* hdr = malloc(4096);
544	    if (!hdr)
545	        return VELA_TLS_ERR_OVERFLOW;
546	
547	    int pos = 0;
548	    int ret;
549	
550	#define HDR_APPEND(fmt, ...)                                    \
551	    pos += snprintf(hdr + pos, 4096 - pos, fmt, ##__VA_ARGS__); \
552	    if (pos >= 4096) {                                          \
553	        free(hdr);                                              \
554	        return VELA_TLS_ERR_OVERFLOW;                           \
555	    }
556	
557	    HDR_APPEND("%s %s HTTP/1.1\r\n", method, path);
558	    HDR_APPEND("Host: %s\r\n", host);
559	    HDR_APPEND("Connection: keep-alive\r\n");
560	    HDR_APPEND("User-Agent: agent-vela/1.0\r\n");
561	
562	    if (body && body_len > 0) {
563	        HDR_APPEND("Content-Length: %zu\r\n", body_len);
564	    }
565	
566	    if (headers) {
567	        for (const vela_header_t* h = headers; h->name != NULL; h++) {
568	            HDR_APPEND("%s: %s\r\n", h->name, h->value);
569	        }
570	    }
571	
572	    HDR_APPEND("\r\n");
573	#undef HDR_APPEND
574	
575	    /* Write headers */
576	    int written = 0;
577	    while (written < pos) {
578	        ret = mbedtls_ssl_write(&ctx->ssl,
579	            (const unsigned char*)(hdr + written),
580	            (size_t)(pos - written));
581	        if (ret > 0) {
582	            written += ret;
583	        } else if (ret == 0) {
584	            free(hdr);
585	            return VELA_TLS_ERR_WRITE;
586	        } else if (ret != MBEDTLS_ERR_SSL_WANT_WRITE) {
587	            free(hdr);
588	            return VELA_TLS_ERR_WRITE;
589	        }
590	    }
591	
592	    free(hdr);
593	
594	    /* Write body */
595	    if (body && body_len > 0) {
596	        size_t bw = 0;
597	        while (bw < body_len) {
598	            ret = mbedtls_ssl_write(&ctx->ssl,
599	                (const unsigned char*)(body + bw),
600	                body_len - bw);
601	            if (ret > 0) {
602	                bw += (size_t)ret;
603	            } else if (ret == 0) {
604	                return VELA_TLS_ERR_WRITE;
605	            } else if (ret != MBEDTLS_ERR_SSL_WANT_WRITE) {
606	                return VELA_TLS_ERR_WRITE;
607	            }
608	        }
609	    }
610	
611	    return 0;
612	}
