1070	int vela_https_get(const char* host, const char* port, const char* path,
1071	    char* resp_buf, size_t resp_cap)
1072	{
1073	    return vela_https_request(host, port, "GET", path, NULL, NULL, 0,
1074	        resp_buf, resp_cap, NULL);
1075	}
