1077	int vela_https_post_json(const char* host, const char* port, const char* path,
1078	    const vela_header_t* extra_headers,
1079	    const char* json_body,
1080	    char* resp_buf, size_t resp_cap)
1081	{
1082	    /* Build a merged header list: Content-Type first, then caller extras */
1083	    const int MAX_HDRS = 32;
1084	    vela_header_t merged[MAX_HDRS];
1085	    int n = 0;
1086	
1087	    merged[n++] = (vela_header_t) { "Content-Type", "application/json" };
1088	
1089	    if (extra_headers) {
1090	        for (const vela_header_t* h = extra_headers; h->name && n < MAX_HDRS - 1; h++) {
1091	            merged[n++] = *h;
1092	        }
1093	    }
1094	    merged[n] = (vela_header_t) { NULL, NULL };
1095	
1096	    size_t body_len = json_body ? strlen(json_body) : 0;
1097	    return vela_https_request(host, port, "POST", path, merged,
1098	        json_body, body_len, resp_buf, resp_cap, NULL);
1099	}
