1101	int vela_https_post_json_stream(const char* host, const char* port,
1102	    const char* path, const vela_header_t* extra_headers,
1103	    const char* json_body, vela_stream_cb_t cb, void* ctx)
1104	{
1105	    const int MAX_HDRS = 32;
1106	    vela_header_t merged[MAX_HDRS];
1107	    int n = 0;
1108	
1109	    merged[n++] = (vela_header_t) { "Content-Type", "application/json" };
1110	
1111	    if (extra_headers) {
1112	        for (const vela_header_t* h = extra_headers; h->name && n < MAX_HDRS - 1; h++) {
1113	            merged[n++] = *h;
1114	        }
1115	    }
1116	    merged[n] = (vela_header_t) { NULL, NULL };
1117	
1118	    size_t body_len = json_body ? strlen(json_body) : 0;
1119	    tls_ctx_t tls;
1120	    int ret;
1121	
1122	    /* Always use a fresh connection: a streamed response stays open for the
1123	     * whole generation and is not compatible with pooled keep-alive reuse. */
1124	    if ((ret = tls_ctx_connect_retry(&tls, host, port)) != 0) {
1125	        tls_ctx_free(&tls);
1126	        return ret;
1127	    }
1128	
