200	 * mutex so the status byte and the text can't be torn apart mid-read (which
201	 * made a "final" status pair up with a stale short fragment). */
202	static char    g_pending_msg[MSG_BUF_LEN];
203	static bool    g_msg_ready = false;
204	static int     g_msg_status = 0;
205	static pthread_mutex_t g_msg_lock = PTHREAD_MUTEX_INITIALIZER;
206	
207	/* Streaming TTS state: a single worker thread speaks the whole reply in one
208	 * voice_channel_speak() call once the reply is complete. voice_channel_speak()
209	 * aborts any in-progress speak when called concurrently, so every speak must
210	 * go through this one thread. The pending slot is "latest wins" — a newer
211	 * fragment replaces an older one still waiting to be spoken. */
212	static pthread_mutex_t g_tts_lock = PTHREAD_MUTEX_INITIALIZER;
213	static pthread_cond_t  g_tts_cond  = PTHREAD_COND_INITIALIZER;
214	static char     g_tts_pending[MSG_BUF_LEN];
215	static bool     g_tts_pending_ready = false;
216	static bool     g_tts_pending_final = false;
217	static size_t   g_spoken_len = 0;      /* bytes already spoken this response */
218	static unsigned int g_tts_epoch = 0;   /* bumped each new question */
219	
220	/* Wake-word listening state. g_reply_busy is set when an interaction (an LLM
221	 * request + TTS reply, or a standalone spoken prompt) is in flight and the
222	 * wake loop must not open the mic; the TTS worker clears it once the final
223	 * reply finishes playing. A simple volatile flag is enough here — races only
224	 * shift the listen window by one ~20 ms chunk. */
225	static volatile int g_reply_busy = 0;
226	
227	/* Set to 1 while the wake loop has the capture mic open (listen_one_utterance
228	 * holds the codec's only DMA channel the whole time it is listening). An async
229	 * reminder (kid_notify_cb) must wait for this to clear before its TTS playback
230	 * can acquire the DMA channel, otherwise the reminder shows text but is silent. */
231	static volatile int g_mic_open = 0;
232	
233	/* Monotonic ms at which the last reply finished playing (set by the TTS worker
234	 * when it clears g_reply_busy). Drives the follow-up answer window: while
235	 * now_ms() - g_last_reply_ms < FOLLOW_UP_MS the kid may answer without the
236	 * wake word. 0 means "no reply yet", so no follow-up at boot. */
237	static volatile int64_t g_last_reply_ms = 0;
238	
239	/* Monotonic ms until which the wake loop backs off after an ASR hard failure
240	 * (ret<0: HTTP 429 rate-limit / network error). See ASR_BACKOFF_MS. */
241	static volatile int64_t g_asr_backoff_until = 0;
242	
243	/* Voice-command handoff: the wake thread writes the recognized command (wake
244	 * word already stripped) under g_wake_cmd_lock, and the LVGL timer thread
245	 * reads it and calls send_to_llm() — LVGL objects must only be touched from
246	 * the LVGL thread, so the wake thread never calls send_to_llm() directly. */
247	static char     g_wake_cmd[MSG_BUF_LEN];
248	static bool     g_wake_cmd_ready = false;
249	static pthread_mutex_t g_wake_cmd_lock = PTHREAD_MUTEX_INITIALIZER;
