261	 * LLM Callback (called from ai_agent thread, NOT LVGL thread)
262	 ****************************************************************************/
263	
264	static void llm_response_cb(int status, const char *response, void *cookie)
265	{
266	    (void)cookie;
267	
268	    pthread_mutex_lock(&g_msg_lock);
269	
270	    g_msg_status = status;
271	    if ((status == 0 || status == 1) && response != NULL)
272	      {
273	        /* status 0 = final reply, status 1 = streaming fragment (cumulative
274	         * text so far). Both carry the running reply text. */
275	        strncpy(g_pending_msg, response, MSG_BUF_LEN - 1);
276	        g_pending_msg[MSG_BUF_LEN - 1] = '\0';
277	      }
278	    else
279	      {
280	        snprintf(g_pending_msg, MSG_BUF_LEN, "[LLM error: %d]", status);
281	      }
282	    g_msg_ready = true;
283	
284	    syslog(LOG_INFO, "[kid_buddy] llm_cb status=%d len=%d\n",
285	           status, (int)strlen(g_pending_msg));
286	
287	    pthread_mutex_unlock(&g_msg_lock);
288	}
289	
290	/* Notify callback for UNSOLICITED outbound messages (e.g. cron-fired
291	 * reminders) delivered while no velaclaw_ask is in flight. Route into the
292	 * same g_pending_msg / g_msg_ready slot that llm_response_cb uses, so the
293	 * existing poll_timer_cb path (emoji/markdown strip → LCD → TTS) speaks and
294	 * displays the reminder with zero new UI code. Partial fragments (status 1)
295	 * are ignored — cron reminders arrive as a single complete message. */
296	static void kid_notify_cb(int status, const char *msg, void *cookie)
297	{
298	    (void)cookie;
299	
300	    if (msg == NULL || status == 1)
301	      {
302	        return;
303	      }
304	
305	    /* A reminder needs to speak, but the wake loop may be holding the capture
306	     * mic (and the codec's shared DMA channel) right now. Raise g_reply_busy so
307	     * the wake loop aborts its listen and releases the mic; the TTS worker then
308	     * waits for g_mic_open to clear before it opens playback. */
309	    g_reply_busy = 1;
310	
311	    /* A reminder is an independent, complete message — not a streaming fragment
312	     * of an in-flight LLM reply. Reset the streaming TTS offset so the TTS
313	     * worker speaks it from the beginning; otherwise, if the previous reply was
314	     * longer, len <= spoken and the reminder is silently skipped (text on LCD
315	     * but no voice). */
316	    pthread_mutex_lock(&g_tts_lock);
317	    g_tts_epoch++;
318	    g_spoken_len = 0;
319	    g_tts_pending_ready = false;
320	    g_tts_pending_final = false;
321	    pthread_mutex_unlock(&g_tts_lock);
322	
323	    pthread_mutex_lock(&g_msg_lock);
324	    g_msg_status = 0;
325	    strncpy(g_pending_msg, msg, MSG_BUF_LEN - 1);
326	    g_pending_msg[MSG_BUF_LEN - 1] = '\0';
327	    g_msg_ready = true;
328	    pthread_mutex_unlock(&g_msg_lock);
329	
330	    syslog(LOG_INFO, "[kid_buddy] notify_cb len=%d\n", (int)strlen(msg));
331	}
