435	    g_tts_pending_ready = false;
436	    g_tts_pending_final = false;
437	    pthread_mutex_unlock(&g_tts_lock);
438	
439	    lv_label_set_text(g_chat_status, "Thinking...");
440	    if (g_chat_spinner)
441	      {
442	        lv_obj_clear_flag(g_chat_spinner, LV_OBJ_FLAG_HIDDEN);
443	      }
444	
445	    int ret = velaclaw_ask(g_agent_client, &req, llm_response_cb, NULL);
446	    if (ret < 0)
447	      {
448	        lv_label_set_text(g_chat_status, "Failed to send message");
449	        if (g_chat_spinner)
450	          {
451	            lv_obj_add_flag(g_chat_spinner, LV_OBJ_FLAG_HIDDEN);
452	          }
453	        g_reply_busy = 0;  /* request failed, release the wake loop */
454	      }
455	}
