505	/* ── Streaming TTS worker ─────────────────────────────────────
506	 * Speak a response aloud in a background thread so the LVGL UI stays
507	 * responsive while TTS synthesizes and plays. A single worker thread
508	 * serializes every speak (voice_channel_speak aborts any in-progress speak
509	 * on a concurrent call). The worker does NOT speak partial fragments as they
510	 * stream: it waits for the final fragment and speaks the whole reply in one
511	 * voice_channel_speak() call. This keeps a single ALSA open/close cycle and
512	 * lets voice_channel_speak() buffer the full reply for continuous playback. */
513	
514	static void *tts_stream_worker(void *arg)
515	{
516	    (void)arg;
517	
518	    for (;;)
519	      {
520	        char text[MSG_BUF_LEN];
521	        bool final = false;
522	        unsigned int epoch;
523	        size_t spoken;
524	
525	        pthread_mutex_lock(&g_tts_lock);
526	        while (!g_tts_pending_ready)
527	          {
528	            pthread_cond_wait(&g_tts_cond, &g_tts_lock);
529	          }
530	        strncpy(text, g_tts_pending, MSG_BUF_LEN - 1);
531	        text[MSG_BUF_LEN - 1] = '\0';
532	        final = g_tts_pending_final;
533	        epoch = g_tts_epoch;
534	        spoken = g_spoken_len;
535	        g_tts_pending_ready = false;
536	        g_tts_pending_final = false;
537	        pthread_mutex_unlock(&g_tts_lock);
538	
539	        size_t len = strlen(text);
540	
541	        if (spoken > len)
542	          {
543	            spoken = len; /* offset reset under us mid-speak */
544	          }
545	
546	        /* Speak the whole reply in one voice_channel_speak() call, and only
547	         * once the reply is complete (final). Speaking sentence-by-sentence
548	         * as the text streamed made the worker open/close the ALSA codec
549	         * once per fragment; the codec's external-speaker PA (gpio_spk) is
550	         * armed on the first open but not reliably re-armed on a later open
551	         * in the same response, so only the first sentence was audible. A
552	         * single open/prepare/write/close cycle is the sequence the codec
553	         * plays reliably, and voice_channel_speak() already buffers the full
554	         * reply (fetch-then-play) so the story reads continuously. We trade
555	         * a later first word for complete, continuous speech — the priority
556	         * for a child's toy. */
557	        if (!final)
558	          {
559	            continue;
560	          }
561	
562	        syslog(LOG_INFO,
563	               "[kid_buddy] tts_worker final=1 len=%d speak_whole\n",
564	               (int)len);
565	
566	        if (len > spoken)
567	          {
568	            g_reply_busy = 1;
569	            /* A reminder can arrive while the wake loop still holds the mic
570	             * (and the codec's shared DMA channel). Wait for it to release the
571	             * mic before opening playback, else the reminder is silent. */
572	            for (int i = 0; i < 100 && g_mic_open; i++)
573	              {
574	                usleep(10 * 1000);  /* 10 ms */
575	              }
576	            voice_channel_speak(text);
577	            g_reply_busy = 0;   /* final reply spoken, wake loop may listen */
578	            g_last_reply_ms = now_ms();  /* arm the follow-up answer window */
579	
580	            pthread_mutex_lock(&g_tts_lock);
581	            /* Advance only if no newer question reset the offset mid-speak. */
582	            if (epoch == g_tts_epoch)
583	              {
584	                g_spoken_len = len;
585	              }
586	            pthread_mutex_unlock(&g_tts_lock);
587	          }
588	      }
589	
590	    return NULL;
591	}
592	
593	/* Enqueue the latest cumulative reply text for speaking. "latest wins" — a
594	 * newer fragment replaces an older one still waiting in the slot. */
595	static void enqueue_tts(const char *text, bool final)
596	{
597	    pthread_mutex_lock(&g_tts_lock);
598	    strncpy(g_tts_pending, text, MSG_BUF_LEN - 1);
599	    g_tts_pending[MSG_BUF_LEN - 1] = '\0';

745	
746	/* Listen for a single utterance and return its ASR text (heap-allocated).
747	 * Returns NULL if nothing was heard or ASR failed; caller free()s the result.
748	 * The mic is opened fresh each call so it is only live while we are actually
749	 * waiting for speech (never during TTS playback).
750	 *
751	 * timeout_ms > 0 bounds the listen: if the kid hasn't started speaking within
752	 * timeout_ms (used for the follow-up answer window), give up and return NULL.
753	 * timeout_ms == 0 waits indefinitely for speech (normal wake-word listening). */
754	static char *listen_one_utterance(int timeout_ms)
755	{
756	    /* Never open the mic while a reply is playing: capture and playback share
757	     * the codec's DMA engine, and opening the mic holds a DMA channel that the
758	     * TTS playback then fails to acquire ("request dma chan failed").  Check
759	     * BEFORE opening — not just inside the read loop — so the mic is not even
760	     * opened (and no DMA channel is grabbed) during a reply. */
761	    if (g_reply_busy)
762	      {
763	        return NULL;
764	      }
765	
766	    audio_capture_t *cap = audio_capture_open(NULL, WAKE_SAMPLE_RATE, 1, 16);
767	    if (!cap) {
768	        syslog(LOG_ERR, "[kid_buddy] wake: capture open failed\n");
769	        return NULL;
770	    }
771	
772	    if (audio_capture_start(cap) < 0) {
773	        syslog(LOG_ERR, "[kid_buddy] wake: capture start failed\n");
774	        audio_capture_close(cap);
775	        return NULL;
776	    }
777	    g_mic_open = 1;
778	
779	    unsigned char *pcm = malloc(WAKE_MAX_BYTES);
780	    if (!pcm) {
781	        g_mic_open = 0;
782	        audio_capture_close(cap);
783	        return NULL;
784	    }
785	
786	    size_t pcm_len = 0;
787	    bool started = false;
788	    int silence_run = 0;
789	    int64_t deadline = (timeout_ms > 0) ? (now_ms() + timeout_ms) : 0;
790	
791	    syslog(LOG_INFO, "[kid_buddy] wake: listening...\n");
792	
793	    while (pcm_len < WAKE_MAX_BYTES) {
794	        /* A touch-triggered interaction may have started while we listened. */
795	        if (g_reply_busy) {
796	            syslog(LOG_INFO, "[kid_buddy] wake: reply busy, abort listen\n");
797	            break;
798	        }
799	
800	        /* Follow-up window closed: if speech hasn't started yet, stop waiting. */
801	        if (!started && deadline > 0 && now_ms() >= deadline) {
802	            syslog(LOG_INFO, "[kid_buddy] wake: follow-up timeout\n");
803	            break;
804	        }
805	
806	        int16_t chunk[WAKE_CHUNK_BYTES / 2];
807	        int n = audio_capture_read(cap, chunk, sizeof(chunk));
808	        if (n <= 0) {
809	            if (n < 0) {
810	                syslog(LOG_WARNING, "[kid_buddy] wake: read=%d\n", n);
811	                break;
812	            }
813	            continue;  /* EAGAIN / zero-length */
814	        }
815	
816	        int nsamp = n / (int)sizeof(int16_t);
817	        int64_t sum = 0;
818	        for (int i = 0; i < nsamp; i++) {
819	            int32_t v = chunk[i];
820	            sum += (int64_t)v * v;
821	        }
822	        int64_t ms = nsamp > 0 ? sum / nsamp : 0;
823	
824	        if (!started && ms >= WAKE_START_MSQ) {
825	            started = true;
826	            silence_run = 0;
827	            syslog(LOG_INFO, "[kid_buddy] wake: speech start (msq=%lld)\n",
828	                   (long long)ms);
829	        }
830	
831	        if (started) {
832	            if (pcm_len + (size_t)n <= WAKE_MAX_BYTES) {
833	                memcpy(pcm + pcm_len, chunk, n);
834	                pcm_len += n;
835	            }
836	
837	            if (ms < WAKE_END_MSQ) {
838	                if (++silence_run >= WAKE_SILENCE_CHUNKS) {
839	                    syslog(LOG_INFO, "[kid_buddy] wake: speech end (%zu bytes)\n",
840	                           pcm_len);
841	                    break;
842	                }
843	            } else {
844	                silence_run = 0;
845	            }
846	        }
847	    }
848	
849	    audio_capture_abort(cap);
850	    audio_capture_close(cap);
851	    g_mic_open = 0;
852	
853	    if (!started || pcm_len < WAKE_CHUNK_BYTES) {
854	        syslog(LOG_INFO, "[kid_buddy] wake: no speech (%zu bytes)\n", pcm_len);
855	        free(pcm);
856	        return NULL;
857	    }
858	
859	    char text[MSG_BUF_LEN];
860	    int ret = voice_asr_recognize(pcm, pcm_len, text, sizeof(text));
861	    free(pcm);
862	
863	    if (ret < 0 || text[0] == '\0') {
864	        syslog(LOG_WARNING, "[kid_buddy] wake: ASR failed/empty (ret=%d)\n",
865	               ret);
866	        /* A hard ASR error (HTTP 429 rate-limit, network) means retrying
867	         * immediately just re-fails and hammers MiMo. Back off so the wake
868	         * loop pauses before its next listen. */
869	        if (ret < 0) {
870	            g_asr_backoff_until = now_ms() + ASR_BACKOFF_MS;
871	        }
872	        return NULL;
873	    }
874	
875	    return strdup(text);
876	}
877	
878	/* Speak a standalone prompt (e.g. "我在呢") through the TTS worker so it is
879	 * serialized with reply speech, and mark the reply busy so the wake loop
880	 * stays quiet while the prompt plays. */
881	static void wake_speak_prompt(const char *text)
882	{
883	    pthread_mutex_lock(&g_tts_lock);
884	    g_tts_epoch++;
885	    g_spoken_len = 0;
886	    g_tts_pending_ready = false;
887	    g_tts_pending_final = false;
888	    pthread_mutex_unlock(&g_tts_lock);
889	
890	    g_reply_busy = 1;
891	    enqueue_tts(text, true);
892	}
893	
894	static void *wake_listen_worker(void *arg)
895	{
896	    (void)arg;
897	
898	    /* Settle briefly so ai_agent finishes registering the ASR backends. */
899	    usleep(2 * 1000 * 1000);
900	
901	    for (;;) {
902	        /* Wait for any in-flight reply to finish, then a short cooldown so
903	         * the tail of the TTS doesn't bleed into the mic. */
904	        while (g_reply_busy) {
905	            usleep(100 * 1000);
906	        }
907	        usleep(300 * 1000);
908	
909	        /* Back off after a recent ASR rate-limit/network failure rather than
910	         * immediately re-listening and re-failing on the same endpoint. */
911	        while (g_asr_backoff_until && now_ms() < g_asr_backoff_until) {
912	            usleep(200 * 1000);
913	        }
914	
915	        /* Follow-up window: for a short while after the buddy finishes a
916	         * reply, accept the kid's next utterance as a command even without
917	         * the wake word (so they can pick a story option by just answering,
918	         * not by re-saying "小伙伴"). */
919	        int64_t elapsed = now_ms() - g_last_reply_ms;
920	        bool follow_up = (g_last_reply_ms != 0 && elapsed < FOLLOW_UP_MS);
921	        int timeout_ms = follow_up ? (int)(FOLLOW_UP_MS - elapsed) : 0;
922	
923	        char *asr_text = listen_one_utterance(timeout_ms);
924	        if (!asr_text) {
925	            continue;
926	        }
927	
928	        syslog(LOG_INFO, "[kid_buddy] wake: heard \"%s\"%s\n", asr_text,
929	               follow_up ? " (follow-up)" : "");
930	
931	        bool has_wake = (strstr(asr_text, WAKE_WORD) != NULL);
932	        char command[MSG_BUF_LEN];
933	        size_t clen = strip_wake_word(asr_text, command, sizeof(command));
934	        free(asr_text);
935	
936	        if (!has_wake && !follow_up) {
937	            syslog(LOG_INFO, "[kid_buddy] wake: not the wake word, ignore\n");
938	            continue;
939	        }
940	
941	        if (clen == 0) {
942	            if (has_wake) {
943	                /* Wake word only — acknowledge and keep listening. */
944	                syslog(LOG_INFO, "[kid_buddy] wake: wake word only, prompt\n");
945	                wake_speak_prompt(WAKE_IDLE_PROMPT);
946	            } else {
947	                syslog(LOG_INFO, "[kid_buddy] wake: empty follow-up, ignore\n");
948	            }
949	            continue;
950	        }
951	
952	        /* A bare "嗯/啊/哦" is not a command — the kid murmuring or the mic
953	         * catching the TTS tail, not an answer. Sending it to the LLM makes
954	         * the buddy answer itself and repeat the story in a loop. */
955	        if (is_filler_utterance(command)) {
956	            syslog(LOG_INFO, "[kid_buddy] wake: filler \"%s\" ignored\n",
957	                   command);
958	            continue;
959	        }
960	
961	        /* Hand the command to the LVGL thread (which calls send_to_llm).
962	         * Mark busy NOW (before this loop iterates) so the wake loop re-enters
963	         * the g_reply_busy wait and does NOT re-open the mic — and steal the
964	         * codec DMA channel — before the LVGL timer calls send_to_llm().
965	         * send_to_llm() sets it again (idempotent) and the TTS worker clears
966	         * it after the reply is spoken. */
967	        g_reply_busy = 1;
968	        pthread_mutex_lock(&g_wake_cmd_lock);
969	        strncpy(g_wake_cmd, command, MSG_BUF_LEN - 1);
970	        g_wake_cmd[MSG_BUF_LEN - 1] = '\0';
971	        g_wake_cmd_ready = true;
972	        pthread_mutex_unlock(&g_wake_cmd_lock);
973	
974	        syslog(LOG_INFO, "[kid_buddy] wake: command \"%s\"\n", command);
975	    }
976	
977	    return NULL;
978	}
