85	velaclaw_client_t* velaclaw_client_open(const char* name)
86	{
87	    if (g_client_instance) {
88	        return g_client_instance;
89	    }
90	
91	    /* Check if message_bus is alive by trying a dummy operation */
92	    agent_msg_t probe = { 0 };
93	    strncpy(probe.channel, "__probe__", sizeof(probe.channel) - 1);
94	
95	    /* We can't easily probe, so just assume agent is running if
96	     * mbus_tap_register succeeds (it uses the same global state) */
97	
98	    struct velaclaw_client_s* c = calloc(1, sizeof(*c));
99	    if (!c) {
100	        return NULL;
101	    }
102	
103	    strncpy(c->app_id, name ? name : "app", sizeof(c->app_id) - 1);
104	    pthread_mutex_init(&c->mtx, NULL);
105	    sem_init(&c->reply_sem, 0, 0);
106	    c->reply_text = NULL;
107	    c->reply_status = 0;
108	
109	    if (mbus_tap_register(CLIENT_CHANNEL, tap_callback, c) != OK) {
110	        syslog(LOG_ERR, "[%s] tap register failed (agent not running?)\n", TAG);
111	        sem_destroy(&c->reply_sem);
112	        pthread_mutex_destroy(&c->mtx);
113	        free(c);
114	        return NULL;
115	    }
116	
117	    g_client_instance = c;
118	    syslog(LOG_INFO, "[%s] client opened: %s\n", TAG, c->app_id);
119	    return c;
120	}
