122	void velaclaw_client_close(velaclaw_client_t* c)
123	{
124	    if (!c) {
125	        return;
126	    }
127	
128	    mbus_tap_unregister(CLIENT_CHANNEL);
129	
130	    pthread_mutex_destroy(&c->mtx);
131	    sem_destroy(&c->reply_sem);
132	    free(c->reply_text);
133	    c->reply_text = NULL;
134	
135	    if (g_client_instance == c) {
136	        g_client_instance = NULL;
137	    }
138	
139	    free(c);
140	    syslog(LOG_INFO, "[%s] client closed\n", TAG);
141	}
