156	int velaclaw_ask(velaclaw_client_t* c,
157	    const velaclaw_ask_req_t* req,
158	    void (*cb)(int, const char*, void*), void* cookie)
159	{
160	    if (!c || !req || !req->text) {
161	        return -EINVAL;
162	    }
163	
164	    /* Set up async callback */
165	    pthread_mutex_lock(&c->mtx);
166	    c->async_cb = cb;
167	    c->async_cookie = cookie;
168	    pthread_mutex_unlock(&c->mtx);
169	
170	    /* Push message to agent inbound queue */
171	    agent_msg_t msg = { 0 };
172	    strncpy(msg.channel, CLIENT_CHANNEL, sizeof(msg.channel) - 1);
173	    strncpy(msg.chat_id, c->app_id, sizeof(msg.chat_id) - 1);
174	    msg.content = strdup(req->text);
175	    if (!msg.content) {
176	        return -ENOMEM;
177	    }
178	
179	    int ret = message_bus_push_inbound(&msg);
180	    if (ret != OK) {
181	        free(msg.content);
182	        pthread_mutex_lock(&c->mtx);
183	        c->async_cb = NULL;
184	        c->async_cookie = NULL;
185	        pthread_mutex_unlock(&c->mtx);
186	        return -EIO;
187	    }
188	
189	    return 0;
190	}
