int velaclaw_publish(velaclaw_client_t* c, const char* channel, const char* chat_id, const char* text)
{
    (void)c;
    if (!channel || !chat_id || !text) {
        return -EINVAL;
    }
    agent_msg_t msg = { 0 };
    strncpy(msg.channel, channel, sizeof(msg.channel) - 1);
    strncpy(msg.chat_id, chat_id, sizeof(msg.chat_id) - 1);
    msg.content = strdup(text);
    if (!msg.content) {
        return -ENOMEM;
    }
    int ret = message_bus_push_outbound(&msg);
    if (ret != OK) {
        free(msg.content);
        return -EIO;
    }
    return 0;
}
```

