301	/* Notify callback for UNSOLICITED outbound messages (e.g. cron-fired
302	 * reminders) delivered while no velaclaw_ask is in flight. Route into the
303	 * same g_pending_msg / g_msg_ready slot that llm_response_cb uses, so the
304	 * existing poll_timer_cb path (emoji/markdown strip → LCD → TTS) speaks and
305	 * displays the reminder with zero new UI code. Partial fragments (status 1)
306	 * are ignored — cron reminders arrive as a single complete message. */
307	static void kid_notify_cb(int status, const char *msg, void *cookie)
308	{
309	    (void)cookie;
310	
311	    if (msg == NULL || status == 1)
312	      {
313	        return;
314	      }
315	
316	    /* A cron reminder may carry a [KID_REPORT:<channel>|<chat_id>] prefix
317	     * asking for a child-confirmation report. Strip it, remember the report
318	     * destination, and speak only the reminder text itself. */
319	    const char *text = msg;
320	    if (strncmp(msg, "[KID_REPORT:", 12) == 0)
321	      {
322	        const char *end = strchr(msg, ']');
323	        const char *sep = strchr(msg + 12, '|');
324	        if (end && sep && sep < end)
325	          {
326	            size_t clen = (size_t)(sep - (msg + 12));
327	            size_t cidlen = (size_t)(end - (sep + 1));
328	            if (clen < sizeof(g_report_channel)
329	                && cidlen < sizeof(g_report_chat_id))
330	              {
331	                pthread_mutex_lock(&g_msg_lock);
332	                memcpy(g_report_channel, msg + 12, clen);
333	                g_report_channel[clen] = '\0';
334	                memcpy(g_report_chat_id, sep + 1, cidlen);
335	                g_report_chat_id[cidlen] = '\0';
336	                pthread_mutex_unlock(&g_msg_lock);
337	
338	                text = end + 1;
339	                if (*text == '\n')
340	                  {
341	                    text++;
342	                  }
343	                g_report_pending = 1;
344	              }
345	          }
346	      }
347	
348	    /* A reminder needs to speak, but the wake loop may be holding the capture
349	     * mic (and the codec's shared DMA channel) right now. Raise g_reply_busy so
350	     * the wake loop aborts its listen and releases the mic; the TTS worker then
351	     * waits for g_mic_open to clear before it opens playback. */
352	    g_reply_busy = 1;
353	
354	    /* A reminder is an independent, complete message — not a streaming fragment
