116	             + strlen(job->message) + 1;
117	    char* out = malloc(n);
118	
119	    if (!out) {
120	        return NULL;
121	    }
122	
123	    snprintf(out, n, "%s%s|%s]\n%s",
124	        KID_REPORT_TAG, job->report_channel, job->report_chat_id, job->message);
125	    return out;
