                .tv_usec = 0 };
            setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &ctv, sizeof(ctv));

            if (connect(fd, cur->ai_addr, cur->ai_addrlen) != 0) {
                close(fd);
