314	/* Run the TLS handshake, bounding total elapsed time to
315	 * AGENT_TLS_HANDSHAKE_TIMEOUT_SEC.  Returns 0 on success, otherwise
316	 * VELA_TLS_ERR_HANDSHAKE. */
317	static int tls_do_handshake(tls_ctx_t* ctx)
318	{
319	    int ret;
320	    struct timespec hs0;
321	    clock_gettime(CLOCK_MONOTONIC, &hs0);
322	
323	    while ((ret = mbedtls_ssl_handshake(&ctx->ssl)) != 0) {
324	        if (ret != MBEDTLS_ERR_SSL_WANT_READ && ret != MBEDTLS_ERR_SSL_WANT_WRITE) {
325	#if defined(MBEDTLS_ERROR_C)
326	            char err_buf[128];
327	            mbedtls_strerror(ret, err_buf, sizeof(err_buf));
328	            syslog(LOG_ERR, "[%s] ssl_handshake ret=-0x%04x: %s\n", TAG, -ret, err_buf);
329	#else
330	            syslog(LOG_ERR, "[%s] ssl_handshake ret=-0x%04x\n", TAG, -ret);
331	#endif
332	            if (ret == MBEDTLS_ERR_SSL_FATAL_ALERT_MESSAGE) {
333	                syslog(LOG_ERR, "[%s] Server sent fatal alert message\n", TAG);
334	            }
335	            return VELA_TLS_ERR_HANDSHAKE;
336	        }
337	
338	        struct timespec hs1;
339	        clock_gettime(CLOCK_MONOTONIC, &hs1);
340	        if (hs1.tv_sec - hs0.tv_sec >= AGENT_TLS_HANDSHAKE_TIMEOUT_SEC) {
341	            syslog(LOG_ERR, "[%s] ssl_handshake timed out (>%ds)\n",
342	                TAG, AGENT_TLS_HANDSHAKE_TIMEOUT_SEC);
343	            return VELA_TLS_ERR_HANDSHAKE;
344	        }
345	    }
346	
347	    return 0;
348	}
