20	#define TAG "velaclaw_client"
21	#define CLIENT_CHANNEL "local_client"
22	
23	struct velaclaw_client_s {
24	    char app_id[32];
25	    pthread_mutex_t mtx;
26	    sem_t reply_sem;
27	    char* reply_text;
28	    int reply_status;
29	    void (*async_cb)(int, const char*, void*);
30	    void* async_cookie;
31	    void (*notify_cb)(int, const char*, void*);
32	    void* notify_cookie;
33	};
34	
35	static struct velaclaw_client_s* g_client_instance;
36	
37	static void tap_callback(const agent_msg_t* msg, void* cookie)
38	{
39	    struct velaclaw_client_s* c = (struct velaclaw_client_s*)cookie;
40	    if (!c) {
41	        return;
42	    }
43	
44	    pthread_mutex_lock(&c->mtx);
45	
46	    if (c->async_cb) {
47	        /* Async mode: invoke user callback directly.
48	         * Streaming replies arrive as a series of partial fragments
49	         * (status 1) followed by one final fragment (status 0). Keep the
50	         * callback registered across partial fragments so the whole stream
51	         * reaches the caller; clear it only on the final fragment. */
52	        void (*cb)(int, const char*, void*) = c->async_cb;
53	        void* ck = c->async_cookie;
54	        int status = msg->partial ? 1 : 0;
55	        if (!msg->partial) {
56	            c->async_cb = NULL;
57	            c->async_cookie = NULL;
58	        }
59	        pthread_mutex_unlock(&c->mtx);
60	
61	        cb(status, msg->content, ck);
62	        return;
63	    }
64	
65	    /* No ask in flight — route to the persistent notify callback (e.g. cron
66	     * reminders), mirroring async semantics but keeping notify_cb registered. */
67	    if (c->notify_cb) {
68	        void (*cb)(int, const char*, void*) = c->notify_cb;
69	        void* ck = c->notify_cookie;
70	        int status = msg->partial ? 1 : 0;
71	        pthread_mutex_unlock(&c->mtx);
72	        cb(status, msg->content, ck);
73	        return;
74	    }
75	
76	    /* Sync mode: store reply and signal */
77	    free(c->reply_text);
78	    c->reply_text = msg->content ? strdup(msg->content) : NULL;
79	    c->reply_status = 0;
80	    pthread_mutex_unlock(&c->mtx);
81	
82	    sem_post(&c->reply_sem);
83	}
84	
85	velaclaw_client_t* velaclaw_client_open(const char* name)
86	{
87	    if (g_client_instance) {
88	        return g_client_instance;
89	    }
90	
91	    /* Check if message_bus is alive by trying a dummy operation */
92	    agent_msg_t probe = { 0 };
93	    strncpy(probe.channel, "__probe__", sizeof(probe.channel) - 1);
94	
95	    /* We can't easily probe, so just assume agent is running if
96	     * mbus_tap_register succeeds (it uses the same global state) */
97	
98	    struct velaclaw_client_s* c = calloc(1, sizeof(*c));
99	    if (!c) {
100	        return NULL;
101	    }
102	
103	    strncpy(c->app_id, name ? name : "app", sizeof(c->app_id) - 1);
104	    pthread_mutex_init(&c->mtx, NULL);
105	    sem_init(&c->reply_sem, 0, 0);
106	    c->reply_text = NULL;
107	    c->reply_status = 0;
108	
109	    if (mbus_tap_register(CLIENT_CHANNEL, tap_callback, c) != OK) {
110	        syslog(LOG_ERR, "[%s] tap register failed (agent not running?)\n", TAG);
111	        sem_destroy(&c->reply_sem);
112	        pthread_mutex_destroy(&c->mtx);
113	        free(c);
114	        return NULL;
115	    }
116	
117	    g_client_instance = c;
118	    syslog(LOG_INFO, "[%s] client opened: %s\n", TAG, c->app_id);
119	    return c;
120	}
121	
122	void velaclaw_client_close(velaclaw_client_t* c)
123	{
124	    if (!c) {
125	        return;
126	    }
127	
128	    mbus_tap_unregister(CLIENT_CHANNEL);
129	
130	    pthread_mutex_destroy(&c->mtx);
131	    sem_destroy(&c->reply_sem);
132	    free(c->reply_text);
133	    c->reply_text = NULL;
134	
135	    if (g_client_instance == c) {
136	        g_client_instance = NULL;
137	    }
138	
139	    free(c);
140	    syslog(LOG_INFO, "[%s] client closed\n", TAG);
141	}
