143	void velaclaw_set_notify_callback(velaclaw_client_t* c,
144	    void (*cb)(int, const char*, void*), void* cookie)
145	{
146	    if (!c) {
147	        return;
148	    }
149	
150	    pthread_mutex_lock(&c->mtx);
151	    c->notify_cb = cb;
152	    c->notify_cookie = cookie;
153	    pthread_mutex_unlock(&c->mtx);
154	}
