156	int velaclaw_publish(velaclaw_client_t* c,
157	    const char* channel, const char* chat_id, const char* text)
158	{
159	    (void)c; /* the bus is a shared singleton — no per-client state needed */
160	
161	    if (!channel || !chat_id || !text) {
162	        return -EINVAL;
163	    }
164	
165	    agent_msg_t msg = { 0 };
166	    strncpy(msg.channel, channel, sizeof(msg.channel) - 1);
167	    strncpy(msg.chat_id, chat_id, sizeof(msg.chat_id) - 1);
168	    msg.content = strdup(text);
169	
170	    if (!msg.content) {
171	        return -ENOMEM;
172	    }
173	
174	    int ret = message_bus_push_outbound(&msg);
175	
176	    if (ret != OK) {
177	        free(msg.content);
178	        return -EIO;
179	    }
180	
181	    syslog(LOG_INFO, "[%s] publish to %s:%s (%zu bytes)\n",
182	        TAG, channel, chat_id, strlen(text));
183	    return 0;
184	}
