186	int velaclaw_ask(velaclaw_client_t* c,
187	    const velaclaw_ask_req_t* req,
188	    void (*cb)(int, const char*, void*), void* cookie)
189	{
190	    if (!c || !req || !req->text) {
191	        return -EINVAL;
192	    }
193	
194	    /* Set up async callback */
195	    pthread_mutex_lock(&c->mtx);
196	    c->async_cb = cb;
197	    c->async_cookie = cookie;
198	    pthread_mutex_unlock(&c->mtx);
199	
200	    /* Push message to agent inbound queue */
201	    agent_msg_t msg = { 0 };
202	    strncpy(msg.channel, CLIENT_CHANNEL, sizeof(msg.channel) - 1);
203	    strncpy(msg.chat_id, c->app_id, sizeof(msg.chat_id) - 1);
204	    msg.content = strdup(req->text);
205	    if (!msg.content) {
206	        return -ENOMEM;
207	    }
208	
209	    int ret = message_bus_push_inbound(&msg);
210	    if (ret != OK) {
211	        free(msg.content);
212	        pthread_mutex_lock(&c->mtx);
213	        c->async_cb = NULL;
214	        c->async_cookie = NULL;
215	        pthread_mutex_unlock(&c->mtx);
216	        return -EIO;
217	    }
218	
219	    return 0;
220	}
