483	        /* Use timedwait instead of usleep so that cron_nudge() can
484	         * wake us immediately when a new job is added.  This also
485	         * survives NuttX deep-sleep better than plain usleep. */
486	        struct timespec ts;
487	        clock_gettime(CLOCK_REALTIME, &ts);
488	        ts.tv_sec += AGENT_CRON_CHECK_INTERVAL_MS / 1000;
489	
490	        pthread_mutex_lock(&s_cron_lock);
491	        pthread_cond_timedwait(&s_cron_wake, &s_cron_lock, &ts);
492	        pthread_mutex_unlock(&s_cron_lock);
493	
494	        cron_process_due_jobs();
495	    }
496	
