327	ssize_t mqtt_pal_recvall(mqtt_pal_socket_handle fd, void* buf, size_t bufsz, int flags) {
328	    const void *const start = buf;
329	    ssize_t rv;
330	    do {
331	        rv = recv(fd, buf, bufsz, flags);
332	        if (rv > 0) {
333	            /* successfully read bytes from the socket */
334	            buf += rv;
335	            bufsz -= rv;
336	        } else if (rv == 0 || (rv < 0 && errno != EAGAIN && errno != EWOULDBLOCK)) {
337	            /* an error occurred that wasn't "nothing to read". */
338	            return MQTT_ERROR_SOCKET_ERROR;
339	        }
340	    } while (rv > 0);
341	
342	    return buf - start;
343	}
