252	static void parse_broker(const char *broker, char *host, size_t host_sz,
253	                         int *port)
254	{
255	    const char *colon = strrchr(broker, ':');
256	
257	    if (colon && colon != broker) {
258	        size_t hlen = (size_t)(colon - broker);
259	
260	        if (hlen >= host_sz) {
261	            hlen = host_sz - 1;
262	        }
263	
264	        memcpy(host, broker, hlen);
265	        host[hlen] = '\0';
266	        *port = atoi(colon + 1);
267	    } else {
268	        strncpy(host, broker, host_sz - 1);
269	        host[host_sz - 1] = '\0';
270	        *port = AGENT_MQTT_DEFAULT_PORT;
271	    }
272	
273	    if (*port <= 0 || *port > 65535) {
274	        *port = AGENT_MQTT_DEFAULT_PORT;
275	    }
276	}
