342	/**
343	 * Reads messages from the outbound queue and dispatches them to the
344	 * appropriate channel (FeiShu, WebSocket, CLI, etc.).
345	 */
346	static void* outbound_dispatch_task(void* arg)
347	{
348	    (void)arg;
349	    syslog(LOG_INFO, "[%s] Outbound dispatch started\n", TAG);
350	
351	    while (!g_shutdown_requested) {
352	        agent_msg_t msg;
353	        if (message_bus_pop_outbound(&msg, 1000) != OK)
354	            continue;
355	        msg.channel[sizeof(msg.channel) - 1] = '\0';
356	        msg.chat_id[sizeof(msg.chat_id) - 1] = '\0';
357	
358	        if (!msg.content) {
359	            syslog(LOG_WARNING, "[%s] Skip outbound message with NULL content\n", TAG);
360	            continue;
361	        }
362	
363	        syslog(LOG_INFO, "[%s] Dispatching response → %s:%s\n", TAG, msg.channel, msg.chat_id);
364	
365	        /* Let registered taps intercept before normal dispatch */
366	        if (mbus_tap_try_deliver(&msg)) {
367	            free(msg.content);
368	            continue;
369	        }
370	
371	        if (strcmp(msg.channel, AGENT_CHAN_FEISHU) == 0) {
372	            bool delivered = false;
373	#ifdef CONFIG_AI_AGENT_FEISHU
374	            const char* app_id = feishu_get_app_id();
375	            if (app_id && app_id[0] != '\0') {
376	                feishu_send_message(msg.chat_id, msg.content);
377	                delivered = true;
378	            }
379	#endif
380	#ifdef CONFIG_AI_AGENT_NODE
381	            if (!delivered) {
382	                delivered = node_client_send_chat_message(
383	                    msg.channel, msg.chat_id, msg.content) == OK;
384	            }
385	#endif
386	            if (!delivered) {
387	                syslog(LOG_WARNING,
388	                    "[%s] Feishu message dropped: no local config "
389	                    "and no gateway\n",
