980	static bool check_tool_dup(const llm_response_t* resp,
981	    char* prev_sig, int* dup_count,
982	    char* prev_name, int* name_repeat)
983	{
984	    if (resp->call_count != 1) {
985	        prev_sig[0] = '\0';
986	        *dup_count = 0;
987	        prev_name[0] = '\0';
988	        *name_repeat = 0;
989	        return false;
990	    }
991	
992	    /* Exact match (name + args) */
993	    char cur_sig[512];
994	
995	    snprintf(cur_sig, sizeof(cur_sig), "%s|%.400s",
996	        resp->calls[0].name,
997	        resp->calls[0].input ? resp->calls[0].input : "");
998	
999	    if (strcmp(cur_sig, prev_sig) == 0) {
1000	        (*dup_count)++;
1001	        if (*dup_count >= 2) {
1002	            syslog(LOG_WARNING,
1003	                "[%s] Duplicate tool call detected (%s), breaking\n",
1004	                TAG, resp->calls[0].name);
1005	            return true;
1006	        }
1007	    } else {
1008	        *dup_count = 0;
1009	    }
1010	    strncpy(prev_sig, cur_sig, 511);

