179	
180	static void on_reconnect(struct mqtt_client *client, void **state)
181	{
182	    (void)state;
183	
184	    /* Close old socket if any */
185	    if (s_sockfd >= 0) {
186	        close(s_sockfd);
187	        s_sockfd = -1;
188	    }
189	
190	    syslog(LOG_INFO, "[%s] Reconnecting to %s:%d...\n",
191	           TAG, s_broker_host, s_broker_port);
192	
193	    s_sockfd = tcp_connect(s_broker_host, s_broker_port);
194	    if (s_sockfd < 0) {
195	        syslog(LOG_ERR, "[%s] Reconnect TCP failed\n", TAG);
196	        /* Reinit with invalid fd so MQTT-C stays in error state
197	         * and will call reconnect_callback again on next mqtt_sync. */
198	        mqtt_reinit(client, -1,
199	                    s_sendbuf, sizeof(s_sendbuf),
200	                    s_recvbuf, sizeof(s_recvbuf));
201	        return;
202	    }
203	
204	    mqtt_reinit(client, s_sockfd,
205	                s_sendbuf, sizeof(s_sendbuf),
206	                s_recvbuf, sizeof(s_recvbuf));
207	
208	    uint8_t flags = MQTT_CONNECT_CLEAN_SESSION;
209	    const char *user = s_username[0] ? s_username : NULL;
210	    const char *pass = s_password[0] ? s_password : NULL;
211	
212	    enum MQTTErrors err = mqtt_connect(client, s_client_id,
213	                                       NULL, NULL, 0,
214	                                       user, pass, flags,
215	                                       AGENT_MQTT_KEEPALIVE);
216	    if (err != MQTT_OK) {
217	        syslog(LOG_ERR, "[%s] mqtt_connect failed: %d\n", TAG, (int)err);
218	        return;
219	    }
220	
221	    /* Subscribe to inbound topic */
222	    mqtt_subscribe(client, s_topic_in, 1);
223	    syslog(LOG_INFO, "[%s] Subscribed to %s\n", TAG, s_topic_in);
224	}
