154	/* Open TCP connection to proxy + send CONNECT, returns fd or -1. */
155	static int open_connect_tunnel(const char *host, int port, int timeout_ms)
156	{
157	    struct addrinfo hints = { .ai_family = AF_UNSPEC, .ai_socktype = SOCK_STREAM };
158	    struct addrinfo *res = NULL;
159	    char proxy_port_str[8];
160	    snprintf(proxy_port_str, sizeof(proxy_port_str), "%d", s_proxy_port);
161	
162	    if (getaddrinfo(s_proxy_host, proxy_port_str, &hints, &res) != 0 || !res) {
163	        syslog(LOG_ERR, "[%s] DNS failed for proxy %s\n", TAG, s_proxy_host);
164	        return -1;
165	    }
166	
167	    int sock = socket(res->ai_family, SOCK_STREAM, 0);
168	    if (sock < 0) { freeaddrinfo(res); return -1; }
169	
170	    /* Non-blocking connect with select() timeout — SO_SNDTIMEO does not
171	     * affect connect() on all platforms (NuttX sim included). */
172	    int flags = fcntl(sock, F_GETFL, 0);
173	    fcntl(sock, F_SETFL, flags | O_NONBLOCK);
174	
175	    int rc = connect(sock, res->ai_addr, res->ai_addrlen);
176	    freeaddrinfo(res);
177	
178	    if (rc != 0 && errno != EINPROGRESS) {
179	        syslog(LOG_ERR, "[%s] TCP connect to proxy %s:%d failed: %s\n",
180	               TAG, s_proxy_host, s_proxy_port, strerror(errno));
181	        close(sock);
182	        return -1;
183	    }
184	
185	    /* Wait for connect to complete */
186	    fd_set wfds;
187	    FD_ZERO(&wfds);
188	    FD_SET(sock, &wfds);
189	    struct timeval tv = { .tv_sec = timeout_ms / 1000,
190	                          .tv_usec = (timeout_ms % 1000) * 1000 };
191	    rc = select(sock + 1, NULL, &wfds, NULL, &tv);
192	    if (rc <= 0) {
193	        syslog(LOG_ERR, "[%s] TCP connect timeout to proxy %s:%d\n",
194	               TAG, s_proxy_host, s_proxy_port);
