393	static void send_to_llm(const char *user_text)
394	{
395	    /* A voice wake command can arrive before the kid has tapped a role: the
396	     * chat widgets (g_chat_status etc.) are created lazily in
397	     * ui_show_chat_screen(), so they are still NULL and lv_label_set_text()
398	     * below would fault.  Show the default-role chat screen first so every
399	     * label we touch actually exists. */
400	    if (g_chat_status == NULL)
401	      {
402	        ui_show_chat_screen();
403	      }
404	
405	    if (!g_agent_connected || g_agent_client == NULL)
406	      {
407	        lv_label_set_text(g_chat_status, "Agent offline - start 'ai_agent &' first");
408	        return;
409	      }
410	
411	    /* Mark an interaction in flight so the wake loop stays quiet through the
412	     * LLM request + TTS reply. Cleared by the TTS worker after the final
413	     * reply is spoken (or here if the request fails immediately). */
414	    g_reply_busy = 1;
415	
416	    /* Build full prompt: system prompt + user text */
417	    const role_def_t *role = &g_roles[g_current_role];
418	    char full_prompt[MSG_BUF_LEN];
419	    snprintf(full_prompt, MSG_BUF_LEN,
420	             "[SYSTEM]\n%s\n\n[USER]\n%s",
421	             role->system_prompt, user_text);
422	
423	    velaclaw_ask_req_t req = {
424	        .text       = full_prompt,
425	        .timeout_ms = 15000  /* 15 second timeout */
426	    };
427	
428	    /* Start a fresh response: bump the epoch and reset the spoken offset so
429	     * the streamed reply is spoken from the beginning, and drop any stale
430	     * fragment still queued for the previous question. */
431	    pthread_mutex_lock(&g_tts_lock);
432	    g_tts_epoch++;
433	    g_spoken_len = 0;
434	    g_tts_pending_ready = false;
435	    g_tts_pending_final = false;
436	    pthread_mutex_unlock(&g_tts_lock);
437	
438	    lv_label_set_text(g_chat_status, "Thinking...");
439	    if (g_chat_spinner)
440	      {
441	        lv_obj_clear_flag(g_chat_spinner, LV_OBJ_FLAG_HIDDEN);
442	      }
443	
444	    int ret = velaclaw_ask(g_agent_client, &req, llm_response_cb, NULL);
445	    if (ret < 0)
446	      {
447	        lv_label_set_text(g_chat_status, "Failed to send message");
448	        if (g_chat_spinner)
449	          {
450	            lv_obj_add_flag(g_chat_spinner, LV_OBJ_FLAG_HIDDEN);
451	          }
452	        g_reply_busy = 0;  /* request failed, release the wake loop */
453	      }
