41	/* djb2 hash over the FULL string. Hash the whole message, not just a fixed
42	 * prefix: kid_buddy sends "[SYSTEM]…\n[USER]\n<query>", so the meaningful
43	 * part (the query) is at the END. Hashing only the first LLM_CACHE_KEY_LEN
44	 * bytes made every query under one role collide on the same cached reply. */
45	
46	static uint32_t djb2_hash(const char* str, size_t len)
47	{
48	    uint32_t h = 5381;
49	
50	    for (size_t i = 0; i < len; i++) {
51	        h = ((h << 5) + h) + (unsigned char)str[i];
52	    }
53	    return h;
54	}
