287	
288	/**
289	 * Parse first line as title: expects "# Title"
290	 * Returns pointer past "# " or the line itself if no prefix.
291	 */
292	static const char *extract_title(const char *line, size_t len, char *out, size_t out_size)
293	{
294	    const char *start = line;
295	    if (len >= 2 && line[0] == '#' && line[1] == ' ') {
296	        start = line + 2;
297	        len -= 2;
298	    }
299	
300	    /* Trim trailing whitespace/newline */
301	    while (len > 0 && (start[len - 1] == '\n' || start[len - 1] == '\r' || start[len - 1] == ' ')) {
302	        len--;
303	    }
304	
305	    size_t copy = len < out_size - 1 ? len : out_size - 1;
306	    memcpy(out, start, copy);
307	    out[copy] = '\0';
308	    return out;
309	}
310	
311	/**
312	 * Extract description: text between the first line and the first blank line.
313	 */
314	static void extract_description(FILE *f, char *out, size_t out_size)
315	{
316	    size_t off = 0;
317	    char line[256];
318	
319	    while (fgets(line, sizeof(line), f) && off < out_size - 1) {
320	        size_t len = strlen(line);
321	
322	        /* Stop at blank line or section header */
323	        if (len == 0 || (len == 1 && line[0] == '\n') ||
324	            (len >= 2 && line[0] == '#' && line[1] == '#')) {
325	            break;
326	        }
327	
328	        /* Skip leading blank lines */
329	        if (off == 0 && line[0] == '\n') continue;
330	
331	        /* Trim trailing newline for concatenation */
332	        if (line[len - 1] == '\n') {
333	            line[len - 1] = ' ';
334	        }
335	
336	        size_t copy = len < out_size - off - 1 ? len : out_size - off - 1;
337	        memcpy(out + off, line, copy);
338	        off += copy;
339	    }
340	
341	    /* Trim trailing space */
342	    while (off > 0 && out[off - 1] == ' ') off--;
343	    out[off] = '\0';
344	}
