346	size_t skill_loader_build_summary(char *buf, size_t size)
347	{
348	    /*
349	     * On Vela/NuttX we have real directories, so we can simply opendir
350	     * on the skills directory and iterate over .md files.
351	     * (Original version used flat namespace readdir from mount root.)
352	     */
353	    DIR *dir = opendir(AGENT_SKILLS_DIR);
354	    if (!dir) {
355	        syslog(LOG_WARNING, "[%s] Cannot open skills directory for enumeration: %s\n", TAG, AGENT_SKILLS_DIR);
356	        buf[0] = '\0';
357	        return 0;
358	    }
359	
360	    size_t off = 0;
361	    struct dirent *ent;
362	
363	    while ((ent = readdir(dir)) != NULL && off < size - 1) {
364	        const char *name = ent->d_name;
365	        size_t name_len = strlen(name);
366	
367	        /* Match .md files only */
368	        if (name_len < 4) continue;
369	        if (strcmp(name + name_len - 3, ".md") != 0) continue;
370	
371	        /* Skip hidden files */
372	        if (name[0] == '.') continue;
373	
374	        /* Build full path */
375	        char full_path[256];
376	        snprintf(full_path, sizeof(full_path), "%s%s", AGENT_SKILLS_DIR, name);
377	
378	        FILE *f = fopen(full_path, "r");
379	        if (!f) continue;

380	
381	        /* Read first line for title */
382	        char first_line[128];
383	        if (!fgets(first_line, sizeof(first_line), f)) {
384	            fclose(f);
385	            continue;
386	        }
387	
388	        char title[64];
389	        extract_title(first_line, strlen(first_line), title, sizeof(title));
390	
391	        /* Read description (until blank line) */
392	        char desc[256];
393	        extract_description(f, desc, sizeof(desc));
394	        fclose(f);
395	
396	        /* Append to summary */
397	        off += snprintf(buf + off, size - off,
398	            "- **%s**: %s (read with: read_file %s)\n",
399	            title, desc, full_path);
400	    }
401	
402	    closedir(dir);
403	
404	    buf[off] = '\0';
405	    syslog(LOG_INFO, "[%s] Skills summary: %d bytes\n", TAG, (int)off);
406	    return off;
407	}
