566	/* ── Streaming TTS worker ─────────────────────────────────────
567	 * Speak a response aloud in a background thread so the LVGL UI stays
568	 * responsive while TTS synthesizes and plays. A single worker thread
569	 * serializes every speak (voice_channel_speak aborts any in-progress speak
570	 * on a concurrent call). The worker does NOT speak partial fragments as they
571	 * stream: it waits for the final fragment and speaks the whole reply in one
572	 * voice_channel_speak() call. This keeps a single ALSA open/close cycle and
573	 * lets voice_channel_speak() buffer the full reply for continuous playback. */
574	
575	static void *tts_stream_worker(void *arg)
576	{
577	    (void)arg;
578	
579	    for (;;)
580	      {
581	        char text[MSG_BUF_LEN];
582	        bool final = false;
583	        unsigned int epoch;
584	        size_t spoken;
585	
586	        pthread_mutex_lock(&g_tts_lock);
587	        while (!g_tts_pending_ready)
588	          {
589	            pthread_cond_wait(&g_tts_cond, &g_tts_lock);
590	          }
591	        strncpy(text, g_tts_pending, MSG_BUF_LEN - 1);
592	        text[MSG_BUF_LEN - 1] = '\0';
593	        final = g_tts_pending_final;
594	        epoch = g_tts_epoch;
595	        spoken = g_spoken_len;
596	        g_tts_pending_ready = false;
597	        g_tts_pending_final = false;
598	        pthread_mutex_unlock(&g_tts_lock);
599	
600	        size_t len = strlen(text);
601	
602	        if (spoken > len)
603	          {
604	            spoken = len; /* offset reset under us mid-speak */
605	          }
606	
607	        /* Speak the whole reply in one voice_channel_speak() call, and only
608	         * once the reply is complete (final). Speaking sentence-by-sentence
609	         * as the text streamed made the worker open/close the ALSA codec
610	         * once per fragment; the codec's external-speaker PA (gpio_spk) is
611	         * armed on the first open but not reliably re-armed on a later open
612	         * in the same response, so only the first sentence was audible. A
613	         * single open/prepare/write/close cycle is the sequence the codec
614	         * plays reliably, and voice_channel_speak() already buffers the full
615	         * reply (fetch-then-play) so the story reads continuously. We trade
616	         * a later first word for complete, continuous speech — the priority
617	         * for a child's toy. */
618	        if (!final)
619	          {
620	            continue;
621	          }
622	
623	        syslog(LOG_INFO,
624	               "[kid_buddy] tts_worker final=1 len=%d speak_whole\n",
625	               (int)len);
626	
627	        if (len > spoken)
628	          {
629	            g_reply_busy = 1;
630	            /* A reminder can arrive while the wake loop still holds the mic
631	             * (and the codec's shared DMA channel). Wait for it to release the
632	             * mic before opening playback, else the reminder is silent. */
633	            for (int i = 0; i < 100 && g_mic_open; i++)
634	              {
635	                usleep(10 * 1000);  /* 10 ms */
636	              }
637	            voice_channel_speak(text);
638	            g_reply_busy = 0;   /* final reply spoken, wake loop may listen */
639	            g_last_reply_ms = now_ms();  /* arm the follow-up answer window */
640	
641	            pthread_mutex_lock(&g_tts_lock);
642	            /* Advance only if no newer question reset the offset mid-speak. */
643	            if (epoch == g_tts_epoch)
644	              {
645	                g_spoken_len = len;
646	              }
647	            pthread_mutex_unlock(&g_tts_lock);
648	          }
649	      }
650	
651	    return NULL;
652	}
