654	/* Enqueue the latest cumulative reply text for speaking. "latest wins" — a
655	 * newer fragment replaces an older one still waiting in the slot. */
656	static void enqueue_tts(const char *text, bool final)
657	{
658	    pthread_mutex_lock(&g_tts_lock);
659	    strncpy(g_tts_pending, text, MSG_BUF_LEN - 1);
660	    g_tts_pending[MSG_BUF_LEN - 1] = '\0';
661	    g_tts_pending_final = final;
662	    g_tts_pending_ready = true;
663	    syslog(LOG_INFO, "[kid_buddy] enqueue_tts final=%d len=%d\n",
664	           (int)final, (int)strlen(g_tts_pending));
665	    pthread_cond_signal(&g_tts_cond);
666	    pthread_mutex_unlock(&g_tts_lock);
667	}
