104	
105	int voice_tts_speak_stream(const char* text,
106	    voice_tts_chunk_cb cb,
107	    void* user_data)
108	{
109	    if (!s_active) {
110	        syslog(LOG_ERR, "[%s] No TTS backend for streaming\n", TAG);
111	        return -ENODEV;
112	    }
113	
114	    if (s_active->synthesize_stream) {
115	        return s_active->synthesize_stream(text, cb, user_data);
116	    }
117	
118	    /* Batch fallback: synthesize the whole utterance, then deliver it
119	     * as a single chunk followed by the is_last notification. */
120	    unsigned char* pcm = malloc(AGENT_VOICE_PCM_BUF_SIZE);
121	
122	    if (!pcm) {
123	        syslog(LOG_ERR, "[%s] stream fallback: OOM\n", TAG);
124	        return -ENOMEM;
125	    }
126	
127	    size_t len = 0;
128	    int ret = s_active->synthesize(text, pcm,
129	        AGENT_VOICE_PCM_BUF_SIZE, &len);
130	
131	    if (ret == 0 && len > 0) {
132	        cb(pcm, len, 0, user_data);
133	        cb(NULL, 0, 1, user_data);
134	    }
135	
136	    free(pcm);
137	    return ret;
138	}
