125	/* One fetched TTS response. resp holds the raw HTTP body; root holds the
126	 * parsed JSON (the base64 string lives inside root, not resp). */
127	typedef struct {
128	    char* resp;      /* owned, caller frees */
129	    cJSON* root;     /* owned, caller frees */
130	    const char* b64; /* pointer into root's strings */
131	    size_t b64_len;
132	} mimo_audio_t;
133	
134	static void mimo_audio_free(mimo_audio_t* a)
135	{
136	    if (a->root) {
137	        cJSON_Delete(a->root);
138	    }
139	    free(a->resp);
140	    memset(a, 0, sizeof(*a));
141	}
