984	static int tts_sentence_end_len(const char* p)
985	{
986	    static const char* const TERM[] = {
987	        "。", "！", "？", "；", "…", "\n", "!", "?", ";", ".", "~", NULL
988	    };
989	
990	    for (int i = 0; TERM[i] != NULL; i++) {
991	        size_t n = strlen(TERM[i]);
992	
993	        if (strncmp(p, TERM[i], n) == 0) {
994	            return (int)n;
995	        }
996	    }
997	
998	    return 0;
999	}
1000	
1001	/* ── TTS: fetch-then-play ───────────────────────────────────── */
1002	
1003	/* One sentence's decoded PCM (owned). Sentences are fetched sequentially,
1004	 * buffered, then played back-to-back so the story reads continuously with
1005	 * no network-sized silence between sentences. */
1006	typedef struct {
1007	    unsigned char* pcm;
1008	    size_t pcm_len;
1009	    size_t pcm_cap;
1010	    int rc;   /* 0 on success; backend error, or -ENOMEM on capture failure */
1011	} tts_buf_t;
1012	
1013	/* Capture callback: accumulate streamed PCM into b->pcm. (voice_tts_chunk_cb
1014	 * returns void, so a capture failure just sets b->rc and stops copying.) */
1015	static void tts_capture_cb(const unsigned char* pcm, size_t len,
1016	    int is_last, void* user_data)
1017	{
1018	    tts_buf_t* b = user_data;
1019	    (void)is_last;
1020	
1021	    if (s_voice.tts_abort || b->rc != 0) {
1022	        return;
1023	    }
1024	
1025	    if (pcm && len > 0) {
1026	        if (!s_tts_first_chunk) {
1027	            struct timespec now;
1028	            clock_gettime(CLOCK_MONOTONIC, &now);
1029	            long ms = (now.tv_sec - s_tts_start.tv_sec) * 1000
1030	                + (now.tv_nsec - s_tts_start.tv_nsec) / 1000000;
1031	            syslog(LOG_INFO, "[%s] TTS first chunk: %ldms\n", TAG, ms);
1032	            s_tts_first_chunk = 1;
1033	        }
1034	
1035	        if (b->pcm_len + len > b->pcm_cap) {
1036	            size_t ncap = b->pcm_cap ? b->pcm_cap : 0;
1037	            while (ncap < b->pcm_len + len) {
1038	                ncap = ncap ? ncap * 2 : (64 * 1024);
1039	            }
1040	            unsigned char* nd = realloc(b->pcm, ncap);
1041	            if (!nd) {
1042	                b->rc = -ENOMEM;
1043	                return;
1044	            }
1045	            b->pcm = nd;
1046	            b->pcm_cap = ncap;
1047	        }
1048	        memcpy(b->pcm + b->pcm_len, pcm, len);
1049	        b->pcm_len += len;
1050	    }
1051	}
1052	
1053	/* Copy a [s, s+len) slice into a NUL-terminated string with leading
1054	 * whitespace stripped; returns NULL if nothing but whitespace remains. */
1055	static char* tts_slice_dup(const char* s, int len)
1056	{
1057	    char* d = malloc(len + 1);
1058	    if (!d) {
1059	        return NULL;
1060	    }
1061	    memcpy(d, s, len);
1062	    d[len] = '\0';
1063	
1064	    char* c = d;
1065	    while (*c == ' ' || *c == '\n' || *c == '\t' || *c == '\r') {
1066	        c++;
1067	    }
1068	    if (*c == '\0') {
1069	        free(d);
1070	        return NULL;
1071	    }
1072	    if (c != d) {
1073	        memmove(d, c, strlen(c) + 1);
1074	    }
1075	    return d;
1076	}
1077	
1078	/* Synthesize text one sentence at a time, buffering each sentence's PCM,
1079	 * then play them all back-to-back. Chunking by sentence keeps each TTS
1080	 * response small (a single utterance's base64 audio can overflow
1081	 * MIMO_TTS_RESP_SIZE), while buffering first — instead of playing each
1082	 * sentence immediately after its own fetch — removes the 5-12s network
1083	 * silence that used to sit between sentences and made a story sound like
1084	 * it stopped after the first line. The cost is one combined first-sentence
1085	 * delay, but the story then reads continuously. */
1086	static int tts_speak_chunked(const char* text, audio_playback_t* pb)
1087	{
1088	    /* First pass: split into sentence slices. */
1089	    #define MAX_SLICES 128
1090	    const char* slice_start[MAX_SLICES];
1091	    int slice_len[MAX_SLICES];
1092	    int nslices = 0;
1093	
1094	    const char* start = text;
1095	    while (*start && nslices < MAX_SLICES) {
1096	        /* Bail early if the network dropped (e.g. WiFi disconnect) so we
1097	         * don't grind through the remaining sentences with doomed
1098	         * handshakes and retries. */
1099	        if (!network_is_connected()) {
1100	            syslog(LOG_WARNING, "[%s] network down, stopping TTS\n", TAG);
1101	            break;
1102	        }
1103	
1104	        const char* p = start;
1105	        int tlen = 0;
1106	        while (*p) {
1107	            tlen = tts_sentence_end_len(p);
1108	            if (tlen > 0) {
1109	                break;
1110	            }
1111	            p++;
1112	        }
1113	
1114	        const char* end;
1115	        if (*p) {
1116	            end = p + tlen;
1117	
1118	            /* Absorb immediately-following terminators (e.g. "!!!") so
1119	             * they don't become empty one-punctuation sentences. */
1120	            while (*end) {
1121	                int n = tts_sentence_end_len(end);
1122	                if (n > 0) {
1123	                    end += n;
1124	                } else {
1125	                    break;
1126	                }
1127	            }
1128	        } else {
1129	            end = p; /* end of string */
1130	        }
1131	
1132	        if (end > start) {
1133	            slice_start[nslices] = start;
1134	            slice_len[nslices] = (int)(end - start);
1135	            nslices++;
1136	        }
1137	
1138	        if (*end == '\0') {
1139	            break;
1140	        }
1141	        start = end;
1142	    }
1143	
1144	    if (nslices == 0) {
1145	        return -EPROTO;
1146	    }
1147	
1148	    tts_buf_t bufs[MAX_SLICES];
1149	    memset(bufs, 0, sizeof(bufs));
1150	
1151	    int first_err = 0;
1152	    int any_ok = 0;
1153	
1154	    /* Phase 1: fetch every sentence's audio sequentially into memory. */
1155	    for (int i = 0; i < nslices; i++) {
1156	        if (s_voice.tts_abort) {
1157	            break;
1158	        }
1159	        if (!network_is_connected()) {
1160	            syslog(LOG_WARNING, "[%s] network down, stopping TTS\n", TAG);
1161	            if (first_err == 0) {
1162	                first_err = -EIO;
1163	            }

1163	            }
1164	            break;
1165	        }
1166	
1167	        char* sent = tts_slice_dup(slice_start[i], slice_len[i]);
1168	        if (!sent) {
1169	            bufs[i].rc = -ENOMEM;
1170	            if (first_err == 0) {
1171	                first_err = -ENOMEM;
1172	            }
1173	            continue;
1174	        }
1175	
1176	        int r = voice_tts_speak_stream(sent, tts_capture_cb, &bufs[i]);
1177	        free(sent);
1178	
1179	        /* Keep a capture failure (e.g. -ENOMEM) over a clean backend result. */
1180	        if (bufs[i].rc == 0) {
1181	            bufs[i].rc = r;
1182	        }
1183	
1184	        if (r == 0 && bufs[i].pcm_len > 0) {
1185	            any_ok = 1;
1186	        } else if (bufs[i].rc != 0 && first_err == 0) {
1187	            first_err = bufs[i].rc;
1188	        }
1189	    }
1190	
1191	    /* Phase 2: play all buffered sentences back-to-back (continuous). */
1192	    for (int i = 0; i < nslices; i++) {
1193	        if (s_voice.tts_abort) {
1194	            break;
1195	        }
1196	        if (bufs[i].rc == 0 && bufs[i].pcm_len > 0) {
1197	            audio_playback_write(pb, bufs[i].pcm, bufs[i].pcm_len);
1198	        }
1199	    }
1200	
1201	    for (int i = 0; i < nslices; i++) {
1202	        free(bufs[i].pcm);
1203	    }
1204	
1205	    #undef MAX_SLICES
1206	    return any_ok ? 0 : (first_err ? first_err : -EPROTO);
1207	}
