1209	int voice_channel_speak(const char* text)
1210	{
1211	    if (!text || text[0] == '\0') {
1212	        return -EINVAL;
1213	    }
1214	
1215	    /* ── Serialize concurrent speak calls ── */
1216	    /* If another thread is already speaking, abort its TTS playback
1217	     * so we don't overlap media_player sessions (which causes the
1218	     * media framework to attempt a ~1.3GB allocation and crash). */
1219	    pthread_mutex_lock(&s_voice.lock);
1220	    if (s_voice.tts_pb) {
1221	        syslog(LOG_INFO, "[%s] speak: aborting previous TTS\n", TAG);
1222	        s_voice.tts_abort = 1;
1223	        audio_playback_stop(s_voice.tts_pb);
1224	    }
1225	    pthread_mutex_unlock(&s_voice.lock);
1226	
1227	    pthread_mutex_lock(&s_voice.speak_lock);
1228	
1229	    /* ── AEC workaround: reject TTS while PTT is recording ── */
1230	    pthread_mutex_lock(&s_voice.lock);
1231	    if (s_voice.state != VOICE_IDLE) {
1232	        pthread_mutex_unlock(&s_voice.lock);
1233	        pthread_mutex_unlock(&s_voice.speak_lock);
1234	        syslog(LOG_INFO,
1235	            "[%s] speak: skipped, recording active\n", TAG);
1236	        return -EBUSY;
1237	    }
1238	    pthread_mutex_unlock(&s_voice.lock);
1239	
1240	    /* Work on a mutable copy so we can strip markdown in-place */
1241	    size_t text_len = strlen(text);
1242	    char* clean = malloc(text_len + 1);
1243	
1244	    if (!clean) {
1245	        pthread_mutex_unlock(&s_voice.speak_lock);
1246	        return -ENOMEM;
1247	    }
1248	
1249	    memcpy(clean, text, text_len + 1);
1250	    tts_strip_markdown(clean);
1251	
1252	    /* If stripping left nothing, bail out */
1253	    if (clean[0] == '\0') {
1254	        free(clean);
1255	        pthread_mutex_unlock(&s_voice.speak_lock);
1256	        return 0;
1257	    }
1258	
1259	    syslog(LOG_INFO, "[%s] speak: \"%.*s\" (%zu bytes)\n",
1260	        TAG, 60, clean, strlen(clean));
1261	
1262	    clock_gettime(CLOCK_MONOTONIC, &s_tts_start);
1263	    s_tts_first_chunk = 0;
1264	
1265	    if (s_asr_done_ts.tv_sec > 0) {
1266	        long llm_ms = (s_tts_start.tv_sec - s_asr_done_ts.tv_sec) * 1000
1267	            + (s_tts_start.tv_nsec - s_asr_done_ts.tv_nsec) / 1000000;
1268	        syslog(LOG_INFO, "[%s] LLM latency: %ldms\n", TAG, llm_ms);
1269	    }
1270	
1271	    /* Try streaming TTS first (callback per chunk) */
1272	    audio_playback_t* pb = audio_playback_open(
1273	        AGENT_AUDIO_PLAYBACK_DEV,
1274	        AGENT_TTS_WS_SAMPLE_RATE,
1275	        AGENT_VOICE_CHANNELS,
1276	        AGENT_VOICE_BITS);
1277	
1278	    if (!pb) {
1279	        syslog(LOG_ERR, "[%s] playback open failed\n", TAG);
1280	        free(clean);
1281	        pthread_mutex_unlock(&s_voice.speak_lock);
1282	        return -EIO;
1283	    }
1284	
1285	    /* Register active playback so voice_channel_start() can abort it */
1286	    pthread_mutex_lock(&s_voice.lock);
1287	    s_voice.tts_abort = 0;
1288	    s_voice.tts_pb = pb;
1289	    pthread_mutex_unlock(&s_voice.lock);
1290	
1291	    /* Use streaming TTS, split sentence-by-sentence so a long story
1292	     * doesn't overflow the TTS response buffer. */
1293	    int ret = tts_speak_chunked(clean, pb);
1294	
1295	    struct timespec tts_net;
1296	    clock_gettime(CLOCK_MONOTONIC, &tts_net);
1297	    long net_ms = (tts_net.tv_sec - s_tts_start.tv_sec) * 1000
1298	        + (tts_net.tv_nsec - s_tts_start.tv_nsec) / 1000000;
1299	    syslog(LOG_INFO, "[%s] TTS network done: %ldms\n", TAG, net_ms);
1300	
1301	    /* Unregister active playback */
1302	    pthread_mutex_lock(&s_voice.lock);
1303	    s_voice.tts_pb = NULL;
1304	    s_voice.tts_abort = 0;
1305	    pthread_mutex_unlock(&s_voice.lock);
1306	
1307	    audio_playback_close(pb);
1308	    free(clean);
1309	
1310	    if (ret != 0) {
1311	        syslog(LOG_ERR, "[%s] TTS stream failed: %d\n", TAG, ret);
1312	        pthread_mutex_unlock(&s_voice.speak_lock);
1313	        return ret;
1314	    }
1315	
1316	    struct timespec tend;
1317	    clock_gettime(CLOCK_MONOTONIC, &tend);
1318	    long total_ms = (tend.tv_sec - s_tts_start.tv_sec) * 1000
1319	        + (tend.tv_nsec - s_tts_start.tv_nsec) / 1000000;
1320	    syslog(LOG_INFO, "[%s] speak done: total %ldms (play wait %ldms)\n",
1321	        TAG, total_ms, total_ms - net_ms);
1322	    pthread_mutex_unlock(&s_voice.speak_lock);
1323	    return 0;
1324	}
