298	int audio_playback_write(audio_playback_t* pb, const void* buf, size_t len)
299	{
300	    if (!pb || !buf || len == 0) {
301	        return -EINVAL;
302	    }
303	
304	    if (pb->stopped) {
305	        return -ECANCELED;
306	    }
307	
308	#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
309	    if (pb->backend == AUDIO_PLAYBACK_BACKEND_ALSA) {
310	        snd_pcm_t* pcm = pb->handle.pcm;
311	        const unsigned char* src = buf;
312	        size_t written_bytes = 0;
313	
314	        while (written_bytes < len) {
315	            snd_pcm_uframes_t frames = snd_vela_pcm_bytes_to_frames(pcm,
316	                len - written_bytes);
317	            snd_pcm_sframes_t n = snd_vela_pcm_writei(pcm, src, frames);
318	
319	            if (n == -EAGAIN) {
320	                usleep(10 * 1000);
321	                continue;
322	            }
323	
324	            if (n == -EPIPE || n == -ESTRPIPE) {
325	                snd_vela_pcm_prepare(pcm);
326	                continue;
327	            }
328	
329	            if (n <= 0) {
330	                syslog(LOG_ERR, "[%s] ALSA write failed: %ld\n",
331	                    TAG, (long)n);
332	                return (n < 0) ? (int)n : -EIO;
333	            }
334	
335	            size_t bytes = (size_t)n * (size_t)pb->bytes_per_frame;
336	            src += bytes;
337	            written_bytes += bytes;
338	        }
339	
340	        pb->total_written += written_bytes;
341	        return (int)written_bytes;
342	    }
343	#endif
344	
345	    ssize_t n = media_player_write_data(pb->handle.player, buf, len);
346	
347	    if (n > 0) {
348	        pb->total_written += (size_t)n;
349	    }
350	
351	    return (int)n;
352	}
