/* ── TTS: pipelined fetch + play ──────────────────────────────
 *
 * Synthesize text one sentence at a time (each sentence is its own MiMo TTS
 * request, so a long reply never overflows MIMO_TTS_RESP_SIZE), but overlap
 * synthesis with playback: a fetch thread runs one sentence ahead while the
 * caller writes the previous sentence to the already-open ALSA stream. This
 * drops the first word from "sum of all fetches" to "first sentence's fetch"
 * and hides the rest of the network latency behind playback — roughly halving
 * total time for a multi-sentence story.
 *
 * Playback stays a single ALSA session (open once in voice_channel_speak(),
 * write N times here, close once), so the codec's external-speaker PA re-arm
 * issue — which made the old per-sentence open/close only play the first
 * sentence — is NOT reintroduced. A fetch that runs longer than its sentence's
 * playback leaves a brief silence before the next sentence; capacity 2 means
 * we only ever prefetch one sentence, so a slow network can't exhaust memory.
 */

#define TTS_PIPE_CAP 2

typedef struct {
    pthread_mutex_t lock;
    pthread_cond_t  cond;      /* broadcast on filled-- (space) or filled++ (data) */
    tts_buf_t       slots[TTS_PIPE_CAP];
    const char* const* slice_start;
    const int*      slice_len;
    int             nslices;
    int             put_idx;   /* producer writes slots[put_idx] */
    int             get_idx;   /* consumer reads slots[get_idx] */
    int             filled;    /* slots currently holding a produced sentence */
    int             producer_done;
    int             abort;     /* consumer -> producer: stop fetching */
} tts_pipe_t;
