270	int tool_cron_list_execute(const char* input_json,
271	    char* output, size_t output_size)
272	{
273	    (void)input_json;
274	
275	    /* cron_job_t is ~800 bytes; 16 of them on the stack would be ~12 KB, which
276	     * risks overflowing the 16 KB tool-thread stack. Allocate on the heap. */
277	    cron_job_t* jobs = malloc(sizeof(cron_job_t) * AGENT_CRON_MAX_JOBS);
278	
279	    if (!jobs) {
280	        snprintf(output, output_size, "Error: out of memory");
281	        return ERROR;
282	    }
283	
284	    int count = cron_list_jobs(jobs, AGENT_CRON_MAX_JOBS);
285	
286	    if (count == 0) {
287	        free(jobs);
288	        snprintf(output, output_size, "No cron jobs scheduled.");
289	        return OK;
290	    }
291	
292	    size_t off = 0;
293	
294	    off += snprintf(output + off, output_size - off,
295	        "Scheduled jobs (%d):\n", count);
296	
297	    for (int i = 0; i < count && off < output_size - 1; i++) {
298	        const cron_job_t* j = &jobs[i];
299	
300	        if (j->kind == CRON_KIND_EVERY) {
301	            off += snprintf(output + off, output_size - off,
302	                "  %d. [%s] \"%s\" every %lus, %s, "
303	                "next=%lld, last=%lld, ch=%s:%s\n",
304	                i + 1, j->id, j->name,
305	                (unsigned long)j->interval_s,
306	                j->enabled ? "enabled" : "disabled",
307	                (long long)j->next_run,
308	                (long long)j->last_run,
309	                j->channel, j->chat_id);
310	        } else {
311	            off += snprintf(output + off, output_size - off,
312	                "  %d. [%s] \"%s\" at %lld, %s, "
313	                "last=%lld, ch=%s:%s%s\n",
314	                i + 1, j->id, j->name,
315	                (long long)j->at_epoch,
316	                j->enabled ? "enabled" : "disabled",
317	                (long long)j->last_run,
318	                j->channel, j->chat_id,
319	                j->delete_after_run ? " (auto-delete)" : "");
320	        }
321	    }
322	
323	    syslog(LOG_INFO, "[tool_cron] cron_list: %d jobs\n", count);
324	    free(jobs);
325	    return OK;
326	}
