308	/* Notify callback for UNSOLICITED outbound messages (e.g. cron-fired
309	 * reminders) delivered while no velaclaw_ask is in flight. Route into the
310	 * same g_pending_msg / g_msg_ready slot that llm_response_cb uses, so the
311	 * existing poll_timer_cb path (emoji/markdown strip → LCD → TTS) speaks and
312	 * displays the reminder with zero new UI code. Partial fragments (status 1)
313	 * are ignored — cron reminders arrive as a single complete message. */
314	static void kid_notify_cb(int status, const char *msg, void *cookie)
315	{
316	    (void)cookie;
317	
318	    if (msg == NULL || status == 1)
319	      {
320	        return;
321	      }
322	
323	    /* A cron reminder may carry a [KID_REPORT:<channel>|<chat_id>] prefix
324	     * asking for a child-confirmation report. Strip it, remember the report
325	     * destination, and speak only the reminder text itself. */
326	    const char *text = msg;
327	    if (strncmp(msg, "[KID_REPORT:", 12) == 0)
328	      {
329	        const char *end = strchr(msg, ']');
330	        const char *sep = strchr(msg + 12, '|');
331	        if (end && sep && sep < end)
332	          {
333	            size_t clen = (size_t)(sep - (msg + 12));
334	            size_t cidlen = (size_t)(end - (sep + 1));
335	            if (clen < sizeof(g_report_channel)
336	                && cidlen < sizeof(g_report_chat_id))
337	              {
338	                pthread_mutex_lock(&g_msg_lock);
339	                memcpy(g_report_channel, msg + 12, clen);
340	                g_report_channel[clen] = '\0';
341	                memcpy(g_report_chat_id, sep + 1, cidlen);
342	                g_report_chat_id[cidlen] = '\0';
343	                pthread_mutex_unlock(&g_msg_lock);
344	
345	                text = end + 1;
346	                if (*text == '\n')
347	                  {
348	                    text++;
349	                  }
350	                g_report_pending = 1;
351	              }
352	          }
353	      }
354	
355	    /* A reminder needs to speak, but the wake loop may be holding the capture
356	     * mic (and the codec's shared DMA channel) right now. Raise g_reply_busy so
357	     * the wake loop aborts its listen and releases the mic; the TTS worker then
358	     * waits for g_mic_open to clear before it opens playback. */
359	    g_reply_busy = 1;
360	
361	    /* A reminder is an independent, complete message — not a streaming fragment
362	     * of an in-flight LLM reply. Reset the streaming TTS offset so the TTS
363	     * worker speaks it from the beginning; otherwise, if the previous reply was
364	     * longer, len <= spoken and the reminder is silently skipped (text on LCD
365	     * but no voice). */
366	    pthread_mutex_lock(&g_tts_lock);
367	    g_tts_epoch++;
368	    g_spoken_len = 0;
369	    g_tts_pending_ready = false;
370	    g_tts_pending_final = false;
371	    pthread_mutex_unlock(&g_tts_lock);
372	
373	    /* The confirmation window only opens once the reminder finishes playing
374	     * (the TTS worker arms g_last_reply_ms). Clear any stale arm from a prior
375	     * reply so the kid must acknowledge *after* hearing the reminder. */
376	    g_last_reply_ms = 0;
377	
378	    pthread_mutex_lock(&g_msg_lock);
379	    g_msg_status = 0;
380	    strncpy(g_pending_msg, text, MSG_BUF_LEN - 1);
381	    g_pending_msg[MSG_BUF_LEN - 1] = '\0';
382	    if (g_report_pending)
383	      {
384	        strncpy(g_report_reminder, text, MSG_BUF_LEN - 1);
385	        g_report_reminder[MSG_BUF_LEN - 1] = '\0';
386	      }
387	    g_msg_ready = true;
388	    pthread_mutex_unlock(&g_msg_lock);
389	
390	    syslog(LOG_INFO, "[kid_buddy] notify_cb len=%d report=%d\n",
391	           (int)strlen(text), g_report_pending);
392	}
