153	/* Auto-inject channel/chat_id into cron_add input JSON. */
154	static char* inject_cron_context(const char* tool_name,
155	    const char* input_json, const char* channel, const char* chat_id)
156	{
157	    if (strcmp(tool_name, "cron_add") != 0) {
158	        return NULL;
159	    }
160	    if (!channel || !channel[0] || !chat_id || !chat_id[0]) {
161	        return NULL;
162	    }
163	
164	    cJSON* root = cJSON_Parse(input_json);
165	    if (!root) {
166	        return NULL;
167	    }
168	
169	    cJSON_DeleteItemFromObject(root, "channel");
170	    cJSON_DeleteItemFromObject(root, "chat_id");
171	    cJSON_AddStringToObject(root, "channel", channel);
172	    cJSON_AddStringToObject(root, "chat_id", chat_id);
173	
174	    /* A reminder scheduled from a remote parent channel is for the child:
175	     * speak it on-device (local_client), and report the child's confirmation
176	     * back to the parent's own channel/chat_id. On-device requests
177	     * (local_client/voice/cli) keep their original destination and do not
178	     * get a confirmation report. */
179	    if (is_remote_parent_channel(channel)) {
180	        cJSON_DeleteItemFromObject(root, "report_channel");
181	        cJSON_DeleteItemFromObject(root, "report_chat_id");
182	        cJSON_AddStringToObject(root, "report_channel", channel);
183	        cJSON_AddStringToObject(root, "report_chat_id", chat_id);
184	
185	        cJSON_DeleteItemFromObject(root, "channel");
186	        cJSON_DeleteItemFromObject(root, "chat_id");
187	        cJSON_AddStringToObject(root, "channel", AGENT_CHAN_LOCAL_CLIENT);
188	        cJSON_AddStringToObject(root, "chat_id", "kid_buddy");
189	    }
190	
191	    char* patched = cJSON_PrintUnformatted(root);
192	    cJSON_Delete(root);
193	    return patched;
194	}
