382	int mqtt_channel_start(void)
383	{
384	    if (!s_broker_host[0]) {
385	        syslog(LOG_INFO, "[%s] No mqtt_broker configured, MQTT disabled\n",
386	               TAG);
387	        return OK;
388	    }
389	
390	    /* Idempotent: if a sync thread is already running, don't start another.
391	     * Two threads sharing one s_client + the same client_id will CONNECT
392	     * twice and the broker keeps kicking one off → endless reconnect loop. */
393	    if (s_running) {
394	        syslog(LOG_INFO, "[%s] MQTT already running, skip duplicate start\n",
395	               TAG);
396	        return OK;
397	    }
398	
399	    /* Initialize the MQTT-C client exactly once. mqtt_init_reconnect()
400	     * re-initializes s_client.mutex every call; re-initing a mutex that
401	     * another thread (outbound dispatch via mqtt_publish, or a still-stuck
402	     * old sync thread) may be blocked on is undefined behavior and can leave
403	     * that thread permanently blocked. On re-start we soft-reset instead. */
404	    if (!s_client_inited) {
405	        mqtt_init_reconnect(&s_client, on_reconnect, NULL, on_publish);
406	        s_client_inited = true;
407	    } else {
408	        mqtt_reinit(&s_client, -1,
409	                    s_sendbuf, sizeof(s_sendbuf),
410	                    s_recvbuf, sizeof(s_recvbuf));
411	        /* mqtt_reinit leaves reconnect_callback/publish_response_callback
412	         * intact from the first init; only reset the error so the first
413	         * mqtt_sync triggers on_reconnect. */
414	        s_client.error = MQTT_ERROR_INITIAL_RECONNECT;
415	    }
416	
417	    s_running = true;
418	    s_sync_thread_exited = false;
419	
420	    int ret = agent_task_create(mqtt_sync_thread, "mqtt_sync",
421	                                   AGENT_MQTT_STACK, NULL,
422	                                   AGENT_MQTT_PRIO);
423	    if (ret != OK) {
424	        syslog(LOG_ERR, "[%s] Failed to create sync thread\n", TAG);
425	        s_running = false;
426	        s_sync_thread_exited = true;
427	        return ERROR;
428	    }
429	
430	    syslog(LOG_INFO, "[%s] MQTT channel started → %s:%d\n",
431	           TAG, s_broker_host, s_broker_port);
432	    return OK;
433	}
