435	int mqtt_channel_send(const char *chat_id, const char *text)
436	{
437	    if (!s_running || s_sockfd < 0 || !chat_id || !text) {
438	        return ERROR;
439	    }
440	
441	    /* Build JSON: {"type":"response","content":"...","chat_id":"..."} */
442	    cJSON *resp = cJSON_CreateObject();
443	
444	    cJSON_AddStringToObject(resp, "type", "response");
445	    cJSON_AddStringToObject(resp, "content", text);
446	    cJSON_AddStringToObject(resp, "chat_id", chat_id);
447	
448	    char *json = cJSON_PrintUnformatted(resp);
449	
450	    cJSON_Delete(resp);
451	    if (!json) {
452	        return ERROR;
453	    }
454	
455	    enum MQTTErrors err = mqtt_publish(&s_client, s_topic_out,
456	                                       json, strlen(json),
457	                                       MQTT_PUBLISH_QOS_1);
458	    if (err != MQTT_OK) {
459	        syslog(LOG_ERR, "[%s] Publish failed: %d\n", TAG, (int)err);
460	        free(json);
461	        return ERROR;
462	    }
463	
464	    syslog(LOG_INFO, "[%s] Published to %s (%d bytes)\n",
465	           TAG, s_topic_out, (int)strlen(json));
466	    free(json);
467	    return OK;
468	}
469	
470	void mqtt_channel_stop(void)
471	{
472	    if (!s_running) {
473	        return;
474	    }
475	
476	    s_running = false;
477	
478	    /* Close socket first to unblock any blocking recv in sync thread */
479	    if (s_sockfd >= 0) {
480	        close(s_sockfd);
481	        s_sockfd = -1;
482	    }
483	
484	    /* Wait for the sync thread to actually exit before returning. Without
485	     * this, a fast stop→start (e.g. `set_mqtt`) leaves the old thread alive:
486	     * start() flips s_running back to true and creates a second thread, and
487	     * the two threads CONNECT with the same client_id → the broker keeps
488	     * kicking one off → endless reconnect loop (MQTT_ERROR_SOCKET_ERROR). */
489	    for (int i = 0; i < 20 && !s_sync_thread_exited; i++) {
490	        usleep(100 * 1000);
491	    }
492	
493	    syslog(LOG_INFO, "[%s] MQTT channel stopped\n", TAG);
494	}
