275	static void *mqtt_sync_thread(void *arg)
276	{
277	    (void)arg;
278	
279	    syslog(LOG_INFO, "[%s] Sync thread started\n", TAG);
280	
281	    while (s_running) {
282	        enum MQTTErrors err = mqtt_sync(&s_client);
283	
284	        if (err != MQTT_OK) {
285	            syslog(LOG_WARNING, "[%s] mqtt_sync error: %d\n", TAG, (int)err);
286	            /* MQTT-C will call reconnect_callback automatically */
287	        }
288	
289	        usleep(AGENT_MQTT_SYNC_INTERVAL_MS * 1000);
290	    }
291	
292	    s_sync_thread_exited = true;
293	    syslog(LOG_INFO, "[%s] Sync thread exited\n", TAG);
294	    return NULL;
295	}
