35	enum MQTTErrors mqtt_sync(struct mqtt_client *client) {
36	    /* Recover from any errors */
37	    enum MQTTErrors err;
38	    int reconnecting = 0;
39	    MQTT_PAL_MUTEX_LOCK(&client->mutex);
40	    if (client->error != MQTT_ERROR_RECONNECTING && client->error != MQTT_OK && client->reconnect_callback != NULL) {
41	        client->reconnect_callback(client, &client->reconnect_state);
42	        /* unlocked during CONNECT */
43	    } else {
44	        /* mqtt_reconnect will have queued the disconnect packet - that needs to be sent and then call reconnect */
45	        if (client->error == MQTT_ERROR_RECONNECTING) {
46	            reconnecting = 1;
47	            client->error = MQTT_OK;
48	        }
49	        MQTT_PAL_MUTEX_UNLOCK(&client->mutex);
50	    }
51	
52	    /* Call inspector callback if necessary */
53	    
54	    if (client->inspector_callback != NULL) {
55	        MQTT_PAL_MUTEX_LOCK(&client->mutex);
56	        err = client->inspector_callback(client);
57	        MQTT_PAL_MUTEX_UNLOCK(&client->mutex);
58	        if (err != MQTT_OK) return err;
59	    }
60	
61	    /* Call receive */
62	    err = __mqtt_recv(client);
63	    if (err != MQTT_OK) return err;
64	
65	    /* Call send */
66	    err = __mqtt_send(client);
67	
68	    /* mqtt_reconnect will essentially be a disconnect if there is no callback */
69	    if (reconnecting && client->reconnect_callback != NULL) {
70	        MQTT_PAL_MUTEX_LOCK(&client->mutex);
71	        client->reconnect_callback(client, &client->reconnect_state);
72	    }
73	
74	    return err;
75	}
