77	uint16_t __mqtt_next_pid(struct mqtt_client *client) {
78	    int pid_exists = 0;
79	    if (client->pid_lfsr == 0) {
80	        client->pid_lfsr = 163u;
81	    }
82	    /* LFSR taps taken from: https://en.wikipedia.org/wiki/Linear-feedback_shift_register */
83	    
84	    do {
85	        struct mqtt_queued_message *curr;
86	        unsigned lsb = client->pid_lfsr & 1;
87	        (client->pid_lfsr) >>= 1;
88	        if (lsb) {
89	            client->pid_lfsr ^= 0xB400u;
90	        }
91	
92	        /* check that the PID is unique */
93	        pid_exists = 0;
94	        for(curr = mqtt_mq_get(&(client->mq), 0); curr >= client->mq.queue_tail; --curr) {
95	            if (curr->packet_id == client->pid_lfsr) {
96	                pid_exists = 1;
97	                break;
98	            }
99	        }
100	
101	    } while(pid_exists);
102	    return client->pid_lfsr;
103	}
