38	ssize_t mqtt_pal_sendall(mqtt_pal_socket_handle fd, const void* buf, size_t len, int flags) {
39	    size_t sent = 0;
40	    while(sent < len) {
41	        int rv = mbedtls_ssl_write(fd, buf + sent, len - sent);
42	        if (rv < 0) {
43	            if (rv == MBEDTLS_ERR_SSL_WANT_READ ||
44	                rv == MBEDTLS_ERR_SSL_WANT_WRITE
45	#if defined(MBEDTLS_ERR_SSL_ASYNC_IN_PROGRESS)
46	                || rv == MBEDTLS_ERR_SSL_ASYNC_IN_PROGRESS
47	#endif
48	#if defined(MBEDTLS_ERR_SSL_CRYPTO_IN_PROGRESS)
49	                || rv == MBEDTLS_ERR_SSL_CRYPTO_IN_PROGRESS
50	#endif
51	                ) {
52	                /* should call mbedtls_ssl_write later again */
53	                break;
54	            }
55	            return MQTT_ERROR_SOCKET_ERROR;
56	        }
57	        sent += (size_t) rv;
58	    }
59	    return sent;
60	}
