62	ssize_t mqtt_pal_recvall(mqtt_pal_socket_handle fd, void* buf, size_t bufsz, int flags) {
63	    const void *const start = buf;
64	    int rv;
65	    do {
66	        rv = mbedtls_ssl_read(fd, buf, bufsz);
67	        if (rv == 0) {
68	            /*
69	             * Note: mbedtls_ssl_read returns 0 when the underlying
70	             * transport was closed without CloseNotify.
71	             */
72	            if (buf == start) {
73	                /*
74	                 * Raise an error to trigger a reconnect.
75	                 */
76	                return MQTT_ERROR_SOCKET_ERROR;
77	            }
78	            break;
79	        }
80	        if (rv < 0) {
81	            if (rv == MBEDTLS_ERR_SSL_WANT_READ ||
82	                rv == MBEDTLS_ERR_SSL_WANT_WRITE
83	#if defined(MBEDTLS_ERR_SSL_ASYNC_IN_PROGRESS)
84	                || rv == MBEDTLS_ERR_SSL_ASYNC_IN_PROGRESS
85	#endif
86	#if defined(MBEDTLS_ERR_SSL_CRYPTO_IN_PROGRESS)
87	                || rv == MBEDTLS_ERR_SSL_CRYPTO_IN_PROGRESS
88	#endif
89	                ) {
90	                /* should call mbedtls_ssl_read later again */
91	                break;
92	            }
93	            return MQTT_ERROR_SOCKET_ERROR;
94	        }
95	        buf = (char*)buf + rv;
96	        bufsz -= rv;
97	    } while (rv > 0);
98	
99	    return buf - start;
100	}
