144	static int do_rec_data(mqtt_pal_socket_handle fd, unsigned int status) {
145	    ssize_t rc;
146	    uint8_t *buffer;
147	    size_t length;
148	    int err;
149	
150	    err = br_ssl_engine_last_error(&fd->sc.eng);
151	
152	    if (err != BR_ERR_OK) {
153	        return MQTT_ERROR_SOCKET_ERROR;
154	    }
155	
156	    if ((status & BR_SSL_SENDREC) == BR_SSL_SENDREC) {
157	        buffer = br_ssl_engine_sendrec_buf(&fd->sc.eng, &length);
158	
159	        if (length > 0) {
160	            if ((rc = fd->low_write(&fd->fd, buffer, length)) < 0) {
161	                return MQTT_ERROR_SOCKET_ERROR;
162	            }
163	
164	            br_ssl_engine_sendrec_ack(&fd->sc.eng, rc);
165	        }
166	    }
167	    else if ((status & BR_SSL_RECVREC) == BR_SSL_RECVREC) {
168	        buffer = br_ssl_engine_recvrec_buf(&fd->sc.eng, &length);
169	
170	        if (length > 0) {
171	            if ((rc = fd->low_read(&fd->fd, buffer, length)) < 0) {
172	                return MQTT_ERROR_SOCKET_ERROR;
173	            }
174	            
175	            br_ssl_engine_recvrec_ack(&fd->sc.eng, rc);
176	        }
177	    }
178	    else if ((status && BR_SSL_CLOSED) == BR_SSL_CLOSED) {
179	        return MQTT_ERROR_SOCKET_ERROR;
180	    }
181	
182	    return MQTT_OK;
183	}
