185	ssize_t mqtt_pal_sendall(mqtt_pal_socket_handle fd, const void* buf, size_t len, int flags) {
186	    int rc = MQTT_OK;
187	    uint8_t *buffer;
188	    size_t length;
189	    size_t remaining_bytes = len;
190	    const uint8_t *walker = buf;
191	    unsigned int status;
192	
193	    while (remaining_bytes > 0) {
194	
195	        if (rc == MQTT_ERROR_SOCKET_ERROR) {
196	            return rc;
197	        }
198	
199	        status = br_ssl_engine_current_state(&fd->sc.eng);
200	
201	        if ((status & BR_SSL_CLOSED) != 0) {
202	            return MQTT_ERROR_SOCKET_ERROR;
203	        }
204	
205	        if ((status & (BR_SSL_RECVREC | BR_SSL_SENDREC)) != 0) {
206	            rc = do_rec_data(fd, status);
207	
208	            if (rc != MQTT_OK) {
209	                return rc;
210	            }
211	            status = br_ssl_engine_current_state(&fd->sc.eng);
212	        }
213	
214	        if ((status & BR_SSL_SENDAPP) == BR_SSL_SENDAPP) {
215	            buffer = br_ssl_engine_sendapp_buf(&fd->sc.eng, &length);
216	
217	            if (length > 0) {
218	                size_t write = length >= remaining_bytes? remaining_bytes : length;
219	                memcpy(buffer, walker, write);
220	                remaining_bytes -= write;
221	                walker += write;
222	                br_ssl_engine_sendapp_ack(&fd->sc.eng, write);
223	                br_ssl_engine_flush(&fd->sc.eng, 0);
224	            }
225	        }
226	    }
227	
228	    return len;
229	}
