70	static int tcp_connect(const char *host, int port)
71	{
72	    char port_str[8];
73	    int fd;
74	    int flags;
75	
76	    snprintf(port_str, sizeof(port_str), "%d", port);
77	
78	    struct addrinfo hints;
79	    struct addrinfo *res;
80	
81	    memset(&hints, 0, sizeof(hints));
82	    hints.ai_family = AF_INET;
83	    hints.ai_socktype = SOCK_STREAM;
84	
85	    if (getaddrinfo(host, port_str, &hints, &res) != 0 || !res) {
86	        syslog(LOG_ERR, "[%s] DNS resolve failed: %s\n", TAG, host);
87	        return -1;
88	    }
89	
90	    fd = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
91	
92	    if (fd < 0) {
93	        freeaddrinfo(res);
94	        return -1;
95	    }
96	
97	    /* Non-blocking connect with a bounded timeout (see the comment on
98	     * MQTT_TCP_CONNECT_TIMEOUT_MS for why this matters). */
99	    flags = fcntl(fd, F_GETFL, 0);
100	    fcntl(fd, F_SETFL, flags | O_NONBLOCK);
101	
102	    if (connect(fd, res->ai_addr, res->ai_addrlen) != 0
103	        && errno != EINPROGRESS) {
104	        syslog(LOG_ERR, "[%s] TCP connect failed: %s:%d (%s)\n",
105	               TAG, host, port, strerror(errno));
106	        close(fd);
107	        freeaddrinfo(res);
108	        return -1;
109	    }
110	
111	    freeaddrinfo(res);
112	
113	    fd_set wfds;
114	    FD_ZERO(&wfds);
115	    FD_SET(fd, &wfds);
116	    struct timeval tv = {
117	        .tv_sec = MQTT_TCP_CONNECT_TIMEOUT_MS / 1000,
118	        .tv_usec = (MQTT_TCP_CONNECT_TIMEOUT_MS % 1000) * 1000
119	    };
120	
121	    if (select(fd + 1, NULL, &wfds, NULL, &tv) <= 0) {
122	        syslog(LOG_ERR, "[%s] TCP connect timeout: %s:%d\n",
123	               TAG, host, port);
124	        close(fd);
125	        return -1;
126	    }
127	
128	    int sock_err = 0;
129	    socklen_t sock_errlen = sizeof(sock_err);
130	
131	    getsockopt(fd, SOL_SOCKET, SO_ERROR, &sock_err, &sock_errlen);
132	    if (sock_err != 0) {
133	        syslog(LOG_ERR, "[%s] TCP connect failed: %s:%d (%s)\n",
134	               TAG, host, port, strerror(sock_err));
135	        close(fd);
136	        return -1;
137	    }
138	
139	    /* Restore blocking mode for subsequent send/recv */
140	    fcntl(fd, F_SETFL, flags);
141	
142	    /* Set recv timeout so mqtt_sync is not blocked forever.
143	     * This allows MQTT-C to send PINGREQ on time. */
144	    struct timeval tv_rcv;
145	
146	    tv_rcv.tv_sec = 1;
147	    tv_rcv.tv_usec = 0;
148	    setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv_rcv, sizeof(tv_rcv));
149	
150	    syslog(LOG_INFO, "[%s] TCP connected to %s:%d (fd=%d)\n",
151	           TAG, host, port, fd);
152	    return fd;
153	}
