656	    ssize_t mqtt_recv_ret = MQTT_OK;
657	    MQTT_PAL_MUTEX_LOCK(&client->mutex);
658	
659	    /* read until there is nothing left to read, or there was an error */
660	    while(mqtt_recv_ret == MQTT_OK) {
661	        /* read in as many bytes as possible */
662	        ssize_t rv, consumed;
663	        struct mqtt_queued_message *msg = NULL;
664	
665	        rv = mqtt_pal_recvall(client->socketfd, client->recv_buffer.curr, client->recv_buffer.curr_sz, 0);
666	        if (rv < 0) {
667	            /* an error occurred */
668	            client->error = rv;
669	            MQTT_PAL_MUTEX_UNLOCK(&client->mutex);
670	            return rv;
671	        } else {
672	            client->recv_buffer.curr += rv;
673	            client->recv_buffer.curr_sz -= rv;
674	        }
675	
676	        /* attempt to parse */
677	        consumed = mqtt_unpack_response(&response, client->recv_buffer.mem_start, client->recv_buffer.curr - client->recv_buffer.mem_start);
678	
679	        if (consumed < 0) {
680	            client->error = consumed;
681	            MQTT_PAL_MUTEX_UNLOCK(&client->mutex);
682	            return consumed;
683	        } else if (consumed == 0) {
684	            /* if curr_sz is 0 then the buffer is too small to ever fit the message */
685	            if (client->recv_buffer.curr_sz == 0) {
686	                client->error = MQTT_ERROR_RECV_BUFFER_TOO_SMALL;
687	                MQTT_PAL_MUTEX_UNLOCK(&client->mutex);
688	                return MQTT_ERROR_RECV_BUFFER_TOO_SMALL;
689	            }
690	
691	            /* just need to wait for the rest of the data */
692	            MQTT_PAL_MUTEX_UNLOCK(&client->mutex);
693	            return MQTT_OK;
694	        }
695	
696	        /* response was unpacked successfully */
697	
698	        /*
699	        The switch statement below manages how the client responds to messages from the broker.
700	
701	        Control Types (that we expect to receive from the broker):
702	        MQTT_CONTROL_CONNACK:
703	            -> release associated CONNECT
704	            -> handle response
705	        MQTT_CONTROL_PUBLISH:
706	            -> stage response, none if qos==0, PUBACK if qos==1, PUBREC if qos==2
707	            -> call publish callback
708	        MQTT_CONTROL_PUBACK:
709	            -> release associated PUBLISH
710	        MQTT_CONTROL_PUBREC:
711	            -> release PUBLISH
712	            -> stage PUBREL
713	        MQTT_CONTROL_PUBREL:
