342	/**
343	 * Reads messages from the outbound queue and dispatches them to the
344	 * appropriate channel (FeiShu, WebSocket, CLI, etc.).
345	 */
346	static void* outbound_dispatch_task(void* arg)
347	{
348	    (void)arg;
349	    syslog(LOG_INFO, "[%s] Outbound dispatch started\n", TAG);
350	
351	    while (!g_shutdown_requested) {
352	        agent_msg_t msg;
353	        if (message_bus_pop_outbound(&msg, 1000) != OK)
354	            continue;
355	        msg.channel[sizeof(msg.channel) - 1] = '\0';
356	        msg.chat_id[sizeof(msg.chat_id) - 1] = '\0';
357	
358	        if (!msg.content) {
359	            syslog(LOG_WARNING, "[%s] Skip outbound message with NULL content\n", TAG);
360	            continue;
361	        }
362	
363	        syslog(LOG_INFO, "[%s] Dispatching response → %s:%s\n", TAG, msg.channel, msg.chat_id);
364	
365	        /* Let registered taps intercept before normal dispatch */
366	        if (mbus_tap_try_deliver(&msg)) {
367	            free(msg.content);
368	            continue;
369	        }
370	
371	        if (strcmp(msg.channel, AGENT_CHAN_FEISHU) == 0) {
372	            bool delivered = false;
373	#ifdef CONFIG_AI_AGENT_FEISHU
374	            const char* app_id = feishu_get_app_id();
375	            if (app_id && app_id[0] != '\0') {
376	                feishu_send_message(msg.chat_id, msg.content);
377	                delivered = true;
378	            }
379	#endif
380	#ifdef CONFIG_AI_AGENT_NODE
381	            if (!delivered) {
382	                delivered = node_client_send_chat_message(
383	                    msg.channel, msg.chat_id, msg.content) == OK;
384	            }
385	#endif
386	            if (!delivered) {
387	                syslog(LOG_WARNING,
388	                    "[%s] Feishu message dropped: no local config "
389	                    "and no gateway\n",
390	                    TAG);
391	            }
392	        } else if (strcmp(msg.channel, AGENT_CHAN_WEBSOCKET) == 0) {
393	            ws_server_send(msg.chat_id, msg.content);
394	#ifdef CONFIG_AI_AGENT_MQTT
395	        } else if (strcmp(msg.channel, AGENT_CHAN_MQTT) == 0) {
396	            mqtt_channel_send(msg.chat_id, msg.content);
397	#endif
398	        } else if (strcmp(msg.channel, AGENT_CHAN_VOICE) == 0) {
399	            /* Check voice cooldown — skip voice dispatch if a recent
400	             * speak call failed, to prevent error-message cascade. */
401	            if (s_voice_cooldown && time(NULL) < s_voice_cooldown_until) {
402	                syslog(LOG_WARNING,
403	                    "[%s] voice cooldown active, dropping message\n", TAG);
404	            } else {
405	                s_voice_cooldown = false;
406	                int vret = voice_channel_speak(msg.content);
407	                if (vret != 0) {
408	                    syslog(LOG_ERR, "[%s] voice_channel_speak failed: %d\n", TAG, vret);
409	                    s_voice_cooldown = true;
410	                    s_voice_cooldown_until = time(NULL) + 5;
411	                }
412	            }
413	#ifdef CONFIG_AI_AGENT_LVGL_UI
414	        } else if (strcmp(msg.channel, AGENT_CHAN_LVGL_UI) == 0) {
415	            int uret = lvgl_ui_channel_send(msg.content);
416	            if (uret != 0) {
417	                syslog(LOG_ERR, "[%s] lvgl_ui_channel_send failed: %d\n", TAG, uret);
418	            }
419	#endif
420	#ifdef CONFIG_AI_AGENT_WEIXIN
421	        } else if (strcmp(msg.channel, AGENT_CHAN_WEIXIN) == 0) {
422	            /* chat_id format: "from_user_id|context_token" */
423	            char uid[64] = "";
424	            const char* ctx = "";
425	            char* sep = strchr(msg.chat_id, '|');
426	            if (sep) {
427	                size_t ulen = (size_t)(sep - msg.chat_id);
428	                if (ulen >= sizeof(uid))
429	                    ulen = sizeof(uid) - 1;
430	                memcpy(uid, msg.chat_id, ulen);
431	                uid[ulen] = '\0';
432	                ctx = sep + 1;
433	            } else {
434	                strncpy(uid, msg.chat_id, sizeof(uid) - 1);
435	            }
436	            weixin_channel_send(uid, ctx, msg.content);
437	#endif
438	        } else if (strcmp(msg.channel, AGENT_CHAN_SYSTEM) == 0) {
439	            syslog(LOG_INFO, "[%s] System message [%s]: %.128s\n", TAG, msg.chat_id, msg.content);
440	#ifdef CONFIG_FEATURE_SYSTEM_VELACLAW
441	        } else if (strcmp(msg.channel, AGENT_CHAN_QUICKAPP) == 0) {
442	            quickapp_mq_dispatch(msg.chat_id, msg.content);
443	#endif
444	        } else if (strcmp(msg.channel, "cli") == 0) {
445	            pthread_mutex_lock(&g_stdout_lock);
446	            printf("\n[Agent]: %s\nvela> ", msg.content);
447	            fflush(stdout);
448	            pthread_mutex_unlock(&g_stdout_lock);
449	            syslog(LOG_INFO, "[agent] [Agent]: %s\n", msg.content);
450	        } else {
451	            syslog(LOG_WARNING, "[%s] Unknown channel: %s\n", TAG, msg.channel);
452	        }
453	
454	        free(msg.content);
455	    }
456	
457	    syslog(LOG_INFO, "[%s] Outbound dispatch exiting\n", TAG);
458	    return NULL;
459	}
