/* Set recv timeout so mqtt_sync is not blocked forever.
 * This allows MQTT-C to send PINGREQ on time.
 *
 * NOTE: a blocking recv() here holds client->mutex inside __mqtt_recv(),
 * which used to starve mqtt_publish() on the outbound dispatch thread
 * (head-of-line blocking). That starvation is fixed in the MQTT-C library
 * itself — __mqtt_recv() now releases client->mutex during the socket
 * read (apps/netutils/mqttc/MQTT-C/src/mqtt.c), so a blocking recv no
 * longer blocks the publisher. */
struct timeval tv_rcv;

tv_rcv.tv_sec = 1;
tv_rcv.tv_usec = 0;
setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv_rcv, sizeof(tv_rcv));

syslog(LOG_INFO, "[%s] TCP connected to %s:%d (fd=%d)\n",
       TAG, host, port, fd);
