1166	static int tts_speak_chunked(const char* text, audio_playback_t* pb)
1167	{
1168	    /* First pass: split into sentence slices. */
1169	    #define MAX_SLICES 128
1170	    const char* slice_start[MAX_SLICES];
1171	    int slice_len[MAX_SLICES];
1172	    int nslices = 0;
1173	
1174	    const char* start = text;
1175	    while (*start && nslices < MAX_SLICES) {
1176	        const char* p = start;
1177	        int tlen = 0;
1178	        while (*p) {
1179	            tlen = tts_sentence_end_len(p);
1180	            if (tlen > 0) {
1181	                break;
1182	            }
1183	            p++;
1184	        }
1185	
1186	        const char* end;
1187	        if (*p) {
1188	            end = p + tlen;
1189	
1190	            /* Absorb immediately-following terminators (e.g. "!!!") so
1191	             * they don't become empty one-punctuation sentences. */
1192	            while (*end) {
1193	                int n = tts_sentence_end_len(end);
1194	                if (n > 0) {
1195	                    end += n;
1196	                } else {
1197	                    break;
1198	                }
1199	            }
1200	        } else {
1201	            end = p; /* end of string */
1202	        }
1203	
1204	        if (end > start) {
1205	            slice_start[nslices] = start;
1206	            slice_len[nslices] = (int)(end - start);
1207	            nslices++;
1208	        }
1209

1288	        if (s_voice.tts_abort) {
1289	            free(b.pcm);
1290	            break;
1291	        }
1292	
1293	        if (b.rc == 0 && b.pcm_len > 0) {
1294	            audio_playback_write(pb, b.pcm, b.pcm_len);
1295	            any_ok = 1;
1296	        } else if (b.rc != 0 && first_err == 0) {
1297	            first_err = b.rc;
1298	        }
1299	        free(b.pcm);
1300	    }
1301	
1302	    /* Stop the producer and wait for it before returning. */
1303	    pthread_mutex_lock(&p.lock);
1304	    p.abort = 1;
1305	    pthread_cond_broadcast(&p.cond);
1306	    pthread_mutex_unlock(&p.lock);
1307	    pthread_join(tid, NULL);
1308	
1309	    pthread_cond_destroy(&p.cond);
1310	    pthread_mutex_destroy(&p.lock);
1311	
1312	    #undef MAX_SLICES
1313	    return any_ok ? 0 : (first_err ? first_err : -EPROTO);
1314	}
