1316	int voice_channel_speak(const char* text)
1317	{
1318	    if (!text || text[0] == '\0') {
1319	        return -EINVAL;
1320	    }
1321	
1322	    /* ── Serialize concurrent speak calls ── */
1323	    /* If another thread is already speaking, abort its TTS playback
1324	     * so we don't overlap media_player sessions (which causes the
1325	     * media framework to attempt a ~1.3GB allocation and crash). */
