1342	            "[%s] speak: skipped, recording active\n", TAG);
1343	        return -EBUSY;
1344	    }
1345	    pthread_mutex_unlock(&s_voice.lock);
1346	
1347	    /* Work on a mutable copy so we can strip markdown in-place */
1348	    size_t text_len = strlen(text);
1349	    char* clean = malloc(text_len + 1);
1350	
1351	    if (!clean) {
1352	        pthread_mutex_unlock(&s_voice.speak_lock);
1353	        return -ENOMEM;
1354	    }
1355	
1356	    memcpy(clean, text, text_len + 1);
1357	    tts_strip_markdown(clean);
1358	
1359	    /* If stripping left nothing, bail out */
1360	    if (clean[0] == '\0') {
1361	        free(clean);
1362	        pthread_mutex_unlock(&s_voice.speak_lock);
1363	        return 0;
1364	    }
1365	
1366	    syslog(LOG_INFO, "[%s] speak: \"%.*s\" (%zu bytes)\n",
1367	        TAG, 60, clean, strlen(clean));
1368	
1369	    clock_gettime(CLOCK_MONOTONIC, &s_tts_start);
1370	    s_tts_first_chunk = 0;
1371	
1372	    if (s_asr_done_ts.tv_sec > 0) {
1373	        long llm_ms = (s_tts_start.tv_sec - s_asr_done_ts.tv_sec) * 1000
1374	            + (s_tts_start.tv_nsec - s_asr_done_ts.tv_nsec) / 1000000;
1375	        syslog(LOG_INFO, "[%s] LLM latency: %ldms\n", TAG, llm_ms);
1376	    }
1377	
1378	    /* Try streaming TTS first (callback per chunk) */
1379	    audio_playback_t* pb = audio_playback_open(
1380	        AGENT_AUDIO_PLAYBACK_DEV,
1381	        AGENT_TTS_WS_SAMPLE_RATE,
1382	        AGENT_VOICE_CHANNELS,
1383	        AGENT_VOICE_BITS);
1384	
1385	    if (!pb) {
1386	        syslog(LOG_ERR, "[%s] playback open failed\n", TAG);
1387	        free(clean);
1388	        pthread_mutex_unlock(&s_voice.speak_lock);
1389	        return -EIO;
1390	    }
1391	
1392	    /* Register active playback so voice_channel_start() can abort it */
1393	    pthread_mutex_lock(&s_voice.lock);
1394	    s_voice.tts_abort = 0;
1395	    s_voice.tts_pb = pb;
1396	    pthread_mutex_unlock(&s_voice.lock);
1397	
1398	    /* Use streaming TTS, split sentence-by-sentence so a long story
1399	     * doesn't overflow the TTS response buffer. */
1400	    int ret = tts_speak_chunked(clean, pb);
1401	
1402	    struct timespec tts_net;
1403	    clock_gettime(CLOCK_MONOTONIC, &tts_net);
1404	    long net_ms = (tts_net.tv_sec - s_tts_start.tv_sec) * 1000
1405	        + (tts_net.tv_nsec - s_tts_start.tv_nsec) / 1000000;
1406	    syslog(LOG_INFO, "[%s] TTS network done: %ldms\n", TAG, net_ms);
1407	
1408	    /* Unregister active playback */
1409	    pthread_mutex_lock(&s_voice.lock);
1410	    s_voice.tts_pb = NULL;
1411	    s_voice.tts_abort = 0;
1412	    pthread_mutex_unlock(&s_voice.lock);
1413	
1414	    audio_playback_close(pb);
1415	    free(clean);
1416	
1417	    if (ret != 0) {
1418	        syslog(LOG_ERR, "[%s] TTS stream failed: %d\n", TAG, ret);
1419	        pthread_mutex_unlock(&s_voice.speak_lock);
1420	        return ret;
1421	    }
1422	
1423	    struct timespec tend;
1424	    clock_gettime(CLOCK_MONOTONIC, &tend);
1425	    long total_ms = (tend.tv_sec - s_tts_start.tv_sec) * 1000
1426	        + (tend.tv_nsec - s_tts_start.tv_nsec) / 1000000;
1427	    syslog(LOG_INFO, "[%s] speak done: total %ldms (play wait %ldms)\n",
1428	        TAG, total_ms, total_ms - net_ms);
1429	    pthread_mutex_unlock(&s_voice.speak_lock);
1430	    return 0;
1431	}
