570	
571	static int tls_ctx_connect_retry(tls_ctx_t* ctx, const char* host,
572	    const char* port)
573	{
574	    int ret = VELA_TLS_ERR_HANDSHAKE;
575	    /* Backoff in ms: 500, 1000, 2000, 4000 for the 4 gaps between 5 attempts. */
