143	static int mimo_fetch_audio(const char* text, mimo_audio_t* out)
144	{
145	    memset(out, 0, sizeof(*out));
146	
147	    mimo_tts_init();
148	
149	    if (s_api_key[0] == '\0') {
150	        syslog(LOG_ERR, "[%s] API key not configured (set 'api_key')\n",
151	            TAG);
152	        return -ENOENT;
153	    }
154	
155	    char* body = build_tts_request(text);
156	
157	    if (!body) {
158	        syslog(LOG_ERR, "[%s] failed to build TTS request\n", TAG);
159	        return -ENOMEM;
160	    }
161	
162	    char auth[256];
163	    snprintf(auth, sizeof(auth), "Bearer %s", s_api_key);
164	
165	    /* NOTE: do NOT send "Connection: close". tls_write_request() already
166	     * emits "Connection: keep-alive", and a "close" header here would force
167	     * the server to drop the socket after every sentence. That made each
168	     * TTS sentence pay a fresh TCP+TLS handshake (~2-3s, or 10s+ on the
169	     * flaky MiMo edge), which is why a long story took ~50s to speak. */
170	    vela_header_t hdrs[] = {
171	        { "Authorization", auth },
172	        { "Content-Type", "application/json" },
173	        { NULL, NULL }
174	    };
175	
176	    char* resp = calloc(1, MIMO_TTS_RESP_SIZE);
177	
178	    if (!resp) {
179	        free(body);
180	        return -ENOMEM;
181	    }
182	
183	    syslog(LOG_INFO, "[%s] TTS request: text=%zu bytes host=%s\n",
184	        TAG, strlen(text), s_host);
185	
186	    size_t body_len;
187	    int status = vela_https_request(
188	        s_host, "443", "POST", MIMO_TTS_PATH, hdrs,
189	        body, strlen(body),
190	        resp, MIMO_TTS_RESP_SIZE, &body_len);
191	
192	    free(body);
193	
194	    if (status != 200) {
195	        syslog(LOG_ERR, "[%s] TTS HTTP %d: %.256s\n",
196	            TAG, status, resp);
197	        free(resp);
198	        return -EIO;
199	    }
200	
201	    if (body_len == 0) {
202	        syslog(LOG_ERR, "[%s] TTS: empty response body\n", TAG);
203	        free(resp);
204	        return -EPROTO;
205	    }
206	
207	    cJSON* root = cJSON_Parse(resp);
208	
209	    if (!root) {
210	        syslog(LOG_ERR, "[%s] TTS: bad JSON: %.256s\n", TAG, resp);
211	        free(resp);
212	        return -EPROTO;
213	    }
214	
215	    /* choices[0].message.audio.data */
216	    cJSON* choices = cJSON_GetObjectItem(root, "choices");
217	    cJSON* choice0 = (choices && cJSON_IsArray(choices))
218	        ? cJSON_GetArrayItem(choices, 0) : NULL;
219	    cJSON* msg = choice0 ? cJSON_GetObjectItem(choice0, "message") : NULL;
220	    cJSON* audio = msg ? cJSON_GetObjectItem(msg, "audio") : NULL;
221	    cJSON* data = audio ? cJSON_GetObjectItem(audio, "data") : NULL;
222	
223	    if (!data || !cJSON_IsString(data) || !data->valuestring[0]) {
224	        syslog(LOG_ERR, "[%s] TTS: no audio.data in response: %.256s\n",
225	            TAG, resp);
226	        cJSON_Delete(root);
227	        free(resp);
228	        return -EPROTO;
229	    }
230	
231	    out->resp = resp;
232	    out->root = root;
233	    out->b64 = data->valuestring;
234	    out->b64_len = strlen(data->valuestring);
235	    return 0;
236	}
