351	    .name = "mimo",
352	    .init = mimo_tts_init,
353	    .synthesize = mimo_tts_synthesize,
354	    .synthesize_stream = mimo_tts_synthesize_stream,
355	    .deinit = NULL,
356	};
357	
358	int mimo_tts_register(void)
359	{
360	    return voice_tts_register(&s_mimo_tts_ops);
361	}
