868	/* Incremental chunked-transfer decoder.  Chunked framing is
869	 *   <hex-size>\r\n<data>\r\n ... 0\r\n\r\n
870	 * and the chunk headers/data may be split arbitrarily across TLS reads,
871	 * so we carry incomplete bytes between calls.  Fully-received chunk
872	 * payloads are emitted to cb(). */
873	typedef struct {
874	    char  buf[8192];
875	    size_t len;
876	} chunk_decoder_t;
877	
878	/* Feed `len` raw (still-encoded) body bytes into the decoder.
879	 * Returns 1 when the final (zero-size) chunk has been consumed, 0 while
880	 * more data is expected, -1 on malformed framing. */
881	static int chunk_decoder_feed(chunk_decoder_t *cd, const char *data,
882	    size_t len, vela_stream_cb_t cb, void *ctx)
883	{
884	    while (len > 0) {
885	        size_t room = sizeof(cd->buf) - cd->len;
886	        size_t n = len < room ? len : room;
887	        memcpy(cd->buf + cd->len, data, n);
888	        cd->len += n;
889	        data += n;
890	        len -= n;
891	        if (cd->len == sizeof(cd->buf)) {
892	            syslog(LOG_ERR, "[%s] chunk decoder overflow\n", TAG);
893	            return -1;
894	        }
895	    }
896	
897	    for (;;) {
898	        char *crlf = (char *)memmem(cd->buf, cd->len, "\r\n", 2);
899	        if (!crlf)
900	            break; /* incomplete size line */
901	
902	        char *endptr = NULL;
903	        long chunk_sz = strtol(cd->buf, &endptr, 16);
904	        while (endptr < crlf && *endptr == ' ')
905	            endptr++;
906	        if (endptr == cd->buf || endptr != crlf || chunk_sz < 0) {
907	            syslog(LOG_ERR, "[%s] malformed chunk header\n", TAG);
908	            return -1;
909	        }
910	
911	        size_t hdr_len = (size_t)(crlf - cd->buf) + 2; /* size line + CRLF */
912	
913	        if (chunk_sz == 0) {
914	            cd->len = 0; /* final chunk — done */
915	            return 1;
916	        }
917	
918	        size_t need = hdr_len + (size_t)chunk_sz + 2; /* payload + CRLF */
919	        if (cd->len < need)
920	            break; /* not all of this chunk has arrived yet */
921	
922	        if (cb(cd->buf + hdr_len, (size_t)chunk_sz, ctx) != 0)
923	            return 1; /* caller aborted */
924	
925	        size_t consumed = hdr_len + (size_t)chunk_sz + 2;
926	        memmove(cd->buf, cd->buf + consumed, cd->len - consumed);
927	        cd->len -= consumed;
928	    }
929	
930	    return 0;
931	}
