933	/* Read a response, delivering decoded body bytes to cb() as they arrive.
934	 * Mirrors tls_read_response() but does not buffer the whole body. */
935	static int tls_read_response_stream(tls_ctx_t *ctx, vela_stream_cb_t cb,
936	    void *uctx)
937	{
938	    char *raw = tls_raw_acquire();
939	    size_t raw_len = 0;
940	    int ret;
941	    int result = VELA_TLS_ERR_READ;
942	    chunk_decoder_t *cd = NULL;
943	    char *tmp = NULL;
944	
945	    /* Read until full header (double CRLF). */
946	    while (raw_len < TLS_RAW_BUF_SIZE - 1) {
947	        ret = mbedtls_ssl_read(&ctx->ssl,
948	            (unsigned char *)(raw + raw_len), TLS_RAW_BUF_SIZE - 1 - raw_len);
949	        if (ret > 0) {
950	            raw_len += (size_t)ret;
951	            if (memmem(raw, raw_len, "\r\n\r\n", 4))
952	                break;
953	        } else if (ret == 0 || ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
954	            break;
955	        } else if (ret != MBEDTLS_ERR_SSL_WANT_READ) {
956	            syslog(LOG_ERR, "[%s] ssl_read (header) ret=0x%x\n", TAG, -ret);
957	            goto cleanup;
958	        }
959	    }
960	    raw[raw_len] = '\0';
961	
962	    int http_status = 0;
963	    if (sscanf(raw, "HTTP/1.%*d %d", &http_status) != 1) {
964	        syslog(LOG_ERR, "[%s] Failed to parse HTTP status\n", TAG);
965	        goto cleanup;
966	    }
967	    result = http_status;
968	
969	    char *body_start = (char *)memmem(raw, raw_len, "\r\n\r\n", 4);
970	    if (!body_start) {
971	        goto cleanup; /* no body */
972	    }
973	    body_start += 4;
974	
975	    long content_length = -1;
976	    {
977	        char *cl_hdr = strcasestr(raw, "Content-Length:");
978	        if (cl_hdr && cl_hdr < body_start) {
979	            content_length = strtol(cl_hdr + strlen("Content-Length:"), NULL, 10);
980	            if (content_length < 0 || content_length > 10 * 1024 * 1024)
981	                content_length = -1;
982	        }
983	    }
984	    int chunked = 0;
985	    {
986	        char *te_hdr = strcasestr(raw, "Transfer-Encoding:");
987	        if (te_hdr && te_hdr < body_start)
988	            chunked = (strcasestr(te_hdr, "chunked") != NULL);
989	    }
990	
991	    /* Initial fragment (bytes already read past the header). */
992	    size_t initial = (size_t)(raw + raw_len - body_start);
993	    long emitted = (long)initial;
994	
995	    /* Heap-allocate the chunk decoder + read buffer: the caller's task stack
996	     * (agent loop) is only 32KB and already carries a tls_ctx_t. */
997	    cd = calloc(1, sizeof(*cd));
998	    tmp = malloc(4096);
999	    if (!cd || !tmp) {
1000	        goto cleanup;
1001	    }
1002	
1003	    if (chunked) {
1004	        int r = chunk_decoder_feed(cd, body_start, initial, cb, uctx);
1005	        if (r < 0) {
1006	            result = VELA_TLS_ERR_READ;
1007	            goto cleanup;
1008	        }
1009	        if (r == 1) {
1010	            goto cleanup; /* final chunk already received */
1011	        }
1012	    } else if (initial > 0) {
1013	        if (cb(body_start, initial, uctx) != 0) {
1014	            goto cleanup;
1015	        }
1016	        if (content_length >= 0 && emitted >= content_length) {
1017	            goto cleanup;
1018	        }
1019	    }
1020	    tls_raw_release(raw);
1021	    raw = NULL;
1022	
1023	    /* Keep reading the body. */
1024	    for (;;) {
1025	        ret = mbedtls_ssl_read(&ctx->ssl, (unsigned char *)tmp, 4096);
1026	        if (ret > 0) {
1027	            if (chunked) {
1028	                int r = chunk_decoder_feed(cd, tmp, (size_t)ret, cb, uctx);
1029	                if (r < 0) {
1030	                    result = VELA_TLS_ERR_READ;
1031	                    break;
1032	                }
1033	                if (r == 1)
1034	                    break; /* final chunk — stop reading, don't wait for EOF */
1035	            } else {
1036	                if (cb(tmp, (size_t)ret, uctx) != 0)
1037	                    break;
1038	                emitted += ret;
1039	                if (content_length >= 0 && emitted >= content_length)
1040	                    break;
1041	            }
1042	        } else if (ret == 0 || ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
1043	            break;
1044	        } else if (ret != MBEDTLS_ERR_SSL_WANT_READ) {
1045	            break;
1046	        }
1047	    }
