    size_t sent = 0;
    while(sent < len) {
        ssize_t tmp = send(fd, buf + sent, len - sent, flags);
        if (tmp < 1) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                /* Socket is non-blocking and the send buffer is full right
