23	struct velaclaw_client_s {
24	    char app_id[32];
25	    pthread_mutex_t mtx;
26	    sem_t reply_sem;
27	    char* reply_text;
28	    int reply_status;
29	    void (*async_cb)(int, const char*, void*);
30	    void* async_cookie;
31	    void (*notify_cb)(int, const char*, void*);
