/* True for the code points that survive normalization: ASCII letters and
 * digits, and CJK unified ideographs. Everything else -- space, punctuation,
 * full-width forms, emoji -- is a separator and is skipped when matching. */
static bool wake_kept(unsigned int cp)
{
    return (cp >= '0' && cp <= '9') || (cp >= 'A' && cp <= 'Z')
        || (cp >= 'a' && cp <= 'z') || (cp >= 0x4e00 && cp <= 0x9fff);
}

