/* The Gemini-S1 has no RTC, so the clock starts at 1970.  TLS certificate
 * notBefore checks then fail and every cloud call (ASR / LLM / TTS) dies
 * silently.  There is nothing to read the real time from at boot, so seed
 * the clock with the build date -- only if it is still obviously unset, so
 * a future NTP sync (or a real RTC) is never stomped.
 */

static void seed_clock_if_unset(void)
{
  struct timespec now;
  struct tm tm;
  time_t when;

  if (clock_gettime(CLOCK_REALTIME, &now) == 0 && now.tv_sec > 1600000000)
    {
      return;                      /* Already sane (> 2020-09); leave it */
    }

  memset(&tm, 0, sizeof(tm));
  tm.tm_year = 2026 - 1900;
  tm.tm_mon  = 9 - 1;              /* September */
  tm.tm_mday = 10;
  tm.tm_hour = 12;
  tm.tm_min  = 0;
  tm.tm_sec  = 0;
  tm.tm_isdst = 0;

  when = mktime(&tm);

  struct timespec ts;
  ts.tv_sec  = when;
  ts.tv_nsec = 0;

  if (clock_settime(CLOCK_REALTIME, &ts) < 0)
    {
      syslog(LOG_WARNING, "[kid_buddy] clock_settime failed: %d\n", errno);
    }
  else
    {
      syslog(LOG_INFO, "[kid_buddy] no RTC, clock seeded to %s", ctime(&when));
    }
}
