415	static void kid_notify_cb(int status, const char *msg, void *cookie)
416	{
417	    (void)cookie;
418	
419	    if (msg == NULL || status == 1)
420	      {
421	        return;
422	      }
423	
424	    /* A cron reminder may carry a [KID_REPORT:<channel>|<chat_id>] prefix
425	     * asking for a child-confirmation report. Strip it, remember the report
426	     * destination, and speak only the reminder text itself. */
427	    const char *text = msg;
428	    if (strncmp(msg, "[KID_REPORT:", 12) == 0)
429	      {
430	        const char *end = strchr(msg, ']');
431	        const char *sep = strchr(msg + 12, '|');
432	        if (end && sep && sep < end)
433	          {
434	            size_t clen = (size_t)(sep - (msg + 12));
435	            size_t cidlen = (size_t)(end - (sep + 1));
436	            if (clen < sizeof(g_report_channel)
437	                && cidlen < sizeof(g_report_chat_id))
438	              {
439	                pthread_mutex_lock(&g_msg_lock);
440	                memcpy(g_report_channel, msg + 12, clen);
441	                g_report_channel[clen] = '\0';
442	                memcpy(g_report_chat_id, sep + 1, cidlen);
443	                g_report_chat_id[cidlen] = '\0';
444	                pthread_mutex_unlock(&g_msg_lock);
445	
446	                text = end + 1;
447	                if (*text == '\n')
448	                  {
449	                    text++;
450	                  }
451	                g_report_pending = 1;
452	              }
453	          }
454	      }
455	
456	    /* A reminder needs to speak, but the wake loop may be holding the capture
457	     * mic (and the codec's shared DMA channel) right now. Raise g_reply_busy so
458	     * the wake loop aborts its listen and releases the mic; the TTS worker then
459	     * waits for g_mic_open to clear before it opens playback. */
460	    busy_mark();
461	
462	    /* A reminder is an independent, complete message — not a streaming fragment
463	     * of an in-flight LLM reply. Reset the streaming TTS offset so the TTS
464	     * worker speaks it from the beginning; otherwise, if the previous reply was
465	     * longer, len <= spoken and the reminder is silently skipped (text on LCD
466	     * but no voice). */
467	    pthread_mutex_lock(&g_tts_lock);
468	    g_tts_epoch++;
469	    g_spoken_len = 0;
470	    g_tts_pending_ready = false;
471	    g_tts_pending_final = false;
472	    pthread_mutex_unlock(&g_tts_lock);
473	
474	    /* The confirmation window only opens once the reminder finishes playing
475	     * (the TTS worker arms g_last_reply_ms). Clear any stale arm from a prior
476	     * reply so the kid must acknowledge *after* hearing the reminder. */
477	    g_last_reply_ms = 0;
478	
479	    pthread_mutex_lock(&g_msg_lock);
480	    g_msg_status = 0;
481	    strncpy(g_pending_msg, text, MSG_BUF_LEN - 1);
482	    g_pending_msg[MSG_BUF_LEN - 1] = '\0';
483	    if (g_report_pending)
484	      {
485	        strncpy(g_report_reminder, text, MSG_BUF_LEN - 1);
486	        g_report_reminder[MSG_BUF_LEN - 1] = '\0';
487	      }
488	    g_msg_ready = true;
489	    pthread_mutex_unlock(&g_msg_lock);
490	
491	    syslog(LOG_INFO, "[kid_buddy] notify_cb len=%d report=%d\n",
492	           (int)strlen(text), g_report_pending);
493	}
