```c
/* Quotation marks, half- and full-width.  MiMo TTS reads every one of them
 * aloud, which breaks up the reply badly in a story (the characters' dialogue
 * is normally quoted).  Drop them and let the words stand on their own: the
 * child hears the sentence, not "左引号 ... 右引号".  The role prompts also ask
 * the model not to emit them, but a prompt is a request, not a guarantee --
 * this is the part that always runs. */
static bool is_quote_cp(unsigned int cp)
{
    switch (cp)
      {
        case 0x0022:  /* " */
        case 0x0027:  /* ' */
        case 0x0060:  /* ` */
        case 0x2018:  /* ' */
        case 0x2019:  /* ' */
        case 0x201A:
        case 0x201B:
        case 0x201C:  /* " */
        case 0x201D:  /* " */
        case 0x201E:
        case 0x201F:
        case 0x2032:  /* prime */
        case 0x2033:  /* double prime */
        case 0x2035:
        case 0x2036:
        case 0x300C:  /* 「 */
        case 0x300D:  /* 」 */
        case 0x300E:  /* 『 */
        case 0x300F:  /* 』 */
        case 0x301D:
        case 0x301E:
        case 0x301F:
        case 0xFF02:  /* ＂ */
        case 0xFF07:  /* ＇ */
            return true;
        default:
            return false;
      }
}

static void strip_quotes(char *s)
{
    char *src = s;
    char *dst = s;

    while (*src)
      {
        unsigned int cp = 0;
        int n = utf8_decode(src, &cp);

        if (is_quote_cp(cp))
          {
            src += n;
            continue;
          }

        for (int i = 0; i < n; i++)
          {
            *dst++ = *src++;
          }
      }

    *dst = '\0';
}
```

