        strncpy(msg.chat_id, job->chat_id, sizeof(msg.chat_id) - 1);
        msg.content = cron_build_reminder_content(job);

        if (msg.content) {
            int content_len = (int)strlen(msg.content);
            int err = message_bus_push_outbound(&msg);
