/* Append fmt to buf at off, never letting off leave [0, size-1].
 * snprintf returns the length it *would* have written, so the naive
 * "off += snprintf(buf + off, size - off, ...)" overshoots size on
 * truncation; every later (size - off) then underflows size_t into a huge
 * value and writes run off the end of the buffer. Callers must use the
 * returned offset instead of adding snprintf's return themselves. */
static size_t append_bounded(char *buf, size_t size, size_t off, const char *fmt, ...)
{
    if (size == 0) return 0;
    if (off >= size - 1) return size - 1;   /* full: refuse, stay in bounds */

    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(buf + off, size - off, fmt, ap);
