/* Append a formatted chunk at off, never letting off leave [0, size - 1].
 *
 * snprintf returns the length it *would* have written, so the usual
 * "off += snprintf(buf + off, size - off, ...)" overshoots size the moment a
 * chunk gets truncated. Every later (size - off) then underflows size_t into
 * a huge value while buf + off is already past the end of the buffer —
 * snprintf sees "plenty of room" and writes an unbounded amount onto the
 * stack. The system prompt is assembled from a dozen such chunks and does get
 * truncated (the skills summary alone is ~1.7 KB), so every step is clamped
 * here instead. Returns the new offset; on truncation it stops at size - 1. */
static size_t append_fmt(char *buf, size_t size, size_t off, const char *fmt, ...)
{
    if (size == 0) {
        return 0;
    }

    if (off >= size - 1) {
        return size - 1;   /* already full — refuse, stay in bounds */
    }

    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(buf + off, size - off, fmt, ap);
    va_end(ap);

    if (n < 0) {
        return off;        /* encoding error, nothing written */
    }

    if ((size_t)n >= size - off) {
        return size - 1;   /* truncated */
    }

    return off + (size_t)n;
}

/* Build a comma-separated list of registered tool names.
