                first ? "" : ", ", name->valuestring);
            first = false;
        }
    }

    cJSON_Delete(arr);
    return off;
}

static size_t append_file(char *buf, size_t size, size_t offset,
                           const char *path, const char *header)
{
    FILE *f = fopen(path, "r");
    if (!f) return offset;

    if (header) {
