37	static void tap_callback(const agent_msg_t* msg, void* cookie)
38	{
39	    struct velaclaw_client_s* c = (struct velaclaw_client_s*)cookie;
40	    if (!c) {
41	        return;
42	    }
43	
44	    pthread_mutex_lock(&c->mtx);
45	
46	    if (c->async_cb) {
47	        /* Async mode: invoke user callback directly.
48	         * Streaming replies arrive as a series of partial fragments
49	         * (status 1) followed by one final fragment (status 0). Keep the
50	         * callback registered across partial fragments so the whole stream
51	         * reaches the caller; clear it only on the final fragment. */
52	        void (*cb)(int, const char*, void*) = c->async_cb;
53	        void* ck = c->async_cookie;
54	        int status = msg->partial ? 1 : 0;
55	        if (!msg->partial) {
56	            c->async_cb = NULL;
57	            c->async_cookie = NULL;
58	        }
59	        pthread_mutex_unlock(&c->mtx);
60	
61	        cb(status, msg->content, ck);
62	        return;
63	    }
64	
65	    /* No ask in flight — route to the persistent notify callback (e.g. cron
66	     * reminders), mirroring async semantics but keeping notify_cb registered. */
67	    if (c->notify_cb) {
68	        void (*cb)(int, const char*, void*) = c->notify_cb;
69	        void* ck = c->notify_cookie;
70	        int status = msg->partial ? 1 : 0;
71	        pthread_mutex_unlock(&c->mtx);
72	        cb(status, msg->content, ck);
73	        return;
74	    }
75	
76	    /* Sync mode: store reply and signal */
77	    free(c->reply_text);
78	    c->reply_text = msg->content ? strdup(msg->content) : NULL;
79	    c->reply_status = 0;
80	    pthread_mutex_unlock(&c->mtx);
81	
82	    sem_post(&c->reply_sem);
83	}
