842	    g_spoken_len = 0;
843	    g_tts_pending_ready = false;
844	    g_tts_pending_final = false;
845	    pthread_mutex_unlock(&g_tts_lock);
846	
847	    lv_label_set_text(g_chat_status, "Thinking...");
848	    if (g_chat_spinner)
849	      {
850	        lv_obj_clear_flag(g_chat_spinner, LV_OBJ_FLAG_HIDDEN);
851	      }
852	
853	    syslog(LOG_INFO, "[kid_buddy] llm ask via=%s story=%d \"%.48s\"\n",
854	           via, g_story_mode, user_text);
855	
856	    int ret = velaclaw_ask(g_agent_client, &req, llm_response_cb, NULL);
857	    if (ret < 0)
858	      {
