870	 * Idle story continuation (剧情主动续讲 / 上下文主动): the kid listened to half
871	 * an adventure, then walked away. Once the story has been quiet for
872	 * IDLE_STORY_MS, proactively ask whether to continue — the same "主动" story
873	 * the boot-time probe tells, but mid-session. Runs on the LVGL thread; the
874	 * proactive turn resets g_last_interaction_ms (in send_raw_to_llm), so this
875	 * fires at most once per idle period and never spams.
876	 ****************************************************************************/
877	
878	static void idle_story_timer_cb(lv_timer_t *timer)
879	{

1884	}
1885	
1886	static void poll_timer_cb(lv_timer_t *timer)
1887	{
1888	    static int heartbeat;
1889	
1890	    (void)timer;
1891	
1892	    /* Liveness probe — logs once every ~10s (200ms period × 50). If this
1893	     * stops after a TTS speak finishes, the LVGL thread has hung (screen
1894	     * frozen), as opposed to a touch-only stall. */
1895	    if (++heartbeat % 50 == 0)
1896	      {
1897	        syslog(LOG_INFO, "[kid_buddy] LVGL heartbeat #%d\n", heartbeat);
1898	      }
1899	
1900	    /* Watchdog: release a reply that died somewhere between the request and
1901	     * the TTS callback. While the request is healthy every LLM fragment and
1902	     * every TTS speak refreshes g_busy_since_ms, so a stamp older than
1903	     * REPLY_BUSY_TIMEOUT_MS means nothing is coming. Leaving the flag set
1904	     * would keep the wake loop out of the mic forever — the board silences
1905	     * itself and stops answering, which reads as a frozen screen and used to
1906	     * need a power cycle to clear. */
1907	    if (g_reply_busy && g_busy_since_ms != 0
1908	        && now_ms() - g_busy_since_ms > REPLY_BUSY_TIMEOUT_MS)
1909	      {
1910	        syslog(LOG_WARNING,
1911	               "[kid_buddy] reply watchdog: no response for %lldms, "
1912	               "releasing the wake loop\n",
1913	               (long long)(now_ms() - g_busy_since_ms));
1914	        g_reply_busy = 0;
1915	        g_busy_since_ms = 0;
1916	        if (g_chat_spinner)
1917	          {
1918	            lv_obj_add_flag(g_chat_spinner, LV_OBJ_FLAG_HIDDEN);
1919	          }
1920	      }
1921	
1922	    /* Snapshot the latest LLM message under the same lock the callback uses,
1923	     * so the status and text are read as one consistent pair (a torn read
1924	     * could otherwise tag a stale short fragment as "final" and drop the
1925	     * rest of the reply). */
1926	    int  msg_status;
1927	    char msg_text[MSG_BUF_LEN];
1928	    bool have_msg = false;
1929	
1930	    pthread_mutex_lock(&g_msg_lock);
1931	    if (g_msg_ready)
1932	      {
1933	        g_msg_ready = false;
1934	        msg_status = g_msg_status;
1935	        strncpy(msg_text, g_pending_msg, MSG_BUF_LEN - 1);
1936	        msg_text[MSG_BUF_LEN - 1] = '\0';
1937	        have_msg = true;
1938	      }
1939	    pthread_mutex_unlock(&g_msg_lock);
1940	
1941	    if (have_msg)
1942	      {
1943	        /* Drop emoji before display AND before TTS: the LCD font can't show
1944	         * them (tofu boxes) and MiMo TTS reads them as a stray "think" word. */
1945	        strip_emoji(msg_text);
1946	        /* Drop Markdown ("---", **bold**, #headers, bullets) — TTS reads the
1947	         * "---" rule as a stray word too. */
1948	        strip_markdown(msg_text);
1949	        /* Drop quotation marks — TTS reads 「」""'' aloud, and story dialogue
1950	         * is quoted on nearly every line. */
1951	        strip_quotes(msg_text);
1952	
1953	        /* Hide spinner as soon as the first text arrives. */
1954	        if (g_chat_spinner)
1955	          {
1956	            lv_obj_add_flag(g_chat_spinner, LV_OBJ_FLAG_HIDDEN);
1957	          }
1958	
1959	        if (msg_status == 0 || msg_status == 1)
1960	          {
1961	            /* Show the running reply text. */
1962	            lv_label_set_text(g_chat_msg_area, msg_text);
1963	
1964	            /* Feed the cumulative text to the TTS worker. Partial fragments
1965	             * (status 1) are spoken sentence-by-sentence as they complete;
1966	             * the final fragment (status 0) flushes the remainder. */
1967	            enqueue_tts(msg_text, msg_status == 0);
1968	
1969	            if (msg_status == 0)
1970	              {
1971	                lv_label_set_text(g_chat_status, "Tap 'Ask me!' to continue");
1972	              }
1973	            else
1974	              {
1975	                lv_label_set_text(g_chat_status, "Replying...");
1976	              }
1977	          }
1978	        else
1979	          {
1980	            lv_label_set_text(g_chat_msg_area, msg_text);
1981	            lv_label_set_text(g_chat_status, "Error - check LLM config");
1982	            g_reply_busy = 0;  /* LLM errored out, release the wake loop */
1983	          }
1984	      }
1985	
1986	    /* Voice wake-word command handoff: the wake thread writes the command
1987	     * (wake word already stripped), we call send_to_llm() here so all LVGL
1988	     * access stays on this thread. */
1989	    char wake_cmd[MSG_BUF_LEN];
1990	    bool have_wake = false;
1991	
1992	    pthread_mutex_lock(&g_wake_cmd_lock);
1993	    if (g_wake_cmd_ready)
1994	      {
1995	        g_wake_cmd_ready = false;
1996	        strncpy(wake_cmd, g_wake_cmd, MSG_BUF_LEN - 1);
1997	        wake_cmd[MSG_BUF_LEN - 1] = '\0';
1998	        have_wake = true;
1999	      }
2000	    pthread_mutex_unlock(&g_wake_cmd_lock);
2001	
2002	    if (have_wake)
2003	      {
2004	        send_to_llm("voice", wake_cmd);
2005	        return;
2006	      }
2007	
2008	    /* Wake-word-only acknowledgement handoff. Show it on the chat screen and
2009	     * speak it from here; the wake thread deliberately did neither (it cannot
2010	     * touch LVGL) beyond raising g_reply_busy. A bare wake word is also the
2011	     * most likely first interaction of a session, so this is usually what
2012	     * creates the chat screen in the first place. */
2013	    char wake_prompt[MSG_BUF_LEN];
2014	    bool have_prompt = false;
2015	
2016	    pthread_mutex_lock(&g_msg_lock);
2017	    if (g_wake_prompt_ready)
2018	      {
2019	        g_wake_prompt_ready = false;
2020	        strncpy(wake_prompt, g_wake_prompt, MSG_BUF_LEN - 1);
2021	        wake_prompt[MSG_BUF_LEN - 1] = '\0';
2022	        have_prompt = true;
2023	      }
2024	    pthread_mutex_unlock(&g_msg_lock);
2025	
2026	    if (have_prompt)
2027	      {
2028	        if (g_chat_status == NULL)
2029	          {
2030	            ui_show_chat_screen();
2031	          }
2032	
2033	        lv_label_set_text(g_chat_msg_area, wake_prompt);
2034	        lv_label_set_text(g_chat_status, "Tap 'Ask me!' to continue");
2035	        enqueue_tts(wake_prompt, true);
2036	      }
2037	}
