2382	/****************************************************************************
2383	 * Public Functions
2384	 ****************************************************************************/
2385	
2386	int main(int argc, char *argv[])
2387	{
2388	    lv_nuttx_dsc_t info;
2389	    lv_nuttx_result_t result;
2390	
2391	    /* Both the display backend and the AI daemon need a sane clock, so do
2392	     * this before anything else comes up. */
2393	
2394	    seed_clock_if_unset();
2395	
2396	    if (lv_is_initialized())
2397	      {
2398	        LV_LOG_ERROR("LVGL already initialized! aborting.");
2399	        return -1;
2400	      }
2401	
2402	#ifdef NEED_BOARDINIT
2403	    boardctl(BOARDIOC_INIT, 0);
2404	#endif
2405	
2406	    /* Step 1: Initialize LVGL */
2407	    lv_init();
2408	
2409	    /* Step 2: Configure NuttX display backend */
2410	    lv_nuttx_dsc_init(&info);
2411	
2412	#ifdef CONFIG_LV_USE_NUTTX_LCD
2413	    info.fb_path = "/dev/lcd0";
2414	#endif
2415	
2416	#ifdef CONFIG_INPUT_TOUCHSCREEN
2417	    info.input_path = "/dev/input0";
2418	#endif
2419	
2420	    lv_nuttx_init(&info, &result);
2421	
2422	    /* Necessary delay for LCD initialization timing */
2423	    usleep(100000);
2424	
2425	    if (result.disp == NULL)
2426	      {
2427	        LV_LOG_ERROR("Display initialization failure!");
2428	        return 1;
2429	      }
2430	
2431	    /* Step 3: Connect to ai_agent daemon */
2432	    g_agent_client = velaclaw_client_open("kid_buddy");
2433	    if (g_agent_client != NULL)
2434	      {
2435	        g_agent_connected = true;
2436	        /* Receive unsolicited outbound messages (cron reminders pushed to the
2437	         * local_client channel) so the buddy can speak them proactively. */
2438	        velaclaw_set_notify_callback(g_agent_client, kid_notify_cb, NULL);
2439	        LV_LOG_USER("Connected to AI Agent daemon.");
2440	      }
2441	    else
2442	      {
2443	        g_agent_connected = false;
2444	        LV_LOG_WARN("AI Agent daemon not available. UI only mode.");
2445	      }
2446	
2447	    /* Step 4: Create UI and start on role selection */
2448	    ui_create_role_select();
2449	    lv_scr_load(g_scr_role_select);
2450	
2451	    /* Step 5: Create poll timer to update UI from LLM callbacks */
2452	    lv_timer_create(poll_timer_cb, 200, NULL);
2453	
2454	    /* Step 5a: Restore story mode BEFORE the boot probe fires, so a board
2455	     * that was powered off mid-adventure resumes inside the story session. */
2456	    story_mode_load();
2457	
2458	    /* Step 5b: Boot greeting + proactive continuation — speaks a fixed local
2459	     * welcome line a few seconds after startup, then hands over to the LLM
2460	     * probe that resumes an unfinished story or opens the conversation. */
2461	    lv_timer_create(proactive_timer_cb, 1000, NULL);
2462	
2463	    /* Step 5c: Idle story continuation — periodically checks whether the kid
2464	     * walked away mid-story and, if so, proactively offers to carry on. */
2465	    lv_timer_create(idle_story_timer_cb, IDLE_CHECK_MS, NULL);
2466	
2467	    /* Step 5d: Start the single TTS worker thread that speaks the streamed
2468	     * reply sentence-by-sentence (serialized so it never aborts itself). */
2469	    pthread_attr_t tts_attr;
2470	
2471	    pthread_attr_init(&tts_attr);
2472	    pthread_attr_setstacksize(&tts_attr, 65536);
2473	    pthread_t tts_tid;
2474	
2475	    if (pthread_create(&tts_tid, &tts_attr, tts_stream_worker, NULL) != 0)
2476	      {
2477	        syslog(LOG_ERR, "[kid_buddy] Failed to start TTS worker\n");
2478	      }
2479	    pthread_attr_destroy(&tts_attr);
2480	
2481	    /* Step 5e: Start the wake-word listening thread. It waits for the reply
2482	     * to finish before opening the mic, then uses local VAD + MiMo ASR to
2483	     * detect the wake word and hand the command to the LLM. */
2484	    pthread_attr_t wake_attr;
2485	    pthread_t wake_tid;
2486	
2487	    pthread_attr_init(&wake_attr);
2488	    pthread_attr_setstacksize(&wake_attr, 65536);
2489	
2490	    if (pthread_create(&wake_tid, &wake_attr, wake_listen_worker, NULL) != 0)
2491	      {
2492	        syslog(LOG_ERR, "[kid_buddy] Failed to start wake worker\n");
2493	      }
2494	    pthread_attr_destroy(&wake_attr);
2495	
2496	    /* Step 6: Main loop */
2497	    while (1)
2498	      {
2499	        uint32_t idle = lv_timer_handler();
2500	        idle = idle ? idle : 1;
2501	        usleep(idle * 1000);
2502	      }
2503	
2504	    return 0;
2505	}
