925	 *   1. ~4s  — speak a fixed local welcome line. No network, no LLM, so the
926	 *             board says something even with no connectivity or a slow first
927	 *             token. This is what the child hears on power-up.
928	 *   2. ~12s — ask the LLM to check history and either resume an unfinished
929	 *             story/RPG or pick up the conversation. Deletes the timer, and is
930	 *             skipped entirely when there is no network (see below).
931	 *
932	 * The two phases are separated on purpose; see BOOT_GREETING_TICKS.
933	 ****************************************************************************/
934	
935	static void proactive_timer_cb(lv_timer_t *timer)
936	{
937	    static int ticks = 0;
938	
939	    ticks++;
940	
941	    /* ── Phase 1: local greeting ─────────────────────────────── */
942	    if (!g_boot_greeted && ticks >= BOOT_GREETING_TICKS)
943	      {
944	        g_boot_greeted = true;
945	
946	        syslog(LOG_INFO, "[kid_buddy] boot greeting (local)\n");
947	
948	        /* Chat widgets only exist once the chat screen has been built; the
949	         * board boots on the role-selection screen, so this is normally a
950	         * no-op. The greeting is meant for the ear — do NOT switch screens
951	         * here, that would skip the role picker the kid boots into. */
952	        if (g_chat_msg_area != NULL)
953	          {
954	            lv_label_set_text(g_chat_msg_area, KID_BUDDY_BOOT_GREETING);
955	          }
956	
957	        /* Mark busy before queueing, exactly as wake_speak_prompt() does: the
958	         * wake loop re-opens the mic whenever g_reply_busy is clear, and the
959	         * codec's DMA channel is shared with playback — a mic opened during
960	         * the greeting makes it play silently. The TTS worker clears the flag
961	         * once the line has been spoken (and the watchdog in poll_timer_cb
962	         * recovers it if that never happens). */
963	        busy_mark();
964	        enqueue_tts(KID_BUDDY_BOOT_GREETING, true);
965	
966	        /* Never share a tick with the probe — send_raw_to_llm() would clear
967	         * the slot the greeting was just queued into. */
968	        return;
969	      }
970	
971	    /* ── Phase 2: boot-probe LLM turn ────────────────────────── */
972	    if (ticks < BOOT_PROBE_TICKS)
973	      {
974	        return;
975	      }
976	
977	    lv_timer_delete(timer);
978	
979	    if (!g_agent_connected || g_agent_client == NULL)
980	      {
981	        return;
982	      }
983	
984	    if (g_reply_busy)
985	      {
986	        return;  /* kid already interacting — don't interrupt */
