static void face_geom(void)
{
    int band_w = g_scr_w - TAPE_W;

    /* The face is a VERTICAL STACK -- props, brows, eyes, mouth -- so it is
     * laid out in fractions of the screen height, not of a notional "face
     * diameter". An earlier draft scaled everything off min(band_w, height);
     * on this 320x240 panel (which is wider than it is tall) that produced a
     * small face marooned in the middle of a wide, empty band. Percentages of
     * the height cannot do that: 17%, 38%, 58%, 82% stay evenly spaced
     * whatever the panel turns out to be.
     *
     * Props go above the face on purpose. Overhead is where a thought sits;
     * the same shapes below the mouth would read as objects being stood on. */
    g_face_cy = g_scr_h * 58 / 100;   /* the eye line */
    g_face_cx = band_w / 2;

    g_geo.eye_h  = g_scr_h * 33 / 100;
    g_geo.eye_w  = g_geo.eye_h * 58 / 100;   /* taller than wide: room to squint */
    g_geo.eye_dx = g_geo.eye_w * 115 / 100;
    g_geo.eye_cy = g_face_cy;

    /* Keep the pair inside the band. eye_w is what gives, not the gap: two
     * narrower eyes still read as a face, whereas eyes running under the
     * bookmarks read as a bug. The pair is 2*1.15*eye_w + eye_w = 3.3 wide. */
    if (g_geo.eye_dx * 2 + g_geo.eye_w > band_w * 88 / 100)
      {
        g_geo.eye_w  = band_w * 88 / 100 * 100 / 330;
        g_geo.eye_dx = g_geo.eye_w * 115 / 100;
      }

    /* Width of the eye pair -- the scale the props are sized against. */
    g_face_d = g_geo.eye_dx * 2 + g_geo.eye_w;

    g_geo.pupil_d  = g_geo.eye_w * 58 / 100;
    g_geo.glint_d  = g_geo.eye_w * 18 / 100;
    g_geo.brow_w   = g_geo.eye_w * 105 / 100;
    g_geo.brow_h   = g_geo.eye_h * 10 / 100;
    g_geo.brow_cy  = g_scr_h * 38 / 100;
    g_geo.mouth_cy = g_scr_h * 82 / 100;
    g_geo.mouth_w  = g_geo.eye_w * 160 / 100;
    g_geo.prop_cy  = g_scr_h * 17 / 100;
}

