def cjk(size=16):
    """SimSun_16's stand-in for the preview. Not the same typeface -- the
    metrics that matter here (16 px full-width cells, 19 px line) are.

    Serif before sans because SimSun is a Song face: at 16 px its thin
    horizontals and the serif on the sans are the parts that decide whether a
    child can read it, so previewing with Noto Sans CJK would flatter it.
    """
    from PIL import ImageFont
    for path in (CJK_TTF,
                 "/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc",
                 "/usr/share/fonts/truetype/droid/DroidSansFallbackFull.ttf"):
        try:
            return ImageFont.truetype(path, size)
        except OSError:
            continue
    return ImageFont.load_default(size)

