2503	static void face_make_eyes(void)
2504	{
2505	    int w = g_geo.eye_w;
2506	    int h = g_geo.eye_h;
2507	
2508	    for (int i = 0; i < 2; i++)
2509	      {
2510	        int cx = g_face_cx + (i == 0 ? -g_geo.eye_dx : g_geo.eye_dx);
2511	
2512	        /* The eye is a rounded rect whose SIZE animates. Its radius is pinned
2513	         * to eye_r and never changes: lv_draw_sw_mask.c caches the
2514	         * antialiased circle mask keyed on radius alone (4 slots), so a radius
2515	         * that changes per frame means a cache miss per frame, and a miss
2516	         * costs two lv_malloc()s inside circ_calc_aa4().
2517	         *
2518	         * eye_r is deliberately BELOW eye_w/2 rather than a capsule, because
2519	         * the effective radius is min(eye_r, h/2) and a capsule only stays
2520	         * cache-friendly while h >= eye_w -- which would leave the entire
2521	         * squint range 16 px wide. See face_eye_h(). */
2522	        lv_obj_t *eye = face_blob(g_face.scr, w, h, FACE_CREAM);
2523	        lv_obj_set_style_radius(eye, g_geo.eye_r, LV_PART_MAIN);
2524	        lv_obj_set_pos(eye, cx - w / 2, g_geo.eye_cy - h / 2);
2525	        g_face.eye_white[i] = eye;
2526	
2527	        /* Pupil + highlight ride inside the eye, so they follow it. */
2528	        g_face.pupil[i] = face_circle(eye, g_geo.pupil_d, FACE_PUPIL);
2529	        lv_obj_align(g_face.pupil[i], LV_ALIGN_CENTER, 0, 0);
2530	
2531	        g_face.glint[i] = face_circle(eye, g_geo.glint_d, FACE_GLINT);
