/* One character's width in half-width cells: 1 for anything narrow, 2 for CJK
 * and the full-width forms. This is the unit the panel is measured in, and it
 * is why the truncation below works in cells rather than in bytes -- a byte
 * budget would cut a mixed Chinese/Latin line at a different visual width
 * depending on how much of it happened to be ASCII.
 *
 * The threshold is a guess at the font, not a measurement of it: SimSun_16 is
 * 16 px per CJK glyph and 8 px per ASCII one, and everything from U+2000 up in
 * this font is full-width. get_glyph_width() would be exact, but it wants the
 * font descriptor and a per-frame table lookup to produce the same 8 or 16. */
static int face_cp_cells(unsigned int cp)
{
    return (cp < 0x2000) ? 1 : 2;
}

/* Copy src into dst, cut to at most `budget` cells, and closed with an ellipsis
 * if anything was dropped. The cut lands on a character boundary, never inside
 * a UTF-8 sequence -- slicing bytes would leave the label rendering the tail of
 * a 3-byte character as garbage.
 *
 * Truncating here rather than leaning on LV_LABEL_LONG_DOT is deliberate: DOT
 * does not wrap, so a long reply would come out as one clipped line, and the
 * label is the one object on this screen whose invalidation costs a full-screen
 * flush, so its content is worth getting right before it is ever set. */
static int face_fit(char *dst, size_t cap, const char *src, int budget)
{
    size_t n = 0;
    int used = 0;

    while (*src)
      {
        unsigned int cp;
        int len = utf8_decode(src, &cp);
        int w   = face_cp_cells(cp);

        if (used + w > budget)
          {
            break;
          }

        if (n + (size_t)len + 4 > cap)   /* + ellipsis + NUL */
          {
            break;
          }

        memcpy(dst + n, src, (size_t)len);
        n += (size_t)len;
        used += w;
        src += len;
      }

    /* Number of characters dropped, so we only add the ellipsis when the text
     * was actually cut -- and so a caller can tell "empty" from "truncated to
     * nothing", which are different things to draw. */
    while (n > 0 && dst[n - 1] == ' ')
      {
        n--;
      }

    if (*src)
      {
        memcpy(dst + n, "\xe2\x80\xa6", 3);   /* U+2026, two cells */
        n += 3;
      }

    dst[n] = '\0';
    return (int)(*src != '\0');
}

static void face_set_text(lv_obj_t *lbl, const char *s, int budget, int lines,
                          int x, int y)
{
    char buf[FACE_TEXT_BUF];
    char *cur = buf;

    /* The label's height is fixed at `lines` rows, so a string that wraps to
     * more than that is clipped rather than resized. Wrapping is measured by
     * LVGL against the label's own width, which this function does not know --
     * so it truncates to lines*budget cells first and lets LVGL do the rest. */
    face_fit(buf, sizeof(buf), s, budget * lines);

    /* Only write when the string actually changed. lv_label_set_text() is
     * unconditional: it reallocates the text, calls lv_obj_invalidate(), and on
     * this display an invalidate is a 153 KB full-screen flush (~31 ms on
     * SPI1). The stripped-and-truncated form is what gets compared, so two
     * different raw replies that display identically still cost nothing. */
    if (strcmp(cur, lv_label_get_text(lbl)) != 0)
      {
        lv_label_set_text(lbl, cur);
      }

    lv_obj_set_pos(lbl, x, y);
}

