/* Copy src into dst, cut to at most `budget` cells, and closed with an ellipsis
 * if anything was dropped. The cut lands on a character boundary, never inside
 * a UTF-8 sequence -- slicing bytes would leave the label rendering the tail of
 * a 3-byte character as garbage.
 *
 * Truncating here rather than leaning on LV_LABEL_LONG_DOT is deliberate: DOT
 * does not wrap, so a long reply would come out as one clipped line, and the
 * label is the one object on this screen whose invalidation costs a full-screen
 * flush, so its content is worth getting right before it is ever set. */
static bool face_fit(char *dst, size_t cap, const char *src, int budget)
{
    size_t n = 0;
    int used = 0;
    bool cut = false;

    while (*src)
      {
        unsigned int cp;
        int len = utf8_decode(src, &cp);
        int w   = face_cp_cells(cp);

        if (used + w > budget || n + (size_t)len + 4 > cap)
          {
            cut = true;
            break;
          }

        memcpy(dst + n, src, (size_t)len);
        n += (size_t)len;
        used += w;
        src += len;
      }

    while (n > 0 && dst[n - 1] == ' ')
      {
        n--;
      }

    if (cut)
      {
        memcpy(dst + n, "\xe2\x80\xa6", 3);   /* U+2026, two cells */
        n += 3;
      }

    dst[n] = '\0';
    return cut;
}

