/* store must be a buffer that outlives the label -- see lv_label_set_text_static
 * below. `s` may be any temporary. */
static bool face_set_text(lv_obj_t *lbl, char *store, size_t cap, const char *s,
                          int budget, int lines)
{
    char buf[FACE_TEXT_BUF];

    /* The label's height is fixed at `lines` rows, so a string that wraps past
     * that is clipped rather than resized -- the text would just stop. Wrap it
     * to those rows here instead, so what is dropped is dropped visibly. */
    face_fit(buf, sizeof(buf), s, budget, lines);

    /* Only write when the string actually changed. lv_label_set_text() is
     * unconditional, and on this display an invalidate is a 153 KB full-screen
     * flush (~31 ms on SPI1). Comparing the stripped-and-truncated form means
     * two replies that differ only past the truncation point cost nothing --
     * which is the common case while a reply streams in. */
    if (strcmp(buf, store) == 0)
      {
        return false;
      }

    strncpy(store, buf, cap - 1);
    store[cap - 1] = '\0';

    /* _static, not the copying setter: this runs up to 4x a second per label
     * while a reply streams, and the copying one hands the heap a malloc/free
     * pair every time. The buffers are file-scope, so the pointer stays valid
     * for the life of the label. */
    lv_label_set_text_static(lbl, store);
    return true;
}

