  **`face_fit()` rewritten** — new signature, returns row count:
```c
static int face_fit(char *dst, size_t cap, const char *src, int budget,
                    int max_rows, bool *cut_out)
{
    size_t n = 0;
    int cells = 0;
    int line = 0;
    bool cut = false;
    int rows = 0;

    if (cut_out != NULL) { *cut_out = false; }
    if (budget < 4 || max_rows < 1)
      {
        dst[0] = '\0';
        if (cut_out != NULL) { *cut_out = (*src != '\0'); }
        return 0;
      }
    cap--;
    while (*src) { /* ...unchanged per-character loop, `lines` -> `max_rows`... */ }
    if (cut) { /* ...unchanged ellipsis back-off... */ }
    while (n > 0 && dst[n - 1] == '\n') { n--; }
    dst[n] = '\0';

    /* Counted from the string rather than from `line`, because the strip above
     * can take a row away and `line` would not know: text ending in a newline
     * finishes one line but draws only that many rows. */
    if (n > 0)
      {
        rows = 1;
        for (size_t i = 0; i < n; i++)
          { if (dst[i] == '\n') { rows++; } }
      }
    if (cut_out != NULL) { *cut_out = cut; }
    return rows;
}
```
